/// observed: Ghidra prints one parameter, but the call site in `0x80083AD0`
/// passes a second word (`3`); the callee reads only `[heap+0x10]`.
const HEAP_DESTROY: usize = 0x802B_99C0;

/// `thunk_FUN_8016E980` (`0x80083B30` → `0x8016E980`): restore the saved root
/// heap and clear the save slot. The thunk itself is 4 bytes.
const HEAP_RESTORE: usize = 0x8016_E980;

/// `FUN_80083490(index)`: reads one `u16` from [`PALETTE_FILL_TABLE`].
const PALETTE_ENTRY: usize = 0x8008_3490;

/// `FUN_80083870(model)`: rebuilds the model's tile display lists.
///
/// Not translated (608 bytes, paired-single); called by
/// [`bg_unit_model_create`] with the model in `r3`.
const BG_UNIT_MODEL_REBUILD: usize = 0x8008_3870;

/// `FUN_80083D00(model, layer)`: uploads a bgdat layer into the model.
///
/// Not translated (284 bytes, 0xC48-byte stack frame); called by
/// [`bg_unit_model_create`] with the model and the layer handle.
const BG_UNIT_MODEL_UPLOAD: usize = 0x8008_3D00;

/// `FUN_80101AA0(x)`: wraps an x coordinate across the camera bounds.
///
/// Outside this lane. [`rect_contains_point`] calls it with a `f64` argument
/// and truncates the `f64` result to an integer.
const CAMERA_X_WRAP: usize = 0x8010_1AA0;

/// `FUN_802DCA98(ptr, dtor, size, count)`: Metrowerks `__destroy_arr`.
///
/// observed: walks from `ptr + size*count` downwards, calling
/// `dtor(element, 0xFFFFFFFF)` for each element.
const DESTROY_ARRAY: usize = 0x802D_CA98;

/// `FUN_8008EBA0(ptr, count)`: per-element destructor for the stage objects.
///
/// Translated as [`stage_object_delete`]; passed to [`DESTROY_ARRAY`] by
/// [`stage_objects_release`].
const STAGE_OBJECT_DTOR: usize = 0x8008_EBA0;

/// Calls a PowerPC function with one `f64` argument and an `f64` result.
///
/// Used for `0x80101AA0`, whose argument and result are doubles in `f1`; the
/// integer helpers in [`crate::platform`] cannot carry that ABI.
///
/// # Safety
/// `addr` must point to a function taking and returning `f64`.
unsafe fn call1_f64(addr: usize, a: f64) -> f64 {
    let f: extern "C" fn(f64) -> f64 = core::mem::transmute(addr);
    f(a)
}

// ---------------------------------------------------------------------------
// 0x80083380
// ---------------------------------------------------------------------------

/// Writes one tile cell addressed by absolute tile coordinates.
///
/// The tile map keeps its origin at `+0x24`/`+0x26`. The coordinate is made
/// relative to that origin, bounds-checked against the width/height at
/// `+0x30`/`+0x32`, and the cell is written through the `+0x28` array. The
/// previous value is returned, or `0xFFFF` when the coordinate is outside.
///
/// # Original
/// - Ghidra: `FUN_80083380` at `0x80083380` (84 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80083380_FUN_80083380.c`
/// - observed: `uVar4 = x - *(u16*)(map+0x24)`, `uVar5 = y - *(u16*)(map+0x26)`;
///   the bounds are `uVar4 < *(u16*)(map+0x30)` and
///   `uVar5 < *(u16*)(map+0x32)`; the address is
///   `[map+0x28] + width*uVar5*2 + uVar4*2`.
///
/// # Arguments
/// - `tilemap`: 0x44-byte BG tile-map object built by [`bg_tilemap_construct`].
/// - `x`, `y`: absolute tile coordinates (the map origin is added internally).
/// - `value`: `u16` cell value to store.
///
/// # Returns
/// The value that was in the cell, or `0xFFFF` when out of bounds.
///
/// # Side effects
/// Writes one `u16` into the `+0x28` array.
///
/// # Safety
/// `tilemap` must be a live tile map; the coordinate subtraction is unsigned
/// and wraps exactly as the original's `uint` arithmetic.
///
/// # Confidence
/// high - every load, store and comparison is observed. The difference from
/// [`bg_tilemap_set`] is that this variant takes absolute coordinates and
/// returns the old cell value.
pub unsafe fn bg_tilemap_set_at(tilemap: usize, x: u32, y: u32, value: u16) -> u16 {
    let dx = x.wrapping_sub(read_u16(tilemap + 0x24) as u32);
    let dy = y.wrapping_sub(read_u16(tilemap + 0x26) as u32);
    let width = read_u16(tilemap + 0x30) as u32;
    let height = read_u16(tilemap + 0x32) as u32;
    if dx < width && dy < height {
        let data = read_u32(tilemap + 0x28) as usize;
        let cell = data + (width * dy) as usize * 2 + dx as usize * 2;
        let previous = read_u16(cell);
        write_u16(cell, value);
        previous
    } else {
        0xffff
    }
}

// ---------------------------------------------------------------------------
// 0x80083560
// ---------------------------------------------------------------------------

/// Creates a BG-unit model, or refreshes an existing one.
///
/// A null `model_or_null` allocates `0xC2C` bytes from `allocator`, installs
/// [`BG_UNIT_MODEL_VTABLE`] and records the unit (`+0xC1C`), stage (`+0xC20`)
/// and a null heap slot (`+0xC24`). It then asks the allocator's virtual slot
/// `+0x28` for a size, reserves that size minus `0x100` bytes through
/// `RES_LOAD`, binds the result to the model, rebuilds
/// the display lists, fetches the bgdat layer through
/// [`crate::resource::course::bg_layer_data`], uploads it, and restores the
/// saved root heap.
///
/// # Original
/// - Ghidra: `FUN_80083560` at `0x80083560` (252 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80083560_FUN_80083560.c`
/// - observed: `FUN_802b9240(0xc2c,param_2,4)`; stores at dwords `0x307`/`0x308`
///   (`+0xC1C`/`+0xC20`); virtual call `(**(code**)(*param_2 + 0x28))(param_2,4)`;
///   `FUN_8016e630(size - 0x100, param_2, 0, 0x20, 0)`; then
///   `FUN_80083ad0`, `FUN_80083870`, `FUN_800818b0`, `FUN_80083d00` and
///   `thunk_FUN_8016e980`.
///
/// # Arguments
/// - `model_or_null`: existing model to refresh, or `0` to allocate one.
/// - `allocator`: heap/allocator object; its vtable slot `+0x28` returns the
///   resource size for alignment `4`.
/// - `stage`: stage slot 0..=3 stored at `+0xC20`.
/// - `unit`: BG-unit slot 0..=3 stored at `+0xC1C`.
///
/// # Returns
/// The model pointer (the original returns `r3`), or `0` when allocation
/// failed.
///
/// # Side effects
/// Allocates memory, loads a resource, and calls the rebuild/upload helpers.
///
/// # Safety
/// `allocator` must be a readable object whose vtable slot `+0x28` is a valid
/// function; `model_or_null` must be null or a live model. When the existing
/// model path is taken, the resource word passed to
/// [`bg_unit_model_bind_heap`] is `0`, exactly as printed.
///
/// # Confidence
/// medium - the allocation and field stores are observed; the roles of
/// `allocator`, the `-0x100` size adjustment and the upload call are inferred
/// from the call shape. The two large helpers remain calls by address.
pub unsafe fn bg_unit_model_create(
    model_or_null: usize,
    allocator: usize,
    stage: u32,
    unit: u32,) -> usize {
    let mut model = model_or_null;
    let mut resource = 0u32;
    if model == 0 {
        model = platform::call3(NEW, 0xc2c, allocator as u32, 4) as usize;
        if model != 0 {
            write_u32(model, BG_UNIT_MODEL_VTABLE as u32);
            write_u32(model + 0xc1c, unit);
 // inferred: unit slot
            write_u32(model + 0xc20, stage);
 // inferred: stage slot
            write_u32(model + 0xc24, 0);
 // inferred: bound heap/resource
        }
        // observed: the original still runs the allocator query when the
        // 0xC2C-byte allocation failed.
        let vtable = read_u32(allocator) as usize;
        let size_slot = read_u32(vtable + 0x28) as usize;
        let size = platform::call2(size_slot, allocator as u32, 4);
        resource = platform::call5(
            RES_LOAD,
            size.wrapping_sub(0x100),
            allocator as u32,
            0,
            0x20,
            0,
        );
    }
    bg_unit_model_bind_heap(model, resource);
    platform::call1(BG_UNIT_MODEL_REBUILD, model as u32);
    let layer = crate::resource::course::bg_layer_data(
        read_u32(G_BG_MANAGER) as usize,
        stage,
        unit,
    );
    platform::call2(BG_UNIT_MODEL_UPLOAD, model as u32, layer);
    platform::call1(HEAP_RESTORE, model as u32);
    model
}

// ---------------------------------------------------------------------------
// 0x80083660
// ---------------------------------------------------------------------------

/// Clears the BG-unit model's per-tile id table and its pointer area.
///
/// The first loop zeroes 64 rows of 32 bytes at `+0x408` (the 0x800-byte
/// per-tile table that [`bg_unit_model_tile_index`] and
/// [`bg_unit_model_alloc_palette`] index). The second loop zeroes dwords `+4`
/// through `+0x400` in eight 0x80-byte blocks, then the dword at `+0x404`
/// (together covering `+4..+0x407`), and finally the `u16` palette count at
/// `+0xC08`.
///
/// # Original
/// - Ghidra: `FUN_80083660` at `0x80083660` (360 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80083660_FUN_80083660.c`
/// - observed: loop 1 runs `iVar4 = 0x40` times, writing bytes
///   `+0x408..+0x427` and stepping `iVar2` by `0x20`; loop 2 runs eight times,
///   clearing `puVar1[1..0x1F]`, advancing `0x20` dwords, clearing `*puVar1`;
///   then `param_1[0x101] = 0` and `*(u16*)(param_1 + 0x302) = 0`.
///
/// # Arguments
/// - `model`: BG-unit model (0xC2C bytes).
///
/// # Side effects
/// Clears the model body from `+4` through `+0xC09` (pointer area, the
/// 0x800-byte tile table and the palette count). The vtable at `+0` and the
/// tail `+0xC0A..+0xC2B` are deliberately left untouched, matching the
/// original.
///
/// # Safety
/// `model` must be a writable 0xC2C-byte model.
///
/// # Confidence
/// high - the two loops and their strides are explicit in the evidence.
pub unsafe fn bg_unit_model_clear(model: usize) {
    // observed: 64 rows x 32 bytes at +0x408.
    for row in 0..0x40usize {
        for byte in 0..0x20usize {
            write_u8(model + row * 0x20 + 0x408 + byte, 0);
        }
    }
    // observed: eight blocks of 0x80 bytes plus the first dword of the next
    // block; this clears dwords +4..+0x400, including the duplicated boundary
    // dwords at +0x80, +0x100, ... .
    let mut cursor = model;
    for _block in 0..8usize {
        for dword in 1..0x20usize {
            write_u32(cursor + dword * 4, 0);
        }
        cursor += 0x80;
        write_u32(cursor, 0);
    }
    write_u32(model + 0x404, 0);
    write_u16(model + 0xc08, 0);
 // palette-block count
}

// ---------------------------------------------------------------------------
// 0x800837D0
// ---------------------------------------------------------------------------

/// Allocates and fills one palette block for a tile slot.
///
/// The slot's offset in the `+0x408` table is stamped with the current palette
/// count (low byte), a 0x200-byte block is allocated, and all 256 `u16` entries
/// are filled from [`PALETTE_FILL_TABLE`] entry `10`. The block pointer is
/// stored in the pointer array at `+4`, and the count at `+0xC08` grows by one.
///
/// # Original
/// - Ghidra: `FUN_800837d0` at `0x800837D0` (152 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800837d0_FUN_800837d0.c`
/// - observed: `*(char*)(model+slot+0x408) = (char)*(u16*)(model+0xC08);`
///   `FUN_802b9250(0x200)`; 0x100 iterations of `FUN_80083490(10)`;
///   `*(u16**)(model + count*4 + 4) = block;` and count `+= 1`.
///
/// # Arguments
/// - `model`: BG-unit model.
/// - `slot`: byte index into the `+0x408` table (the caller passes a value
///   derived from the tile coordinate).
///
/// # Returns
/// Nothing; the allocated block is stored in the model.
///
/// # Side effects
/// Allocates 0x200 bytes, fills it, writes one byte at `+0x408+slot`, one
/// pointer at `+4+count*4`, and increments `+0xC08`.
///
/// # Safety
/// `model` must be writable; `slot` must land inside the 0x800-byte table and
/// `count` must be below the pointer-array capacity.
///
/// # Confidence
/// high - the allocation, fill and two stores are all observed. The palette
/// value is static (all 256 entries get table index `10`).
pub unsafe fn bg_unit_model_alloc_palette(model: usize, slot: i32) {
    let count = read_u16(model + 0xc08) as usize;
    write_u8(model + slot as usize + 0x408, count as u8);
    let block = platform::call1(NEW_ALIGN4, 0x200) as usize;
    for index in 0..0x100usize {
        // observed: the fill value comes from the static table at
        // PALETTE_FILL_TABLE + 10*2.
        let value = platform::call1(PALETTE_ENTRY, 10) as u16;
        write_u16(block + index * 2, value);
    }
    write_u32(model + count * 4 + 4, block as u32);
    write_u16(model + 0xc08, count as u16 + 1);
}

// ---------------------------------------------------------------------------
// 0x80083AD0
// ---------------------------------------------------------------------------

/// Binds a heap/resource buffer to a BG-unit model.
///
/// If the model has no buffer yet (`+0xC24 == 0`) the argument is stored
/// directly. Otherwise the previous buffer is destroyed through
/// [`HEAP_DESTROY`]. In both cases the root heap is saved
/// ([`HEAP_SAVE_ROOT`]) and then swapped to the model's buffer
/// ([`HEAP_SWAP_ROOT`]); the caller restores it later with
/// [`HEAP_RESTORE`].
///
/// # Original
/// - Ghidra: `FUN_80083ad0` at `0x80083AD0` (84 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80083ad0_FUN_80083ad0.c`
/// - observed: `if ([this+0xC24] == 0) [this+0xC24] = param_2; else
///   FUN_802b99c0([this+0xC24],3);` then `FUN_8016e970();` and
///   `thunk_FUN_802b9170([this+0xC24]);`.
///
/// # Arguments
/// - `model`: BG-unit model.
/// - `heap`: buffer/heap to bind; `0` is valid on the refresh path.
///
/// # Side effects
/// May destroy the previous buffer and changes the global root heap slot.
///
/// # Safety
/// `model` must be writable; `heap` must be null or a heap object.
///
/// # Confidence
/// high - the branch and three calls are observed. The meaning "buffer/heap" is
/// inferred from the swap with the root heap at `r13-0x4870`.
pub unsafe fn bg_unit_model_bind_heap(model: usize, heap: u32) {
    if read_u32(model + 0xc24) == 0 {
        write_u32(model + 0xc24, heap);
    } else {
        // observed: the call site passes a second word, 3.
        platform::call2(HEAP_DESTROY, read_u32(model + 0xc24), 3);
    }
    platform::call0(HEAP_SAVE_ROOT);
    platform::call1(HEAP_SWAP_ROOT, read_u32(model + 0xc24));
}

// ---------------------------------------------------------------------------
// 0x80083B30
// ---------------------------------------------------------------------------

/// Tail-branch thunk for the saved-root-heap restore at `0x8016E980`.
///
/// The four-byte body is a single unconditional branch to
/// [`crate::resource::registry::fn_8016e980`]; expressing it as a call to that
/// translated function keeps the same observable behaviour because the target
/// returns straight to this thunk's caller and the thunk has no stack frame of
/// its own.
///
/// # Original
/// - Ghidra: `thunk_FUN_8016e980` at `0x80083B30` (4 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80083b30_thunk_FUN_8016e980.c`
/// - observed: `functions.tsv` gives 4 bytes, and the word at `0x80083B30` in
///   `work/dol/main.elf` is `0x480EAE50`, i.e. `b 0x8016E980` (opcode 18,
///   `LI = 0xEAE50`). The export prints the target body, which restores the
///   saved root heap and clears the save slot.
///
/// # Arguments
/// None. The thunk forwards the caller's registers unchanged, and the target
/// reads only the `r13`-relative heap save slot.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// None of its own; the target swaps the root heap and clears the save slot.
///
/// # Safety
/// Must run on the original `r13` small-data base, as
/// [`crate::resource::registry::fn_8016e980`] requires.
///
/// # Confidence
/// high - the 4-byte `b 0x8016E980` is verified in the ELF and the export is
/// the target body verbatim.
pub unsafe fn fn_80083b30() {
    crate::resource::registry::fn_8016e980();
}

// ---------------------------------------------------------------------------
// 0x80083F90 / 0x80083B40
// ---------------------------------------------------------------------------

/// Maps a world tile coordinate to an index in the model's `+0x408` table.
///
/// The index is `((x >> 8) & 0xFF) + ((y >> 2) & 0x3FC0)`; values above
/// `0x7FF` are clamped to `0`. The function returns the byte stored at that
/// index, which is the tile's palette-block number.
///
/// # Original
/// - Ghidra: `FUN_80083f90` at `0x80083F90` (36 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80083f90_FUN_80083f90.c`
/// - observed: `uVar1 = (param_2 >> 8 & 0xff) + (param_3 >> 2 & 0x3fc0);`
///   `if (0x7ff < uVar1) uVar1 = 0; return *(byte*)(param_1 + uVar1 + 0x408);`
///
/// # Arguments
/// - `model`: BG-unit model.
/// - `x`, `y`: tile coordinates.
///
/// # Returns
/// The byte at `model + index + 0x408`.
///
/// # Safety
/// `model` must be a readable model; `index` is clamped to `0x7FF`, so the
/// read stays inside the 0x800-byte table when the table is zero-filled as in
/// [`bg_unit_model_clear`].
///
/// # Confidence
/// high - single expression plus the clamp, all observed. The call from
/// `0x80083B40` is printed without arguments by Ghidra; `r3`/`r4`/`r5` are
/// already `model`/`x`/`y` at that call site.
pub unsafe fn bg_unit_model_tile_index(model: usize, x: u32, y: u32) -> u8 {
    let mut index = ((x >> 8) & 0xff) + ((y >> 2) & 0x3fc0);
    if index > 0x7ff {
        index = 0;
    }
    read_u8(model + index as usize + 0x408)
}

/// Locates one 2-byte tile cell inside a BG-unit model.
///
/// Reads the palette-block number through [`bg_unit_model_tile_index`], then
/// indexes the block-pointer array at `+4`. Each block is 0x200 bytes; the
/// in-block offset is `((x >> 3) & 0x1E) + (y & 0xF0) * 2`. When `out_index`
/// is non-null the 16-bit block index is written through it. A null block
/// pointer yields `0`.
///
/// # Original
/// - Ghidra: `FUN_80083b40` at `0x80083B40` (144 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80083b40_FUN_80083b40.c`
/// - observed: `uVar1 = FUN_80083f90();` (arguments elided by Ghidra; r3/r4/r5
///   still hold `model`/`x`/`y`); `*param_4 = uVar1 & 0xffff`;
///   `iVar2 = *(int*)(model + (uVar1 & 0xffff)*4 + 4);` then
///   `iVar2 + (x >> 3 & 0x1e) + (y & 0xf0)*2`.
///
/// # Arguments
/// - `model`: BG-unit model.
/// - `x`, `y`: tile coordinates.
/// - `out_index`: optional address of a `u32` receiving the block index, or 0.
///
/// # Returns
/// The byte address of the tile's 2-byte cell, or `0` when the block is absent.
///
/// # Side effects
/// Writes four bytes through `out_index` when it is non-null.
///
/// # Safety
/// `model` must be readable; `out_index` must be null or writable.
///
/// # Confidence
/// high - the index arithmetic and both branches are observed; only the
/// elided call arguments are supplied from the register convention.
pub unsafe fn bg_unit_model_tile_at(
    model: usize,
    x: u32,
    y: u32,
    out_index: usize,) -> usize {
    let index = bg_unit_model_tile_index(model, x, y) as u32;
    if out_index != 0 {
        write_u32(out_index, index & 0xffff);
    }
    let block = read_u32(model + (index & 0xffff) as usize * 4 + 4) as usize;
    if block == 0 {
        0
    } else {
        block + ((x >> 3) & 0x1e) as usize + ((y & 0xf0) * 2) as usize
    }
}

// ---------------------------------------------------------------------------
// 0x80083BD0
// ---------------------------------------------------------------------------

/// Resolves the model's three unit-name strings to table indices.
///
/// The model's stage slot `+0xC20` selects a row of the BG-manager name block.
/// Units 1, 2 and 3 are compared against three static string-pointer tables;
/// on a match the table index is stored at `+0xC10`, `+0xC14` and `+0xC18`
/// respectively. All three slots (and the unrelated `+0xC0C`) start as
/// `0xFFFFFFFF` and stay at that value when no entry matches.
///
/// # Original
/// - Ghidra: `FUN_80083bd0` at `0x80083BD0` (296 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80083bd0_FUN_80083bd0.c`
/// - observed: the entry calls `FUN_802dcd70` (`__savegprlr_26`, which
///   preserves `r3`), so `iVar1` is the model argument; stores `-1` at
///   `+0xC0C..+0xC18`; `FUN_800813f0(manager,[model+0xC20],unit)` and a
///   `FUN_802e1ab4` scan of `0x28`, `0x10` and `6` table entries.
///
/// # Arguments
/// - `model`: BG-unit model whose name slots are filled.
///
/// # Side effects
/// Writes four dwords at `+0xC0C..+0xC18`; reads the BG manager through
/// [`G_BG_MANAGER`] and the stage slot at `+0xC20`.
///
/// # Safety
/// The manager must hold a populated name block for the model's stage, and the
/// three static tables must be readable.
///
/// # Confidence
/// medium - the loops and stores are observed; the table counts are direct
/// constants, but the meaning of the three name families is inferred from the
/// Ghidra string labels.
pub unsafe fn bg_unit_model_resolve_names(model: usize) {
    let manager = read_u32(G_BG_MANAGER) as usize;
    let stage = read_u32(model + 0xc20);
    write_u32(model + 0xc0c, 0xffff_ffff);
    write_u32(model + 0xc10, 0xffff_ffff);
    write_u32(model + 0xc14, 0xffff_ffff);
    write_u32(model + 0xc18, 0xffff_ffff);
    let mut unit = 1u32;
    for table in [
        (UNIT_NAMES_1, UNIT_NAMES_1_COUNT, 0xc10usize),
        (UNIT_NAMES_2, UNIT_NAMES_2_COUNT, 0xc14usize),
        (UNIT_NAMES_3, UNIT_NAMES_3_COUNT, 0xc18usize),
    ] {
        let name = unit_name(manager, stage, unit);
        let mut entry = 0u32;
        while entry < table.1 {
            if platform::call2(STRCMP, name as u32, read_u32(table.0 + entry as usize * 4)) == 0 {
                write_u32(model + table.2, entry);
                break;
            }
            entry += 1;
        }
        unit += 1;
    }
}

// ---------------------------------------------------------------------------
// 0x8008D3D0 / 0x8008D820
// ---------------------------------------------------------------------------

/// Classifies a point against a 2-D segment ordered along x.
///
/// The two endpoints are `a` and `b` (each two floats). A point outside the
/// `a.x..b.x` span returns `0xFFFFFFFF`. Inside the span the segment's y at the
/// point's x is evaluated and the point is classified as `3` when it lies at
/// or above that line, `2` when below.
///
/// # Original
/// - Ghidra: `FUN_8008d3d0` at `0x8008D3D0` (116 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008d3d0_FUN_8008d3d0.c`
/// - observed: `if ((x < a[0]) || (b[0] < x)) return -1;` else
///   `y <= (float)((float)(x - a[0]) * (b[1]-a[1])) / (b[0]-a[0]) + a[1]`
///   selects `3`, otherwise `2`.
///
/// # Arguments
/// - `x`, `y`: query point (original parameters are doubles).
/// - `a`, `b`: addresses of two `[x, y]` float pairs.
///
/// # Returns
/// `0xFFFFFFFF` outside the x span, `3` above/on the line, `2` below it.
///
/// # Safety
/// `a` and `b` must each be readable for eight bytes.
///
/// # Confidence
/// medium - the branches and comparisons are observed; "segment side" is
/// inferred from the four call sites in `0x8008D460`, which pass pairs of
/// region corners.
pub unsafe fn segment_side_x(x: f64, y: f64, a: usize, b: usize) -> u32 {
    let ax = read_f32(a) as f64;
    let bx = read_f32(b) as f64;
    if x < ax || bx < x {
        return 0xffff_ffff;
    }
    // observed: the interpolation is single precision, left to right:
    // ((x - a.x) * (b.y - a.y)) / (b.x - a.x) + a.y.
    let dx = (x - ax) as f32;
    let line = (dx * (read_f32(b + 4) - read_f32(a + 4))) / (read_f32(b) - read_f32(a))
        + read_f32(a + 4);
    if y <= line as f64 {
        3
    } else {
        2
    }
}

/// Classifies a point against a 2-D segment ordered along y.
///
/// The two endpoints are `a` and `b` (each two floats). A point outside the
/// `b.y..a.y` span returns `0xFFFFFFFF`. Inside the span the segment's x at the
/// point's y is evaluated; the return is `0` when that x is below the point's
/// x and `1` otherwise (the original computes this through
/// `countLeadingZeros` of the comparison result).
///
/// # Original
/// - Ghidra: `FUN_8008d820` at `0x8008D820` (116 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008d820_FUN_8008d820.c`
/// - observed: `if ((a[1] < y) || (y < b[1])) return -1;` else
///   `uVar1 = countLeadingZeros((double)((y - b[1]) * (a[0]-b[0])) /
///   (a[1]-b[1]) + b[0] < x); return uVar1 >> 5;`.
///
/// # Arguments
/// - `x`, `y`: query point.
/// - `a`, `b`: addresses of two `[x, y]` float pairs.
///
/// # Returns
/// `0xFFFFFFFF` outside the y span, otherwise `0` or `1`.
///
/// # Safety
/// `a` and `b` must each be readable for eight bytes.
///
/// # Confidence
/// medium - the arithmetic and the leading-zero trick are observed; the
/// segment-side role is inferred from the call sites in `0x8008D8B0`.
pub unsafe fn segment_side_y(x: f64, y: f64, a: usize, b: usize) -> u32 {
    let ay = read_f32(a + 4) as f64;
    let by = read_f32(b + 4) as f64;
    if ay < y || y < by {
        return 0xffff_ffff;
    }
    // observed: ((y - b.y) * (a.x - b.x)) / (a.y - b.y) + b.x, in f32.
    let dy = (y - by) as f32;
    let line = (dy * (read_f32(a) - read_f32(b))) / (read_f32(a + 4) - read_f32(b + 4))
        + read_f32(b);
    let less = (line as f64) < x;
    (less as u32).leading_zeros() >> 5
}

// ---------------------------------------------------------------------------
// 0x8008DC90 - release the registered spatial owner
// ---------------------------------------------------------------------------

/// Releases the registered spatial object and clears its global slot.
///
/// For a non-null `this` the body frees every node of the position-keyed list
/// ([`spatial_list_release`]), clears the single-word slot
/// [`E283_SPATIAL_OWNER_5810`] and then releases `this` through `0x802B9280`
/// when its own delete flag is positive. The return value is `this`.
///
/// The list head is a *different* SDA word ([`G_SPATIAL_LIST`] at `r13 - 0x5808`),
/// so this body clears the owner slot, not the list head; the setter for that
/// owner slot is the 8-byte `0x8008DC80`, which is not part of this batch.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row for `0x8008DC90`.
/// - Extent: `0x8008DC90..0x8008DCEC` (92 bytes, 23 words), ending at the `blr`
///   at `0x8008DCE8`; one zero word fills `0x8008DCEC..0x8008DCF0` and the list
///   release [`spatial_list_release`] follows.
/// - Reach: no `b`/`bl` in the main image and no data word names it; the only
///   reference is `bl 0x8008DC90` at `0x807B7B04` in `d_basesNP`.
/// - Table: none.
/// - Observed: `9421FFF0 stwu r1,-0x10(r1)`; `mflr r0`; `2C030000 cmpi cr0,r3,0`;
///   `stw r0,0x14(r1)`; `mr r31,r4`; `stw r31,0xC(r1)`; `mr r30,r3`;
///   `stw r30,0x8(r1)`; `41820020 bc 12,2` (`beq`, skip everything);
///   `4800003D bl 0x8008DCF0`; `2C1F0000 cmpi`; `38000000 li r0,0` /
///   `900DA7F0 stw r0,-0x5810(r13)`; `4081000C bc 4,1` (`bf cr0.gt`, free only
///   when the flag is `> 0`); `7FC3F378 mr r3,r30` / `4822B5B5 bl 0x802B9280`;
///   `mr r3,r30`; epilogue.
/// - Evidence: `work/wave283/e_dis.txt`.
///
/// # Arguments
/// - `this`: registered spatial object (`r3`).
/// - `delete_flag`: positive performs the final release (`r4`).
///
/// # Returns
/// `this`, unchanged.
///
/// # Side effects
/// Frees the whole spatial list, clears the owner slot and may free `this`.
///
/// # Safety
/// `this` must be a live allocation when `delete_flag > 0`, and the spatial list
/// must satisfy [`spatial_list_release`]'s contract.
///
/// # Confidence
/// high - the guard, the release call, the slot clear and the `> 0` test (via
/// `bc 4,1` on `cr0.gt`) are all literal.
pub unsafe fn fn_8008dc90(this: usize, delete_flag: i32) -> usize {
    if this != 0 {
        spatial_list_release();
        platform::write_u32(E283_SPATIAL_OWNER_5810, 0);
        if delete_flag > 0 {
            platform::call1(DELETE_ONE, this as u32);
        }
    }
    this
}

// ---------------------------------------------------------------------------
// 0x8008DCF0 / 0x8008DDB0
// ---------------------------------------------------------------------------

/// Frees every entry of the position-keyed spatial list.
///
/// Walks the list at [`G_SPATIAL_LIST`] through the `+4` next links, unlinks
/// each node through [`LIST_REMOVE`], and frees the node's self-pointer at
/// `+8` with [`DELETE_ONE`]. The loop never writes the head slot directly;
/// [`LIST_REMOVE`] does that.
///
/// # Original
/// - Ghidra: `FUN_8008dcf0` at `0x8008DCF0` (96 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008dcf0_FUN_8008dcf0.c`
/// - observed: `iVar1 = *(r13-0x5808); while (iVar1 != 0) { iVar2 = [iVar1+8];
///   iVar1 = [iVar1+4]; if (iVar2 != 0) { FUN_80160f60(r13-0x5808,iVar2);
///   FUN_802b9280(iVar2); } }`.
///
/// # Side effects
/// Unlinks and frees every 0x1C-byte node.
///
/// # Safety
/// The list must be well formed and every node's `+8` must be its own
/// allocation (the writer stores the node pointer there).
///
/// # Confidence
/// high - the traversal and both calls are observed; the node layout is
/// confirmed by the writer in [`spatial_entry_store`].
pub unsafe fn spatial_list_release() {
    let mut node = read_u32(G_SPATIAL_LIST) as usize;
    while node != 0 {
        let payload = read_u32(node + 8) as usize;
        node = read_u32(node + 4) as usize;
        if payload != 0 {
            platform::call2(LIST_REMOVE, G_SPATIAL_LIST as u32, payload as u32);
            platform::call1(DELETE_ONE, payload as u32);
        }
    }
}

/// Inserts or updates one position-keyed list entry.
///
/// The list is searched for an entry whose `x` (`+0xC`), `y` (`+0x10`) and key
/// byte (`+0x1A`) all match. A match updates the `u16` value at `+0x18`.
/// Otherwise a 0x1C-byte node is allocated, initialised with null previous/next
/// links and a self-pointer at `+8`, appended through [`LIST_APPEND`], and
/// filled with `x`, `y`, `z`, the key byte and the value.
///
/// # Original
/// - Ghidra: `FUN_8008ddb0` at `0x8008DDB0` (252 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008ddb0_FUN_8008ddb0.c`
/// - observed: the comparison is exact float equality on `param_2[0]`/`[1]`
///   against `+0xC`/`+0x10` plus the byte at `+0x1A`; the insert path calls
///   `FUN_802b9210(0x1c)`, `FUN_80160fe0(r13-0x5808,node)`, then stores
///   `param_2[0..2]` at `+0xC/+0x10/+0x14`, the key at `+0x1A`, and the value
///   at `+0x18`.
///
/// # Arguments
/// - `_unused`: the original's first argument is never read; kept so the call
///   shape matches.
/// - `position`: address of three `f32` values (`x`, `y`, `z`).
/// - `key`: key byte stored at `+0x1A` (only the low byte is used).
/// - `value`: `u16` stored at `+0x18`.
///
/// # Side effects
/// May allocate one 0x1C-byte node and link it into [`G_SPATIAL_LIST`]; always
/// writes the value on a match.
///
/// # Safety
/// `position` must be readable for 12 bytes; the list must be well formed.
///
/// # Confidence
/// high - all fields and the exact-equality comparisons are observed. What the
/// list is used for is unknown; the name describes its layout only.
pub unsafe fn spatial_entry_store(_unused: u32, position: usize, key: u32, value: u16) {
    let mut found = false;
    let mut node = read_u32(G_SPATIAL_LIST) as usize;
    loop {
        if node == 0 {
            break;
        }
        let entry = read_u32(node + 8) as usize;
        node = read_u32(node + 4) as usize;
        if read_f32(position) == read_f32(entry + 0xc)
            && read_f32(position + 4) == read_f32(entry + 0x10)
            && key == read_u8(entry + 0x1a) as u32
        {
            write_u16(entry + 0x18, value);
            found = true;
            break;
        }
    }
    if !found {
        let entry = platform::call1(NEW_DEFAULT, 0x1c) as usize;
        if entry != 0 {
            write_u32(entry, 0);
            write_u32(entry + 4, 0);
            write_u32(entry + 8, entry as u32);
            platform::call2(LIST_APPEND, G_SPATIAL_LIST as u32, entry as u32);
            write_u32(entry + 0xc, read_u32(position));
            write_u32(entry + 0x10, read_u32(position + 4));
            write_u32(entry + 0x14, read_u32(position + 8));
            write_u8(entry + 0x1a, key as u8);
            write_u16(entry + 0x18, value);
        }
    }
}

