/// Tests two collision areas and optionally records the contact masks.
///
/// This is the shape-dispatched overlap test. It rejects self/owner pairs,
/// checks the area's mask words, then calls the handler selected by the two
/// `+0x9E` shape bytes. When a handler reports a hit and `resolve != 0`, the
/// `0x40000` "already resolved" bits gate the `+0x98..+0x9C` mask updates and
/// the optional `+0x3C` callbacks. The result is whether the first area's
/// `+0x98` mask became non-zero.
///
/// # Original
/// - Ghidra: `FUN_8008c6e0` at `0x8008C6E0` (756 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008c6e0_FUN_8008c6e0.c`
/// - observed: the `0x80310DB0` table is indexed by
///   `a.+0x9E * 4 + b.+0x9E`; callbacks at `+0x3C` are called
///   `(b, a)` for the first and `(a, b)` for the second; the default result is
///   `-(u16 b.+0x98) >> 31`.
///
/// # Arguments
/// - `a`: first collision area.
/// - `b`: second collision area.
/// - `resolve`: when `0`, a handler hit immediately returns `1`; when non-zero,
///   the masks/callbacks are updated first.
///
/// # Returns
/// `1` when the areas interacted, `0` otherwise.
///
/// # Side effects
/// May OR bits into `+0x98`/`+0x9A`/`+0x9C` of both areas and invoke both
/// optional callbacks.
///
/// # Safety
/// Both pointers must be live collision areas (fields through `+0xA2`) and the
/// handler selected by the shape bytes must accept `(area, area)`.
///
/// # Confidence
/// medium - the control flow and offsets are observed; the meaning of the mask
/// bits and the shape indices is inferred, and the class is unnamed.
pub unsafe fn collision_area_overlap(a: usize, b: usize, resolve: i32) -> u32 {
    if a == b {
        return 0;
    }
    if read_u32(a + 4) == read_u32(b + 4) {
        return 0;
    }
    if read_u32(a + 4) == read_u32(b + 8) {
        return 0;
    }
    if read_u32(b + 4) == read_u32(a + 8) {
        return 0;
    }
    if (read_u8(b + 0xa1) & 2) != 0 || (read_u8(a + 0xa1) & 2) != 0 {
        return 0;
    }
    if (read_u8(b + 0x9f) & read_u8(a + 0x9f)) == 0 {
        return 0;
    }
    if read_u8(b + 0xa0) != read_u8(a + 0xa0) {
        return 0;
    }
    let a_bit = 1u32.wrapping_shl(read_u32(a + 0x2c) >> 24);
    let a_in_b = read_u32(b + 0x30) & a_bit;
    let b_bit = 1u32.wrapping_shl(read_u32(b + 0x2c) >> 24);
    let b_34 = read_u32(b + 0x34);
    let b_38 = read_u32(b + 0x38);
    let b_callback = read_u32(b + 0x3c);
    let a_34 = read_u32(a + 0x34);
    let a_38 = read_u32(a + 0x38);
    let a_callback = read_u32(a + 0x3c);
    if a_in_b != 0 {
        let b_in_a = read_u32(a + 0x30) & b_bit;
        if b_in_a != 0 {
            let b_16_bit = 1u32.wrapping_shl((read_u32(b + 0x2c) >> 16) & 0xff);
            let a_16_bit = 1u32.wrapping_shl((read_u32(a + 0x2c) >> 16) & 0xff);
            if (a_in_b & 2) == 0 || (a_16_bit & b_34) != 0 {
                if (b_in_a & 2) == 0 || (b_16_bit & a_34) != 0 {
                    let index =
                        read_u8(a + 0x9e) as usize * 4 + read_u8(b + 0x9e) as usize;
                    let handler = read_u32(COLLISION_DISPATCH_TABLE + index * 4) as usize;
                    let hit = platform::call2(handler, b as u32, a as u32);
                    if hit != 0 {
                        if resolve == 0 {
                            return 1;
                        }
                        if (a_38 & 0x40000) == 0 {
                            write_u16(b + 0x98, read_u16(b + 0x98) | a_bit as u16);
                            if (b_34 & a_16_bit) != 0 {
                                write_u16(b + 0x9c, read_u16(b + 0x9c) | (b_34 & a_16_bit) as u16);
                            }
                            if (b_16_bit & a_34) != 0 {
                                write_u16(b + 0x9a, read_u16(b + 0x9a) | (b_16_bit & a_34) as u16);
                            }
                        }
                        if (b_38 & 0x40000) == 0 {
                            write_u16(a + 0x98, read_u16(a + 0x98) | b_bit as u16);
                            if (b_34 & a_16_bit) != 0 {
                                write_u16(a + 0x9a, read_u16(a + 0x9a) | (b_34 & a_16_bit) as u16);
                            }
                            if (b_16_bit & a_34) != 0 {
                                write_u16(a + 0x9c, read_u16(a + 0x9c) | (b_16_bit & a_34) as u16);
                            }
                        }
                        if (a_38 & 0x40000) == 0 && b_callback != 0 {
                            platform::call2(b_callback as usize, b as u32, a as u32);
                        }
                        if (b_38 & 0x40000) == 0 && a_callback != 0 {
                            platform::call2(a_callback as usize, a as u32, b as u32);
                        }
                    }
                } else {
                    return 0;
                }
            } else {
                return 0;
            }
        }
    }
    (0u32.wrapping_sub(read_u16(b + 0x98) as u32)) >> 31
}

/// Tests every collision area against all later areas, resolving contacts.
///
/// In plain English: walk the `r13 - 0x5820` list from the head; for each area
/// walk its `+0x10` forward chain and call [`collision_area_overlap`] with
/// `resolve = 1`, so every unordered pair is tested exactly once and the
/// contact masks/callbacks are updated. The inner chain starts one node later
/// than the outer one, which is why the body compares `area` with `area` only
/// through `i < j`.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row for `0x8008C9E0`.
/// - Extent: `0x8008C9E0..0x8008CA44` (100 bytes, 25 words), ending at the
///   `blr` at `0x8008CA40`; three zero words follow at
///   `0x8008CA44..0x8008CA50` and the next body starts at `0x8008CA50`
///   (`collision_area_resolve`).
/// - Reach: no `b`/`bl` and no data word in the main image; `d_basesNP` calls
///   it from `0x806C317C`.
/// - Observed: `9421FFF0 stwu r1,-0x10(r1)`; `mflr r0`; `stw r0,0x14(r1)`;
///   `stw r31,0xC(r1)`; `stw r30,0x8(r1)`; `lwz r31,-0x5820(r13)`;
///   `b +0x2C` to the outer test; outer body `lwz r30,0x10(r31)`;
///   `b +0x18` to the inner test; inner body `mr r3,r31`; `mr r4,r30`;
///   `li r5,1`; `bl 0x8008C6E0`; `lwz r30,0x10(r30)`;
///   inner test `cmpi cr0,0,r30,0`; `4082FFE8 bc 4,2` (bne = loop);
///   `lwz r31,0x10(r31)`; outer test `cmpi cr0,0,r31,0`;
///   `4082FFD4 bc 4,2` (bne = loop); epilogue; `4E800020 blr`.
/// - Decoder note: `4082FF..` is `bc 4,2` = `bne`; the two loops are the
///   `while (node)` shape, not a `do/while`. `0x8008C6E0` is the shared
///   overlap test [`collision_area_overlap`].
/// - Evidence: `work/wave285/e_dis.txt`, `work/wave285/e_refs.txt`.
///
/// # Arguments
/// None; the head is [`G_COLLISION_AREA_HEAD`].
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One overlap test per unordered pair of registered areas, which may update
/// contact masks and invoke callbacks.
///
/// # Safety
/// The global list and every `+0x10` link must be well formed, and both areas
/// of every pair must satisfy [`collision_area_overlap`]'s requirements.
///
/// # Confidence
/// high - the two loops, the link offset and the `resolve = 1` argument are
/// literal.
pub unsafe fn fn_8008c9e0() {
    let mut area = read_u32(G_COLLISION_AREA_HEAD) as usize;
    while area != 0 {
        let mut other = read_u32(area + 0x10) as usize;
        while other != 0 {
            collision_area_overlap(area, other, 1);
            other = read_u32(other + 0x10) as usize;
        }
        area = read_u32(area + 0x10) as usize;
    }
}

/// Separates two overlapping collision areas along their centre difference.
///
/// # Original
/// - Ghidra: `FUN_8008ca50` at `0x8008CA50` (328 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008ca50_FUN_8008ca50.c`
/// - observed: centre distances are compared with `+0x24`/`+0x28` half
///   extents; the contact points are stored at `+0x90`/`+0x94`; `+0x38 & 1`
///   (on either area) with no type-8 area returns `1` without a push; the
///   push is `(extent - |distance|) * 0.5f`, negated when the distance is
///   negative, and is written to `+0x50`/`+0x70` of both areas using the other
///   area's `+0x2C` byte as the pair index.
///
/// # Arguments
/// - `a`, `b`: collision areas.
/// - `pa`, `pb`: addresses of two `f32` contact points (`[x, y]`).
///
/// # Returns
/// `1` when the areas overlapped and were handled, `0` otherwise.
///
/// # Side effects
/// Writes the contact points and up to four separation accumulators.
///
/// # Safety
/// `pa`/`pb` must be readable for eight bytes; both areas must be writable and
/// `+0x2C` must be in `0..=7` because it indexes the accumulator pairs.
///
/// # Confidence
/// high - all loads, stores and comparisons are explicit; the accumulator role
/// is inferred from the `+0x50`/`+0x70` pattern in `0x8008C2C0`.
pub unsafe fn collision_area_resolve(a: usize, b: usize, pa: usize, pb: usize) -> u32 {
    let dx = read_f32(pa) - read_f32(pb);
    let width = read_f32(a + 0x24) + read_f32(b + 0x24);
    let dy = read_f32(pa + 4) - read_f32(pb + 4);
    let height = read_f32(a + 0x28) + read_f32(b + 0x28);
    if dx.abs() < width && dy.abs() < height {
        write_f32(a + 0x90, read_f32(pa));
        write_f32(a + 0x94, read_f32(pa + 4));
        write_f32(b + 0x90, read_f32(pb));
        write_f32(b + 0x94, read_f32(pb + 4));
        if ((read_u16(a + 0x38) & 1) != 0 || (read_u16(b + 0x38) & 1) != 0)
            && read_u8(a + 0x2c) != 8
            && read_u8(b + 0x2c) != 8
        {
            return 1;
        }
        let half = read_f32(F_COLLISION_HALF);
        let mut push_x = (width - dx.abs()) * half;
        if dx < read_f32(F_COLLISION_ZERO) {
            push_x = -push_x;
        }
        let mut push_y = (height - dy.abs()) * half;
        if dy < read_f32(F_COLLISION_ZERO) {
            push_y = -push_y;
        }
        let a_pair = read_u8(a + 0x2c) as usize;
        let b_pair = read_u8(b + 0x2c) as usize;
        write_f32(a + b_pair * 4 + 0x50, push_x);
        write_f32(a + b_pair * 4 + 0x70, push_y);
        write_f32(b + a_pair * 4 + 0x50, -push_x);
        write_f32(b + a_pair * 4 + 0x70, -push_y);
        return 1;
    }
    0
}

/// `r2 - 0x707C` → `0x8042C004`: `1/256`, the fixed-point angle scale.
const F_COLLISION_D228_INV_256: usize = SDA2_BASE - 0x707C;

/// `r2 - 0x7074` → `0x8042C00C`: `1.0f`, the sign term of the edge distance.
const F_COLLISION_D228_ONE: usize = SDA2_BASE - 0x7074;

/// `r2 - 0x7070` → `0x8042C010`: `2.0f`, doubling the edge-sign index.
const F_COLLISION_D228_TWO: usize = SDA2_BASE - 0x7070;

/// `0x802BE470`: `f64` square root.
const FN_802BE470_D228: usize = 0x802B_E470;

/// `0x801611C0`: `(y, x)` → 16-bit angle.
const FN_801611C0_D228: usize = 0x8016_11C0;

/// `0x80237BD0`: `f64` sine of a 1/256-turn angle.
const FN_80237BD0_D228: usize = 0x8023_7BD0;

/// `0x80237C40`: `f64` cosine of a 1/256-turn angle.
const FN_80237C40_D228: usize = 0x8023_7C40;

/// `0x802BE640`: `f64` length of a two-`f32` vector.
const FN_802BE640_D228: usize = 0x802B_E640;

/// Handles the shape-0/shape-0 pair by resolving at both centres.
///
/// # Original (untabled)
/// - table `0x80310DB0` slot 0: index `a.+0x9E * 4 + b.+0x9E` = 0
/// - measured extent `0x8008CBA0..0x8008CC4C` (172 bytes, prologue to `blr`)
/// - reached only through [`COLLISION_DISPATCH_TABLE`], loaded by
///   [`collision_area_overlap`] (`0x8008C6E0`, `src/game/stage.rs:4301`)
/// - observed: read both centres, then call `0x8008CA50`
///   ([`collision_area_resolve`]) with the two points and return its `r3`
///
/// The point pairs are stored as `(y, x)`, the order the resolve helper and the
/// `+0x24`/`+0x28` half extents are measured with. The `bl` result is not
/// touched before the epilogue, so this body forwards the resolve result even
/// though Ghidra prints it as `void`.
///
/// # Arguments
/// - `a`, `b`: the two collision areas. The overlap dispatcher calls the table
///   entry as `handler(b, a)`.
///
/// # Returns
/// `collision_area_resolve`'s hit flag.
///
/// # Safety
/// Both pointers must be live collision areas.
///
/// # Confidence
/// medium - the calls and point order are observed; the forwarded return is
/// inferred from the unchanged `r3` across the tail call.
pub unsafe fn collision_area_pair_axis_resolve(a: usize, b: usize) -> u32 {
    let a_point = [collision_area_center_y(a), collision_area_center_x(a)];
    let b_point = [collision_area_center_y(b), collision_area_center_x(b)];
    collision_area_resolve(
        a,
        b,
        a_point.as_ptr() as u32 as usize,
        b_point.as_ptr() as u32 as usize,
    )
}

/// Handles the shape-1/shape-1 pair as a radial push.
///
/// # Original (untabled)
/// - table `0x80310DB0` slot 5: index `a.+0x9E * 4 + b.+0x9E` = 5
/// - measured extent `0x8008CDA0..0x8008CF74` (468 bytes, prologue to `blr`)
/// - reached only through [`COLLISION_DISPATCH_TABLE`], loaded by
///   [`collision_area_overlap`] (`0x8008C6E0`, `src/game/stage.rs:4301`)
/// - observed: centre distance against
///   `(a.+0x24 + b.+0x24 + a.+0x28 + b.+0x28) * 0.5f`; rejects when the
///   distance is greater; otherwise the penetration is split along the
///   `0x801611C0` angle through `sin`/`cos` and written to `+0x50`/`+0x70`
///
/// # Arguments
/// - `a`, `b`: the two collision areas. The overlap dispatcher calls the table
///   entry as `handler(b, a)`.
///
/// # Returns
/// `1` on a hit, `0` when the centre distance exceeds the combined radius.
///
/// # Side effects
/// Writes the contact points at `+0x90`/`+0x94` and four push accumulators.
///
/// # Safety
/// Both areas must be live; `+0x2C` must index `0..=7`.
///
/// # Confidence
/// medium - the extent sum, rejection and stores are observed; the angle is
/// treated as a 1/256-turn heading as in the other `0x801611C0` callers.
pub unsafe fn collision_area_pair_ellipse_resolve(a: usize, b: usize) -> u32 {
    let ax = collision_area_center_x(a);
    let ay = collision_area_center_y(a);
    let bx = collision_area_center_x(b);
    let by = collision_area_center_y(b);
    let dx = bx - ax;
    let dy = by - ay;
    let combined = ((read_f32(a + 0x24) + read_f32(b + 0x24))
        + (read_f32(a + 0x28) + read_f32(b + 0x28)))
        * read_f32(F_COLLISION_HALF);
    let distance = call1_f64(FN_802BE470_D228, (dy * dy + dx * dx) as f64);
    if distance > combined as f64 {
        return 0;
    }
    let penetration = combined - distance as f32;
    let angle = call2_f64_i16(FN_801611C0_D228, dx as f64, dy.abs() as f64) as u16 as f32
        * read_f32(F_COLLISION_D228_INV_256);
    let cosine = call1_f64(FN_80237C40_D228, angle as f64) as f32;
    let sine = call1_f64(FN_80237BD0_D228, angle as f64) as f32;
    let push_cos = penetration * cosine;
    let push_sin = -(penetration * sine);
    let b_pair = read_u8(b + 0x2c) as usize;
    let a_pair = read_u8(a + 0x2c) as usize;
    write_f32(a + b_pair * 4 + 0x50, push_cos);
    write_f32(a + b_pair * 4 + 0x70, push_sin);
    write_f32(a + 0x90, ay);
    write_f32(a + 0x94, ax);
    write_f32(b + a_pair * 4 + 0x50, -push_cos);
    write_f32(b + a_pair * 4 + 0x70, -push_sin);
    write_f32(b + 0x90, by);
    write_f32(b + 0x94, bx);
    1
}

/// Handles the shape-0/shape-1 pair as a box against a circle.
///
/// # Original (untabled)
/// - table `0x80310DB0` slots 1 and 4: index `a.+0x9E * 4 + b.+0x9E` =
///   `0*4+1` and `1*4+0`
/// - measured extent `0x8008CF80..0x8008D3D0` (1,104 bytes, prologue to `blr`)
/// - reached only through [`COLLISION_DISPATCH_TABLE`], loaded by
///   [`collision_area_overlap`] (`0x8008C6E0`, `src/game/stage.rs:4301`)
/// - observed: the shape-0 area keeps its own `+0x24`/`+0x28` box extents;
///   the other area's `+0x24` is the radius. Its centre is tested against the
///   box's x span, then its y span, then the corner distance through
///   `0x802BE640`; each branch writes a push along one axis or along the
///   corner vector
///
/// The original indexes the shape-0 push with the shape-0 `+0x2C` byte on both
/// areas in the axis branches, but with each area's own `+0x2C` in the corner
/// branch. That asymmetry is preserved.
///
/// # Arguments
/// - `a`, `b`: the two collision areas. The overlap dispatcher calls the table
///   entry as `handler(b, a)`.
///
/// # Returns
/// `1` on a hit, `0` when the centre is outside every box region.
///
/// # Side effects
/// Writes the contact points at `+0x90`/`+0x94` and up to four push words.
///
/// # Safety
/// Both areas must be live; the `+0x2C` bytes must index `0..=7`.
///
/// # Confidence
/// medium - the extents, padding checks and stores are observed; the mapping of
/// the shape-0 area to an axis-aligned box and the other area to a circle is
/// inferred from the arithmetic.
pub unsafe fn collision_area_pair_box_circle_resolve(a: usize, b: usize) -> u32 {
    let (circle, box_area) = if read_u8(a + 0x9e) == 0 {
        (b, a)
    } else {
        (a, b)
    };
    let circle_x = collision_area_center_x(circle);
    let circle_y = collision_area_center_y(circle);
    let box_x = collision_area_center_x(box_area);
    let box_y = collision_area_center_y(box_area);
    let radius = read_f32(circle + 0x24);
    let below = u32::from(box_y >= circle_y);
    let left = u32::from(box_x >= circle_x);
    let box_y_max = box_y + read_f32(box_area + 0x24);
    let box_y_min = box_y - read_f32(box_area + 0x24);
    let box_x_max = box_x + read_f32(box_area + 0x28);
    let box_x_min = box_x - read_f32(box_area + 0x28);
    let zero = read_f32(F_COLLISION_ZERO);
    let circle_pair = read_u8(circle + 0x2c) as usize;
    let box_pair = read_u8(box_area + 0x2c) as usize;
    if box_x_min < circle_x && circle_x < box_x_max {
        let edge = if below == 0 { box_y_max } else { box_y_min };
        let sign = read_f32(F_COLLISION_D228_ONE)
            - read_f32(F_COLLISION_D228_TWO) * below as f32;
        let distance = sign * (circle_y - edge);
        if distance < radius {
            let push = sign * (radius - distance) * read_f32(F_COLLISION_HALF);
            write_f32(circle + circle_pair * 4 + 0x50, push);
            write_f32(circle + circle_pair * 4 + 0x70, zero);
            write_f32(circle + 0x90, circle_y);
            write_f32(circle + 0x94, circle_x);
            write_f32(box_area + circle_pair * 4 + 0x50, -push);
            write_f32(box_area + circle_pair * 4 + 0x70, zero);
            write_f32(box_area + 0x90, box_y);
            write_f32(box_area + 0x94, box_x);
            return 1;
        }
    }
    if box_y_min < circle_y && circle_y < box_y_max {
        let edge = if left == 0 { box_x_max } else { box_x_min };
        let sign =
            read_f32(F_COLLISION_D228_ONE) - read_f32(F_COLLISION_D228_TWO) * left as f32;
        let distance = sign * (circle_x - edge);
        if distance < radius {
            let push = sign * (radius - distance) * read_f32(F_COLLISION_HALF);
            write_f32(circle + circle_pair * 4 + 0x50, zero);
            write_f32(circle + circle_pair * 4 + 0x70, push);
            write_f32(circle + 0x90, circle_y);
            write_f32(circle + 0x94, circle_x);
            write_f32(box_area + circle_pair * 4 + 0x50, zero);
            write_f32(box_area + circle_pair * 4 + 0x70, -push);
            write_f32(box_area + 0x90, box_y);
            write_f32(box_area + 0x94, box_x);
            return 1;
        }
    }
    let corner_x = if left == 0 { box_x_max } else { box_x_min };
    let corner_y = if below == 0 { box_y_max } else { box_y_min };
    let delta = [circle_y - corner_y, circle_x - corner_x];
    let distance = call1_ptr_f64(FN_802BE640_D228, delta.as_ptr() as u32);
    if distance < radius as f64 {
        let push = (radius - distance as f32) * read_f32(F_COLLISION_HALF);
        let push_y = delta[0] * push;
        let push_x = delta[1] * push;
        write_f32(circle + circle_pair * 4 + 0x50, push_y);
        write_f32(circle + circle_pair * 4 + 0x70, push_x);
        write_f32(circle + 0x90, circle_y);
        write_f32(circle + 0x94, circle_x);
        write_f32(box_area + box_pair * 4 + 0x50, -push_y);
        write_f32(box_area + box_pair * 4 + 0x70, -push_x);
        write_f32(box_area + 0x90, box_y);
        write_f32(box_area + 0x94, box_x);
        return 1;
    }
    0
}

