/// Vtable installed by [`stage_slot_construct`] (`&DAT_80310E30`).
const STAGE_SLOT_VTABLE: usize = 0x8031_0E30;

/// `r2 - 0x7040` → `0x8042C040`: `0.0f`, stored in the two loader slots.
const F_STAGE_SLOT_ZERO: usize = SDA2_BASE - 0x7040;

/// `r13 - 0x5704` → `0x80429F7C`: pointer to the object whose `+0x3B3` byte
/// gates a stage-slot refresh. The object type is unknown.
const G_STAGE_SLOT_OWNER: usize = SDA_BASE - 0x5704;

/// `0x80315B9D`: byte compared with the slot's `+0x19` request id. The name
/// "mode" is inferred; values `0x19..0x1F` and `0x28` skip the refresh.
const STAGE_SLOT_MODE: usize = 0x8031_5B9D;

/// `0x80315B98`: `u32` that suppresses a refresh while non-zero.
const STAGE_SLOT_ACTIVE: usize = 0x8031_5B98;

/// `0x80315B9C`: byte compared with the slot's `+0x18` request id.
const STAGE_SLOT_ID: usize = 0x8031_5B9C;

/// `FUN_8008EDB0(this)`: reset a stage-slot record.
const STAGE_SLOT_RESET: usize = 0x8008_EDB0;

/// `FUN_80060110(value)`: first half of the slot-release test.
const STAGE_SLOT_LOOKUP: usize = 0x8006_0110;

/// `FUN_800B4710(result)`: second half of the slot-release test.
const STAGE_SLOT_LOOKUP_CHECK: usize = 0x800B_4710;

/// Per-element deleting destructor for the four 0x3B0-byte stage objects.
///
/// # Original
/// - Ghidra: `FUN_8008eba0` at `0x8008EBA0` (64 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008eba0_FUN_8008eba0.c`
/// - observed: if `ptr != 0 && size > 0`, call `FUN_802b9280(ptr, size)`;
///   return `ptr`. The call keeps both registers, so the deleting operator is
///   the same one used elsewhere.
///
/// # Arguments
/// - `ptr`: element address.
/// - `size`: element size; `0` leaves the storage alone.
///
/// # Returns
/// `ptr`, as the Metrowerks array-destructor ABI requires.
///
/// # Safety
/// A non-null `ptr` must be the start of an allocation when `size > 0`.
///
/// # Confidence
/// high - the null/size tests and the unchanged return are observed.
pub unsafe fn stage_object_delete(ptr: usize, size: i32) -> usize {
    if ptr != 0 && size > 0 {
        platform::call2(DELETE_ONE, ptr as u32, size as u32);
    }
    ptr
}

/// Constructs a stage-slot record.
///
/// # Original
/// - Ghidra: `FUN_8008ed70` at `0x8008ED70` (60 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008ed70_FUN_8008ed70.c`
/// - observed: install vtable `0x80310E30`, call `FUN_8008edb0(this)`,
///   return `this`.
///
/// # Arguments
/// - `this`: address of 0x34 writable bytes.
///
/// # Returns
/// `this`.
///
/// # Safety
/// `this..this+0x34` must be writable.
///
/// # Confidence
/// high - constructor shape and vtable are observed.
pub unsafe fn stage_slot_construct(this: usize) -> usize {
    write_u32(this, STAGE_SLOT_VTABLE as u32);
    platform::call1(STAGE_SLOT_RESET, this as u32);
    this
}

/// Resets a stage-slot record to its idle state.
///
/// # Original
/// - Ghidra: `FUN_8008edb0` at `0x8008EDB0` (80 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008edb0_FUN_8008edb0.c`
/// - observed: `+0x14 = 0`; four bytes at `+0x18..+0x1B = 0xFF`; `+0x1C = 0`;
///   `+0x08`/`+0x0C` = the `r2-0x7040` word (`0.0f`); `+0x04 = 0xFFFFFFFF`;
///   `+0x20`, `+0x24`, `+0x28`, `+0x2C`, `+0x30` = 4.
///
/// # Arguments
/// - `this`: stage-slot record.
///
/// # Side effects
/// Overwrites every field that the loader state machine reads.
///
/// # Safety
/// `this..this+0x34` must be writable.
///
/// # Confidence
/// high - the stores are listed one by one in the Ghidra body.
pub unsafe fn stage_slot_reset(this: usize) {
    let zero = read_u32(F_STAGE_SLOT_ZERO);
    write_u32(this + 0x14, 0);
    write_u8(this + 0x18, 0xff);
    write_u8(this + 0x19, 0xff);
    write_u8(this + 0x1a, 0xff);
    write_u8(this + 0x1b, 0xff);
    write_u8(this + 0x1c, 0);
    write_u32(this + 8, zero);
    write_u32(this + 0x0c, zero);
    write_u32(this + 4, 0xffff_ffff);
    write_u32(this + 0x2c, 4);
    write_u32(this + 0x30, 4);
    write_u32(this + 0x20, 4);
    write_u32(this + 0x24, 4);
    write_u32(this + 0x28, 4);
}

/// Re-validates a stage slot against the current mode/ids and resets it when
/// it no longer matches.
///
/// # Original
/// - Ghidra: `FUN_8008ee00` at `0x8008EE00` (180 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008ee00_FUN_8008ee00.c`
/// - observed: modes `0x19..0x1F` and `0x28` skip the body; otherwise, when
///   the owner byte `+0x3B3` is zero, `0x80315B98` is zero and
///   `+0x19`/`+0x18` match `0x80315B9D`/`0x80315B9C`, the slot is kept if
///   `FUN_8008eec0` returns non-zero; every other path calls
///   `FUN_8008edb0` (reset).
///
/// # Arguments
/// - `this`: stage-slot record.
///
/// # Side effects
/// May reset the record.
///
/// # Safety
/// `this` must be writable; `*(r13-0x5704)` must point to a readable object.
///
/// # Confidence
/// medium - the comparisons are observed, but the meanings of the mode/id
/// globals and of the owner `+0x3B3` byte are unknown.
pub unsafe fn stage_slot_refresh(this: usize) {
    let mode = read_u8(STAGE_SLOT_MODE);
    if (mode < 0x19 || mode > 0x1f) && mode != 0x28 {
        let owner = read_u32(G_STAGE_SLOT_OWNER) as usize;
        if read_u8(owner + 0x3b3) == 0
            && read_u32(STAGE_SLOT_ACTIVE) == 0
            && read_u8(STAGE_SLOT_MODE) == read_u8(this + 0x19)
            && read_u8(STAGE_SLOT_ID) == read_u8(this + 0x18)
        {
            if stage_slot_pair_check(this) == 0 {
                stage_slot_reset(this);
            }
        } else {
            stage_slot_reset(this);
        }
    }
}

/// Tests the two resource slots of a stage-slot record.
///
/// # Original
/// - Ghidra: `FUN_8008eec0` at `0x8008EEC0` (108 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008eec0_FUN_8008eec0.c`
/// - observed: for the two dwords at `+0x2C` and `+0x30`, a value other than
///   `4` calls `FUN_80060110(value)` and then `FUN_800B4710(result)`; a zero
///   result returns `0`. Both slots surviving return `1`.
///
/// # Arguments
/// - `this`: stage-slot record.
///
/// # Returns
/// `1` when both slots are idle (`4`) or their release test is non-zero.
///
/// # Safety
/// The two opaque callees must accept the values passed in `r3`.
///
/// # Confidence
/// medium - the loop is observed; the forwarded result register and the
/// meaning of the two callees are inferred from the unchanged `r3`.
pub unsafe fn stage_slot_pair_check(this: usize) -> u32 {
    let mut slot = this;
    for _ in 0..2 {
        let state = read_u32(slot + 0x2c);
        if state != 4 {
            let value = platform::call1(STAGE_SLOT_LOOKUP, state);
            if platform::call1(STAGE_SLOT_LOOKUP_CHECK, value) == 0 {
                return 0;
            }
        }
        slot += 4;
    }
    1
}

/// Tests whether a stage-slot record matches a requested slot and id pair.
///
/// # Original
/// - Ghidra: `FUN_8008f000` at `0x8008F000` (104 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008f000_FUN_8008f000.c`
/// - observed: `+0x04 == -1` returns `0`; both ids must differ from `0xFF`;
///   the selected slot `+0x2C + slot*4` must differ from `4`, and `id_y`/
///   `id_x` must equal bytes `+0x19`/`+0x18`.
///
/// # Arguments
/// - `this`: stage-slot record.
/// - `slot`: 0 or 1.
/// - `id_x`: expected byte `+0x18`, or `0xFF` for "any".
/// - `id_y`: expected byte `+0x19`, or `0xFF` for "any".
///
/// # Returns
/// `1` on a match, `0` otherwise.
///
/// # Safety
/// `this` must be a readable stage-slot record.
///
/// # Confidence
/// high - the comparisons and the two early exits are explicit.
pub unsafe fn stage_slot_matches(this: usize, slot: u32, id_x: u32, id_y: u32) -> u32 {
    if read_u32(this + 4) == u32::MAX {
        return 0;
    }
    if id_x != 0xff && id_y != 0xff {
        if read_u32(this + slot as usize * 4 + 0x2c) != 4
            && id_y == read_u8(this + 0x19) as u32
            && id_x == read_u8(this + 0x18) as u32
        {
            return 1;
        }
    }
    0
}
