/// `r2 - 0x7164` → `0x8042BF1C`: `0x45610000` = `3600.0f`.
const F_CAMERA_3600: usize = SDA2_BASE - 0x7164;

/// `r2 - 0x7168` → `0x8042BF18`: `0x451C4000` = `2500.0f`.
const F_CAMERA_2500: usize = SDA2_BASE - 0x7168;

/// `r2 - 0x7160` → `0x8042BF20`: `0x40A00000` = `5.0f`.
const F_CAMERA_5: usize = SDA2_BASE - 0x7160;

/// `r2 - 0x715C` → `0x8042BF24`: `0x00000000` = `0.0f`.
const F_CAMERA_0: usize = SDA2_BASE - 0x715C;

/// `r2 - 0x7158` → `0x8042BF28`: `0xC55AC000` = `-3500.0f`.
const F_CAMERA_M3500: usize = SDA2_BASE - 0x7158;

/// `r13 - 0x56E0` → `0x80429FA0`: pointer to the camera-mode owner tested by
/// [`bg_camera_clip_depth`]. BSS.
const G_CAMERA_MODE_OWNER: usize = SDA_BASE - 0x56E0;

/// `r13 - 0x5870` → `0x80429E10`: pointer to the stage object whose `+0x54`
/// byte selects the near/far plane pair.
const G_STAGE_RENDER_OWNER: usize = SDA_BASE - 0x5870;

/// `0x800CD2C0`: returns the camera mode word.
const CAMERA_MODE: usize = 0x800C_D2C0;

/// Returns one of two clip depths, `2500.0f` or `3600.0f`.
///
/// Mode `0` keeps the near value `2500.0f` unless the owner exists and its
/// `+0x20` byte is `1`, in which case `3600.0f` is used. Any other mode always
/// returns `2500.0f`.
///
/// # Original
/// - Ghidra: `FUN_800872e0` at `0x800872E0` (84 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800872e0_FUN_800872e0.c`
/// - observed: `if (FUN_800cd2c0() == 0) { owner = *(r13-0x56E0); if (owner == 0
///   || *(u8*)(owner+0x20) != 1) return r2-0x7164; return r2-0x7168; }
///   return r2-0x7168;`
///
/// # Returns
/// The clip depth as a single-precision float (Ghidra prints `double` because
/// of the `(double)` narrowing, but the value is a float).
///
/// # Safety
/// Calls into code outside this lane and dereferences a global owner pointer
/// that must be readable when non-null.
///
/// # Confidence
/// high - both branches and the four constant addresses are explicit.
pub unsafe fn bg_camera_clip_depth() -> f32 {
    if call0_ret(CAMERA_MODE) == 0 {
        let owner = read_u32(G_CAMERA_MODE_OWNER) as usize;
        if owner == 0 || read_u8(owner + 0x20) != 1 {
            return read_f32(F_CAMERA_3600);
        }
        return read_f32(F_CAMERA_2500);
    }
    read_f32(F_CAMERA_2500)
}

/// Returns the near plane: `5.0f` when the owner's `+0x54` byte is set,
/// otherwise `0.0f`.
///
/// # Original
/// - Ghidra: `FUN_80087340` at `0x80087340` (32 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80087340_FUN_80087340.c`
/// - observed: `if (*(u8*)(*(r13-0x5870)+0x54) != 0) return r2-0x7160;
///   return r2-0x715C;`
///
/// # Returns
/// The near plane distance.
///
/// # Safety
/// `*(r13-0x5870)` must point at a readable stage object.
///
/// # Confidence
/// high - one byte test and two constants.
pub unsafe fn bg_camera_near_plane() -> f32 {
    let owner = read_u32(G_STAGE_RENDER_OWNER) as usize;
    if read_u8(owner + 0x54) != 0 {
        return read_f32(F_CAMERA_5);
    }
    read_f32(F_CAMERA_0)
}

/// Returns the far plane: `0.0f` when the owner's `+0x54` byte is set,
/// otherwise `-3500.0f`.
///
/// # Original
/// - Ghidra: `FUN_80087360` at `0x80087360` (32 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80087360_FUN_80087360.c`
/// - observed: `if (*(u8*)(*(r13-0x5870)+0x54) != 0) return r2-0x715C;
///   return r2-0x7158;`
///
/// # Returns
/// The far plane distance.
///
/// # Safety
/// `*(r13-0x5870)` must point at a readable stage object.
///
/// # Confidence
/// high - one byte test and two constants.
pub unsafe fn bg_camera_far_plane() -> f32 {
    let owner = read_u32(G_STAGE_RENDER_OWNER) as usize;
    if read_u8(owner + 0x54) != 0 {
        return read_f32(F_CAMERA_0);
    }
    read_f32(F_CAMERA_M3500)
}
// ===========================================================================
// Wave 7: stage animation list (0x80087890..0x80087C30)
// ===========================================================================
//
// This owner object keeps a singly-linked list at `+0x34`. Each 0x18-byte
// entry is `{next, u16 id, u8 frame, u8 last, u8 timer, resource, frame table,
// u8 forward}` and the frame table is a byte array of durations terminated by
// a zero byte after the last frame.

/// Advances every animation entry of the owner's list by one step.
///
/// # Original
/// - Ghidra: `FUN_80087890` at `0x80087890` (64 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80087890_FUN_80087890.c`
/// - observed: `for (e = *(u32**)(owner+0x34); e != 0; e = (u32*)*e)
///   FUN_800879a0(e);`
///
/// # Arguments
/// - `owner`: object whose `+0x34` field is the list head.
///
/// # Side effects
/// Updates the frame index/timer of every entry.
///
/// # Safety
/// The list must be well formed and each element must be a live entry.
///
/// # Confidence
/// high - direct list walk.
pub unsafe fn stage_anim_step_all(owner: usize) {
    let mut entry = read_u32(owner + 0x34) as usize;
    while entry != 0 {
        stage_anim_entry_step(entry);
        entry = read_u32(entry) as usize;
    }
}

/// Initialises one 0x18-byte animation entry.
///
/// Stores the id, clears the frame index and timer, records the resource
/// pointer, the frame-duration table and the direction flag, then scans the
/// table for the last frame (`last` is the index whose following byte is zero).
///
/// # Original
/// - Ghidra: `FUN_80087940` at `0x80087940` (84 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80087940_FUN_80087940.c`
/// - observed: `+0x04 = id; +0x06 = 0; +0x08 = 0; +0x0C = resource;
///   +0x10 = frames; +0x14 = forward; if (frames == 0) return; +0x07 = 0;
///   while (frames[+0x07 + 1] != 0) +++0x07;`
///
/// # Arguments
/// - `entry`: address of 0x18 writable bytes.
/// - `id`: `u16` sequence id.
/// - `resource`: opaque resource handle stored at `+0x0C`.
/// - `frames`: address of the duration table, or 0.
/// - `forward`: `+0x14` direction flag.
///
/// # Side effects
/// Writes six fields of the entry and scans the duration table.
///
/// # Safety
/// `entry` must be writable; `frames` must be NUL-terminated one byte past the
/// last duration when non-zero.
///
/// # Confidence
/// high - every store is listed in the Ghidra body.
pub unsafe fn stage_anim_entry_init(
    entry: usize,
    id: u16,
    resource: u32,
    frames: usize,
    forward: u8,) {
    write_u16(entry + 4, id);
    write_u8(entry + 6, 0);
    write_u8(entry + 8, 0);
    write_u32(entry + 0xc, resource);
    write_u32(entry + 0x10, frames as u32);
    write_u8(entry + 0x14, forward);
    if frames == 0 {
        return;
    }
    write_u8(entry + 7, 0);
    while read_u8(frames + read_u8(entry + 7) as usize + 1) != 0 {
        write_u8(entry + 7, read_u8(entry + 7).wrapping_add(1));
    }
}

/// Advances one animation entry by one tick.
///
/// When the direction byte `+0x14` is zero the frame index increases; otherwise
/// it decreases and wraps to the last frame `+0x07`. The timer `+0x08` resets
/// when it reaches the current frame's duration.
///
/// # Original
/// - Ghidra: `FUN_800879a0` at `0x800879A0` (148 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800879a0_FUN_800879a0.c`
/// - observed: `frames = *(int*)(entry+0x10); if (frames == 0) return;`
///   forward path: `if (frames[index] <= timer) { timer = 0; next = index+1;
///   if (frames[next] == 0) next = 0; index = next; } ++timer;`
///   backward path: `index -= 1`; `if (index < 0) index = +0x07`.
///
/// # Arguments
/// - `entry`: live animation entry.
///
/// # Side effects
/// Writes `+0x06` (frame index) and `+0x08` (timer).
///
/// # Safety
/// The frame table at `+0x10` must be readable for every index the entry can
/// reach.
///
/// # Confidence
/// high - the two direction paths are explicit.
pub unsafe fn stage_anim_entry_step(entry: usize) {
    let frames = read_u32(entry + 0x10) as usize;
    if frames == 0 {
        return;
    }
    let index = read_u8(entry + 6) as u32;
    if read_u8(entry + 0x14) == 0 {
        if read_u8(frames + index as usize) as u32 <= read_u8(entry + 8) as u32 {
            write_u8(entry + 8, 0);
            let mut next = index + 1;
            if read_u8(frames + next as usize) == 0 {
                next = 0;
            }
            write_u8(entry + 6, next as u8);
        }
        write_u8(entry + 8, read_u8(entry + 8).wrapping_add(1));
        return;
    }
    if read_u8(frames + index as usize) as u32 <= read_u8(entry + 8) as u32 {
        let previous = index.wrapping_sub(1);
        write_u8(entry + 8, 0);
        let value = if (previous as i32) < 0 {
            read_u8(entry + 7) as u32
        } else {
            previous
        };
        write_u8(entry + 6, value as u8);
    }
    write_u8(entry + 8, read_u8(entry + 8).wrapping_add(1));
}

/// Frees every animation entry of the owner's list and clears the head.
///
/// # Original
/// - Ghidra: `FUN_80087c30` at `0x80087C30` (104 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80087c30_FUN_80087c30.c`
/// - observed: saves `next = *e`, stores `*e = 0`, calls `0x802B9280(e)`, then
///   sets `*(u32*)(owner+0x34) = 0`.
///
/// # Arguments
/// - `owner`: object whose `+0x34` field is the list head.
///
/// # Side effects
/// Frees each entry and clears the list.
///
/// # Safety
/// Every list element must be a separate heap allocation.
///
/// # Confidence
/// high - the walk, the null store and the delete call are explicit.
pub unsafe fn stage_anim_list_release(owner: usize) {
    let mut entry = read_u32(owner + 0x34) as usize;
    while entry != 0 {
        let next = read_u32(entry) as usize;
        write_u32(entry, 0);
        platform::call1(DELETE_ONE, entry as u32);
        entry = next;
    }
    write_u32(owner + 0x34, 0);
}
// ===========================================================================
// Wave 7: stage helpers (0x80088D90..0x800890E0)
// ===========================================================================

/// `0x800D80D0`: returns a per-frame delta as a float in `f1`.
const FRAME_DELTA: usize = 0x800D_80D0;

/// `0x801693A0(this)`: base-object destructor used by
/// [`stage_aux_object_destroy`].
const AUX_BASE_DESTROY: usize = 0x8016_93A0;

/// vtable installed by [`stage_aux_object_destroy`] (`&DAT_80310A78`).
const AUX_OBJECT_VTABLE: usize = 0x8031_0A78;

/// Adds the per-frame delta to the float at `+0x2C`.
///
/// The original widens both operands to `double`, adds, then narrows back to
/// `float` for the store; the widening is reproduced to keep the rounding the
/// same.
///
/// # Original
/// - Ghidra: `FUN_80088d90` at `0x80088D90` (56 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80088d90_FUN_80088d90.c`
/// - observed: `d = (double)FUN_800d80d0();`
///   `*(float*)(this+0x2C) = (float)((double)*(float*)(this+0x2C) + d);`
///
/// # Arguments
/// - `this`: object whose `+0x2C` float accumulator is advanced.
///
/// # Side effects
/// Writes `this+0x2C`.
///
/// # Safety
/// `this+0x2C` must be readable and writable.
///
/// # Confidence
/// high - the add and the two conversions are explicit; only the callee's
/// meaning is unknown.
pub unsafe fn stage_timer_advance(this: usize) {
    let delta = call0_f32(FRAME_DELTA);
    let sum = read_f32(this + 0x2c) as f64 + delta as f64;
    write_f32(this + 0x2c, sum as f32);
}

/// Destroys an object of the `0x80310A78` class.
///
/// Installs the vtable, runs the base destructor, and frees the storage when
/// `size > 0`. Returns the object address, as the Metrowerks deleting-destructor
/// ABI requires.
///
/// # Original
/// - Ghidra: `FUN_80088fd0` at `0x80088FD0` (96 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80088fd0_FUN_80088fd0.c`
/// - observed: `if (this != 0) { *this = &DAT_80310a78; FUN_801693a0();
///   if (0 < size) FUN_802b9280(this); } return this;`
///
/// # Arguments
/// - `this`: object address, or 0.
/// - `size`: when positive, the object is released through `0x802B9280`.
///
/// # Returns
/// `this` unchanged.
///
/// # Side effects
/// May free the object.
///
/// # Safety
/// A non-null `this` must be a live object of the `0x80310A78` class.
///
/// # Confidence
/// medium - Ghidra prints the delete call with one argument; the `size` word is
/// forwarded because `r4` still holds it.
pub unsafe fn stage_aux_object_destroy(this: usize, size: i32) -> usize {
    if this != 0 {
        write_u32(this, AUX_OBJECT_VTABLE as u32);
        platform::call1(AUX_BASE_DESTROY, this as u32);
        if size > 0 {
            platform::call2(DELETE_ONE, this as u32, size as u32);
        }
    }
    this
}

/// Maps a stage kind id to a small 0..=5 code.
///
/// The stage object is selected by the stage-info stage byte, then the section
/// id byte selects a section-4B entry. Kinds `4`, `5`, `2`, `0x12` and `0x13`
/// map to `1..=5`; every other kind maps to `0`. When the stage object's `+0x2C`
/// field is null the lookup is performed with a null stage object.
///
/// # Original
/// - Ghidra: `FUN_80089030` at `0x80089030` (168 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80089030_FUN_80089030.c`
/// - observed: `stage = *(r13-0x57E8) + *(u8*)(*(r13-0x54B8)+0x120E)*0x3B0;
///   if (*(int*)(stage+0x2C) == 0) stage = 0;
///   kind = FUN_8008e6b0(stage, *(u8*)(*(r13-0x54B8)+0x120F));`
///   then the five comparisons.
///
/// # Returns
/// The stage kind code, `0` for unknown kinds.
///
/// # Safety
/// The stage-object table and stage-info object must be populated.
///
/// # Confidence
/// high - the comparisons are a literal chain; the symbol meanings are inferred
/// from their neighbours.
pub unsafe fn stage_type_code() -> u32 {
    let info = read_u32(G_STAGE_INFO) as usize;
    let mut stage = read_u32(G_STAGE_OBJECTS) as usize
        + read_u8(info + 0x120e) as usize * 0x3b0;
    if read_u32(stage + 0x2c) == 0 {
        stage = 0;
    }
    match section4b_u16_8(stage, read_u8(info + 0x120f) as u32) {
        4 => 1,
        5 => 2,
        2 => 3,
        0x12 => 4,
        0x13 => 5,
        _ => 0,
    }
}
// ===========================================================================
// Wave 7: dDyl stage resource slots (0x8008F110..0x8008F870)
// ===========================================================================
//
// A dDyl slot is a 0x14-byte record: `+0x00` vtable, `+0x04` id (-1 idle),
// `+0x08` loader handle, `+0x0C` loader object, `+0x10` result handle. The
// globals below are the slot allocator, the current loader and its completion
// callback.

/// `r13 - 0x57D8` → `0x80429EA8`: optional completion callback called as
/// `callback(name, loader_object)` after a slot finishes loading.
const G_DDYL_CALLBACK: usize = SDA_BASE - 0x57D8;

/// `r13 - 0x57BC` → `0x80429EC4`: "a dDyl slot is ready" word read by
/// [`ddyl_slot_is_ready`].
const G_DDYL_READY: usize = SDA_BASE - 0x57BC;

/// `r13 - 0x57B8` → `0x80429EC8`: handle of the asynchronous loader started by
/// [`ddyl_slot_finish`]'s counterpart.
const G_DDYL_LOADER_HANDLE: usize = SDA_BASE - 0x57B8;

/// `0x8016B220`: first dDyl global initialiser.
const DDYL_INIT_A: usize = 0x8016_B220;

/// `0x8016B0A0`: second dDyl global initialiser.
const DDYL_INIT_B: usize = 0x8016_B0A0;

/// `0x8016BC10(value)`: dDyl state write; the flag meaning is unknown.
const DDYL_INIT_C: usize = 0x8016_BC10;

/// `0x8016BF70(name, arg2, loader)`: creates a loader and returns its handle.
const DDYL_LOADER_CREATE: usize = 0x8016_BF70;

/// `0x8016B180()`: returns the default loader object.
const DDYL_DEFAULT_LOADER: usize = 0x8016_B180;

/// `0x8016B7E0(handle)`: releases a finished loader handle.
const DDYL_LOADER_RELEASE: usize = 0x8016_B7E0;

/// `0x80160080(this)`: base constructor of the loader wrapper.
const DDYL_BASE_CONSTRUCT: usize = 0x8016_0080;

/// Runs the three dDyl global initialisers, in order.
///
/// # Original
/// - Ghidra: `FUN_8008f110` at `0x8008F110` (48 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008f110_FUN_8008f110.c`
/// - observed: `FUN_8016b220(); FUN_8016b0a0(); FUN_8016bc10(1);`
///
/// # Side effects
/// Initialises the dDyl global state outside this lane.
///
/// # Safety
/// The three callees must be the dDyl initialisers at the shipped addresses.
///
/// # Confidence
/// high - three unconditional calls; only the callee roles are inferred.
pub unsafe fn ddyl_global_init() {
    platform::call0(DDYL_INIT_A);
    platform::call0(DDYL_INIT_B);
    platform::call1(DDYL_INIT_C, 1);
}

/// Constructs a dDyl slot record in its idle state.
///
/// # Original
/// - Ghidra: `FUN_8008f140` at `0x8008F140` (40 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008f140_FUN_8008f140.c`
/// - observed: `*this = &DAT_80310e40; this[1] = -1; this[2] = 0;
///   this[3] = 0; this[4] = 0;`
///
/// # Arguments
/// - `this`: address of 0x14 writable bytes.
///
/// # Returns
/// `this`.
///
/// # Safety
/// `this..this+0x14` must be writable.
///
/// # Confidence
/// high - vtable and four field stores are explicit.
pub unsafe fn ddyl_slot_construct(this: usize) -> usize {
    write_u32(this, DDYL_SLOT_VTABLE as u32);
    write_u32(this + 8, 0);
    write_u32(this + 4, 0xffff_ffff);
    write_u32(this + 0xc, 0);
    write_u32(this + 0x10, 0);
    this
}

/// Deletes a dDyl slot record.
///
/// # Original
/// - Ghidra: `FUN_8008f170` at `0x8008F170` (64 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008f170_FUN_8008f170.c`
/// - observed: `if (this != 0 && 0 < size) FUN_802b9280(); return this;`
///
/// # Arguments
/// - `this`: slot address, or 0.
/// - `size`: when positive, the storage is released.
///
/// # Returns
/// `this`.
///
/// # Safety
/// A non-null `this` must be the start of an allocation when `size > 0`.
///
/// # Confidence
/// medium - the delete call is printed without arguments; `r3`/`r4` still hold
/// `this`/`size`, as in [`stage_object_delete`].
pub unsafe fn ddyl_slot_delete(this: usize, size: i32) -> usize {
    if this != 0 && size > 0 {
        platform::call2(DELETE_ONE, this as u32, size as u32);
    }
    this
}

/// Releases the acquired result of a dDyl slot through its heap object.
///
/// In plain English: when both the heap/loader word at `+0x0C` and the result
/// word at `+0x10` are non-zero, call virtual slot `+0x18` of the `+0x0C`
/// object with that object as receiver, then clear the result and mark the slot
/// unloaded by writing `-1` at `+0x04`. This is the release slot (`+0x0C`) of
/// [`DDYL_SLOT_VTABLE`] (`0x80310E40`), the twin of
/// [`ddyl_slot_delete`] at `+0x08`.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row for `0x8008F380`.
/// - Extent: `0x8008F380..0x8008F3E4` (100 bytes, 25 words), ending at the
///   `blr` at `0x8008F3E0`; three zero words follow at
///   `0x8008F3E4..0x8008F3F0` and the next body starts at `0x8008F3F0`.
/// - Reach: no `b`/`bl` in the executable segments. The one data word naming
///   it, `0x80310E4C`, is slot `+0x0C` of [`DDYL_SLOT_VTABLE`]; the slot at
///   `0x80310E48` is [`ddyl_slot_delete`]. Not inside a pointer-run interior.
/// - Observed: `9421FFF0 stwu r1,-0x10(r1)`; `mflr r0`; `stw r0,0x14(r1)`;
///   `stw r31,0xC(r1)`; `mr r31,r3`; `lwz r0,0xC(r3)`;
///   `cmpi cr0,0,r0,0`; `41820034 bc 12,2,+0x34` (beq to the return);
///   `lwz r4,0x10(r3)`; `cmpi cr0,0,r4,0`; `41820028 bc 12,2` (beq);
///   `mr r3,r0`; `lwz r12,0(r3)`; `lwz r12,0x18(r12)`; `mtspr CTR,r12`;
///   `4E800421 bcctrl 20,0` (call); `li r3,0`; `li r0,-1`;
///   `stw r3,0x10(r31)`; `stw r0,0x4(r31)`; epilogue; `4E800020 blr`.
/// - Decoder note: the receiver for the virtual call is the `+0x0C` object
///   itself, not `this + 0x0C`; `4E800421` is a call that falls through.
/// - Evidence: `work/wave285/e_dis.txt`, `work/wave285/e_refs.txt`.
///
/// # Arguments
/// - `this`: dDyl slot record previously filled by [`ddyl_slot_acquire`].
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One virtual release call on the `+0x0C` object and two slot stores.
///
/// # Safety
/// A non-null `+0x0C` object with a non-null `+0x10` result must have a vtable
/// whose `+0x18` slot is callable.
///
/// # Confidence
/// high - both guards, the receiver selection and the two stores are literal;
/// the vtable link is the slot `0x80310E4C` data word.
pub unsafe fn fn_8008f380(this: usize) {
    let holder = read_u32(this + 0xC) as usize;
    if holder == 0 {
        return;
    }
    if read_u32(this + 0x10) == 0 {
        return;
    }
    let vtable = read_u32(holder) as usize;
    platform::call1(read_u32(vtable + 0x18) as usize, holder as u32);
    write_u32(this + 0x10, 0);
    write_u32(this + 4, 0xFFFF_FFFF);
}

/// Acquires the result handle of a dDyl slot, starting the load if needed.
///
/// When `+0x10` already holds a result it is returned unchanged. Otherwise the
/// slot creates a loader handle on first use (`+0x08`), waits for it to
/// complete (`loader+8 != 0`), moves the loader's `+0x10`/`+0x14` words into
/// the slot, releases the loader and calls the global callback.
///
/// # Original
/// - Ghidra: `FUN_8008f1b0` at `0x8008F1B0` (248 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008f1b0_FUN_8008f1b0.c`
/// - observed: `value = *(int*)(this+0x10); if (value == 0) { ... }`;
///   `if (*(int*)(this+8) == 0) { *(this+4) = -1; if (heap == 0)
///   heap = FUN_8016b180(); *(this+0xC) = heap;
///   *(this+8) = FUN_8016bf70(name, arg3, heap); }`
///   `handle = *(int*)(this+8); if (handle == 0 || *(u8*)(handle+8) == 0)
///   value = 0; else { ... move fields ... call callback(name, *(this+0xC)); }`
///
/// # Arguments
/// - `this`: dDyl slot record.
/// - `name`: name/id forwarded to the loader.
/// - `arg3`: second loader argument.
/// - `heap`: loader heap; 0 means the default loader from `0x8016B180`.
///
/// # Returns
/// The acquired result handle, or 0 while the load is still pending.
///
/// # Side effects
/// Creates and releases a loader handle and may invoke the global callback.
///
/// # Safety
/// The slot record and any non-null loader handle must be readable/writable.
///
/// # Confidence
/// medium - the field moves are observed; the callback's two arguments are
/// inferred from the unchanged `r4`/`r5`.
pub unsafe fn ddyl_slot_acquire(this: usize, name: u32, arg3: u32, heap: u32) -> u32 {
    let mut value = read_u32(this + 0x10);
    if value == 0 {
        if read_u32(this + 8) == 0 {
            write_u32(this + 4, 0xffff_ffff);
            let heap = if heap == 0 {
                call0_ret(DDYL_DEFAULT_LOADER)
            } else {
                heap
            };
            write_u32(this + 0xc, heap);
            let handle = platform::call3(DDYL_LOADER_CREATE, name, arg3, heap);
            write_u32(this + 8, handle);
        }
        let handle = read_u32(this + 8) as usize;
        if handle == 0 || read_u8(handle + 8) == 0 {
            value = 0;
        } else {
            write_u32(this + 0x10, read_u32(handle + 0x10));
            write_u32(this + 4, read_u32(handle + 0x14));
            write_u32(handle + 0x10, 0);
            platform::call1(DDYL_LOADER_RELEASE, read_u32(this + 8));
            write_u32(this + 8, 0);
            let callback = read_u32(G_DDYL_CALLBACK);
            if callback != 0 {
                platform::call2(callback as usize, name, read_u32(this + 0xc));
            }
            value = read_u32(this + 0x10);
        }
    }
    value
}

/// Polls a dDyl slot: releases a finished load and rewinds the record to idle.
///
/// # Original
/// - Ghidra: `FUN_8008f2b0` at `0x8008F2B0` (84 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008f2b0_FUN_8008f2b0.c`
/// - observed: `ok = FUN_8008f3f0(this); if (ok != 0) { *(this+0x10) = 0;
///   *(this+0xC) = 0; *(this+4) = -1; } return ok != 0;`
///
/// # Arguments
/// - `this`: dDyl slot record.
///
/// # Returns
/// `1` when the release test succeeded, `0` otherwise.
///
/// # Side effects
/// May reset three slot fields.
///
/// # Safety
/// `this` must be a live slot record.
///
/// # Confidence
/// high - the three stores and the boolean return are explicit.
pub unsafe fn ddyl_slot_poll(this: usize) -> u32 {
    let ok = ddyl_slot_release_if_loaded(this);
    if ok != 0 {
        write_u32(this + 0x10, 0);
        write_u32(this + 0xc, 0);
        write_u32(this + 4, 0xffff_ffff);
    }
    if ok != 0 {
        1
    } else {
        0
    }
}

/// Polls a dDyl slot and runs the vtable slot `+0xC` when the load finished.
///
/// # Original
/// - Ghidra: `FUN_8008f310` at `0x8008F310` (104 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008f310_FUN_8008f310.c`
/// - observed: `ok = FUN_8008f3f0(this); if (ok != 0) {
///   (**(code**)(*this + 0xC))(this); *(this+0x10) = 0; *(this+0xC) = 0;
///   *(this+4) = -1; } return ok != 0;`
///
/// # Arguments
/// - `this`: dDyl slot record.
///
/// # Returns
/// `1` when the release test succeeded, `0` otherwise.
///
/// # Side effects
/// Invokes the virtual method and resets three fields.
///
/// # Safety
/// The vtable at `this+0` and its `+0xC` entry must be valid.
///
/// # Confidence
/// high - the virtual call and the stores are explicit.
pub unsafe fn ddyl_slot_poll_release(this: usize) -> u32 {
    let ok = ddyl_slot_release_if_loaded(this);
    if ok != 0 {
        let vtable = read_u32(this) as usize;
        let slot = read_u32(vtable + 0xc) as usize;
        platform::call1(slot, this as u32);
        write_u32(this + 0x10, 0);
        write_u32(this + 0xc, 0);
        write_u32(this + 4, 0xffff_ffff);
    }
    if ok != 0 {
        1
    } else {
        0
    }
}

/// Releases the loader of a slot whose `+0x08` handle is set.
///
/// # Original
/// - Ghidra: `FUN_8008f3f0` at `0x8008F3F0` (108 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008f3f0_FUN_8008f3f0.c`
/// - observed: `if (*(int*)(this+8) != 0) { ok = FUN_8008f1b0(this,0,0,0);
///   if (ok == 0) return 0; (**(code**)(*this+0xC))(this); } return 1;`
///
/// # Arguments
/// - `this`: dDyl slot record.
///
/// # Returns
/// `0` when the acquire step failed, `1` otherwise.
///
/// # Side effects
/// Waits for the load, then invokes the virtual method.
///
/// # Safety
/// The slot record and its vtable must be valid.
///
/// # Confidence
/// high - the guard, the acquire call and the virtual call are explicit.
pub unsafe fn ddyl_slot_release_if_loaded(this: usize) -> u32 {
    if read_u32(this + 8) != 0 {
        let value = ddyl_slot_acquire(this, 0, 0, 0);
        if value == 0 {
            return 0;
        }
        let vtable = read_u32(this) as usize;
        let slot = read_u32(vtable + 0xc) as usize;
        platform::call1(slot, this as u32);
    }
    1
}

/// Returns `1` when the global dDyl-ready word is non-zero.
///
/// The original computes the value with the branch-free
/// `(-word | word) >> 31` idiom, which is `word != 0`.
///
/// # Original
/// - Ghidra: `FUN_8008f620` at `0x8008F620` (20 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008f620_FUN_8008f620.c`
/// - observed: `return (-*(u32*)(r13-0x57BC) | *(u32*)(r13-0x57BC)) >> 31;`
///
/// # Returns
/// `1` when `*(r13-0x57BC)` is non-zero, `0` otherwise.
///
/// # Safety
/// The global word must be readable (it is BSS, so always readable).
///
/// # Confidence
/// high - the idiom is fully visible.
pub unsafe fn ddyl_slot_is_ready() -> u32 {
    let word = read_u32(G_DDYL_READY);
    (word.wrapping_neg() | word) >> 31
}

/// Finishes the global dDyl loader: `1` when idle, `0` while pending.
///
/// Returns `1` when no handle is recorded. When the handle exists but its
/// `+0x08` completion byte is zero the load is still pending and `0` is
/// returned; otherwise the handle is released, the global cleared and `1`
/// returned.
///
/// # Original
/// - Ghidra: `FUN_8008f7b0` at `0x8008F7B0` (84 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008f7b0_FUN_8008f7b0.c`
/// - observed: `handle = *(int*)(r13-0x57B8); if (handle == 0) return 1;
///   if (*(u8*)(handle+8) == 0) return 0; FUN_8016b7e0();
///   *(r13-0x57B8) = 0; return 1;`
///
/// # Returns
/// `1` when the global loader is idle or was just released, `0` while pending.
///
/// # Side effects
/// Releases the loader handle and clears the global.
///
/// # Safety
/// A non-null handle must be a live loader handle.
///
/// # Confidence
/// high - both guards and the release path are explicit; Ghidra prints the
/// release call without arguments, and `r3` still holds the handle.
pub unsafe fn ddyl_slot_finish() -> u32 {
    let handle = read_u32(G_DDYL_LOADER_HANDLE);
    if handle == 0 {
        return 1;
    }
    if read_u8(handle as usize + 8) == 0 {
        return 0;
    }
    platform::call1(DDYL_LOADER_RELEASE, handle);
    write_u32(G_DDYL_LOADER_HANDLE, 0);
    1
}

/// Constructs the loader wrapper and installs its vtable at `+0xC`.
///
/// # Original
/// - Ghidra: `FUN_8008f870` at `0x8008F870` (60 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008f870_FUN_8008f870.c`
/// - observed: `FUN_80160080(); *(u32*)(this+0xC) = &DAT_80310e98;
///   return this;`
///
/// # Arguments
/// - `this`: address of the wrapper.
///
/// # Returns
/// `this`.
///
/// # Safety
/// `this` must be a live, writable wrapper object and the base constructor must
/// accept it in `r3`.
///
/// # Confidence
/// high - the call and the vtable store are explicit; Ghidra prints the base
/// constructor without arguments because `r3` is unchanged.
pub unsafe fn ddyl_loader_construct(this: usize) -> usize {
    platform::call1(DDYL_BASE_CONSTRUCT, this as u32);
    write_u32(this + 0xc, DDYL_LOADER_VTABLE as u32);
    this
}
