/// - Ghidra: `FUN_80089150` at `0x80089150` (188 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80089150_FUN_80089150.c`
/// - observed: `*param_1 = &DAT_80310b70; FUN_80069020(param_1+1);` then the
///   zero stores at dword indices `8..0x25`; `*(r13-0x585c) = param_1`.
///
/// # Arguments
/// - `this`: address of the environment block.
///
/// # Returns
/// `this`.
///
/// # Side effects
/// Installs a vtable, constructs the `+0x04` subobject, clears 0x94 bytes of
/// slots and writes the global owner.
///
/// # Safety
/// `this..this+0x98` must be writable.
///
/// # Confidence
/// high - every cleared index is listed in the evidence.
pub unsafe fn stage_env_construct(this: usize) -> usize {
    write_u32(this, STAGE_ENV_VTABLE as u32);
    platform::call1(CAMERA_BASE_CONSTRUCT, (this + 4) as u32);
    for index in [8usize, 9, 10, 0xd, 0xe, 0xf, 0x20, 0x21, 0x22, 0x24] {
        write_u32(this + index * 4, 0);
    }
    write_u8(this + 0x25 * 4, 0);
    for index in [0xbusize, 0xc, 0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f] {
        write_u32(this + index * 4, 0);
    }
    write_u32(G_STAGE_ENV, this as u32);
    this
}

// ---------------------------------------------------------------------------
// 0x80089210
// ---------------------------------------------------------------------------

/// Destroys the stage environment object.
///
/// Reinstalls the vtable, releases the two child slots at `+0x2C`/`+0x30` when
/// the object's heap id changed, frees the `+0x04` subobject, clears the four
/// tail words and the global owner, and finally frees the block when `size > 0`.
///
/// # Original
/// - Ghidra: `FUN_80089210` at `0x80089210` (224 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80089210_FUN_80089210.c`
/// - observed: `iVar1 = FUN_8016a5d0(); if (param_1[6] != iVar1) { loop twice:
///   virtual +0x10; FUN_8016a880(param_1+1); }` then `param_1[0x1C..0x1F]=0`
///   and `FUN_80069060(param_1+1, -1)`.
///
/// # Arguments
/// - `this`: environment address, or 0.
/// - `size`: when positive, the block is released.
///
/// # Returns
/// `this`.
///
/// # Side effects
/// May release two children, the `+0x04` subobject and the block itself.
///
/// # Safety
/// A non-null `this` must be a live environment object.
///
/// # Confidence
/// high - the guard, the two-child loop and the three cleanup calls are
/// explicit.
pub unsafe fn stage_env_destroy(this: usize, size: i32) -> usize {
    if this != 0 {
        write_u32(this, STAGE_ENV_VTABLE as u32);
        if read_u32(this + 0x18) != call0_ret(CAMERA_CURRENT_QUERY) {
            for index in 0..2usize {
                let child = read_u32(this + 0x2c + index * 4) as usize;
                if child != 0 {
                    call_vtable_slot1(child, 0x10);
                }
            }
            platform::call1(CAMERA_CHILD_RELEASE, (this + 4) as u32);
        }
        write_u32(this + 0x70, 0);
        write_u32(this + 0x74, 0);
        write_u32(this + 0x78, 0);
        write_u32(this + 0x7c, 0);
        write_u32(G_STAGE_ENV, 0);
        platform::call2(CAMERA_BASE_DESTROY, (this + 4) as u32, 0xffff_ffff);
        if size > 0 {
            platform::call2(DELETE_ONE, this as u32, size as u32);
        }
    }
    this
}

