/// `base+8 + index*3`, which is one triple per index.
const COIN_RESOURCE_TRIPLES: usize = 0x802F_00D0;

/// `r13 - 0x7C70` → `0x80427A10`: the six-byte prefix `"Wm_01_"` used in
/// game mode 2. The bytes are visible in the shipped image.
const DDYL_PATH_PREFIX_2: usize = SDA_BASE - 0x7C70;

/// `r13 - 0x7C68` → `0x80427A18`: the six-byte prefix `"Wm_02_"` used in
/// game mode 3.
const DDYL_PATH_PREFIX_3: usize = SDA_BASE - 0x7C68;

/// `r13 - 0x7C60` → `0x80427A20`: the six-byte prefix `"Wm_03_"` used in
/// game mode 4.
const DDYL_PATH_PREFIX_4: usize = SDA_BASE - 0x7C60;

/// `r13 - 0x7C48` → `0x80427A38`: "current dDyl path id" global, set to the
/// argument while a loader call runs and restored to `-1` afterwards.
const G_DDYL_CURRENT_PATH: usize = SDA_BASE - 0x7C48;

/// `0x802E19F8`: padded string copy (`strncpy` shape).
const STRNCPY_PAD: usize = 0x802E_19F8;

/// `0x80004364`: byte copy (`memmove` shape).
const MEMMOVE_BYTES: usize = 0x8000_4364;

/// `0x8005FFB0`: returns the current game/scene mode (`2`, `3` or `4` select a
/// path prefix). Role inferred from the three comparisons.
const GAME_MODE_CODE: usize = 0x8005_FFB0;

/// `0x8016C890`: dDyl loader entry that consumes a path and four options.
const DDYL_LOAD_PATH: usize = 0x8016_C890;

/// `0x80160110`: base release used by the dDyl path-record delete thunk.
const DDYL_PATH_RELEASE: usize = 0x8016_0110;

/// `0x800DF180`: archive/subre source loader used by the coin model.
const ARC_LOAD_SUB_18: usize = 0x800D_F180;

/// `0x80239E30`: create a model from a loaded resource and a model name.
const J3D_MODEL_CREATE_18: usize = 0x8023_9E30;

/// `0x8016A3A0`: bind an animation/model handle to a J3D object.
const J3D_SETUP_18: usize = 0x8016_A3A0;

/// `0x80064BF0`: finish a J3D model setup.
const J3D_FINISH_18: usize = 0x8006_4BF0;

/// `0x801C6BA0`: allocate a GX texture object (`width, height, format, ...`).
const GX_TEX_ALLOC: usize = 0x801C_6BA0;

/// `0x802B9260`: allocate the texture's 0x20-byte descriptor block.
const GX_TEX_DESCRIPTOR_ALLOC: usize = 0x802B_9260;

/// `0x8000EFC0`: initialise a GX texture object from its descriptor.
const GX_TEX_INIT: usize = 0x8000_EFC0;

/// Reads a big-endian IEEE-754 double from `addr`.
///
/// The Ghidra output prints several paired-single loads as `double`; this
/// helper preserves the eight bytes the original read.
///
/// # Safety
/// `addr` must be a readable, 4-byte aligned address.
unsafe fn read_f64(addr: usize) -> f64 {
    let hi = read_u32(addr) as u64;
    let lo = read_u32(addr + 4) as u64;
    f64::from_bits((hi << 32) | lo)
}

/// Calls a PowerPC function with six `f32` arguments (`f1..f6`).
///
/// # Safety
/// `addr` must be a PowerPC function with this floating-point ABI.
unsafe fn call6_f32(addr: usize, a: f32, b: f32, c: f32, d: f32, e: f32, f: f32) {
    let func: extern "C" fn(f32, f32, f32, f32, f32, f32) = core::mem::transmute(addr);
    func(a, b, c, d, e, f);
}

/// Calls a PowerPC function with four `f32` arguments followed by two words.
///
/// Used by the GX colour call at `0x801C8920`, which takes
/// `(f32, f32, f32, f32, selector, &word)`.
///
/// # Safety
/// `addr` must be a PowerPC function with this mixed ABI.
unsafe fn call4_f32_2(addr: usize, a: f32, b: f32, c: f32, d: f32, e: u32, f: u32) {
    let func: extern "C" fn(f32, f32, f32, f32, u32, u32) = core::mem::transmute(addr);
    func(a, b, c, d, e, f);
}

/// Advances every BG scroll layer of a scene to the current camera position.
///
/// The scene's first word points at the camera owner. The three floats at
/// owner `+0xAC..+0xB4` are the camera x/y/z; the three words at scene
/// `+0x94..+0x9C` are the layer origins (stored as integers) and `+0xB0`/
/// `+0xB4` are the horizontal/vertical accumulators. After the per-layer
/// update the accumulators are cleared.
///
/// # Original
/// - Ghidra: `FUN_80080170` at `0x80080170` (288 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80080170_FUN_80080170.c`
/// - observed: a `+0x6C`-linked list at `+0x0C` and two four-entry arrays at
///   `+0x18` and `+0x28` are passed to `0x8007FFA0` with selector `0`, `1`
///   and `2`; the function then stores the `r2-0x71F8` zero at `+0xB0`/`+0xB4`.
///
/// # Arguments
/// - `scene`: BG scene/manager base whose `+0x00` word points at the camera
///   owner.
///
/// # Side effects
/// Calls `0x8007FFA0` once per active layer; writes the two accumulators.
///
/// # Safety
/// `scene` and `[scene]` must be readable and the layer objects writable.
///
/// # Confidence
/// medium - the field arithmetic is observed; the camera/layer naming is
/// inferred from the matching collision-area edge accessors.
pub unsafe fn bg_scene_follow_layers(scene: usize) {
    let owner = read_u32(scene) as usize;
    let origin_x = read_u32(scene + 0x94) as i32 as f32;
    let origin_y = read_u32(scene + 0x98) as i32 as f32;
    let origin_z = read_u32(scene + 0x9c) as i32 as f32;
    let accum_x = read_u32(scene + 0xb0) as i32 as f32;
    let accum_y = read_u32(scene + 0xb4) as i32 as f32;
    let mut position = [0f32;
 3];
    position[0] = (read_f32(owner + 0xac) - origin_x) + accum_x;
    position[1] = (read_f32(owner + 0xb0) - origin_y) + accum_y;
    position[2] = read_f32(owner + 0xb4) - origin_z;
    // observed: the linked list starts at scene+0x0C and follows +0x6C.
    let mut layer = read_u32(scene + 0x0c) as usize;
    while layer != 0 {
        platform::call4(
            0x8007_FFA0,
            scene as u32,
            layer as u32,
            position.as_ptr() as u32,
            0,
        );
        layer = read_u32(layer + 0x6c) as usize;
    }
    for index in 0..4usize {
        let entry = read_u32(scene + 0x18 + index * 4) as usize;
        if entry != 0 {
            platform::call4(
                0x8007_FFA0,
                scene as u32,
                entry as u32,
                position.as_ptr() as u32,
                1,
            );
        }
    }
    for index in 0..4usize {
        let entry = read_u32(scene + 0x28 + index * 4) as usize;
        if entry != 0 {
            platform::call4(
                0x8007_FFA0,
                scene as u32,
                entry as u32,
                position.as_ptr() as u32,
                2,
            );
        }
    }
    // observed: the source is the 0.0f small-data float read as a word.
    let zero = read_u32(F_ZERO_WAVE18);
    write_u32(scene + 0xb0, zero);
    write_u32(scene + 0xb4, zero);
}

/// Adds a handle to the first free slot of the scene's `+0x18` array.
///
/// # Original
/// - Ghidra: `FUN_800803f0` at `0x800803F0` (156 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800803f0_FUN_800803f0.c`
/// - observed: four unrolled equality tests at `+0x18..+0x24`, then a
///   four-iteration scan that stores at the first zero slot.
///
/// # Arguments
/// - `scene`: BG scene base.
/// - `handle`: word to insert.
///
/// # Returns
/// `1` when the handle was already present or a free slot was filled, `0` when
/// all four slots hold another value.
///
/// # Safety
/// `scene..scene+0x38` must be readable/writable.
///
/// # Confidence
/// high - the two loops and every comparison are explicit.
pub unsafe fn bg_scene_layer_add_a(scene: usize, handle: u32) -> u32 {
    for index in 0..4usize {
        if read_u32(scene + 0x18 + index * 4) == handle {
            return 1;
        }
    }
    for index in 0..4usize {
        let slot = scene + 0x18 + index * 4;
        if read_u32(slot) == 0 {
            write_u32(slot, handle);
            return 1;
        }
    }
    0
}

/// Adds a handle to the first free slot of the scene's `+0x28` array.
///
/// # Original
/// - Ghidra: `FUN_80080530` at `0x80080530` (156 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80080530_FUN_80080530.c`
/// - observed: identical to `0x800803F0` but with the base `+0x28`.
///
/// # Arguments
/// - `scene`: BG scene base.
/// - `handle`: word to insert.
///
/// # Returns
/// `1` when inserted or already present, `0` when the array is full.
///
/// # Safety
/// `scene..scene+0x48` must be readable/writable.
///
/// # Confidence
/// high - the body is a literal copy of the `+0x18` variant.
pub unsafe fn bg_scene_layer_add_b(scene: usize, handle: u32) -> u32 {
    for index in 0..4usize {
        if read_u32(scene + 0x28 + index * 4) == handle {
            return 1;
        }
    }
    for index in 0..4usize {
        let slot = scene + 0x28 + index * 4;
        if read_u32(slot) == 0 {
            write_u32(slot, handle);
            return 1;
        }
    }
    0
}

/// Clears the BG scene's per-layer bookkeeping.
///
/// The eleven words `+0x0C..+0x34` are zeroed in the order printed by Ghidra,
/// the low bit of `+0xD8` is kept, and either the `+0x3C` pointer or the
/// `+0xC4` `u16` is cleared depending on whether `+0x3C` was set.
///
/// # Original
/// - Ghidra: `FUN_800805d0` at `0x800805D0` (88 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800805d0_FUN_800805d0.c`
/// - observed: the store order below; `+0xD8 &= 1`; `if (+0x3C != 0) {
///   +0x3C = 0 } else { +0xC4 = 0 }`.
///
/// # Arguments
/// - `scene`: BG scene base.
///
/// # Side effects
/// Clears the layer handles and one of the two camera/tile words.
///
/// # Safety
/// `scene..scene+0xD9` must be readable/writable.
///
/// # Confidence
/// high - every store and the branch are visible.
pub unsafe fn bg_scene_layer_clear(scene: usize) {
    write_u32(scene + 0x0c, 0);
    write_u32(scene + 0x10, 0);
    write_u32(scene + 0x14, 0);
    write_u32(scene + 0x18, 0);
    write_u32(scene + 0x28, 0);
    write_u32(scene + 0x1c, 0);
    write_u32(scene + 0x2c, 0);
    write_u32(scene + 0x20, 0);
    write_u32(scene + 0x30, 0);
    write_u32(scene + 0x24, 0);
    write_u32(scene + 0x34, 0);
    write_u32(scene + 0xd8, read_u32(scene + 0xd8) & 1);
    if read_u32(scene + 0x3c) != 0 {
        write_u32(scene + 0x3c, 0);
        return;
    }
    write_u16(scene + 0xc4, 0);
}

/// Tests whether a `bias`-relative span covers `[lo, hi]`.
///
/// The span is selected by bits `12..15` of the `u16` reachable through the
/// owner's `+0xBC` pointer. Two `.rodata` tables at `0x802EF8C0`/`0x802EF8D0`
/// turn that nibble into an object index; the two half-extents live at
/// `owner + index*8 + 0x60`.
///
/// # Original
/// - Ghidra: `FUN_80080880` at `0x80080880` (128 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80080880_FUN_80080880.c`
/// - observed: `if (hi < lo) swap; idx = ((int)**(short**)(owner+0xBC) >> 12)
///   & 0xC; if (bias + tableA[idx] < lo) return 0; return
///   countLeadingZeros(hi < bias + tableB[idx]) >> 5;`
///
/// # Arguments
/// - `lo`, `hi`: span endpoints (order is normalised like the original).
/// - `bias`: offset added to both stored half-extents.
/// - `owner`: object whose `+0xBC` word points at the `u16` selector and whose
///   `+0x60` array holds the extents.
///
/// # Returns
/// `1` when both endpoints are inside the selected span, `0` otherwise.
///
/// # Safety
/// The selector pointer and the `+0x60` array must be readable.
///
/// # Confidence
/// medium - the arithmetic and table accesses are observed; the table units
/// and the field roles are inferred.
pub unsafe fn bg_scene_span(lo: f32, hi: f32, bias: f32, owner: usize) -> u32 {
    let (lo, hi) = if hi < lo { (hi, lo) } else { (lo, hi) };
    let selector = read_u16(read_u32(owner + 0xbc) as usize) as i32;
    let index = ((selector as u32 >> 12) & 0xc) as usize;
    let low_index = read_u32(STAGE_SPAN_TABLE_A + index) as usize;
    if bias + read_f32(owner + low_index * 8 + 0x60) < lo {
        return 0;
    }
    let high_index = read_u32(STAGE_SPAN_TABLE_B + index) as usize;
    (hi < bias + read_f32(owner + high_index * 8 + 0x60)) as u32
}

/// Returns `1` when a layer should be processed without asking its vtable.
///
/// # Original
/// - Ghidra: `FUN_80080d00` at `0x80080D00` (52 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80080d00_FUN_80080d00.c`
/// - observed: `if (this[0x34] & 0x80000) return 1; if (this[0x13] == 0)
///   return 0; return this[0x13](*this);` - the indirect jump has no recovered
///   prototype, so the argument is the first word of the object.
///
/// # Arguments
/// - `this`: BG scene layer object.
///
/// # Returns
/// The vtable result, or the constant `1`/`0` from the two guards.
///
/// # Safety
/// A non-null `+0x4C` entry must be callable with one integer argument.
///
/// # Confidence
/// medium - the guard is explicit; the call is an unrecovered indirect jump.
pub unsafe fn bg_scene_layer_mode_a(this: usize) -> u32 {
    if (read_u32(this + 0xd0) & 0x0008_0000) != 0 {
        return 1;
    }
    let function = read_u32(this + 0x4c) as usize;
    if function == 0 {
        return 0;
    }
    platform::call1(function, read_u32(this))
}

/// Same query as [`bg_scene_layer_mode_a`] with the `0x100000` flag and the
/// `+0x50` callback slot.
