/// Calls a PowerPC function with one pointer argument (`r3`) and returns a
/// double from `f1`.
///
/// Used for `0x801C14C0`, the vector-length helper.
///
/// # Safety
/// `addr` must use this mixed ABI.
unsafe fn call1_ptr_f64(addr: usize, ptr: u32) -> f64 {
    let f: extern "C" fn(u32) -> f64 = core::mem::transmute(addr);
    f(ptr)
}

