/// Resolves the x-ordered overlap between two collision areas.
///
/// The first test rejects pairs whose y extents do not overlap. The three
/// corridor tests then compare the x offsets stored at `+0x40..+0x4C` with
/// the second area's x bounds, and two `segment_side_x` calls check the two
/// diagonals. On success both areas' `+0x50`/`+0x70` slots are zeroed and
/// their `+0x90`/`+0x94` centres copied, exactly like the original.
///
/// # Original
/// - Ghidra: `FUN_8008d460` at `0x8008D460` (952 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008d460_FUN_8008d460.c`
/// - observed: `if (a[+0x24]+b[+0x24] <= ABS(center_y(a)-center_y(b))) return 0;`
///   followed by the three guards and the `side != 3` / `side != 2` tests.
///
/// # Arguments
/// - `a`, `b`: 0x98-byte collision-area objects.
///
/// # Returns
/// `1` when the two areas overlap and the centres were recorded, `0` otherwise.
///
/// # Safety
/// Both areas must be readable/writable through their `+0x90` slots.
///
/// # Confidence
/// medium - the arithmetic is observed; the `3`/`2` side constants come from
/// [`segment_side_x`]'s documented return values, and the flag semantics are
/// inferred from the shared tail with `0x8008D8B0`.
pub unsafe fn stage_area_overlap_x(a: usize, b: usize) -> u32 {
    let a_center_x = collision_area_center_x(a);
    let a_center_y = collision_area_center_y(a);
    let b_center_x = collision_area_center_x(b);
    let b_center_y = collision_area_center_y(b);
    if read_f32(a + 0x24) + read_f32(b + 0x24) <= (a_center_y - b_center_y).abs() {
        return 0;
    }
    let b_min_y = collision_area_min_y(b) as f64;
    let b_max_y = collision_area_max_y(b) as f64;
    let b_max_x = collision_area_max_x(b) as f64;
    let b_min_x = collision_area_min_x(b) as f64;
    let edge0 = a_center_x + read_f32(a + 0x40);
    let edge1 = a_center_x + read_f32(a + 0x44);
    let edge2 = a_center_x + read_f32(a + 0x48);
    let edge3 = a_center_x + read_f32(a + 0x4c);
    let a_min_y = collision_area_min_y(a);
    let a_max_y = collision_area_max_y(a);
    if !((b_min_x <= edge0 as f64 || b_min_x <= edge2 as f64)
        && ((edge1 as f64) <= b_max_x || (edge3 as f64) <= b_max_x)
        && ((a_min_y as f64) < b_min_y || b_max_y < a_max_y as f64))
    {
        return 0;
    }
    let pair_a = [a_min_y, edge0];
    let pair_b = [a_max_y, edge2];
    if segment_side_x(b_min_y, b_min_x, pair_a.as_ptr() as usize, pair_b.as_ptr() as usize) != 3 {
        let second_a = [a_min_y, edge0];
        let second_b = [a_max_y, edge2];
        if segment_side_x(
            b_max_y,
            b_min_x,
            second_a.as_ptr() as usize,
            second_b.as_ptr() as usize,
        ) != 3
        {
            return 0;
        }
    }
    let pair_c = [a_min_y, edge1];
    let pair_d = [a_max_y, edge3];
    if segment_side_x(b_min_y, b_max_x, pair_c.as_ptr() as usize, pair_d.as_ptr() as usize) != 2 {
        let second_c = [a_min_y, edge1];
        let second_d = [a_max_y, edge3];
        if segment_side_x(
            b_max_y,
            b_max_x,
            second_c.as_ptr() as usize,
            second_d.as_ptr() as usize,
        ) != 2
        {
            return 0;
        }
    }
    let zero = read_u32(F_COLLISION_ZERO);
    write_u32(a + read_u8(b + 0x2c) as usize * 4 + 0x50, zero);
    write_u32(a + read_u8(b + 0x2c) as usize * 4 + 0x70, zero);
    let a_cx = collision_area_center_x(a);
    let a_cy = collision_area_center_y(a);
    write_f32(a + 0x90, a_cy);
    write_f32(a + 0x94, a_cx);
    write_u32(b + read_u8(a + 0x2c) as usize * 4 + 0x50, zero);
    write_u32(b + read_u8(a + 0x2c) as usize * 4 + 0x70, zero);
    let b_cx = collision_area_center_x(b);
    let b_cy = collision_area_center_y(b);
    write_f32(b + 0x90, b_cy);
    write_f32(b + 0x94, b_cx);
    1
}

/// Resolves the y-ordered overlap between two collision areas.
///
/// This is the twin of [`stage_area_overlap_x`] for areas ordered along y: it
/// rejects pairs whose x extents do not overlap, runs the three corridor
/// tests against the y offsets at `+0x40..+0x4C`, and uses two
/// `segment_side_y` calls with the `0`/`1` side values.
///
/// # Original
/// - Ghidra: `FUN_8008d8b0` at `0x8008D8B0` (912 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008d8b0_FUN_8008d8b0.c`
/// - observed: `if (a[+0x28]+b[+0x28] <= ABS(center_x(a)-center_x(b))) return 0;`
///   then the mirrored guards, `side != 0` and `side != 1` tests, and the
///   same four-slot centre write-back.
///
/// # Arguments
/// - `a`, `b`: 0x98-byte collision-area objects.
///
/// # Returns
/// `1` when the two areas overlap and the centres were recorded, `0` otherwise.
///
/// # Safety
/// Both areas must be readable/writable through their `+0x90` slots.
///
/// # Confidence
/// medium - the arithmetic is observed; the side constants come from
/// [`segment_side_y`].
pub unsafe fn stage_area_overlap_y(a: usize, b: usize) -> u32 {
    let a_center_x = collision_area_center_x(a);
    let a_center_y = collision_area_center_y(a);
    let b_center_x = collision_area_center_x(b);
    let b_center_y = collision_area_center_y(b);
    if read_f32(a + 0x28) + read_f32(b + 0x28) <= (a_center_x - b_center_x).abs() {
        return 0;
    }
    let b_min_y = collision_area_min_y(b) as f64;
    let b_max_y = collision_area_max_y(b) as f64;
    let b_max_x = collision_area_max_x(b) as f64;
    let b_min_x = collision_area_min_x(b) as f64;
    let edge0 = a_center_y + read_f32(a + 0x40);
    let edge1 = a_center_y + read_f32(a + 0x44);
    let edge2 = a_center_y + read_f32(a + 0x48);
    let edge3 = a_center_y + read_f32(a + 0x4c);
    let a_max_x = collision_area_max_x(a);
    let a_min_x = collision_area_min_x(a);
    let upper_overlap = (edge0 as f64) <= b_max_y || (edge2 as f64) <= b_max_y;
    let lower_overlap = b_min_y <= edge1 as f64 || b_min_y <= edge3 as f64;
    if !(upper_overlap && lower_overlap) {
        return 0;
    }
    if !((a_min_x as f64) < b_min_x || b_max_x < a_max_x as f64) {
        return 0;
    }
    let pair_a = [edge0, a_max_x];
    let pair_b = [edge2, a_min_x];
    if segment_side_y(b_max_y, b_max_x, pair_a.as_ptr() as usize, pair_b.as_ptr() as usize) != 0 {
        let second_a = [edge0, a_max_x];
        let second_b = [edge2, a_min_x];
        if segment_side_y(
            b_max_y,
            b_min_x,
            second_a.as_ptr() as usize,
            second_b.as_ptr() as usize,
        ) != 0
        {
            return 0;
        }
    }
    let pair_c = [edge1, a_max_x];
    let pair_d = [edge3, a_min_x];
    if segment_side_y(b_min_y, b_max_x, pair_c.as_ptr() as usize, pair_d.as_ptr() as usize) != 1 {
        let second_c = [edge1, a_max_x];
        let second_d = [edge3, a_min_x];
        if segment_side_y(
            b_min_y,
            b_min_x,
            second_c.as_ptr() as usize,
            second_d.as_ptr() as usize,
        ) != 1
        {
            return 0;
        }
    }
    let zero = read_u32(F_COLLISION_ZERO);
    write_u32(a + read_u8(b + 0x2c) as usize * 4 + 0x50, zero);
    write_u32(a + read_u8(b + 0x2c) as usize * 4 + 0x70, zero);
    let a_cx = collision_area_center_x(a);
    let a_cy = collision_area_center_y(a);
    write_f32(a + 0x90, a_cy);
    write_f32(a + 0x94, a_cx);
    write_u32(b + read_u8(a + 0x2c) as usize * 4 + 0x50, zero);
    write_u32(b + read_u8(a + 0x2c) as usize * 4 + 0x70, zero);
    let b_cx = collision_area_center_x(b);
    let b_cy = collision_area_center_y(b);
    write_f32(b + 0x90, b_cy);
    write_f32(b + 0x94, b_cx);
    1
}

// ---------------------------------------------------------------------------
// 0x80080290 / 0x80080670: point and wrap tests
// ---------------------------------------------------------------------------

/// Wraps a position around a circular stage boundary.
///
/// When `+0xC4` holds a non-zero turn angle, the function converts the
/// position offset into polar coordinates (`atan2` from `0x80237ED0`), adds
/// the stored angle, evaluates `sin`/`cos` through `0x80237C40`/`0x80237BD0`
/// at 1/256 scale, and writes the point back on the circle. `0x80101AA0`
/// applies the stage's horizontal wrap to x only.
///
/// # Original
/// - Ghidra: `FUN_80080290` at `0x80080290` (348 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80080290_FUN_80080290.c`
/// - observed: `if (*(short *)(param_1 + 0xc4) == 0) return;`,
///   `FUN_802be470(dx*dx+dy*dy)`, `FUN_80237ed0(dy,dx)`, then four
///   `FUN_80237c40`/`FUN_80237bd0` calls scaled by `[r2-0x71F0]`.
///
/// # Arguments
/// - `this`: object with the centre at `+0x58`/`+0x5C` and the angle at
///   `+0xC4`.
/// - `position`: in/out `[x, y]` float pair.
///
/// # Side effects
/// Rewrites both floats of `position`.
///
/// # Safety
/// `this+0x58..+0xC6` and `position..position+8` must be accessible.
///
/// # Confidence
/// medium - the math is observed, but the four `sin`/`cos` calls include two
/// dead results and the `s16` conversions come from paired-single GQR forms.
pub unsafe fn stage_circle_wrap(this: usize, position: usize) {
    let stored_angle = read_u16(this + 0xc4) as i16;
    if stored_angle == 0 {
        return;
    }
    let dy = read_f32(position + 4) - read_f32(this + 0x5c);
    let dx = read_f32(position) - read_f32(this + 0x58);
    let radius = call1_f64(0x802B_E470, (dx * dx + dy * dy) as f64);
    let atan = call2_f64_i16(0x8023_7ED0, dy as f64, dx as f64);
    let angle = stored_angle.wrapping_add(atan);
    let radians =
        (read_f32(W23_F_ANGLE_SCALE) as f64 * angle as f64) as f32 as f64;
    // observed: the original evaluates sin/cos twice; the first pair's results
    // are discarded but the calls remain in the body.
    call1_f64(0x8023_7C40, radians);
    call1_f64(0x8023_7BD0, radians);
    let sin = call1_f64(0x8023_7C40, radians);
    let x = read_f32(this + 0x58) + (radius * sin) as f32;
    let wrapped_x = call1_f64(0x8010_1AA0, x as f64) as f32;
    write_f32(position, wrapped_x);
    let cos = call1_f64(0x8023_7BD0, radians);
    write_f32(position + 4, read_f32(this + 0x5c) + (radius * cos) as f32);
}

/// Tests whether a world point lies inside a BG-unit actor's region.
///
/// Three shapes are supported by the `+0xC8` mode word: a circle (radius at
/// `+0x90`), an axis-aligned rectangle (`+0x60..+0x74`), and a rotated
/// rectangle (angle `s16` at `[+0xBC]`, extents at `+0x80..+0x8C`). All
/// coordinates are integers in the object and are converted numerically to
/// floats, matching the Ghidra `(float)param_2[...]` forms.
///
/// # Original
/// - Ghidra: `FUN_80080670` at `0x80080670` (520 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80080670_FUN_80080670.c`
/// - observed: `if (*param_2 != 0)`, the `param_2[0x32] == 1` circle path,
///   the `*(short *)param_2[0x2f] == 0` rectangle path, and the rotated path
///   with `FUN_8016ee30`, `FUN_801c0bd0`, `FUN_801c0540`,
///   `FUN_8016f130`.
///
/// # Arguments
/// - `base`: camera/stage x origin added to the object's x fields.
/// - `object`: BG-unit actor record.
/// - `point`: `[x, y, z]` float point.
///
/// # Returns
/// `1` when the point is inside the region, `0` otherwise.
///
/// # Safety
/// The object and the pointer at `[object+0xBC]` must be readable.
///
/// # Confidence
/// medium - the branch structure is observed; the three float arguments of
/// `0x801C0BD0` are not printed by Ghidra, so they are inferred from the
/// three offsets computed immediately before the call.
pub unsafe fn bg_unit_contains_point(base: f64, object: usize, point: usize) -> u32 {
    if read_u32(object) == 0 {
        return 0;
    }
    if read_u32(object + 0xc8) == 1 {
        let center_y = read_i32(object + 0x5c) as f32;
        let center_x = (base + read_i32(object + 0x58) as f32 as f64) as f32;
        let zero = read_f32(F_ZERO_WAVE18);
        let mut offset = [0f32;
 3];
        offset[0] = center_x - read_f32(point);
        offset[1] = center_y - read_f32(point + 4);
        offset[2] = zero - read_f32(point + 8);
        let distance = call1_ptr_f64(0x801C_14C0, offset.as_ptr() as u32);
        if distance <= read_i32(object + 0x90) as f32 as f64 {
            return 1;
        }
    } else if read_u16(read_u32(object + 0xbc) as usize) == 0 {
        let y = read_f32(point + 4);
        let x = read_f32(point);
        let low_x = (base + read_i32(object + 0x60) as f32 as f64) as f32;
        let high_x = (base + read_i32(object + 0x70) as f32 as f64) as f32;
        if y <= read_i32(object + 0x64) as f32
            && read_i32(object + 0x74) as f32 <= y
            && x <= high_x
            && low_x <= x
        {
            return 1;
        }
    } else {
        let mut angle = [(read_u16(read_u32(object + 0xbc) as usize) as i16).wrapping_neg();
 1];
        let edge_y = read_i32(object + 0x64) as f32;
        let edge_x = (base + read_i32(object + 0x60) as f32 as f64) as f32;
        let zero = read_f32(F_ZERO_WAVE18);
        let mut rotation = [0u32;
 12];
        platform::call2(
            0x8016_EE30,
            rotation.as_mut_ptr() as u32,
            angle.as_mut_ptr() as u32,
        );
        let dz = read_f32(point + 8) - zero;
        let dy = read_f32(point + 4) - edge_y;
        let dx = read_f32(point) - edge_x;
        let mut translation = [0u32;
 12];
        // inferred: the three floats were left in f1..f3 by the three
        // subtractions above; Ghidra printed the call without them.
        call3_f32_ptr(
            0x801C_0BD0,
            dx,
            dy,
            dz,
            translation.as_mut_ptr() as u32,
        );
        platform::call3(
            0x801C_0540,
            rotation.as_mut_ptr() as u32,
            translation.as_mut_ptr() as u32,
            rotation.as_mut_ptr() as u32,
        );
        let mut local = [0f32;
 3];
        platform::call2(
            0x8016_F130,
            rotation.as_ptr() as u32,
            local.as_mut_ptr() as u32,
        );
        if zero <= local[0]
            && local[0] <= read_i32(object + 0x88) as f32 - read_i32(object + 0x80) as f32
            && local[1] <= zero
            && read_i32(object + 0x8c) as f32 - read_i32(object + 0x84) as f32 <= local[1]
        {
            return 1;
        }
    }
    0
}

// ---------------------------------------------------------------------------
// 0x8008A2E0 .. 0x8008B030: stage-block construction and GX state
// ---------------------------------------------------------------------------

/// Creates a stage-block render buffer and binds the two optional slots.
///
/// # Original
/// - Ghidra: `FUN_8008a2e0` at `0x8008A2E0` (144 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008a2e0_FUN_8008a2e0.c`
/// - observed: `iVar1 = thunk_FUN_80164fd0(param_1,param_2,0);` on success
///   writes `+8 = param_4`, `+0x10 = param_5`, calls
///   `FUN_8016a2a0(param_1,param_3,0xFFFFFFFF)` and
///   `FUN_8016a0f0(param_1,7,1)`.
///
/// # Arguments
/// - `this`: block object.
/// - `resource`: buffer/resource handle.
/// - `a3`: selector forwarded to `0x8016A2A0`.
/// - `a4`, `a5`: words stored at `+8` and `+0x10`.
///
/// # Returns
/// `1` when the buffer was created, `0` otherwise.
///
/// # Safety
/// `this..this+0x14` must be writable and the buffer owner live.
///
/// # Confidence
/// high - one predicate and four calls with literal offsets.
pub unsafe fn stage_block_bind_resource(
    this: usize,
    resource: u32,
    a3: u32,
    a4: u32,
    a5: u32,) -> u32 {
    let created = platform::call3(TILEMAP_CREATE_BUFFER, this as u32, resource, 0);
    if created != 0 {
        write_u32(this + 8, a4);
        write_u32(this + 0x10, a5);
        platform::call3(0x8016_A2A0, this as u32, a3, 0xffff_ffff);
        platform::call3(0x8016_A0F0, this as u32, 7, 1);
    }
    (created != 0) as u32
}

/// Creates a stage-block render buffer and binds two independent slots.
///
/// The two "negative selector" paths call `0x8016A0F0` instead of storing the
/// value, exactly like the original.
///
/// # Original
/// - Ghidra: `FUN_8008a5e0` at `0x8008A5E0` (172 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008a5e0_FUN_8008a5e0.c`
/// - observed: `FUN_802dcd74` (`__savegprlr_27`) keeps `r3`/`r4`; the body
///   then uses `param_1`/`param_2` as the buffer pair, stores `param_5` at
///   `+8` or calls `FUN_8016a0f0(param_1,6,1)`, and stores `param_6` at
///   `+0xC` or calls `FUN_8016a0f0(param_1,7,1)`.
///
/// # Arguments
/// - `this`: block object.
/// - `resource`: buffer/resource handle.
/// - `a3`, `a4`: signed selectors; negative selects the fallback call.
/// - `a5`, `a6`: words stored at `+8` and `+0xC`.
///
/// # Returns
/// `1` on success, `0` when the buffer could not be created.
///
/// # Safety
/// `this..this+0x10` must be writable.
///
/// # Confidence
/// medium - the register pair is recovered from the save-helper convention;
/// the selector meaning is inferred from the branches.
pub unsafe fn stage_block_bind_pair(
    this: usize,
    resource: u32,
    a3: i32,
    a4: i32,
    a5: u32,
    a6: u32,) -> u32 {
    let created = platform::call3(TILEMAP_CREATE_BUFFER, this as u32, resource, 0);
    if created == 0 {
        return 0;
    }
    platform::call3(0x8016_A2A0, this as u32, a3 as u32, a4 as u32);
    if a3 < 0 {
        platform::call3(0x8016_A0F0, this as u32, 6, 1);
    } else {
        write_u32(this + 8, a5);
    }
    if a4 < 0 {
        platform::call3(0x8016_A0F0, this as u32, 7, 1);
    } else {
        write_u32(this + 0x0c, a6);
    }
    1
}

/// Initialises a stage block's texture and coin/block model.
///
/// # Original
/// - Ghidra: `FUN_8008a6d0` at `0x8008A6D0` (156 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008a6d0_FUN_8008a6d0.c`
/// - observed: on success writes `+0x24 = param_3`, `+0x18 = 0x20`, calls
///   `0x8008AF10(this)`, `0x8008AF80(this,param_2)`,
///   `FUN_8016a2a0(this,0,0x7F)` and `FUN_8016a0f0(this,7,1)`.
///
/// # Arguments
/// - `this`: block object.
/// - `resource`: resource handle passed to the model loader.
/// - `model_index`: coin/block model selector stored at `+0x24`.
///
/// # Returns
/// `1` on success.
///
/// # Safety
/// `this..this+0x28` writable; the texture/model loaders live.
///
/// # Confidence
/// high - the in-batch callees are known and all stores are literal.
pub unsafe fn stage_block_init(this: usize, resource: u32, model_index: u32) -> u32 {
    let created = platform::call3(TILEMAP_CREATE_BUFFER, this as u32, resource, 0);
    if created != 0 {
        write_u32(this + 0x24, model_index);
        write_u32(this + 0x18, 0x20);
        stage_block_texture_init(this);
        stage_block_coin_models_load(this, resource);
        platform::call3(0x8016_A2A0, this as u32, 0, 0x7f);
        platform::call3(0x8016_A0F0, this as u32, 7, 1);
    }
    (created != 0) as u32
}

/// Places a stage-block actor: builds its matrix and programs four slots.
///
/// # Original
/// - Ghidra: `FUN_8008a780` at `0x8008A780` (344 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008a780_FUN_8008a780.c`
/// - observed: `FUN_801c0bd0(0.0f,0.0f,-128.0f,&matrix)`;
///   `FUN_8016edd0(&matrix,&angle)` with the `u16` from `r13-0x57FE`;
///   interface test through slot `+8` with `&DAT_802f8ff0`; then
///   `FUN_802574e0(object,0,&matrix)`, three `+0xDC..+0xE4` writes of
///   `1.5f`, and four `+0xC` virtual calls with selectors `1,4,2,6`.
///
/// # Arguments
/// - `this`: block object; `+0x0C` holds the interface pointer.
/// - `arg`: forwarded as the fourth argument of the selector-4 call.
///
/// # Safety
/// `this+0x0C` must point at a live object and the vtable slots callable.
///
/// # Confidence
/// medium - the matrix calls and stores are observed; the slot meanings are
/// inferred from their selectors.
pub unsafe fn stage_block_actor_setup(this: usize, arg: u32) {
    let mut matrix = [0u32;
 12];
    call3_f32_ptr(
        0x801C_0BD0,
        0.0,
        0.0,
        read_f32(W23_F_MINUS_128),
        matrix.as_mut_ptr() as u32,
    );
    let mut angle = [0u16;
 2];
    angle[0] = read_u16(W23_G_BLOCK_ANGLE);
    platform::call2(0x8016_EDD0, matrix.as_mut_ptr() as u32, angle.as_ptr() as u32);
    let object = read_u32(this + 0x0c) as usize;
    let mut found = false;
    if object != 0 {
        let mut descriptor = W23_TYPE_DESC_B as u32;
        let result = call_vtable_slot2(
            object,
            8,
            &mut descriptor as *mut u32 as u32,
        );
        if result != 0 {
            found = true;
        }
    }
    let target = if found { object } else { 0 };
    platform::call3(0x8025_74E0, target as u32, 0, matrix.as_ptr() as u32);
    let scale = read_u32(W23_F_ONE_AND_HALF);
    write_u32(target + 0xdc, scale);
    write_u32(target + 0xe0, scale);
    write_u32(target + 0xe4, scale);
    let vtable = read_u32(target) as usize;
    let setter = read_u32(vtable + 0x0c) as usize;
    platform::call4(setter, target as u32, 1, 0, 0);
    platform::call4(setter, target as u32, 4, 0, arg);
    platform::call4(setter, target as u32, 2, 0, 0);
    platform::call4(setter, target as u32, 6, 0, 0);
}

/// Programs the stage block's fixed GX state block.
///
/// # Original
/// - Ghidra: `FUN_8008a9c0` at `0x8008A9C0` (672 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008a9c0_FUN_8008a9c0.c`
/// - observed: the long literal call sequence from `0x801C4070` through
///   `0x801C5570(0x80,0,4)`, ending with `_DAT_cc008000 = [r2-0x70B0]`
///   (`-10000.0f`).
///
/// # Arguments
/// - `_this`: unused by the original body.
/// - `viewport`: pointer read once for `0x801C8430(1, *viewport)`.
/// - `layer`: selector passed to `0x801C9940`.
///
/// # Side effects
/// Programs the GX pipeline and writes one float to the FIFO at
/// `0xCC008000`.
///
/// # Safety
/// `viewport` must be readable and the GX device initialised.
///
/// # Confidence
/// high - every call and its literal arguments are visible; only the GX state
/// names are unknown.
pub unsafe fn stage_block_gx_state(_this: usize, viewport: usize, layer: u32) {
    platform::call0(0x801C_4070);
    platform::call2(0x801C_37C0, 9, 1);
    platform::call5(0x801C_40B0, 0, 9, 1, 4, 0);
    platform::call1(0x801C_6AC0, 1);
    platform::call7(0x801C_6AF0, 4, 0, 0, 0, 1, 2, 2);
    platform::call1(0x801C_4A20, 0);
    platform::call1(0x801C_8110, 0);
    platform::call1(0x801C_88F0, 1);
    platform::call1(0x801C_8130, 0);
    platform::call4(0x801C_8790, 0, 0xff, 0xff, 4);
    platform::call5(0x801C_82F0, 0, 0x0f, 0x0c, 2, 0x0f);
    platform::call6(0x801C_8370, 0, 0, 0, 0, 1, 0);
    platform::call5(0x801C_8330, 0, 7, 7, 7, 7);
    platform::call6(0x801C_83D0, 0, 0, 0, 0, 1, 0);
    platform::call1(0x801C_8EB0, 1);
    platform::call4(0x801C_8DC0, 1, 1, 0, 0x0f);
    platform::call3(0x801C_8E70, 1, 7, 1);
    platform::call5(0x801C_86C0, 7, 0, 0, 7, 0);
    platform::call1(0x802D_2F80, 1);
    platform::call1(0x802D_2F20, 1);
    let mut colour = [0u32;
 1];
    let grey = read_f32(F_GX_SCALE) as f64;
    call4_f64_2(
        0x801C_8920,
        grey,
        grey,
        grey,
        grey,
        0,
        colour.as_mut_ptr() as u32,
    );
    platform::call3(0x801C_8CB0, 0, 0, 0);
    platform::call1(0x801C_5860, 0);
    platform::call1(0x801C_8F90, 1);
    platform::call1(0x801C_9D60, 0);
    platform::call2(0x801C_9940, layer, 0);
    platform::call1(0x801C_9A60, 0);
    let mut word = read_u32(viewport);
    platform::call2(0x801C_8430, 1, &mut word as *mut u32 as u32);
    platform::call3(0x801C_5570, 0x80, 0, 4);
    write_u32(0xCC00_8000, read_u32(W23_F_MINUS_10000));
}

/// Creates a stage block from a location and a parameter value.
///
/// # Original
/// - Ghidra: `FUN_8008b030` at `0x8008B030` (180 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008b030_FUN_8008b030.c`
/// - observed: `FUN_802dcd74` (`__savegprlr_27`) keeps `r3`/`r4`; on success
///   writes `+8 = param_3`, `+0xC = f1`, `+0x14 = param_6`, calls
///   `FUN_8016a2a0(param_1,param_4,param_5)` and conditionally
///   `FUN_8016a0f0(...,6,1)` / `(...,7,1)`.
///
/// # Arguments
/// - `this`: block object.
/// - `resource`: buffer/resource handle.
/// - `a3`: word stored at `+8`.
/// - `value`: float arriving in `f1` and stored at `+0xC`.
/// - `a4`, `a5`: signed selectors for `0x8016A2A0`.
/// - `a6`: byte stored at `+0x14`.
///
/// # Returns
/// `1` on success, `0` otherwise.
///
/// # Safety
/// `this..this+0x18` must be writable.
///
/// # Confidence
/// medium - the `f1` argument is not in the Ghidra parameter list; it is
/// recovered from `extraout_f1` and the stored `(float)dVar4`.
pub unsafe fn stage_block_spawn(
    this: usize,
    resource: u32,
    a3: u32,
    value: f32,
    a4: i32,
    a5: i32,
    a6: u8,) -> u32 {
    let created = platform::call3(TILEMAP_CREATE_BUFFER, this as u32, resource, 0);
    if created == 0 {
        return 0;
    }
    write_u32(this + 8, a3);
    write_f32(this + 0x0c, value);
    write_u8(this + 0x14, a6);
    platform::call3(0x8016_A2A0, this as u32, a4 as u32, a5 as u32);
    if a4 < 0 {
        platform::call3(0x8016_A0F0, this as u32, 6, 1);
    }
    if a5 < 0 {
        platform::call3(0x8016_A0F0, this as u32, 7, 1);
    }
    1
}

/// Chooses and programs the stage block's polygonal model.
///
/// Called once per frame while the block's type byte is `0x7F`. It tests the
/// object's `+8` interface (through the `+8` vtable slot and
/// `0x802F8FD8`), resolves the model name from the block resource, and
/// switches between [`stage_render_mode_a`] and [`stage_render_mode_b`].
/// The model-name cascade (`MH_model`, `SMH_model`, `LH_model`,
/// `SLH_model`) toggles bit 1 of the selected polygon's `+0x34` flags.
///
/// # Original
/// - Ghidra: `FUN_8008bbd0` at `0x8008BBD0` (656 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008bbd0_FUN_8008bbd0.c`
/// - observed: `__savegprlr_25` keeps `r3`/`r4`; `FUN_802df098(name,"block_",
///   6)`; `FUN_802e1ab4(name,"MH_model")` and the three-name cascade; the
///   `+0xC` virtual call with selector `6`; `FUN_801c8640(0,0,1,2,3)`.
///
/// # Arguments
/// - `this`: block object; `+0xD0` is the type byte and `+0xE8` the resource.
/// - `state`: per-block state; `+8` is the active render mode.
///
/// # Safety
/// Both objects and the name strings must be readable, and `+0xC` must be a
/// callable vtable slot.
///
/// # Confidence
/// medium - every branch and string is observed; the interface descriptor
/// and bit-1 meanings are inferred from the call shape.
pub unsafe fn stage_block_model_dispatch(this: usize, state: usize) {
    if read_u8(this + 0xd0) != 0x7f {
        return;
    }
    let mut descriptor = W23_TYPE_DESC_A as u32;
    let mut has_interface = false;
    let result = call_vtable_slot2(this, 8, &mut descriptor as *mut u32 as u32);
    if result != 0 {
        has_interface = true;
    }
    if !has_interface || state == 0 {
        return;
    }
    let mut object_slot = [read_u32(this + 0xe8);
 1];
    let object = object_slot[0];
    let relative = read_u32(object as usize + 0x48) as i32;
    let base = if relative == 0 {
        0usize
    } else {
        (object as usize).wrapping_add(relative as usize)
    };
    let mode = read_u32(state + 8);
    let mut changed = false;
    let mut node = 0usize;
    if platform::call3(0x802D_F098, base as u32, W23_STR_BLOCK_PREFIX as u32, 6) == 0 {
        if mode != 2 {
            stage_render_mode_b();
            write_u32(state + 8, 2);
            changed = true;
        }
    } else {
        changed = mode != 1;
        if changed {
            stage_render_mode_a();
            write_u32(state + 8, 1);
        }
        let mh = platform::call2(0x802E_1AB4, base as u32, W23_STR_MH_MODEL as u32);
        if mh == 0 {
            node = polygon_node(object_slot.as_mut_ptr() as u32);
        } else {
            let smh = platform::call2(0x802E_1AB4, base as u32, W23_STR_SMH_MODEL as u32);
            if smh == 0 {
                node = polygon_node(object_slot.as_mut_ptr() as u32);
            } else {
                let lh = platform::call2(0x802E_1AB4, base as u32, W23_STR_LH_MODEL as u32);
                if lh == 0 {
                    node = platform::call2(
                        0x8023_B900,
                        object_slot.as_mut_ptr() as u32,
                        W23_STR_POLYGON3 as u32,
                    ) as usize;
                    set_node_flag(node);
                } else {
                    let slh =
                        platform::call2(0x802E_1AB4, base as u32, W23_STR_SLH_MODEL as u32);
                    if slh == 0 {
                        node = platform::call2(
                            0x8023_B900,
                            object_slot.as_mut_ptr() as u32,
                            W23_STR_POLYGON3 as u32,
                        ) as usize;
                        set_node_flag(node);
                    }
                }
            }
        }
    }
    let vtable = read_u32(this) as usize;
    let setter = read_u32(vtable + 0x0c) as usize;
    let mut selector = 0x0cu32;
    platform::call4(setter, this as u32, 6, 0, &mut selector as *mut u32 as u32);
    if node != 0 {
        write_u32(node + 0x34, read_u32(node + 0x34) & 0xffff_fffd);
    }
    if changed {
        platform::call5(0x801C_8640, 0, 0, 1, 2, 3);
    }
}

/// Selects `"polygon0"` or `"polygon3"` from the load-stage variant flag and
/// marks the node's bit 1.
///
/// # Arguments
/// - `slot`: address of the one-word object handle table.
///
/// # Returns
/// The node pointer, or zero.
///
/// # Confidence
/// medium - the two strings and the flag test are observed; the node's
/// `+0x34` bit is inferred from the matching clears in the caller.
unsafe fn polygon_node(slot: u32) -> usize {
    let name = if read_u32(W23_G_POLYGON_VARIANT) == 0 {
        W23_STR_POLYGON0
    } else {
        W23_STR_POLYGON3
    };
    let node = platform::call2(0x8023_B900, slot, name as u32) as usize;
    set_node_flag(node);
    node
}

/// Sets bit 1 of a node's `+0x34` flags (`observed` in three branches of
/// `0x8008BBD0`). The original does not test the node for zero.
unsafe fn set_node_flag(node: usize) {
    write_u32(node + 0x34, read_u32(node + 0x34) | 2);
}

/// Tests whether the block's render resource is loaded and binds it.
///
/// # Original
/// - Ghidra: `FUN_8008be60` at `0x8008BE60` (112 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008be60_FUN_8008be60.c`
/// - observed: `iVar1 = thunk_FUN_80164fd0(param_1,param_2,0);` on success
///   `FUN_8016a2a0(param_1,param_3,0xFFFFFFFF)` and
///   `FUN_8016a0f0(param_1,7,1)`.
///
/// # Arguments
/// - `this`: block object.
/// - `resource`: buffer/resource handle.
/// - `a3`: selector for `0x8016A2A0`.
///
/// # Returns
/// `1` when the resource was bound.
///
/// # Safety
/// `this` must be a live buffer object.
///
/// # Confidence
/// high - three calls and one predicate.
pub unsafe fn stage_block_resources_ready(this: usize, resource: u32, a3: u32) -> u32 {
    let created = platform::call3(TILEMAP_CREATE_BUFFER, this as u32, resource, 0);
    if created != 0 {
        platform::call3(0x8016_A2A0, this as u32, a3, 0xffff_ffff);
        platform::call3(0x8016_A0F0, this as u32, 7, 1);
    }
    (created != 0) as u32
}

/// Installs the model dispatcher as the block's render callback.
///
/// # Original
/// - Ghidra: `FUN_8008bed0` at `0x8008BED0` (100 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008bed0_FUN_8008bed0.c`
/// - observed: `*(u32*)(param_1+8)=0; FUN_8024d5e0(0x7ff);
///   piVar1 = FUN_80164b10(); (**(code**)(*piVar1+0x1C))(piVar1,
///   FUN_8008bbd0, param_1, 0); FUN_801c9d60(0);`
///
/// # Arguments
/// - `this`: block object registered as the callback argument.
///
/// # Safety
/// `this+8` writable and the global buffer owner live.
///
/// # Confidence
/// high - four calls and one store with literal offsets.
pub unsafe fn stage_block_render_setup(this: usize) {
    write_u32(this + 8, 0);
    platform::call1(0x8024_D5E0, 0x7ff);
    let owner = call0_ret(0x8016_4B10) as usize;
    let vtable = read_u32(owner) as usize;
    let register = read_u32(vtable + 0x1c) as usize;
    platform::call4(
        register,
        owner as u32,
        W23_MODEL_DISPATCH as u32,
        this as u32,
        0,
    );
    platform::call1(0x801C_9D60, 0);
}

