const W29_SUBOBJECT_CTOR: usize = 0x802D_7AA0;
const W29_SUBOBJECT_DTOR: usize = 0x802D_7B20;

/// `0x8016A2F0`/`0x8016A340`: element constructor/destructor of a 0xC-byte
