const W29_ELEM_CTOR_A: usize = 0x8016_A2F0;
const W29_ELEM_DTOR_A: usize = 0x8016_A340;

/// `0x80169CD0`: element constructor of the long variant's 0x40-count array.
const W29_ELEM_CTOR_B: usize = 0x8016_9CD0;

/// `0x800929E0`: element constructor used by the long variant's 0x1C-byte
