const W29_ELEM_CTOR_2: usize = 0x8009_2970;

/// `0x80015E30`: constructor of the long variant's 0xC-byte arrays.
const W29_ELEM_CTOR_D: usize = 0x8001_5E30;

/// `0x800908B0`: deleting destructor of the long variant's 0x1C-byte array.
const W29_ELEM_DTOR_C: usize = 0x8009_08B0;

