const W29_SEGMENT_ROTATE: usize = 0x8006_4AF0;

/// `0x801C0BD0`: builds a translation matrix from three floats.
const W29_MTX_TRANSLATION: usize = 0x801C_0BD0;

/// `0x8016EDD0`/`0x8016ECB0`/`0x8016EEF0`: apply one rotation angle to a
/// matrix (the three axes used by the segment movers).
const W29_MTX_ROTATE_A: usize = 0x8016_EDD0;
const W29_MTX_ROTATE_B: usize = 0x8016_ECB0;
const W29_MTX_ROTATE_C: usize = 0x8016_EEF0;

/// `0x8016A170`/`0x8016A150`/`0x8016A1A0`: bind a matrix to a model, copy the
/// base transform, and clear the model flag.
const W29_MODEL_SET_MATRIX: usize = 0x8016_A170;
const W29_MODEL_SET_BASE: usize = 0x8016_A150;
const W29_MODEL_SET_FLAG: usize = 0x8016_A1A0;

/// `0x80090440`/`0x80090590`: post-update helpers of the animated block.
const W29_SEGMENT_FOLLOWUP_A: usize = 0x8009_0440;
const W29_SEGMENT_FOLLOWUP_B: usize = 0x8009_0590;

/// `0x8016C890`: path/effect submitter used by the water-wave variant.
const W29_EFFECT_PATH: usize = 0x8016_C890;

/// Calls a PowerPC function with two `f32` arguments and two words, returning
/// its `r3` word. Used for the ground probe `0x80075270`, which Ghidra prints
/// with `(double)` casts for its two single-precision loads.
///
/// # Safety
/// `addr` must use this mixed floating/integer ABI.
unsafe fn call_f32x2_u32x2(addr: usize, a: f32, b: f32, c: u32, d: u32) -> u32 {
    let function: extern "C" fn(f32, f32, u32, u32) -> u32 = core::mem::transmute(addr);
    function(a, b, c, d)
}

// ---------------------------------------------------------------------------
// 0x80090230
// ---------------------------------------------------------------------------

/// Advances the animated block's segment table by one frame.
///
/// # Original
/// - Ghidra: `FUN_80090230` at `0x80090230` (392 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80090230_FUN_80090230.c`
/// - observed: the countdown at `+0x48` reaches zero and sets `+0x50 = 1`;
///   otherwise the angle at `+0x38` advances by `0x800`, every entry of the
///   `+0x230` table is copied into `+4..+0x18`, [`stage_block_vertical_advance`]
///   and [`stage_block_position_add`] run, and the six words are written back.
///   The scale at `r2-0x6FE0` is applied when bit 4 of `+0x44` is set.
/// - observed: Ghidra also prints `unaff_GQR0`/`ldexpf` guards around the float
///   loads; they are treated as load-format artefacts because the recovered
///   body uses ordinary single-precision values.
///
/// # Arguments
/// - `this`: stage block object.
///
/// # Side effects
/// Writes the countdown, the angle, the copied segment words and `+0x50`;
/// calls `0x80090440` and `0x80090590` at the end of the active branch.
///
/// # Safety
/// `this` must be a live block whose `+0x230` table has `+0x2D0` entries.
///
/// # Confidence
/// medium - the timer and segment copies are literal; the two post helpers and
/// the scale's gameplay meaning are inferred.
pub unsafe fn stage_block_advance_segments(this: usize) {
    let mut timer = read_u16(this + 0x48);
    if timer != 0 {
        timer = timer.wrapping_sub(1);
        write_u16(this + 0x48, timer);
    }
    if timer == 0 {
        write_u32(this + 0x50, 1);
    } else {
        write_u16(this + 0x38, read_u16(this + 0x38).wrapping_add(0x800));
        if read_i32(this + 0x2D0) > 0 {
            let scale = read_f32(W29_F_SEGMENT_SCALE) as f64;
            let mut entry = this + 0x230;
            let mut index = 0i32;
            while index < read_i32(this + 0x2D0) {
                write_u32(this + 4, read_u32(entry));
                write_u32(this + 8, read_u32(entry + 4));
                write_u32(this + 0x0C, read_u32(entry + 8));
                write_u32(this + 0x10, read_u32(entry + 0x0C));
                write_u32(this + 0x14, read_u32(entry + 0x10));
                write_u32(this + 0x18, read_u32(entry + 0x14));
                stage_block_vertical_advance(this);
                let mut x = read_f32(this + 0x10);
                let mut y = read_f32(this + 0x14);
                let mut z = read_f32(this + 0x18);
                if (read_u32(this + 0x44) >> 4) & 1 != 0 {
                    x = (x as f64 * scale) as f32;
                    y = (y as f64 * scale) as f32;
                    z = (z as f64 * scale) as f32;
                }
                let offset = [x, y, z];
                stage_block_position_add(this, offset.as_ptr() as usize);
                write_u32(entry + 0x0C, read_u32(this + 0x10));
                write_u32(entry + 0x10, read_u32(this + 0x14));
                write_u32(entry + 0x14, read_u32(this + 0x18));
                write_u32(entry, read_u32(this + 4));
                write_u32(entry + 4, read_u32(this + 8));
                write_u32(entry + 8, read_u32(this + 0x0C));
                entry += 0x1C;
                index += 1;
            }
        }
        platform::call1(W29_SEGMENT_FOLLOWUP_A, this as u32);
        platform::call1(W29_SEGMENT_FOLLOWUP_B, this as u32);
    }
}

// ---------------------------------------------------------------------------
// 0x800913A0
// ---------------------------------------------------------------------------

/// Rebuilds the four segment matrices of a conveyor block.
///
/// # Original
/// - Ghidra: `FUN_800913a0` at `0x800913A0` (276 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800913a0_FUN_800913a0.c`
/// - observed: four iterations, each rotates the `+0xB0` position by the three
///   `u16` angles at `+0x110/+0x112/+0x114`, builds a translation matrix, applies
///   the three rotations in the order y, x, z, and binds it to the model at
///   `+0x80`.
///
/// # Arguments
/// - `this`: `this` comes from the `__savegprlr_27` prologue helper, which
///   preserves the incoming `r3`; the object is otherwise not a parameter in
///   Ghidra's signature.
///
/// # Side effects
/// Writes four 12-word matrices at `+0x80`, `+0x8C`, `+0x98` and `+0xA4`.
///
/// # Safety
/// `this+0xB0..this+0xDC` and `+0x110..+0x11A` must be readable.
///
/// # Confidence
/// medium - the matrix call order is observed; the axis meanings are inferred
/// from the three GX rotation helpers.
pub unsafe fn stage_block_four_segment_matrices(this: usize) {
    let mut matrix = [0u32;
 12];
    let mut i = 0usize;
    while i < 4 {
        let position_addr = this + 0xB0 + i * 0x0C;
        let angle_addr = this + 0x110 + i * 6;
        let mut position = [
            read_f32(position_addr),
            read_f32(position_addr + 4),
            read_f32(position_addr + 8),
        ];
        let angles = [
            read_u16(angle_addr),
            read_u16(angle_addr + 2),
            read_u16(angle_addr + 4),
        ];
        platform::call3(
            W29_SEGMENT_ROTATE,
            position.as_mut_ptr() as u32,
            angles.as_ptr() as u32,
            1,
        );
        call3_f32_ptr(
            W29_MTX_TRANSLATION,
            position[0],
            position[1],
            position[2],
            matrix.as_mut_ptr() as u32,
        );
        let mut angle_y = [angles[1], 0u16];
        platform::call2(
            W29_MTX_ROTATE_A,
            matrix.as_mut_ptr() as u32,
            angle_y.as_mut_ptr() as u32,
        );
        let mut angle_x = [angles[0], 0u16];
        platform::call2(
            W29_MTX_ROTATE_B,
            matrix.as_mut_ptr() as u32,
            angle_x.as_mut_ptr() as u32,
        );
        let mut angle_z = [angles[2], 0u16];
        platform::call2(
            W29_MTX_ROTATE_C,
            matrix.as_mut_ptr() as u32,
            angle_z.as_mut_ptr() as u32,
        );
        let model = this + 0x80 + i * 0x0C;
        platform::call2(W29_MODEL_SET_MATRIX, model as u32, matrix.as_ptr() as u32);
        platform::call2(W29_MODEL_SET_BASE, model as u32, (this + 0x28) as u32);
        platform::call2(W29_MODEL_SET_FLAG, model as u32, 0);
        i += 1;
    }
}

