/// Resets the four segment positions to the block origin.
///
/// # Original
/// - Ghidra: `FUN_800914c0` at `0x800914C0` (84 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800914c0_FUN_800914c0.c`
/// - observed: loads `+0x04/+0x08/+0x0C` once and writes the same triple to
///   `+0xB0`, `+0xBC`, `+0xC8` and `+0xD4`.
///
/// # Arguments
/// - `this`: block object.
///
/// # Side effects
/// Writes twelve words.
///
/// # Safety
/// `this+0x04..this+0xDC` must be writable.
///
/// # Confidence
/// high - a literal four-way copy.
pub unsafe fn stage_block_four_segment_reset(this: usize) {
    let x = read_u32(this + 4);
    let y = read_u32(this + 8);
    let z = read_u32(this + 0x0C);
    let mut cursor = this + 0xB0;
    for _ in 0..4 {
        write_u32(cursor, x);
        write_u32(cursor + 4, y);
        write_u32(cursor + 8, z);
        cursor += 0x0C;
    }
}

