/// Initialises the four-segment motion table and copies the selected row.
///
/// # Original
/// - Ghidra: `FUN_80091520` at `0x80091520` (244 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80091520_FUN_80091520.c`
/// - observed: on first use the twelve `r2-0x6FAC..0x6F80` constants are copied
///   into `0x80356060..0x8035609C`, with `+0x88/+0x94/+0x98/+0x9C` mirrored
///   from earlier entries. The selector is bit 0 of `+0x44`; the chosen
///   eight-word row is copied into `+0xE0..+0x10C`, with `r2-0x6F7C` (`0.0f`)
///   written at every fourth slot.
///
/// # Arguments
/// - `this`: block object.
///
/// # Side effects
/// May write the global table and the one-time flag at `r13-0x57A8`; writes
/// sixteen words of the block.
///
/// # Safety
/// `this+0x44`, `+0xE0..+0x10C` and the BSS flag must be writable.
///
/// # Confidence
/// high - all stores and the row stride are literal.
pub unsafe fn stage_block_four_segment_motion_init(this: usize) {
    if read_u8(W29_F4_TABLE_INIT) == 0 {
        write_u32(W29_F4_MOTION_TABLE, read_u32(W29_F4_MOTION_0));
        write_u32(W29_F4_MOTION_TABLE + 4, read_u32(W29_F4_MOTION_1));
        write_u32(W29_F4_MOTION_TABLE + 0x0C, read_u32(W29_F4_MOTION_3));
        write_u32(W29_F4_MOTION_TABLE + 0x18, read_u32(W29_F4_MOTION_5));
        write_u32(W29_F4_MOTION_TABLE + 8, read_u32(W29_F4_MOTION_2));
        write_u32(W29_F4_MOTION_TABLE + 0x10, read_u32(W29_F4_MOTION_4));
        write_u32(W29_F4_MOTION_TABLE + 0x14, read_u32(W29_F4_MOTION_5));
        write_u32(W29_F4_MOTION_TABLE + 0x1C, read_u32(W29_F4_MOTION_7));
        write_u32(W29_F4_MOTION_TABLE + 0x20, read_u32(W29_F4_MOTION_8));
        write_u32(W29_F4_MOTION_TABLE + 0x24, read_u32(W29_F4_MOTION_9));
        write_u32(W29_F4_MOTION_TABLE + 0x2C, read_u32(W29_F4_MOTION_10));
        write_u32(W29_F4_MOTION_TABLE + 0x30, read_u32(W29_F4_MOTION_11));
        write_u32(W29_F4_MOTION_TABLE + 0x28, read_u32(W29_F4_MOTION_0));
        write_u32(W29_F4_MOTION_TABLE + 0x34, read_u32(W29_F4_MOTION_3));
        write_u32(W29_F4_MOTION_TABLE + 0x38, read_u32(W29_F4_MOTION_5));
        write_u32(W29_F4_MOTION_TABLE + 0x3C, read_u32(W29_F4_MOTION_1));
        write_u8(W29_F4_TABLE_INIT, 1);
    }
    let row = (read_u32(this + 0x44) & 1) as usize * 0x20;
    let zero = read_u32(W29_F_ZERO);
    write_u32(this + 0xE8, zero);
    write_u32(this + 0xE0, read_u32(W29_F4_MOTION_TABLE + row));
    let a = read_u32(W29_F4_MOTION_TABLE + row + 8);
    let b = read_u32(W29_F4_MOTION_TABLE + row + 0x0C);
    let c = read_u32(W29_F4_MOTION_TABLE + row + 0x10);
    let d = read_u32(W29_F4_MOTION_TABLE + row + 0x14);
    let e = read_u32(W29_F4_MOTION_TABLE + row + 0x18);
    let f = read_u32(W29_F4_MOTION_TABLE + row + 0x1C);
    write_u32(this + 0xE4, read_u32(W29_F4_MOTION_TABLE + row + 4));
    write_u32(this + 0xEC, a);
    write_u32(this + 0xF0, b);
    write_u32(this + 0xF4, zero);
    write_u32(this + 0xF8, c);
    write_u32(this + 0xFC, d);
    write_u32(this + 0x100, zero);
    write_u32(this + 0x104, e);
    write_u32(this + 0x108, f);
    write_u32(this + 0x10C, zero);
}

