/// Advances the four segment positions and yaw angles by one frame.
///
/// # Original
/// - Ghidra: `FUN_80091660` at `0x80091660` (292 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80091660_FUN_80091660.c`
/// - observed: two iterations cover four segments; the vertical velocity is
///   integrated with the clamp at `+0x20`, the position xyz is advanced, and
///   the `u16` angle at `+0x114`/`+0x11A` (then `+0x120`/`+0x126`) is bumped by
///   `+0x600` or `-0x600` depending on the sign of the x velocity at `r2-0x6F7C`.
///
/// # Arguments
/// - `this`: block object.
///
/// # Side effects
/// Writes four positions, four velocities and four `u16` angles.
///
/// # Safety
/// `this+0x20..+0x126` must be readable/writable.
///
/// # Confidence
/// high - every offset and both angle steps are literal.
pub unsafe fn stage_block_four_segment_advance(this: usize) {
    let threshold = read_f32(W29_F_ZERO);
    for i in 0..2usize {
        let pos = this + i * 0x18;
        let ang = this + i * 0x0C;
        let mut vy = read_f32(pos + 0xE4) + read_f32(this + 0x3C);
        write_f32(pos + 0xE4, vy);
        if vy < read_f32(this + 0x20) {
            vy = read_f32(this + 0x20);
            write_f32(pos + 0xE4, vy);
        }
        write_f32(pos + 0xB0, read_f32(pos + 0xB0) + read_f32(pos + 0xE0));
        write_f32(pos + 0xB4, read_f32(pos + 0xB4) + vy);
        write_f32(pos + 0xB8, read_f32(pos + 0xB8) + read_f32(pos + 0xE8));
        if read_f32(pos + 0xE0) < threshold {
            write_u16(ang + 0x114, read_u16(ang + 0x114).wrapping_add(0x600));
        } else {
            write_u16(ang + 0x114, read_u16(ang + 0x114).wrapping_sub(0x600));
        }
        let mut vy = read_f32(pos + 0xF0) + read_f32(this + 0x3C);
        write_f32(pos + 0xF0, vy);
        if vy < read_f32(this + 0x20) {
            vy = read_f32(this + 0x20);
            write_f32(pos + 0xF0, vy);
        }
        write_f32(pos + 0xBC, read_f32(pos + 0xBC) + read_f32(pos + 0xEC));
        write_f32(pos + 0xC0, read_f32(pos + 0xC0) + vy);
        write_f32(pos + 0xC4, read_f32(pos + 0xC4) + read_f32(pos + 0xF4));
        if read_f32(pos + 0xEC) < threshold {
            write_u16(ang + 0x11A, read_u16(ang + 0x11A).wrapping_add(0x600));
        } else {
            write_u16(ang + 0x11A, read_u16(ang + 0x11A).wrapping_sub(0x600));
        }
    }
}

