/// Initialises the six-segment motion table and copies it into the block.
///
/// # Original
/// - Ghidra: `FUN_80091c10` at `0x80091C10` (248 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80091c10_FUN_80091c10.c`
/// - observed: on first use the nine `r2-0x6F68..0x6F48` constants are copied
///   into `0x803560A0..0x803560CC`, with `+0xBC/+0xC4/+0xCC` mirrored from
///   earlier entries. The eighteen words are then copied into
///   `+0x110..+0x154`, with `2.0f` at every third slot.
///
/// # Arguments
/// - `this`: block object.
///
/// # Side effects
/// May write the global table and the one-time flag at `r13-0x57A0`; writes
/// eighteen words of the block.
///
/// # Safety
/// The BSS flag and `this+0x110..+0x154` must be writable.
///
/// # Confidence
/// high - all stores are literal; the table values were read from the ELF.
pub unsafe fn stage_block_six_segment_motion_init(this: usize) {
    if read_u8(W29_F6_TABLE_INIT) == 0 {
        write_u32(W29_F6_MOTION_TABLE, read_u32(W29_F_MOTION_0));
        write_u32(W29_F6_MOTION_TABLE + 4, read_u32(W29_F_MOTION_1));
        write_u32(W29_F6_MOTION_TABLE + 0x0C, read_u32(W29_F_MOTION_3));
        write_u32(W29_F6_MOTION_TABLE + 0x14, read_u32(W29_F_MOTION_5));
        write_u32(W29_F6_MOTION_TABLE + 8, read_u32(W29_F_MOTION_2));
        write_u32(W29_F6_MOTION_TABLE + 0x10, read_u32(W29_F_MOTION_4));
        write_u32(W29_F6_MOTION_TABLE + 0x18, read_u32(W29_F_MOTION_6));
        write_u32(W29_F6_MOTION_TABLE + 0x20, read_u32(W29_F_MOTION_7));
        write_u32(W29_F6_MOTION_TABLE + 0x28, read_u32(W29_F_MOTION_8));
        write_u32(W29_F6_MOTION_TABLE + 0x1C, read_u32(W29_F_MOTION_3));
        write_u32(W29_F6_MOTION_TABLE + 0x24, read_u32(W29_F_MOTION_1));
        write_u32(W29_F6_MOTION_TABLE + 0x2C, read_u32(W29_F_MOTION_5));
        write_u8(W29_F6_TABLE_INIT, 1);
    }
    let two = read_u32(W29_F_MOTION_STRIDE);
    write_u32(this + 0x110, read_u32(W29_F6_MOTION_TABLE));
    write_u32(this + 0x114, read_u32(W29_F6_MOTION_TABLE + 4));
    write_u32(this + 0x118, two);
    write_u32(this + 0x11C, read_u32(W29_F6_MOTION_TABLE + 8));
    write_u32(this + 0x120, read_u32(W29_F6_MOTION_TABLE + 0x0C));
    write_u32(this + 0x124, two);
    write_u32(this + 0x128, read_u32(W29_F6_MOTION_TABLE + 0x10));
    write_u32(this + 0x12C, read_u32(W29_F6_MOTION_TABLE + 0x14));
    write_u32(this + 0x130, two);
    write_u32(this + 0x134, read_u32(W29_F6_MOTION_TABLE + 0x18));
    write_u32(this + 0x138, read_u32(W29_F6_MOTION_TABLE + 0x1C));
    write_u32(this + 0x13C, two);
    write_u32(this + 0x140, read_u32(W29_F6_MOTION_TABLE + 0x20));
    write_u32(this + 0x144, read_u32(W29_F6_MOTION_TABLE + 0x24));
    write_u32(this + 0x148, two);
    write_u32(this + 0x14C, read_u32(W29_F6_MOTION_TABLE + 0x28));
    write_u32(this + 0x150, read_u32(W29_F6_MOTION_TABLE + 0x2C));
    write_u32(this + 0x154, two);
}

