/// Clears the six-segment angle table.
///
/// # Original
/// - Ghidra: `FUN_80091d10` at `0x80091D10` (80 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80091d10_FUN_80091d10.c`
/// - observed: eighteen `u16` stores of zero at `+0x158..+0x17A`.
///
/// # Arguments
/// - `this`: block object.
///
/// # Safety
/// `this+0x158..+0x17A` must be writable.
///
/// # Confidence
/// high - literal zero fill.
pub unsafe fn stage_block_six_segment_angles_clear(this: usize) {
    let mut cursor = this + 0x158;
    for _ in 0..18 {
        write_u16(cursor, 0);
        cursor += 2;
    }
}

// ---------------------------------------------------------------------------
// 0x80091D60
// ---------------------------------------------------------------------------

/// Advances the six segment positions and yaw angles by one frame.
///
/// # Original
/// - Ghidra: `FUN_80091d60` at `0x80091D60` (292 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80091d60_FUN_80091d60.c`
/// - observed: three iterations cover six segments; each vertical velocity is
///   integrated with the clamp at `+0x20`, each position xyz is advanced, and
///   the `u16` angle at `+0x15C`/`+0x162` (then `+0x168`/`+0x16E`, then
///   `+0x174`/`+0x17A`) is bumped by `+0x600` or `-0x600` depending on the sign
///   of the x velocity at `r2-0x6F7C`.
///
/// # Arguments
/// - `this`: block object.
///
/// # Side effects
/// Writes six positions, six velocities and six `u16` angles.
///
/// # Safety
/// `this+0x20..+0x17A` must be readable/writable.
///
/// # Confidence
/// high - every offset and both angle steps are literal.
pub unsafe fn stage_block_six_segment_advance(this: usize) {
    let threshold = read_f32(W29_F_ZERO);
    for i in 0..3usize {
        let pos = this + i * 0x18;
        let ang = this + i * 0x0C;
        let mut vy = read_f32(pos + 0x114) + read_f32(this + 0x3C);
        write_f32(pos + 0x114, vy);
        if vy < read_f32(this + 0x20) {
            vy = read_f32(this + 0x20);
            write_f32(pos + 0x114, vy);
        }
        write_f32(pos + 0xC8, read_f32(pos + 0xC8) + read_f32(pos + 0x110));
        write_f32(pos + 0xCC, read_f32(pos + 0xCC) + vy);
        write_f32(pos + 0xD0, read_f32(pos + 0xD0) + read_f32(pos + 0x118));
        if read_f32(pos + 0x110) < threshold {
            write_u16(ang + 0x15C, read_u16(ang + 0x15C).wrapping_add(0x600));
        } else {
            write_u16(ang + 0x15C, read_u16(ang + 0x15C).wrapping_sub(0x600));
        }
        let mut vy = read_f32(pos + 0x120) + read_f32(this + 0x3C);
        write_f32(pos + 0x120, vy);
        if vy < read_f32(this + 0x20) {
            vy = read_f32(this + 0x20);
            write_f32(pos + 0x120, vy);
        }
        write_f32(pos + 0xD4, read_f32(pos + 0xD4) + read_f32(pos + 0x11C));
        write_f32(pos + 0xD8, read_f32(pos + 0xD8) + vy);
        write_f32(pos + 0xDC, read_f32(pos + 0xDC) + read_f32(pos + 0x124));
        if read_f32(pos + 0x11C) < threshold {
            write_u16(ang + 0x162, read_u16(ang + 0x162).wrapping_add(0x600));
        } else {
            write_u16(ang + 0x162, read_u16(ang + 0x162).wrapping_sub(0x600));
        }
    }
}

// ---------------------------------------------------------------------------
// 0x80091FB0
// ---------------------------------------------------------------------------

/// Snaps the water-wave block to the ground and flips it once it settles.
///
/// # Original
/// - Ghidra: `FUN_80091fb0` at `0x80091FB0` (96 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80091fb0_FUN_80091fb0.c`
/// - observed: calls `0x80092150(this)`, then virtual slot `+0xB0` of the
///   interface at `+0x68` with `(this+0x68, this+4, 0, this+0x28)`. If that
///   call returns zero, `+0x50` is set to `1` (the original tests
///   `countLeadingZeros(result) >> 5`, which is true only for zero).
///
/// # Arguments
/// - `this`: water-wave block object.
///
/// # Side effects
/// Calls the interface callback and writes `+0x50`.
///
/// # Safety
/// `this+0x68` must point at a live interface with a callable `+0xB0` slot.
///
/// # Confidence
/// medium - the indirect slot is explicit; the interface type is unknown.
pub unsafe fn stage_block_waterwave_step(this: usize) {
    stage_block_waterwave_ground_snap(this);
    let owner = this + 0x68;
    let vtable = read_u32(owner) as usize;
    let slot = read_u32(vtable + 0xB0) as usize;
    let result = platform::call4(
        slot,
        owner as u32,
        (this + 4) as u32,
        0,
        (this + 0x28) as u32,
    );
    if result == 0 {
        write_u32(this + 0x50, 1);
    }
}

// ---------------------------------------------------------------------------
// 0x80092030
// ---------------------------------------------------------------------------

/// Submits the water-wave effect selected by the block mode.
///
/// # Original
/// - Ghidra: `FUN_80092030` at `0x80092030` (284 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80092030_FUN_80092030.c`
/// - observed: in stage 7 area 2, mode 4 scales the three offsets at
///   `+0x28..+0x30` by `r2-0x6F38` (`0.6f`) and mode 5 becomes mode 4. Modes
///   6 and 7 call `0x8016C890(name, 0, &position, 0, &offset)`; every other
///   mode calls virtual slot `+0xA0` of `+0x68` with the same arguments plus
///   the interface as `r3`. The name comes from `0x803115C8[mode]`.
///
/// # Arguments
/// - `this`: water-wave block object.
///
/// # Returns
/// `1` when the direct `0x8016C890` path ran (modes 6/7), otherwise `0`.
///
/// # Side effects
/// May write `+0x60` (mode 5 -> 4) and calls the effect submitter.
///
/// # Safety
/// `this+0x68` must be live and the stage-info pointer readable.
///
/// # Confidence
/// medium - the mode/name selection is observed; the effect name table and the
/// interface slot are inferred from call sites.
pub unsafe fn stage_block_waterwave_effect(this: usize) -> u32 {
    let mut position = [
        read_u32(this + 4),
        read_u32(this + 8),
        read_u32(this + 0x0C),
    ];
    let mut offset = [
        read_f32(this + 0x28),
        read_f32(this + 0x2C),
        read_f32(this + 0x30),
    ];
    let info = read_u32(G_STAGE_INFO) as usize;
    if info != 0 && read_u8(info + 0x120C) == 7 && read_u8(info + 0x120D) == 2 {
        if read_i32(this + 0x60) == 4 {
            let scale = read_f32(W29_F_WATER_SCALE);
            offset[0] *= scale;
            offset[1] *= scale;
            offset[2] *= scale;
        }
        if read_i32(this + 0x60) == 5 {
            write_u32(this + 0x60, 4);
        }
    }
    let mode = read_i32(this + 0x60);
    let name = read_u32(W29_WATERWAVE_NAMES + mode as usize * 4);
    let direct = (mode as u32).wrapping_sub(6) <= 1;
    if !direct {
        let owner = this + 0x68;
        let vtable = read_u32(owner) as usize;
        let slot = read_u32(vtable + 0xA0) as usize;
        platform::call6(
            slot,
            owner as u32,
            name,
            0,
            position.as_mut_ptr() as u32,
            0,
            offset.as_mut_ptr() as u32,
        );
    } else {
        platform::call5(
            W29_EFFECT_PATH,
            name,
            0,
            position.as_mut_ptr() as u32,
            0,
            offset.as_mut_ptr() as u32,
        );
    }
    direct as u32
}

// ---------------------------------------------------------------------------
// 0x80092150
// ---------------------------------------------------------------------------

/// Probes downward for the water-wave ground surface.
///
/// # Original
/// - Ghidra: `FUN_80092150` at `0x80092150` (176 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80092150_FUN_80092150.c`
/// - observed: starts at `y - 8.0f` (`r2-0x6F30`) and retries up to five times,
///   adding `4.0f` (`r2-0x6F2C`) per attempt, through `0x80075270(x, y,
///   flags, &result)`. Status `1`/`3` writes the resulting y back at `+0x08`;
///   status `2` stops without writing. The result word starts at
///   `r2-0x6F34` (`0.0f`).
/// - observed: the `unaff_GQR0`/`ldexpf` guards around the loads are treated as
///   load-format artefacts; the arithmetic is single precision.
///
/// # Arguments
/// - `this`: water-wave block object.
///
/// # Side effects
/// Writes `+0x08` when the probe returns a finite surface.
///
/// # Safety
/// `this+0x04..+0x08` must be readable/writable; the probe must be callable.
///
/// # Confidence
/// medium - the retry loop is literal; the probe status meanings are inferred
/// from the branch structure.
pub unsafe fn stage_block_waterwave_ground_snap(this: usize) {
    let mut result = [read_u32(W29_F_PROBE_ZERO), 0, 0, 0];
    let step = read_f32(W29_F_GROUND_STEP) as f64;
    let mut y = read_f32(this + 8) - read_f32(W29_F_GROUND_FIRST);
    let mut retry = 0;
    loop {
        let probe_y = y as f64;
        let status = call_f32x2_u32x2(
            0x8007_5270,
            read_f32(this + 4),
            y,
            read_u32(this + 0x64) & 0xFF,
            result.as_mut_ptr() as u32,
        );
        if status != 0 {
            if status != 2 {
                write_f32(this + 8, f32::from_bits(result[0]));
            }
            break;
        }
        retry += 1;
        y = (probe_y + step) as f32;
        if retry >= 5 {
            break;
        }
    }
}

