///
/// # Safety
/// `offset` must be readable for 12 bytes; `this+4..+0xC` writable.
///
/// # Confidence
/// high - literal three-word add.
pub unsafe fn stage_block_position_add(this: usize, offset: usize) {
    write_f32(this + 4, read_f32(this + 4) + read_f32(offset));
    write_f32(this + 8, read_f32(this + 8) + read_f32(offset + 4));
    write_f32(this + 0x0C, read_f32(this + 0x0C) + read_f32(offset + 8));
}

