// ---------------------------------------------------------------------------

// Wave-31 local call helpers

// ---------------------------------------------------------------------------

/// Calls a PowerPC function with one `f64` argument and returns an `i32` from
/// `r3`.
///
/// # Safety
/// `addr` must use this floating-point ABI.
unsafe fn call1_f64_i32(addr: usize, a: f64) -> i32 {
    let f: extern "C" fn(f64) -> i32 = core::mem::transmute(addr);
    f(a)
}

/// Calls a PowerPC function with two `f64` arguments and returns an `i32`.
///
/// # Safety
/// `addr` must use this floating-point ABI.
unsafe fn call2_f64_i32(addr: usize, a: f64, b: f64) -> i32 {
    let f: extern "C" fn(f64, f64) -> i32 = core::mem::transmute(addr);
    f(a, b)
}

/// Calls a PowerPC function with one `f64` and one pointer and returns `r3`.
///
/// # Safety
/// `addr` must use this mixed ABI.
unsafe fn call1_f64_ptr(addr: usize, a: f64, ptr: u32) -> u32 {
    let f: extern "C" fn(f64, u32) -> u32 = core::mem::transmute(addr);
    f(a, ptr)
}

/// Calls a PowerPC function with one `f64`, one pointer and one word.
///
/// # Safety
/// `addr` must use this mixed ABI.
unsafe fn call1_f64_ptr2(addr: usize, a: f64, ptr: u32, b: u32) {
    let f: extern "C" fn(f64, u32, u32) = core::mem::transmute(addr);
    f(a, ptr, b);
}

/// Calls a PowerPC function with four pointers and returns `f1` as `f64`.
///
/// Used for `0x802390D0`, which returns the distance to a rectangle edge.
///
/// # Safety
/// All four pointers must be readable.
unsafe fn call3_ptr_f64(addr: usize, a: u32, b: u32, c: u32, d: u32) -> f64 {
    let f: extern "C" fn(u32, u32, u32, u32) -> f64 = core::mem::transmute(addr);
    f(a, b, c, d)
}

/// Calls a PowerPC function with four `f64` arguments and one pointer.
///
/// Used for `0x8015F140`, the stage animation smoother.
///
/// # Safety
/// `addr` must use this mixed ABI and `ptr` must be readable/writable.
unsafe fn call4_f64_ptr(addr: usize, a: f64, b: f64, c: f64, d: f64, ptr: u32) {
    let func: extern "C" fn(f64, f64, f64, f64, u32) = core::mem::transmute(addr);
    func(a, b, c, d, ptr);
}

/// Calls a PowerPC function with six `f64` arguments and one pointer.
///
/// # Safety
/// `addr` must use this mixed ABI and `out` must be writable.
unsafe fn call6_f64_ptr(addr: usize, a: f64, b: f64, c: f64, d: f64, e: f64, f: f64, out: u32) {
    let func: extern "C" fn(f64, f64, f64, f64, f64, f64, u32) = core::mem::transmute(addr);
    func(a, b, c, d, e, f, out);
}

/// Calls a PowerPC function with six `f64` arguments.
///
/// # Safety
/// `addr` must use this floating-point ABI.
unsafe fn call6_f64(addr: usize, a: f64, b: f64, c: f64, d: f64, e: f64, f: f64) {
    let func: extern "C" fn(f64, f64, f64, f64, f64, f64) = core::mem::transmute(addr);
    func(a, b, c, d, e, f);
}

/// Calls a PowerPC function with eight `f64` arguments and one pointer.
///
/// # Safety
/// `addr` must use this mixed ABI and `out` must be writable.
unsafe fn call8_f64_ptr(
    addr: usize,
    a: f64,
    b: f64,
    c: f64,
    d: f64,
    e: f64,
    f: f64,
    g: f64,
    h: f64,
    out: u32,) {
    let func: extern "C" fn(f64, f64, f64, f64, f64, f64, f64, f64, u32) =
        core::mem::transmute(addr);
    func(a, b, c, d, e, f, g, h, out);
}

/// Calls a PowerPC function with nine integer arguments (`r3..r10` + stack).
///
/// # Safety
/// `addr` must use the PowerPC integer ABI.
unsafe fn call9(addr: usize, a: u32, b: u32, c: u32, d: u32, e: u32, f: u32, g: u32, h: u32, i: u32) {
    let func: extern "C" fn(u32, u32, u32, u32, u32, u32, u32, u32, u32) = core::mem::transmute(addr);
    func(a, b, c, d, e, f, g, h, i);
}

/// Calls the virtual method at `slot` with four extra words.
///
/// # Safety
/// `obj` must start with a readable vtable and the chosen slot must accept
/// `(obj, a, b, c, d)`.
unsafe fn call_vtable_slot4(obj: usize, slot: usize, a: u32, b: u32, c: u32, d: u32) {
    let vtable = read_u32(obj) as usize;
    let function = read_u32(vtable + slot) as usize;
    platform::call5(function, obj as u32, a, b, c, d);
}

// ---------------------------------------------------------------------------
// 0x80080900
// ---------------------------------------------------------------------------

/// Snaps a point onto the nearest edge of a BG-scene rectangle and derives a
/// facing angle.
///
/// The area descriptor selects one of two modes. Mode `1` runs the spline
/// helper `0x802394E0` and moves the point's second triple along the segment
/// by the returned parameter. Every other mode treats four corner points from
/// `area+0x60..area+0x7C` as a quad, tests the four edges with `0x802390D0`,
/// and snaps to the closest one.
///
/// # Original
/// - Ghidra: `FUN_80080900` at `0x80080900` (1024 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80080900_FUN_80080900.c`
/// - observed: the mode byte is `area+0xC8`; the four corners are built from
///   the eight words at `area+0x60..0x7C` with `point+8` as their z; the edge
///   selector uses `(u16 at *(u32*)(area+0xBC))` and is flipped by
///   `point.y < point[4]`; the two angle calls are `0x801611C0` with
///   `(dx, -dy)` and the offsets `-0x8000` / `+0x4000`.
///
/// # Arguments
/// - `point`: six floats: the current triple at `+0` and the result triple at
///   `+0xC`.
/// - `area`: area descriptor (a null `[area]` word means "inactive").
/// - `angle_out`: optional `s16` output address; `0` skips the angle.
/// - `mode`: `1` enables the edge mask; other values test every edge.
///
/// # Returns
/// `1` when a snap was performed, `0` otherwise.
///
/// # Side effects
/// Writes three floats at `point+0xC..+0x14` and optionally the `s16` angle.
///
/// # Safety
/// `point+0..0x18` must be writable; `area` must be readable through
/// `+0x7F`; `angle_out` must be null or writable.
///
/// # Confidence
/// medium - the arithmetic is literal, but the psq_l/GQR guards are treated as
/// single-precision load artefacts, as in the wave-29 batch.
pub unsafe fn bg_scene_edge_snap(
    point: usize,
    area: usize,
    angle_out: usize,
    mut mode: u32,) -> u32 {
    if read_u32(area) == 0 {
        return 0;
    }
    if read_u32(area + 0xC8) == 1 {
        // observed: `lfs 0x58(r3)` / `lfs 0x5C(r3)`; Ghidra prints the pair as
        // `(float)piVar10[...]` because of the surrounding psq_l code.
        let mut anchor = [0f32;
 3];
        anchor[0] = read_f32(area + 0x58);
        anchor[1] = read_f32(area + 0x5C);
        anchor[2] = read_f32(point + 8);
        let saved = [anchor[0], anchor[1]];
        let mut t = 0.0f32;
        let mut extra = 0.0f32;
        let found = platform::call4(
            0x8023_94E0,
            point as u32,
            anchor.as_ptr() as u32,
            &mut t as *mut f32 as u32,
            &mut extra as *mut f32 as u32,
        );
        if found == 0 {
            return 0;
        }
        let dx = read_f32(point + 0x0C) - read_f32(point);
        let dy = read_f32(point + 0x10) - read_f32(point + 4);
        let dz = read_f32(point + 0x14) - read_f32(point + 8);
        write_f32(point + 0x0C, dx * t + read_f32(point));
        write_f32(point + 0x10, dy * t + read_f32(point + 4));
        write_f32(point + 0x14, dz * t + read_f32(point + 8));
        if angle_out != 0 {
            let ax = read_f32(point + 0x0C) - saved[0];
            let ay = read_f32(point + 0x10) - saved[1];
            let angle = call2_f64_i16(0x8016_11C0, ax as f64, -(ay as f64));
            write_u16(angle_out, (angle as i32 - 0x8000) as u16);
        }
        return 1;
    }
    // observed: eight `lfs` loads at area+0x60..0x7C; every z is the point's z.
    let z = read_f32(point + 8);
    let mut corners = [[0f32;
 3];
 4];
    let mut corner = 0usize;
    while corner < 4 {
        corners[corner][0] = read_f32(area + 0x60 + corner * 8);
        corners[corner][1] = read_f32(area + 0x64 + corner * 8);
        corners[corner][2] = z;
        corner += 1;
    }
    if read_f32(point) != read_f32(point + 0x0C) {
        mode = 0;
    }
    let mut selected = 0u32;
    let mut opposite = 0u32;
    if mode == 1 {
        let owner = read_u32(area + 0xBC) as usize;
        let raw = read_u16(owner) as i16 as i32;
        selected = (raw.wrapping_neg() as u32 >> 0xE) & 3;
        if read_f32(point + 4) < read_f32(point + 0x10) {
            selected = (selected + 2) & 3;
        }
        opposite = selected.wrapping_sub(1) & 3;
    }
    let mut found = 0u32;
    let mut edge = 0u32;
    while edge < 4 {
        if mode == 0 || selected == edge || opposite == edge {
            let next = ((edge + 1) & 3) as usize;
            let current = corners[edge as usize];
            let following = corners[next];
            let mut distance = 0.0f32;
            let value = call3_ptr_f64(
                0x8023_90D0,
                point as u32,
                current.as_ptr() as u32,
                &mut distance as *mut f32 as u32,
                0,
            ) as f32;
            if value < read_f32(W31_F_ONE) {
                let dx = read_f32(point + 0x0C) - read_f32(point);
                let dy = read_f32(point + 0x10) - read_f32(point + 4);
                let dz = read_f32(point + 0x14) - read_f32(point + 8);
                write_f32(point + 0x0C, dx * distance + read_f32(point));
                write_f32(point + 0x10, dy * distance + read_f32(point + 4));
                write_f32(point + 0x14, dz * distance + read_f32(point + 8));
                if angle_out != 0 {
                    let ax = following[0] - current[0];
                    let ay = following[1] - current[1];
                    let angle = call2_f64_i16(0x8016_11C0, ax as f64, -(ay as f64));
                    write_u16(angle_out, (angle as i32 + 0x4000) as u16);
                }
                found = 1;
            }
        }
        edge += 1;
    }
    found
}

// ---------------------------------------------------------------------------
// 0x80083870
// ---------------------------------------------------------------------------

/// Finds the first BG-unit tile cell that overlaps a collision rectangle and
/// allocates its palette slot.
///
/// The model is cleared first, then a 64 × 32 grid of 16-unit cells is walked.
/// Each cell is tested against every rectangle in stage-section 5 (12 `u16`
/// values per entry, `0x18` bytes); a hit allocates the cell's palette and
/// stops the scan. After the scan the model's `+0xC28` byte records whether the current
/// stage is *not* world 2 / stage 0x18 / area 1.
///
/// # Original
/// - Ghidra: `FUN_80083870` at `0x80083870` (608 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80083870_FUN_80083870.c`
/// - observed: cell index `0..0x7FF`; cell x = `(i & 0x3F) * 16`, cell y =
///   `(i >> 6) * 16`; the rectangle high corner adds 1.0 for a set low nibble;
///   the rectangle test is `0x800B3100`; `0x80081BE0(2,0x18,1)` sets `+0xC28`.
///
/// # Arguments
/// - `model`: BG-unit model (its `+0xC20` is the stage slot).
///
/// # Side effects
/// Clears the model tables, may write palette bytes, and always writes
/// `model+0xC28`.
///
/// # Safety
/// `model` and the stage object behind `r13-0x57E8` must be readable; the
/// section-5 pointer must address `count*0xC` readable bytes.
///
/// # Confidence
/// medium - the grid arithmetic and both rectangle tests are literal; the
/// `0x800B3100` `f1` argument is ignored by that helper, so it is omitted.
pub unsafe fn bg_unit_collision_scan(model: usize) {
    bg_unit_model_resolve_names(model);
    bg_unit_model_clear(model);
    bg_unit_model_alloc_palette(model, 0);
    let stage_index = read_u32(model + 0xC20) as usize;
    let mut stage = read_u32(G_STAGE_OBJECTS) as usize + stage_index * 0x3B0;
    if read_u32(stage + 0x2C) == 0 {
        stage = 0;
    }
    let cell_size = read_f32(W31_F_CELL);
    let one = read_f32(W31_F_ONE_B);
    let mut cell = 0u32;
    loop {
        let cell_x = (cell & 0x3F) as f32 * 16.0;
        let cell_y = (cell >> 6) as f32 * 16.0;
        let low = [cell_x, cell_y];
        let high = [cell_size + cell_x, cell_size + cell_y];
        let entries = read_u32(stage + 0x2C) as usize;
        let count = read_u32(stage + 0x9C) as usize;
        let mut entry = 0usize;
        let mut cursor = entries;
        while entry < count {
            let x0 = (read_u16(cursor) >> 4) as f32;
            let y0 = (read_u16(cursor + 2) >> 4) as f32;
            let mut x1 = x0 + (read_u16(cursor + 4) >> 4) as f32;
            let mut y1 = y0 + (read_u16(cursor + 6) >> 4) as f32;
            if read_u16(cursor + 4) & 0xF != 0 {
                x1 += one;
            }
            if read_u16(cursor + 6) & 0xF != 0 {
                y1 += one;
            }
            let rect_low = [x0, y0];
            let rect_high = [x1, y1];
            let hit = platform::call4(
                0x800B_3100,
                low.as_ptr() as u32,
                high.as_ptr() as u32,
                rect_low.as_ptr() as u32,
                rect_high.as_ptr() as u32,
            );
            if hit != 0 {
                bg_unit_model_alloc_palette(model, cell as i32);
                break;
            }
            // observed: `puVar8 + 0xc` on a `u16 *` advances 0x18 bytes.
            cursor += 0x18;
            entry += 1;
        }
        cell += 1;
        if 0x7FF < cell as i32 {
            let current =
                is_current_stage_unit(2, 0x18, 1);
            write_u8(model + 0xC28, (current == 0) as u8);
            return;
        }
    }
}

// ---------------------------------------------------------------------------
// 0x80088100
// ---------------------------------------------------------------------------

/// Returns whether a BG-unit record's `y` lies inside its upper/lower limit.
///
/// The record carries two heights and a kind byte at `+0xD`. Kind `3` uses the
/// sub-kind at `+0xC` (`1` always passes, `3` compares the two heights); any
/// other kind with a non-zero byte at `+0xE` compares the heights directly,
/// adding the per-object limit from the table at `0x8042BF48` when the owner
/// is in "active" state `2`.
///
/// # Original
/// - Ghidra: `FUN_80088100` at `0x80088100` (264 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80088100_FUN_80088100.c`
/// - observed: both floats are passed through `0x80101AA0` when the game mode
///   at `r13-0x5478` is `1`; the table index is the byte at `*record+0x348`;
///   the owner gate is the byte at `*record+0x1090`.
///
/// # Arguments
/// - `_this`: unused first argument forwarded by the call sites.
/// - `record`: record with `+4`/`+8` heights, `+0xC` sub-kind, `+0xD` kind,
///   `+0xE` enable byte, and a pointer at `+0`.
///
/// # Returns
/// `1` when the record is inside its limit, `0` otherwise.
///
/// # Safety
/// `record` and `*(record)` must be readable.
///
/// # Confidence
/// medium - the comparison tree is literal; the units of the two heights and
/// of the limit table are inferred.
pub unsafe fn bg_unit_priority_check(_this: u32, record: usize) -> u32 {
    let mut upper = read_f32(record + 8) as f64;
    let mut lower = read_f32(record + 4) as f64;
    if read_u32(G_GAME_MODE) == 1 {
        upper = call1_f64(0x8010_1AA0, upper);
        lower = call1_f64(0x8010_1AA0, lower);
    }
    let mut result = 0u32;
    if read_u8(record + 0x0D) as i8 == 3 {
        let sub = read_u8(record + 0x0C) as i8;
        if sub == 1 {
            result = 1;
        } else if sub == 3 && lower < upper {
            result = 1;
        }
    } else if read_u8(record + 0x0E) != 0 {
        let owner = read_u32(record) as usize;
        if read_u8(owner + 0x1090) as i8 == 0 && read_u8(record + 0x0C) as i8 == 2 {
            let index = read_u8(owner + 0x348) as usize;
            let limit = read_f32(W31_F_PRIORITY_TABLE + index * 4) as f64;
            // observed: the sum is narrowed to f32 before the comparison.
            if lower < (upper + limit) as f32 as f64 {
                result = 1;
            }
        } else if lower < upper {
            result = 1;
        }
    }
    result
}

// ---------------------------------------------------------------------------
// 0x80088970
// ---------------------------------------------------------------------------

/// Places the effect associated with one stage actor record.
///
/// The record pointer is also the argument block for
/// [`bg_unit_effect_spawn_a`] / [`bg_unit_effect_spawn_b`]; this function
/// rounds the record's x, moves the camera anchor through `0x80077860`, and
/// then fills the 16-byte effect record. Selector `2` also maps the record's
/// shape index through `0x802F0050`; shape `4` takes the extended camera path.
///
/// # Original
/// - Ghidra: `FUN_80088970` at `0x80088970` (440 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80088970_FUN_80088970.c`
/// - observed: `[record+0xC] == 0` maps shape 3, `== 2` uses the table;
///   `[record+0x10] == 2 && [record+8] != 1` selects the spawn-a path;
///   otherwise the spawn-b path passes `0`.
///
/// # Arguments
/// - `_this`: forwarded unused (kept for the original `r3`).
/// - `record`: actor record: x/y at `+0`/`+4`, shape index at `+8`, selector
///   at `+0xC`, class byte at `+0x10`, flags at `+0x11`/`+0x12`.
///
/// # Side effects
/// Calls the camera anchor helper and one of the two effect spawners.
///
/// # Safety
/// `record` must be readable through `+0x12`.
///
/// # Confidence
/// medium - the record layout is observed from the two spawners; the selector
/// meanings are inferred.
pub unsafe fn stage_actor_place_effect(_this: u32, record: usize) {
    let rounded = call1_f64(0x8010_1AA0, read_f32(record) as f64);
    let x = rounded as i32 as u32;
    let y = read_u32(record + 4);
    let selector = read_u32(record + 0x0C);
    let mut shape = 0u16;
    let mut extended = false;
    if selector == 0 {
        shape = 3;
    } else if selector == 2 {
        let index = read_u32(record + 8) as usize;
        shape = read_u16(W31_EFFECT_SHAPE_TABLE + index * 2);
        if index == 4 {
            extended = true;
        }
    }
    let camera = read_u32(G_CAMERA_OWNER);
    if extended {
        platform::call5(
            0x8007_7860,
            camera,
            x & 0xFFFF,
            y.wrapping_neg() & 0xFFFF,
            0,
            0x0B,
        );
    } else {
        platform::call5(
            0x8007_7860,
            camera,
            x & 0xFFFF,
            y.wrapping_neg() & 0xFFFF,
            0,
            0,
        );
    }
    let mut effect = [0u32;
 4];
    let base = effect.as_mut_ptr() as usize;
    write_f32(base, x as f32);
    write_f32(base + 4, y as f32);
    if read_u8(record + 0x10) == 2 && read_u32(record + 8) != 1 {
        write_u8(base + 8, read_u8(record + 0x10));
        write_u8(base + 9, 1);
        write_u8(base + 0x0A, read_u8(record + 0x12));
        write_u8(base + 0x0B, read_u8(record + 0x11));
        write_u16(base + 0x0C, shape);
        bg_unit_effect_spawn_a(_this as usize, base);
    } else {
        write_u8(base + 8, read_u8(record + 0x10));
        write_u8(base + 9, read_u8(record + 0x11));
        write_u16(base + 0x0A, shape);
        bg_unit_effect_spawn_b(base, 0);
    }
}

// ---------------------------------------------------------------------------
// 0x80088B30
// ---------------------------------------------------------------------------

/// Spawns the mirror/impact effect for one actor record.
///
/// The x coordinate is rounded, the y is negated and both are fed to the two
/// camera probes `0x80070BA0`/`0x80070BF0`. A positive result moves the
/// camera anchor through `0x80077860`, then the effect `0x191` or `0x197` is
/// spawned with the record's shape bits.
///
/// # Original
/// - Ghidra: `FUN_80088b30` at `0x80088B30` (436 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80088b30_FUN_80088b30.c`
/// - observed: hit when `probe_a == 0` or `probe_a & 0x1C != 0` and `probe_b
///   != 0`, or when `probe_a` is a different non-zero value; the variant byte
///   at `+9` maps `-1` to `3`; class byte `+8 == 4` selects effect `0x197`,
///   otherwise `0x191` with `|9`.
///
/// # Arguments
/// - `record`: actor record: x/y at `+0`/`+4`, class at `+8`, variant at `+9`.
///
/// # Side effects
/// May move the camera anchor and spawns one effect.
///
/// # Safety
/// `record` must be readable through `+9`.
///
/// # Confidence
/// medium - the probe result words are read from `r3` although Ghidra types
/// the two probes as `void`; the bit tests are literal.
pub unsafe fn stage_actor_mirror_effect(record: usize) {
    let rounded = call1_f64(0x8010_1AA0, read_f32(record) as f64);
    let x = rounded as i32 as u32;
    let y = read_u32(record + 4);
    let mut variant = read_u8(record + 9) as i8 as i32;
    if variant == -1 {
        variant = 3;
    }
    let neg_y = (y as i32).wrapping_neg() as f64;
    let probe_a = call2_f64_i32(0x8007_0BA0, x as f64, neg_y);
    let probe_b = call2_f64_i32(0x8007_0BF0, x as f64, neg_y);
    let mut place = false;
    if probe_a == 0 || (probe_a & 0x1C) != 0 {
        if probe_b != 0 {
            place = true;
        }
    } else {
        place = true;
    }
    if place {
        platform::call5(
            0x8007_7860,
            read_u32(G_CAMERA_OWNER),
            x & 0xFFFF,
            y & 0xFFFF,
            0,
            0,
        );
    }
    let mut position = [0u32;
 3];
    position[0] = (x as f32).to_bits();
    position[1] = ((y as i32).wrapping_neg() as f32).to_bits();
    position[2] = read_u32(W31_F_EFFECT_Z);
    let shape = ((variant as u32) & 0xF) << 0x0C;
    if read_u8(record + 8) == 4 {
        platform::call5(
            0x8006_4610,
            0x197,
            shape | 0x1_0000,
            position.as_ptr() as u32,
            0,
            0,
        );
    } else {
        platform::call5(
            0x8006_4610,
            0x191,
            shape | 9,
            position.as_ptr() as u32,
            0,
            0,
        );
    }
}

// ---------------------------------------------------------------------------
// 0x80088E80
// ---------------------------------------------------------------------------

/// Advances one animated stage auxiliary object by one frame.
///
/// The object stores a count at `+0x3A`, a current index at `+0x3B`, two
/// `s16` animation phases at `+0x18`/`+0x38` and their per-frame steps at
/// `+0x26`/`+0x56`. The function updates the first phase, smooths the float at
/// `+0x30`, derives `+0x2C` from the first sine, steps the second phase,
/// commits the index, and stores the second sine angle at `+0x34`.
///
/// # Original
/// - Ghidra: `FUN_80088e80` at `0x80088E80` (328 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80088e80_FUN_80088e80.c`
/// - observed: `0x800DF890` advances the phase vector at `+0x18`;
///   `0x8015F140` smooths `+0x30`; `0x80237BD0` is the angle sine; the final
///   angle is truncated into the `s16` at `+0x34`.
///
/// # Arguments
/// - `delta`: frame delta forwarded to `0x800DF890`.
/// - `state`: animated object.
///
/// # Side effects
/// Writes `+0x18`, `+0x2C`, `+0x30`, `+0x34`, `+0x36`, `+0x38` and `+0x3B`.
///
/// # Safety
/// `state+0x18..+0x58` must be readable/writable.
///
/// # Confidence
/// medium - the field arithmetic is literal; the paired-single guards are
/// treated as single-precision loads.
pub unsafe fn stage_aux_object_animate(delta: f64, state: usize) {
    let mut value = read_f32(W31_F_ZERO) as f64;
    let count = read_u8(state + 0x3A) as u32;
    if count != 0 {
        value = read_f32(state + 0x44) as f64;
        if count > 1 {
            let step = (count - 1) as f32;
            value = (value + (read_f32(W31_F_TWO) * step) as f64) as f32 as f64;
        }
    }
    if (read_u8(state + 0x3B) as u32) < count {
        let phase = read_u16(state + 0x18) as i16;
        let step = read_u16(state + 0x26) as i16;
        write_u16(state + 0x18, phase.wrapping_add(step) as u16);
    }
    call1_f64_ptr(0x800D_F890, delta, (state + 0x18) as u32);
    call4_f64_ptr(
        0x8015_F140,
        value,
        read_f32(state + 0x4C) as f64,
        read_f32(state + 0x48) as f64,
        read_f32(state + 0x50) as f64,
        (state + 0x30) as u32,
    );
    let phase = (read_u16(state + 0x36) as i16).wrapping_add(read_u16(state + 0x54) as i16);
    write_u16(state + 0x36, phase as u16);
    let angle = (phase as f64 * read_f32(W31_F_TURN_SCALE) as f64) as f32;
    let sine = call1_f64(0x8023_7BD0, angle as f64);
    write_f32(
        state + 0x2C,
        (sine * read_f32(state + 0x3C) as f64) as f32 - read_f32(state + 0x30),
    );
    stage_timer_advance(state);
    let phase2 = (read_u16(state + 0x38) as i16).wrapping_add(read_u16(state + 0x56) as i16);
    write_u16(state + 0x38, phase2 as u16);
    let angle2 = (phase2 as f64 * read_f32(W31_F_TURN_SCALE) as f64) as f32;
    let sine2 = call1_f64(0x8023_7BD0, angle2 as f64);
    write_u8(state + 0x3B, read_u8(state + 0x3A));
    write_u16(
        state + 0x34,
        (sine2 * read_f32(state + 0x40) as f64) as i32 as u16,
    );
}

