/// Renders the course capture with the current split-screen mode.
///
/// The viewport is derived from the screen size at `r13-0x5200`: a 16:9
/// capture scales the width by `832.0f` and centres the remaining height,
/// while the normal path copies width/height directly. Mode `2` halves both
/// edges, mode `1` halves the source rectangle, and an optional render target
/// is created through `0x802D3700`. The function then emits the four GX
/// viewport calls and restores the previous mode.
///
/// # Original
/// - Ghidra: `FUN_8008a380` at `0x8008A380` (604 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008a380_FUN_8008a380.c`
/// - observed: `0x801C8E70(1,7,1)`, `0x801C5B00(3)`, `0x801C5960`,
///   `0x801C59D0`, `0x801C5F40`, `0x800E48A0`/`0x801C5EC0`,
///   `0x801C6290` and the `0x802D2F80` enable/disable pair.
///
/// # Arguments
/// - `this`: capture object; `+8` is its texture size and `+0xC` the render
///   target handle.
/// - `split`: `0`, `1` or `2`.
/// - `create_target`: non-zero creates a new render target through
///   `0x802D3700`.
///
/// # Side effects
/// Emits GX viewport state and may allocate a render target.
///
/// # Safety
/// The screen-info pointer and the capture object must be live.
///
/// # Confidence
/// medium - every call and comparison is literal; the `0x802D3700` target
/// dimensions are inferred from the surrounding viewport values.
pub unsafe fn stage_capture_render(this: usize, split: i32, create_target: i32) {
    platform::call1(0x802D_2F80, 1);
    platform::call3(0x801C_8E70, 1, 7, 1);
    let screen = read_u32(read_u32(W31_G_SCREEN_INFO) as usize) as usize;
    let width = read_u16(screen + 4) as u32;
    let height = read_u16(screen + 6) as u32;
    // observed: `uVar11` always starts from the raw width; `uVar10` starts
    // from the height in 16:9 mode and from the scaled width otherwise.
    let mut y_limit = height;
    let mut rect_y = 0u32;
    let mut mode_flag = 0u32;
    if call0_ret(0x801D_D1D0) == 0 {
        let scale = (width as f32) / read_f32(W31_F_SCREEN_832);
        let base = read_u16(W31_SCREEN_HEIGHT_4EE) as u32;
        y_limit = (scale * base as f32) as u32;
        rect_y = (read_f32(W31_F_HALF) * ((height as f32) - scale * base as f32)) as u32;
    }
    let mut left =
        width.wrapping_add(read_u32(W31_GRID_ROUNDING + (width & 3) as usize * 4) & 0xFFFF);
    let mut right =
        y_limit.wrapping_add(read_u32(W31_GRID_ROUNDING + (y_limit & 3) as usize * 4) & 0xFFFF);
    let mut tex_w = right;
    let mut tex_h = left;
    if split == 2 {
        mode_flag = 1;
        tex_w = (right >> 1) & 0x7FFF;
        tex_h = (left >> 1) & 0x7FFF;
    } else if split == 1 {
        left = (left >> 1) & 0x7FFF;
        right = (right >> 1) & 0x7FFF;
        tex_w = right;
        tex_h = left;
    }
    if create_target != 0 {
        let target = platform::call3(
            0x802D_3700,
            tex_h & 0xFFFF,
            tex_w & 0xFFFF,
            read_u32(this + 8),
        );
        write_u32(this + 0x0C, target);
    }
    platform::call1(0x801C_5B00, 3);
    platform::call4(
        0x801C_5960,
        0,
        (rect_y.wrapping_add(rect_y & 1)) & 0xFFFF,
        left & 0xFFFF,
        right & 0xFFFF,
    );
    platform::call4(
        0x801C_59D0,
        tex_h & 0xFFFF,
        tex_w & 0xFFFF,
        read_u32(this + 8),
        mode_flag,
    );
    platform::call4(0x801C_5F40, 0, 0, 0, 0);
    let mut colour = [0u32;
 2];
    platform::call1(0x800E_48A0, (colour.as_mut_ptr() as usize + 4) as u32);
    colour[0] = colour[1];
    platform::call2(0x801C_5EC0, colour.as_ptr() as u32, 0x00FF_FFFF);
    platform::call2(
        0x801C_6290,
        read_u32(read_u32(this + 0x0C) as usize + 0x10),
        1,
    );
    platform::call0(0x801C_4F70);
    platform::call0(0x801C_76C0);
    platform::call1(0x802D_2F80, 0);
}

