// ---------------------------------------------------------------------------
// 0x80094660
// ---------------------------------------------------------------------------

/// Builds the 12-word quad matrix used by the stage effects.
///
/// With no BG scene the quad is the full screen: half the width and height
/// with the constant `-0.5..0.5` extent. With a BG scene the height/width are
/// taken from `+0x40`/`+0x44` and either narrowed by `0.11403508f` or scaled
/// through the letterbox object at `r13-0x47B0`.
///
/// # Original
/// - Ghidra: `FUN_80094660` at `0x80094660` (648 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80094660_FUN_80094660.c`
/// - observed: `0x801C10D0` takes eight doubles
///   `(d6,d7,d8,d9,0.5,-0.5,0.5,0.5)`; the scene branch either adds
///   `0.11403508f` to `-0.5`/subtracts it from `0.5`, or multiplies the
///   letterbox `+8/-0xC/+0x28/+0x2C` values; the result is copied to
///   `+0x30..+0x5C`.
///
/// # Arguments
/// - `_this`: unused.
/// - `out`: destination object; receives twelve words at `+0x30`.
///
/// # Safety
/// `out+0x30..+0x5C` must be writable; the screen and letterbox pointers must
/// be readable when the corresponding branch is taken.
///
/// # Confidence
/// medium - the arithmetic is literal; the letterbox field roles are
/// inferred.
pub unsafe fn stage_effect_screen_matrix(_this: u32, out: usize) {
    let mut matrix = [0u32;
 12];
    let scene = read_u32(G_BG_SCENE) as usize;
    if scene == 0 {
        let screen = read_u32(read_u32(W31_G_SCREEN_INFO) as usize) as usize;
        let width = read_u16(screen + 4) as f32;
        let height = read_u16(screen + 6) as f32;
        let half = read_f32(W31_F_HALF_B);
        call8_f64_ptr(
            0x801C_10D0,
            (half * height) as f64,
            -(half * height) as f64,
            -(half * width) as f64,
            (half * width) as f64,
            half as f64,
            -(half as f64),
            half as f64,
            half as f64,
            matrix.as_mut_ptr() as u32,
        );
    } else {
        let half_width = read_f32(scene + 0x44) * read_f32(W31_F_HALF_B);
        let half_height = read_f32(scene + 0x40) * read_f32(W31_F_HALF_B);
        let mut back = read_f32(W31_F_MINUS_HALF) as f64;
        let mut front = read_f32(W31_F_HALF_B) as f64;
        let (d6, d7, d8, d9);
        if call0_ret(0x801D_D1D0) == 0 {
            let inset = read_f32(W31_F_INSET) as f64;
            back = -(read_f32(W31_F_HALF_B) as f64) + inset;
            front = read_f32(W31_F_HALF_B) as f64 - inset;
            d6 = half_width as f64;
            d7 = -(half_width as f64);
            d8 = -(half_height as f64);
            d9 = half_height as f64;
        } else {
            let mut quad = [0f32;
 4];
            let base = quad.as_mut_ptr() as usize;
            platform::call4(
                0x802D_1280,
                (base + 0x0C) as u32,
                (base + 8) as u32,
                (base + 4) as u32,
                base as u32,
            );
            let letterbox = read_u32(W31_G_LETTERBOX) as usize;
            let scale_y = read_f32(letterbox + 0x2C);
            let scale_x = read_f32(letterbox + 0x28);
            let b8 = quad[0];
            let b4 = quad[1];
            let b0 = quad[2] * scale_y;
            let ac = quad[3] * scale_x;
            let centre_y = read_f32(letterbox + 0x0C);
            let centre_x = read_f32(letterbox + 8);
            d6 = ((read_f32(W31_F_HALF_B) * centre_y + b8) * b0) as f64;
            d8 = ((read_f32(W31_F_HALF_B) * -centre_x + b4) * ac) as f64;
            d7 = ((read_f32(W31_F_HALF_B) * -centre_y + b8) * b0) as f64;
            d9 = ((read_f32(W31_F_HALF_B) * centre_x + b4) * ac) as f64;
        }
        call8_f64_ptr(
            0x801C_10D0,
            d6,
            d7,
            d8,
            d9,
            read_f32(W31_F_HALF_B) as f64,
            back,
            read_f32(W31_F_HALF_B) as f64,
            front,
            matrix.as_mut_ptr() as u32,
        );
    }
    let mut word = 0usize;
    while word < 12 {
        write_u32(out + 0x30 + word * 4, matrix[word]);
        word += 1;
    }
}

// ---------------------------------------------------------------------------
// 0x80094DE0
// ---------------------------------------------------------------------------

/// Destroys one stage-effect entry and optionally frees it.
///
/// # Original
/// - Ghidra: `FUN_80094de0` at `0x80094DE0` (88 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80094de0_FUN_80094de0.c`
/// - observed: `if (entry != 0) { 0x802D7B20(entry,0); if (0 < size)
///   0x802B9280(entry); } return entry;`
///
/// # Arguments
/// - `entry`: effect entry.
/// - `size`: positive means "free".
///
/// # Returns
/// The same `entry` pointer.
///
/// # Safety
/// `entry` must be null or a live effect entry.
///
/// # Confidence
/// high - two guarded calls.
pub unsafe fn stage_effect_entry_destroy(entry: usize, size: i32) -> usize {
    if entry != 0 {
        platform::call2(0x802D_7B20, entry as u32, 0);
        if size > 0 {
            platform::call1(DELETE, entry as u32);
        }
    }
    entry
}

// ---------------------------------------------------------------------------

// Wave-33 constants: the BG scroll-layer object
// (0x80074FF0..0x80075800, 0x80076630, 0x800767F0, 0x8007F700..0x8007FDA0)

// ---------------------------------------------------------------------------

/// `r13 - 0x58A0` → `0x80429DE0`: head of the BG scroll-layer list.
///
/// observed: `*(int **)(unaff_r13 + -0x58a0)` seeds every list walk in
/// `0x80076630`, `0x800766f0`, `0x800767f0` and `0x800768d0`, and it is the
/// head written by `0x8007F900` and repaired by `0x8007F950`. BSS → 0 at boot.
const W33_G_SCROLL_HEAD: usize = SDA_BASE - 0x58A0;

/// `r13 - 0x589C` → `0x80429DE4`: tail slot of the scroll-layer list.
///
/// observed: written by `0x8007F900` when the list was empty and by
/// `0x8007F950` when the unlinked node was the first one.
const W33_G_SCROLL_TAIL: usize = SDA_BASE - 0x589C;

/// `r13 - 0x5898` → `0x80429DE8`: last scroll-layer source (`owner` object).
///
/// observed: `if (*(int *)(r13 - 0x5898) != param_2) { ... = param_2; ... }` in
/// `0x8007F9B0`; the comparison drives the generation counter below.
const W33_G_SCROLL_SOURCE: usize = SDA_BASE - 0x5898;

/// `r13 - 0x5894` → `0x80429DEC`: scroll-layer generation counter.
///
/// observed: incremented in `0x8007F9B0` when the source object changes and
/// copied into the new node's `+0xE0` stamp.
const W33_G_SCROLL_GENERATION: usize = SDA_BASE - 0x5894;

/// `r13 - 0x58D4` → `0x80429DAC`: "ground probe succeeded" word.
///
/// observed: `0x80075270` clears it to `0` on entry and sets it to `2` on the
/// `code - 3 < 3` path; `0x80075750`/`0x80075780` only report values when it
/// equals `2`. The stored triple is the probe result below.
const W33_G_PROBE_STATE: usize = SDA_BASE - 0x58D4;

/// `r13 - 0x58D0` → `0x80429DB0`: first word of the last ground-probe result.
const W33_G_PROBE_X: usize = SDA_BASE - 0x58D0;

/// `r13 - 0x58CC` → `0x80429DB4`: second word of the last ground-probe result.
const W33_G_PROBE_Z: usize = SDA_BASE - 0x58CC;

/// `r13 - 0x58C8` → `0x80429DB8`: `u16` layer/tile word of the last ground
/// probe (`*param_1` of the probe's last out-pointer).
const W33_G_PROBE_LAYER: usize = SDA_BASE - 0x58C8;

/// `r13 - 0x5580` → `0x8042A100`: owner object passed as `r3` to the ground
/// probe `0x800EB930`.
const W33_G_PROBE_OWNER: usize = SDA_BASE - 0x5580;

/// `r2 - 0x71F8` → `0x8042BE88`: the zero word copied into the two scroll
/// accumulators (`+0xB0`/`+0xB4`).
///
/// observed: `0x80080170` stores this word at `+0xB0`/`+0xB4` as the reset
/// value ("the `r2-0x71F8` zero" in [`bg_scene_follow_layers`]). Copied as a
/// word here so the translation does not depend on its type.
const W33_F_ZERO_WORD: usize = SDA2_BASE - 0x71F8;

/// `r2 - 0x71F0` → `0x8042BE90`: angle scale applied to the layer's `s16`
/// angle before the trigonometric helpers (1/256 in the shipped data, the same
/// scale used by [`bg_scene_edge_snap`]).
const W33_F_TRIG_SCALE: usize = SDA2_BASE - 0x71F0;

/// `r2 - 0x71EC` → `0x8042BE94`: the `0.5` used to average opposite quad
/// corners into the layer centre.
const W33_F_HALF: usize = SDA2_BASE - 0x71EC;

/// `r2 - 0x741C` → `0x8042BC64`: scale that converts a world x to an index of
/// the camera owner's 80-entry table at `+0x8FECC` (`0x80075270`).
const W33_F_CELL_INV: usize = SDA2_BASE - 0x741C;

/// `r2 - 0x7418` → `0x8042BC68`: step added to the probe height while the
/// ground probe keeps returning the same code (`0x80075270`).
const W33_F_PROBE_STEP: usize = SDA2_BASE - 0x7418;

/// `r2 - 0x7428` → `0x8042BC58`: step removed from the probe height while the
/// ground scan keeps reporting bit `0x200` (`0x80075270`).
const W33_F_PROBE_STEP_BACK: usize = SDA2_BASE - 0x7428;

/// `r2 - 0x7440` → `0x8042BC40`: the zero height used as the probe base and as
/// the z coordinate of the point handed to `bg_unit_contains_point`.
const W33_F_PROBE_FLOOR: usize = SDA2_BASE - 0x7440;

/// `0x8006D170(object, 2, kind, param_4, param_3, 0)`: the attach test that
/// `0x80074FF0` forwards to.
const W33_ATTACH_TEST: usize = 0x8006_D170;

/// `0x8006CED0(float *out, int owner)`: writes `owner+0xAC..0xB4` plus
/// `owner+0xD0..0xD8` into three floats; used by `0x8007FDA0` to seed the
/// layer centre.
const W33_CAMERA_SUM: usize = 0x8006_CED0;

/// `0x800EB930(owner, in_point, out_a, out_height, out_layer, param_3)`:
/// ground probe. Returns a small code, `-1` for "no hit".
const W33_GROUND_PROBE: usize = 0x800E_B930;

/// `0x80070BA0(x, y)`: ground scan returning a bit mask; bit `0x200` means the
/// height is still inside a surface and bit `0x400` marks the alternate mode.
const W33_GROUND_SCAN: usize = 0x8007_0BA0;

/// `0x80070BF0(x, y, param_3)`: the depth-carrying variant of the ground scan.
const W33_GROUND_SCAN_DEPTH: usize = 0x8007_0BF0;

/// `0x80237C40`: first trigonometric helper of the pair used to rotate the
/// scroll-layer quad. Which of the two is sine and which is cosine is not
/// asserted, so the results keep the call order.
const W33_TRIG_A: usize = 0x8023_7C40;

/// `0x80237BD0`: second trigonometric helper of the same pair.
const W33_TRIG_B: usize = 0x8023_7BD0;

/// `0x8007F800`: element constructor passed to `0x802DC9A0` by `0x8007F7A0`.
///
/// Ghidra prints the argument as `&DAT_8007f800` because the address was never
/// promoted to a function; the callee calls it as `code *(element, 1)`, so it
/// is a constructor pointer.
const W33_LAYER_ELEMENT_CTOR: usize = 0x8007_F800;

/// `0x80006DF0`: element deleter of the same array (translated in
/// [`crate::render::geometry`]).
const W33_LAYER_ELEMENT_DTOR: usize = 0x8000_6DF0;

// ---------------------------------------------------------------------------

// Wave-33 local call helpers

// ---------------------------------------------------------------------------

/// Calls a PowerPC function with eight integer arguments (`r3..r10`).
///
/// # Safety
/// `addr` must use the PowerPC integer ABI and accept eight words.
unsafe fn w33_call8(
    addr: usize,
    a: u32,
    b: u32,
    c: u32,
    d: u32,
    e: u32,
    f: u32,
    g: u32,
    h: u32,) -> u32 {
    let func: extern "C" fn(u32, u32, u32, u32, u32, u32, u32, u32) -> u32 =
        core::mem::transmute(addr);
    func(a, b, c, d, e, f, g, h)
}

/// Calls a PowerPC function with two `f64` arguments and returns `r3`.
///
/// # Safety
/// `addr` must use the PowerPC floating-point ABI.
unsafe fn w33_call2_f64_u32(addr: usize, a: f64, b: f64) -> u32 {
    let func: extern "C" fn(f64, f64) -> u32 = core::mem::transmute(addr);
    func(a, b)
}

/// Calls a PowerPC function with two `f64` arguments and one integer, returning
/// `r3`.
///
/// # Safety
/// `addr` must use the PowerPC mixed ABI.
unsafe fn w33_call2_f64_u32_arg(addr: usize, a: f64, b: f64, c: u32) -> u32 {
    let func: extern "C" fn(f64, f64, u32) -> u32 = core::mem::transmute(addr);
    func(a, b, c)
}

/// Stores a signed word, keeping the signed view of the scroll-layer integer
/// fields explicit.
///
/// # Safety
/// `addr` must be a writable aligned word.
unsafe fn w33_write_i32(addr: usize, value: i32) {
    write_u32(addr, value as u32);
}

// ---------------------------------------------------------------------------
// 0x80074FF0
// ---------------------------------------------------------------------------

/// Runs the attach test for one scroll-layer target and latches the layer's
/// target flags on success.
///
/// The layer's `+0xCC` kind selects the third argument of `0x8006D170`: kind
/// `6` passes `2`, kind `7` passes `4`, every other kind passes `0`. On a
/// non-zero result the layer's `+0xD4` word becomes `1` and bit `0` of the
/// `+0xD8` mask is set.
///
/// # Original
/// - Ghidra: `FUN_80074ff0` at `0x80074FF0` (128 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80074ff0_FUN_80074ff0.c`
/// - observed: `if (*(int *)(param_2 + 0xcc) == 6) uVar2 = 2;`, the same test
///   for `7` yielding `4`, then
///   `FUN_8006d170(param_1,2,uVar2,param_4,param_3,0)`, the two stores and
///   `return iVar1 != 0;`.
///
/// # Arguments
/// - `object`: first argument forwarded unchanged to `0x8006D170`.
/// - `layer`: scroll-layer object; `+0xCC` is the target kind.
/// - `param_3`/`param_4`: forwarded as the fifth/fourth argument.
///
/// # Returns
/// `1` when `0x8006D170` reports success, `0` otherwise.
///
/// # Side effects
/// Writes `layer+0xD4` and `layer+0xD8` on success.
///
/// # Safety
/// `layer+0xCC..+0xD8` must be readable/writable.
///
/// # Confidence
/// high - the kind tests, the six-argument call and both stores are literal.
pub unsafe fn fn_80074ff0(object: u32, layer: usize, param_3: u32, param_4: u32) -> u32 {
    let mut kind = 0u32;
    if read_i32(layer + 0xcc) == 6 {
        kind = 2;
    }
    if read_i32(layer + 0xcc) == 7 {
        kind = 4;
    }
    let result = platform::call6(W33_ATTACH_TEST, object, 2, kind, param_4, param_3, 0);
    if result != 0 {
        w33_write_i32(layer + 0xd4, 1);
        write_u32(layer + 0xd8, read_u32(layer + 0xd8) | 1);
    }
    u32::from(result != 0)
}

// ---------------------------------------------------------------------------
// 0x80075070
// ---------------------------------------------------------------------------

/// Clears the five words at `+0x58..+0x68` of a scroll layer.
///
/// # Original
/// - Ghidra: `FUN_80075070` at `0x80075070` (28 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80075070_FUN_80075070.c`
/// - observed: five `*(undefined4 *)(param_1 + N) = 0;` stores for `0x58`,
///   `0x5C`, `0x60`, `0x64` and `0x68`.
///
/// # Arguments
/// - `layer`: scroll-layer object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Zeroes five words of the layer.
///
/// # Safety
/// `layer+0x58..+0x6C` must be writable.
///
/// # Confidence
/// high - five literal stores.
pub unsafe fn fn_80075070(layer: usize) {
    let mut offset = 0x58usize;
    while offset <= 0x68 {
        write_u32(layer + offset, 0);
        offset += 4;
    }
}

// ---------------------------------------------------------------------------
// 0x800751C0
// ---------------------------------------------------------------------------

/// Claims one of the layer's two `(id, value)` slots.
///
/// The two slots are `+0x78`/`+0x7C` (values) with their ids at `+0x80`/`+0x84`.
/// An id that is already registered in either slot is rejected before the scan.
///
/// # Original
/// - Ghidra: `FUN_800751c0` at `0x800751C0` (112 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800751c0_FUN_800751c0.c`
/// - observed: the two `+0x80`/`+0x84` id comparisons returning `0`, then a
///   two-iteration loop testing `+0x78`/`+0x7C` and storing `param_3` and
///   `param_2` in the free slot.
///
/// # Arguments
/// - `layer`: scroll-layer object.
/// - `id`: slot id to register.
/// - `value`: value stored next to the id.
///
/// # Returns
/// `1` when a slot was claimed, `0` when the id already exists or both slots
/// are full.
///
/// # Side effects
/// Writes one value word and one id word.
///
/// # Safety
/// `layer+0x78..+0x88` must be readable/writable.
///
/// # Confidence
/// high - the loop bound is two and every store is literal.
pub unsafe fn fn_800751c0(layer: usize, id: u32, value: u32) -> u32 {
    if read_u32(layer + 0x80) == id || read_u32(layer + 0x84) == id {
        return 0;
    }
    let mut index = 0usize;
    while index < 2 {
        let slot = layer + index * 4;
        if read_u32(slot + 0x78) == 0 {
            write_u32(slot + 0x78, value);
            write_u32(slot + 0x80, id);
            return 1;
        }
        index += 1;
    }
    0
}

// ---------------------------------------------------------------------------
// 0x80075230
// ---------------------------------------------------------------------------

/// Looks up the value registered for `id` in the layer's two slots.
///
/// # Original
/// - Ghidra: `FUN_80075230` at `0x80075230` (64 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80075230_FUN_80075230.c`
/// - observed: a two-iteration loop comparing `*(int *)(param_1 + i*4 + 0x80)`
///   with `param_2` and returning `*(undefined4 *)(param_1 + i*4 + 0x78)`.
///
/// # Arguments
/// - `layer`: scroll-layer object.
/// - `id`: slot id.
///
/// # Returns
/// The stored value, or `0` when the id is not registered.
///
/// # Side effects
/// None.
///
/// # Safety
/// `layer+0x78..+0x88` must be readable.
///
/// # Confidence
/// high - literal two-slot scan.
pub unsafe fn fn_80075230(layer: usize, id: u32) -> u32 {
    let mut index = 0usize;
    while index < 2 {
        if read_u32(layer + index * 4 + 0x80) == id {
            return read_u32(layer + index * 4 + 0x78);
        }
        index += 1;
    }
    0
}

// ---------------------------------------------------------------------------
// 0x80075270
// ---------------------------------------------------------------------------

/// Classifies the ground under a point and publishes the probe result.
///
/// Two course exceptions (`7-2` and `7-23`, read from stage info `+0x120C..+0x120E`)
/// take a shortcut: the camera owner's 80-entry float table at `+0x8FECC` is
/// indexed by `(x - scene+0x38) * scale` and compared against `y`; an index
/// beyond `0x4F` is rejected.
///
/// Every other course first reads `camera+0x8FEC4` as a height limit. When the
/// point is below that limit it runs the ground probe `0x800EB930`, walks the
/// probe's height up while it keeps returning the same code, and maps the final
/// code to a result (`3..5` → `2` with the probe triple published, `0` → `1`,
/// `1` → `3`, `2` → `4`). When the probe reports nothing, or the point is above
/// the limit, the ground scan `0x80070BA0` is consulted instead and bit `0x200`
/// decides between `1` and `0`; the "stick to the surface" loop then rounds the
/// height down to a multiple of `0x10`.
///
/// # Original
/// - Ghidra: `FUN_80075270` at `0x80075270` (752 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80075270_FUN_80075270.c`
/// - observed: `*(undefined4 *)(r13 - 0x58d4) = 0;`, the `+0x120c`/`+0x120d`/
///   `+0x120e` course tests, the `0x4f` bound on the table index, the two
///   `FUN_800eb930` calls, the `iVar6 - 3U < 3` / `iVar6 == 0/1/2` mapping, the
///   `FUN_80070ba0` fallback with bit `0x200`, and the final
///   `CONCAT44(0x43300000, ...) - *(double *)(r2 - 0x7438)` that yields
///   `-(height & 0xFFF0)` as a float.
///
/// # Arguments
/// - `x`: world x of the point.
/// - `y`: world height of the point; the probe loop overwrites it.
/// - `param_3`: forwarded to both probe/scan callees.
/// - `out`: optional address that receives the probed height (or the height
///   limit when the shortcut path is taken); `0` skips the write.
///
/// # Returns
/// `0` (nothing), `1` (surface found), `2` (probe triple published), `3`
/// (shortcut surface) or `4` (probe code `2`).
///
/// # Side effects
/// Clears/sets [`W33_G_PROBE_STATE`] and may write [`W33_G_PROBE_X`],
/// [`W33_G_PROBE_Z`], [`W33_G_PROBE_LAYER`]; writes `*out`.
///
/// # Safety
/// The stage-info, scene, camera and probe owner globals must be live; `out`
/// must be null or writable.
///
/// # Confidence
/// medium - every branch is literal, but the probe codes' meanings and the
/// role of the `+0x8FECC` table are inferred from the surrounding stage code.
pub unsafe fn fn_80075270(x: f64, mut y: f64, param_3: u32, out: usize) -> u8 {
    write_u32(W33_G_PROBE_STATE, 0);
    let info = read_u32(G_STAGE_INFO) as usize;
    let course = read_u8(info + 0x120c);
    let area = read_u8(info + 0x120d);
    let shortcut = (course == 7 && area == 2)
        || (course == 7 && area == 0x17 && read_u8(info + 0x120e) == 3);
    if shortcut {
        if out == 0 {
            return 0;
        }
        let scene = read_u32(G_BG_SCENE) as usize;
        let camera = read_u32(G_CAMERA_OWNER) as usize;
        let index = ((x - read_f32(scene + 0x38) as f64) as f32 * read_f32(W33_F_CELL_INV)) as u32;
        if index > 0x4f {
            return 0;
        }
        let height = read_f32(camera + 0x8fecc + index as usize * 4);
        write_f32(out, height);
        if (height as f64) < y {
            return 0;
        }
        return 3;
    }
    let camera = read_u32(G_CAMERA_OWNER) as usize;
    let limit = read_f32(camera + 0x8fec4);
    if (limit as f64) < y {
        let mut point = [x as f32, y as f32];
        let mut hit = [0u32;
 2];
        let mut height = [0f32;
 1];
        let mut layer = [0u16;
 1];
        let owner = read_u32(W33_G_PROBE_OWNER);
        let mut code = platform::call6(
            W33_GROUND_PROBE,
            owner,
            point.as_mut_ptr() as u32,
            hit.as_mut_ptr() as u32,
            height.as_mut_ptr() as u32,
            layer.as_mut_ptr() as u32,
            param_3,
        ) as u8 as i8 as i32;
        if code != -1 {
            let step = read_f32(W33_F_PROBE_STEP) as f64;
            let mut next = step + height[0] as f64;
            loop {
                point[1] = next as f32;
                let repeat = platform::call6(
                    W33_GROUND_PROBE,
                    owner,
                    point.as_mut_ptr() as u32,
                    0,
                    height.as_mut_ptr() as u32,
                    0,
                    param_3,
                ) as u8 as i8 as i32;
                if code != repeat {
                    break;
                }
                next = step + height[0] as f64;
            }
            if out != 0 {
                write_f32(out, height[0]);
            }
            if (code as u32).wrapping_sub(3) < 3 {
                write_u32(W33_G_PROBE_X, hit[0]);
                write_u32(W33_G_PROBE_Z, hit[1]);
                write_u16(W33_G_PROBE_LAYER, layer[0]);
                write_u32(W33_G_PROBE_STATE, 2);
                return 2;
            }
            if code == 0 {
                return 1;
            }
            if code == 1 {
                return 3;
            }
            if code == 2 {
                return 4;
            }
        }
        let flags = w33_call2_f64_u32(W33_GROUND_SCAN, x, y);
        if (flags & 0x200) == 0 {
            return 0;
        }
        if out != 0 {
            let step = read_f32(W33_F_PROBE_STEP_BACK) as f64;
            let floor = read_f32(W33_F_PROBE_FLOOR) as f64;
            loop {
                if floor <= y {
                    break;
                }
                y = (y + step) as f32 as f64;
                let again = w33_call2_f64_u32(W33_GROUND_SCAN, x, y);
                if (again & 0x200) == 0 {
                    break;
                }
            }
            let masked = ((y - step) as i32 as u32) & 0xfff0;
            // observed: the CONCAT44/0x80000000 pair below is the signed
            // int → f64 conversion, so the stored value is `-(masked)`.
            write_f32(out, 0u32.wrapping_sub(masked) as i32 as f32);
        }
        return 1;
    }
    if out != 0 {
        write_f32(out, limit);
    }
    read_u8(camera + 0x9002c)
}

