///
/// # Safety
/// `out` must be writable for eight bytes.
///
/// # Confidence
/// high - a state test and two literal copies.
pub unsafe fn fn_80075750(out: usize) -> u32 {
    if read_u32(W33_G_PROBE_STATE) == 2 {
        write_u32(out, read_u32(W33_G_PROBE_X));
        write_u32(out + 4, read_u32(W33_G_PROBE_Z));
        return 1;
    }
    0
}

