/// - observed: `param_1[0xf] = 1;`, `FUN_8006ced0(&local_40,*param_1);`,
///   `FUN_80101aa0((double)local_40);`, the `[0x16]`/`[0x17]` stores, the
///   `+0x2f`/`+0x30` tile pair, `[0x2a] = [0x28]`/`[0x2b] = [0x29]`, the
///   `param_1[0x32] == 1` branch, the `+0x80237C40`/`+0x80237BD0` pair with
///   `r2-0x71F0` and `r2-0x71EC`, the eight corner stores, the
///   `FUN_80080170(param_1)` call, the three `*(int *)(iVar21 + 0xac/b0/b4)`
///   copies and the final `*(short *)(param_1 + 0x30) = sVar12;`.
///
/// # Arguments
/// - `layer`: scroll-layer object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Rewrites the layer's position, quad, centre and cached tile id; walks all
/// eight child layers.
///
/// # Safety
/// `layer`, `*(layer+0x00)`, `*(layer+0xBC)` and every child layer must be
/// readable/writable.
///
/// # Confidence
/// medium - the arithmetic and stores are literal, but the `0x80101AA0` call is
/// printed without a destination (it is executed and its result dropped here),
/// and the edge/quad field roles are inferred from their consumers.
pub unsafe fn fn_8007fda0(layer: usize) {
    write_u32(layer + 0x3c, 1);
    let mut centre = [0f32;
 3];
    platform::call2(
        W33_CAMERA_SUM,
        centre.as_mut_ptr() as u32,
        read_u32(layer),
    );
    // observed: the original's 0x80101AA0 call has no printed destination; it
    // is still executed, so the call stays and its result is dropped.
    let _ = call1_f64(CAMERA_X_WRAP, centre[0] as f64);
    w33_write_i32(layer + 0x58, centre[0] as i32);
    w33_write_i32(layer + 0x5c, centre[1] as i32);
    let tile = read_u16(read_u32(layer + 0xbc) as usize);
    let remainder = tile.wrapping_sub(read_u16(layer + 0xc0));
    write_u16(layer + 0xc2, remainder);
    write_u16(layer + 0xc4, remainder);
    write_u32(layer + 0xa8, read_u32(layer + 0xa0));
    write_u32(layer + 0xac, read_u32(layer + 0xa4));
    if read_i32(layer + 0xc8) == 1 {
        let x = centre[0] + read_i32(layer + 0x80) as f32;
        let z = centre[1] + read_i32(layer + 0x84) as f32;
        w33_write_i32(layer + 0x58, x as i32);
        w33_write_i32(layer + 0x5c, z as i32);
        w33_write_i32(layer + 0xa0, x as i32);
        w33_write_i32(layer + 0xa4, z as i32);
    } else {
        let radians =
            (read_f32(W33_F_TRIG_SCALE) as f64 * remainder as i16 as f64) as f32;
        let trig_a = call1_f64(W33_TRIG_A, radians as f64) as f32;
        let trig_b = call1_f64(W33_TRIG_B, radians as f64) as f32;
        let x_edge = read_i32(layer + 0x80) as f32;
        let z_edge = read_i32(layer + 0x84) as f32;
        let x_far = read_i32(layer + 0x88) as f32;
        let z_far = read_i32(layer + 0x8c) as f32;
        let f1 = z_edge * trig_a;
        let f2 = x_edge * trig_b;
        let f3 = x_edge * trig_a;
        let f4 = z_edge * trig_b;
        let f5 = z_far * trig_a;
        let f6 = z_far * trig_b;
        let f7 = x_far * trig_b;
        let f8 = x_far * trig_a;
        let x0 = read_i32(layer + 0x58) as f32;
        let z0 = read_i32(layer + 0x5c) as f32;
        let corner_z_a = z0 + f1 + f2;
        let corner_z_b = z0 + f5 + f7;
        let corner_x_b = x0 + (f8 - f6);
        let corner_x_a = x0 + (f3 - f4);
        w33_write_i32(layer + 0x60, corner_x_a as i32);
        w33_write_i32(layer + 0x64, corner_z_a as i32);
        w33_write_i32(layer + 0x68, (x0 + (f3 - f6)) as i32);
        w33_write_i32(layer + 0x6c, (z0 + f5 + f2) as i32);
        w33_write_i32(layer + 0x70, corner_x_b as i32);
        w33_write_i32(layer + 0x74, corner_z_b as i32);
        w33_write_i32(layer + 0x78, (x0 + (f8 - f4)) as i32);
        w33_write_i32(layer + 0x7c, (z0 + f1 + f7) as i32);
        let half = read_f32(W33_F_HALF);
        w33_write_i32(layer + 0xa0, ((corner_x_a + corner_x_b) * half) as i32);
        w33_write_i32(layer + 0xa4, ((corner_z_a + corner_z_b) * half) as i32);
    }
    bg_scene_follow_layers(layer);
    let owner = read_u32(layer) as usize;
    w33_write_i32(layer + 0x94, read_i32(owner + 0xac));
    w33_write_i32(layer + 0x98, read_i32(owner + 0xb0));
    w33_write_i32(layer + 0x9c, read_i32(owner + 0xb4));
    write_u16(layer + 0xc0, tile);
}

