// Wave 38: dLineMng line-object cluster (0x800C1700..0x800C4E50)

// ---------------------------------------------------------------------------

/// `r2 - 0x6844`: the zero float the circle test compares against.
///
/// observed: `fVar3 = *(float *)(unaff_r2 + -0x6844);` in `0x800C1E10` and
/// `fVar3 != *(float *)(unaff_r2 + -0x6844)` in `0x800C19E0`.
const W38_F_6844: usize = SDA2_BASE - 0x6844;

/// `r2 - 0x6810`: margin float used by the range test and the edge clamps.
///
/// observed: `(float)(param_1 - (double)*(float *)(unaff_r2 + -0x6810))` in
/// `0x800C1A40` and the `+0x40`/`+0x44` clamps in `0x800C3AD0`/`0x800C3B10`.
const W38_F_6810: usize = SDA2_BASE - 0x6810;

/// `r2 - 0x6818`: half-extent offset added/subtracted to points.
///
/// observed: `*param_2 + *(float *)(unaff_r2 + -0x6818)` and friends across
/// `0x800C2700..0x800C4E50`.
const W38_F_6818: usize = SDA2_BASE - 0x6818;

/// `r2 - 0x67F0`: squared-radius float for the `0x800C2700` circle test.
///
/// observed: `fVar1 = *(float *)(unaff_r2 + -0x67f0);` followed by
/// `FUN_800c1e10((double)fVar1, ...)`.
const W38_F_67F0: usize = SDA2_BASE - 0x67F0;

/// `r2 - 0x67EC`: squared-radius float shared by `0x800C27F0..0x800C2B90`.
const W38_F_67EC: usize = SDA2_BASE - 0x67EC;

/// `r2 - 0x67E4`: squared-radius float shared by `0x800C2CB0..0x800C3050`.
const W38_F_67E4: usize = SDA2_BASE - 0x67E4;

/// `r2 - 0x67E8`: half-extent for the second circle family.
const W38_F_67E8: usize = SDA2_BASE - 0x67E8;

/// `r2 - 0x6800`: half-extent for the `0x800C2700` circle test.
const W38_F_6800: usize = SDA2_BASE - 0x6800;

/// `0x802F0FE8`: start of the first four-word line-type table.
const W38_TYPE_TABLE_A: usize = 0x802F_0FE8;

/// `0x802F0FF8`: start of the second eight-word line-type table.
const W38_TYPE_TABLE_B: usize = 0x802F_0FF8;

/// `0x802F1018`: end of the second table (Ghidra prints it as a string label).
const W38_TYPE_TABLE_B_END: usize = 0x802F_1018;

/// `0x80070BA0`: zone-enable test called by the line-type lookup.
const W38_ZONE_TEST: usize = 0x8007_0BA0;

/// `0x80070BF0`: zone lookup called with two doubles and zero.
const W38_ZONE_LOOKUP: usize = 0x8007_0BF0;

/// `0x801611C0`: bearing-to-angle conversion used by the circle handlers.
const W38_ANGLE_CONV: usize = 0x8016_11C0;

/// Transitions a line object through its `+0x6C` interface.
///
/// observed: `(code **)(*(int *)(obj + 0x6c) + 0x18))(obj + 0x6c, &DAT_...)`.
/// The vtable slot and the state pointer are read exactly as printed.
///
/// # Safety
/// `obj + 0x6C` must point at a live interface whose vtable has slot `+0x18`.
unsafe fn w38_transition(obj: usize, state: usize) {
    let iface = obj + 0x6c;
    let vtable = read_u32(iface) as usize;
    let function = read_u32(vtable + 0x18) as usize;
    platform::call2(function, iface as u32, state as u32);
}

// ---------------------------------------------------------------------------
// 0x800C1700
// ---------------------------------------------------------------------------

/// Tests line-type membership in the first table.
///
/// Scans the four words at `0x802F0FE8..0x802F0FF8` for `id` and returns `1`
/// on the first match, `0` after the last entry.
///
/// # Original
/// - Ghidra: `FUN_800c1700` at `0x800C1700` (56 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c1700_FUN_800c1700.c`
/// - observed: `piVar1 = &DAT_802f0fe8; do { if (param_1 == *piVar1)
///   return 1; piVar1 = piVar1 + 1; } while (piVar1 < &DAT_802f0ff8);`
///
/// # Arguments
/// - `id`: line-type id to look up.
///
/// # Returns
/// `1` when `id` is in the table, `0` otherwise.
///
/// # Side effects
/// None.
///
/// # Safety
/// None; the table is fixed data.
///
/// # Confidence
/// high - the scan bounds and match test are literal.
pub unsafe fn fn_800c1700(id: u32) -> u32 {
    let mut cursor = W38_TYPE_TABLE_A;
    loop {
        if id == read_u32(cursor) {
            return 1;
        }
        cursor += 4;
        if cursor >= W38_TYPE_TABLE_B {
            return 0;
        }
    }
}

