///
/// # Side effects
/// None.
///
/// # Safety
/// None; the table is fixed data.
///
/// # Confidence
/// high - the scan bounds and match test are literal.
pub unsafe fn fn_800c1740(id: u32) -> u32 {
    let mut cursor = W38_TYPE_TABLE_B;
    loop {
        if id == read_u32(cursor) {
            return 1;
        }
        cursor += 4;
        if cursor >= W38_TYPE_TABLE_B_END {
            return 0;
        }
    }
}

// ---------------------------------------------------------------------------
// 0x800C1780
// ---------------------------------------------------------------------------

/// Flips a line object's facing flag and speed sign.
///
/// Toggles the byte at `+0x68` and negates the float at `+0x60`.
///
/// # Original
/// - Ghidra: `FUN_800c1780` at `0x800C1780` (28 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c1780_FUN_800c1780.c`
/// - observed: `*(byte *)(param_1 + 0x68) = *(byte *)(param_1 + 0x68) ^ 1;`,
///   `*(float *)(param_1 + 0x60) = -*(float *)(param_1 + 0x60);`
///
/// # Arguments
/// - `obj`: line object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `obj+0x60` and `obj+0x68`.
///
/// # Safety
/// `obj..obj+0x69` must be writable.
///
/// # Confidence
/// high - two stores, both literal.
pub unsafe fn fn_800c1780(obj: usize) {
    write_u8(obj + 0x68, read_u8(obj + 0x68) ^ 1);
    write_f32(obj + 0x60, -read_f32(obj + 0x60));
}

// ---------------------------------------------------------------------------
// 0x800C17A0
// ---------------------------------------------------------------------------

/// Looks up the line type for a point.
///
/// When the zone test at `0x80070BA0` returns zero, forwards the two
/// coordinates to the zone lookup at `0x80070BF0`; otherwise returns zero.
///
/// # Original
/// - Ghidra: `FUN_800c17a0` at `0x800C17A0` (104 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c17a0_FUN_800c17a0.c`
/// - observed: `iVar1 = FUN_80070ba0(0); if (iVar1 == 0) {
///   uVar2 = FUN_80070bf0(param_1,param_2,0); } return uVar2;`
///
/// # Arguments
/// - `x`, `y`: query point (original parameters are doubles).
///
/// # Returns
/// The zone lookup result, or `0` when the zone test is non-zero.
///
/// # Side effects
/// Calls the two zone functions (see Safety).
///
/// # Safety
/// The zone functions at `0x80070BA0`/`0x80070BF0` must be live.
///
/// # Confidence
/// medium - the branch and forwarding are literal; the zone roles are
/// inferred from the argument shapes.
pub unsafe fn fn_800c17a0(x: f64, y: f64) -> u32 {
    if platform::call1(W38_ZONE_TEST, 0) == 0 {
        return w33_call2_f64_u32_arg(W38_ZONE_LOOKUP, x, y, 0);
    }
    0
}

// ---------------------------------------------------------------------------
// 0x800C19E0
// ---------------------------------------------------------------------------

/// Computes the slope and intercept of the line through two points.
///
/// When the x difference is non-zero, stores `(b.y - a.y) / (b.x - a.x)` at
/// `slope` and `b.y - slope * b.x` at `intercept`, returning true.
///
/// # Original
/// - Ghidra: `FUN_800c19e0` at `0x800C19E0` (88 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c19e0_FUN_800c19e0.c`
/// - observed: `fVar3 = fVar1 - *param_1; bVar4 = fVar3 !=
///   *(float *)(unaff_r2 + -0x6844); if (bVar4) { fVar3 =
///   (fVar2 - param_1[1]) / fVar3; *param_3 = fVar3; *param_4 =
///   fVar2 - fVar3 * fVar1; } return bVar4;`
///
/// # Arguments
/// - `a`, `b`: addresses of two `[x, y]` float pairs.
/// - `slope`, `intercept`: writable single-float outputs.
///
/// # Returns
/// True when the line is non-vertical.
///
/// # Side effects
/// Writes `slope` and `intercept` on success.
///
/// # Safety
/// `a`, `b`, `slope` and `intercept` must be readable/writable for their
/// sizes.
///
/// # Confidence
/// high - the guard, division and two stores are literal.
pub unsafe fn fn_800c19e0(a: usize, b: usize, slope: usize, intercept: usize) -> bool {
    let bx = read_f32(b);
    let by = read_f32(b + 4);
    let dx = bx - read_f32(a);
    let non_vertical = dx != read_f32(W38_F_6844);
    if non_vertical {
        let value = (by - read_f32(a + 4)) / dx;
        write_f32(slope, value);
        write_f32(intercept, by - value * bx);
    }
    non_vertical
}

// ---------------------------------------------------------------------------
// 0x800C1A40
// ---------------------------------------------------------------------------

/// Tests whether `v` lies within the tolerance-expanded span of `a`/`b`.
///
/// The pair is ordered first, then `v` is compared against
/// `(min - eps? )` uses the `-0x6810` margin: the test is
/// `lo - margin <= v <= hi + margin` in single precision.
///
/// # Original
/// - Ghidra: `FUN_800c1a40` at `0x800C1A40` (76 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c1a40_FUN_800c1a40.c`
/// - observed: `dVar1 = param_2; if (param_2 < param_1) { dVar1 =
///   param_1; param_1 = param_2; } if (((double)(float)(param_1 -
///   (double)*(float *)(unaff_r2 + -0x6810)) <= param_3) && (param_3 <=
///   (double)(float)(dVar1 + (double)*(float *)(unaff_r2 + -0x6810))))
///   return 1; return 0;`
///
/// # Arguments
/// - `a`, `b`: span endpoints.
/// - `v`: value to test.
///
/// # Returns
/// `1` when `v` is in range, `0` otherwise.
///
/// # Side effects
/// None.
///
/// # Safety
/// None.
///
/// # Confidence
/// high - the ordering and the two single-precision bounds are literal.
pub unsafe fn fn_800c1a40(a: f64, b: f64, v: f64) -> u32 {
    let mut lo = a;
    let mut hi = b;
    if b < a {
        hi = a;
        lo = b;
    }
    let margin = read_f32(W38_F_6810) as f64;
    let lower = (lo - margin) as f32 as f64;
    let upper = (hi + margin) as f32 as f64;
    if lower <= v && v <= upper {
        1
    } else {
        0
    }
}

// ---------------------------------------------------------------------------
// 0x800C1E10
// ---------------------------------------------------------------------------

/// Tests two relative vectors against a squared radius.
///
/// Forms `d0 = |b|^2 - radius` and `d1 = |a|^2 - radius` in double precision,
/// then applies the zero-float comparison: returns `1` on exact zero, `0`
/// when the pair straddles the radius interval, `1` otherwise.
///
/// # Original
/// - Ghidra: `FUN_800c1e10` at `0x800C1E10` (128 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c1e10_FUN_800c1e10.c`
/// - observed: `fVar1 = (float)((double)(*param_3 * *param_3 +
///   param_3[1] * param_3[1]) - param_1); if (fVar1 ==
///   *(float *)(unaff_r2 + -0x6844)) return 1;` then the straddle test on
///   `fVar1`/`fVar2` against the same zero float.
///
/// # Arguments
/// - `radius`: squared radius (double in the original).
/// - `a`, `b`: addresses of two `[x, y]` float pairs.
///
/// # Returns
/// `1` or `0` as described above.
///
/// # Side effects
/// None.
///
/// # Safety
/// `a` and `b` must each be readable for eight bytes.
///
/// # Confidence
/// high - the squared distances and the comparison chain are literal.
pub unsafe fn fn_800c1e10(radius: f64, a: usize, b: usize) -> u32 {
    let zero = read_f32(W38_F_6844);
    let d_b = ((read_f32(b) as f64) * (read_f32(b) as f64)
        + (read_f32(b + 4) as f64) * (read_f32(b + 4) as f64)
        - radius) as f32;
    if d_b == zero {
        return 1;
    }
    let d_a = ((read_f32(a) as f64) * (read_f32(a) as f64)
        + (read_f32(a + 4) as f64) * (read_f32(a + 4) as f64)
        - radius) as f32;
    if (zero <= d_b || d_a < zero) && (d_b < zero || zero <= d_a) {
        return 0;
    }
    1
}

// ---------------------------------------------------------------------------
// 0x800C2700
// ---------------------------------------------------------------------------

/// Runs the first circle test and records its bearing.
///
/// Offsets the centre by the `-0x6800` half-extent, rewrites `a`/`b` as
/// relative vectors, runs [`fn_800c1e10`] with the `-0x67F0` radius and,
/// on success, stores the `0x801611C0` bearing at `+100` plus the centre at
/// `+0x50`/`+0x54`, then transitions to state `0x80359210`.
///
/// # Original
/// - Ghidra: `FUN_800c2700` at `0x800C2700` (240 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c2700_FUN_800c2700.c`
/// - observed: `fVar2 = param_2[1] - *(float *)(unaff_r2 + -0x6800);`,
///   `fVar3 = *param_2 + *(float *)(unaff_r2 + -0x6800);`,
///   `fVar1 = *(float *)(unaff_r2 + -0x67f0);` followed by the four relative
///   stores, `iVar4 = FUN_800c1e10((double)fVar1, param_3, param_4);`,
///   `uVar5 = FUN_801611c0((double)param_4[1], (double)*param_4);` and the
///   stores/transition to `&DAT_80359210`.
///
/// # Arguments
/// - `obj`: line object.
/// - `center`: address of the `[x, y]` circle centre.
/// - `a`, `b`: addresses of two `[x, y]` float pairs rewritten in place as
///   relative vectors.
///
/// # Returns
/// The [`fn_800c1e10`] result.
///
/// # Side effects
/// Rewrites `a`/`b` and, on success, writes `obj+0x50..+0x54` and `obj+100`
/// and calls the transition slot.
///
/// # Safety
/// `center`, `a` and `b` must be readable/writable for eight bytes; `obj`
/// must support the `+0x6C` transition.
///
/// # Confidence
/// medium - the arithmetic and stores are literal; the bearing and state
/// roles are inferred from the call shape.
pub unsafe fn fn_800c2700(obj: usize, center: usize, a: usize, b: usize) -> u32 {
    let off = read_f32(W38_F_6800);
    let rel_y = read_f32(center + 4) - off;
    let rel_x = read_f32(center) + off;
    write_f32(b + 4, read_f32(b + 4) - rel_y);
    write_f32(b, read_f32(b) - rel_x);
    write_f32(a, read_f32(a) - rel_x);
    write_f32(a + 4, read_f32(a + 4) - rel_y);
    let result = fn_800c1e10(read_f32(W38_F_67F0) as f64, a, b);
    if result != 0 {
        let angle = call2_f64_i32(W38_ANGLE_CONV, read_f32(b + 4) as f64, read_f32(b) as f64) as u16;
        let cx = read_f32(center);
        let cy = read_f32(center + 4);
        write_u16(obj + 100, angle);
        write_f32(obj + 0x50, cx);
        write_f32(obj + 0x54, cy);
        w38_transition(obj, 0x8035_9210);
    }
    result
}

// ---------------------------------------------------------------------------
// 0x800C27F0
// ---------------------------------------------------------------------------

/// Runs the offset circle test with a clamped angle.
///
/// Same shape as [`fn_800c2700`] but uses the `-0x6818`/`-0x67EC` pair, adds
/// `0xC100` to the bearing, clamps it to `[0x100, 0x40FF]` (returning `0`
/// when `>= 0x4200`), stores it plus `0x3F00`, flips via [`fn_800c1780`]
/// and transitions to state `0x80359250`.
///
/// # Original
/// - Ghidra: `FUN_800c27f0` at `0x800C27F0` (312 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c27f0_FUN_800c27f0.c`
/// - observed: the `-0x6818` centre offset, the `-0x67ec` radius,
///   `uVar6 = sVar5 + 0xc100; if (uVar6 < 0x4200) { if (uVar6 < 0x100)
///   uVar6 = 0x100; else if (0x40ff < uVar6) uVar6 = 0x40ff; ...` and the
///   `+ 0x3f00` store with the `&DAT_80359250` transition.
///
/// # Arguments
/// - `obj`: line object.
/// - `center`: address of the `[x, y]` circle centre.
/// - `a`, `b`: addresses of two `[x, y]` float pairs rewritten in place.
