///   `local_14 = param_2[1]; local_18 = *param_2 + *(float *)(unaff_r2 +
///   -0x6818); iVar3 = FUN_800c4060(param_1,uVar2,&local_18,param_3); if
///   (iVar3 == 0) { local_14 = param_2[1] + *(float *)(unaff_r2 +
///   -0x6818); iVar3 = FUN_800c3ca0(...); if (iVar3 == 0) { local_18 =
///   *param_2; uVar1 = countLeadingZeros(param_3); iVar3 =
///   FUN_800c43a0(param_1,uVar2,&local_18,uVar1 >> 5); ...`
///
/// # Arguments
/// - `obj`: line object.
/// - `point`: address of the `[x, y]` float pair.
/// - `flag`: forward selector.
