// 0x800B4FB0
// ---------------------------------------------------------------------------

/// Raises one course tile-table entry to at least the given value.
///
/// # Original
/// - Ghidra: `FUN_800b4fb0` at `0x800B4FB0` (144 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b4fb0_FUN_800b4fb0.c`
/// - observed: returns early when `G_COURSE_MODE & 0x10` is clear;
///   clamps `manager + 0x3E4` to `[0, 10]` and `manager + 1000`
///   (`+0x3E8`) to `[0, 9]`, uses `idx = b + a * 10` and the entry
///   `manager + idx * 8`; writes to `+0x404` when mode bit `0x40` is set
///   else `+0x774`, but only when the new value is larger.
///
/// # Arguments
/// - `value`: the value to store when it exceeds the current entry.
///
/// # Side effects
/// Writes one word of the strided tile tables cleared by
/// [`course_manager_clear_tile_lists`]; no write when mode bit `0x10` is
/// clear or when `value` does not exceed the entry.
///
/// # Safety
/// `*(r13 - 0x5704)` must point at a live course manager; the entry at
/// `manager + idx * 8 + 0x404` (or `+ 0x774`) must be writable.
///
/// # Confidence
/// medium - the gate, clamps and store are literal; the roles of the
/// `+0x3E4` / `+0x3E8` indices and of the two tables are inferred from
/// [`course_manager_clear_tile_lists`].
pub unsafe fn fn_800b4fb0(value: i32) {
    if read_u32(G_COURSE_MODE) & 0x10 == 0 {
        return;
    }
    // observed: `manager = *(r13 - 0x5704)`; clamp +0x3E4 to [0, 10],
    // +1000 to [0, 9]; idx = b + a * 10; entry = manager + idx * 8.
    let manager = read_u32(G_STAGE_SLOT_OWNER) as usize;
    let mut a = read_i32(manager + 0x3e4);
    if a < 0 {
        a = 0;
    }
    if a > 10 {
        a = 10;
    }
    let mut b = read_i32(manager + 0x3e8);
    if b < 0 {
        b = 0;
    }
    if b > 9 {
        b = 9;
    }
    let idx = b + a * 10;
    let entry = manager + idx as usize * 8;
    if read_u32(G_COURSE_MODE) & 0x40 != 0 {
        if value <= read_i32(entry + 0x404) {
            return;
        }
        write_u32(entry + 0x404, value as u32);
    } else {
        if value <= read_i32(entry + 0x774) {
            return;
        }
        write_u32(entry + 0x774, value as u32);
    }
}

// ---------------------------------------------------------------------------
// 0x800B5040
// ---------------------------------------------------------------------------

/// Drops one course tile-table entry by one.
///
/// # Original
/// - Ghidra: `FUN_800b5040` at `0x800B5040` (168 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b5040_FUN_800b5040.c`
/// - observed: same mode-`0x10` gate and the same clamped index as
///   [`fn_800b4fb0`]; reads `+0x404` (mode bit `0x40`) or `+0x774`,
///   returns unless the value is `1` or `3`, then stores `value - 1`.
///
/// # Arguments
/// None.
///
/// # Side effects
/// Decrements the selected tile-table entry by one when it is `1` or `3`;
/// no write while mode bit `0x10` is clear.
///
/// # Safety
/// `*(r13 - 0x5704)` must point at a live course manager; the selected
/// entry must be writable.
///
/// # Confidence
/// medium - the gate, clamps and `1` / `3` test are literal; the table
/// roles are inferred as in [`fn_800b4fb0`].
pub unsafe fn fn_800b5040() {
    if read_u32(G_COURSE_MODE) & 0x10 == 0 {
        return;
    }
    let manager = read_u32(G_STAGE_SLOT_OWNER) as usize;
    let mut a = read_i32(manager + 0x3e4);
    if a < 0 {
        a = 0;
    }
    if a > 10 {
        a = 10;
    }
    let mut b = read_i32(manager + 0x3e8);
    if b < 0 {
        b = 0;
    }
    if b > 9 {
        b = 9;
    }
    let idx = b + a * 10;
    let entry = manager + idx as usize * 8;
    if read_u32(G_COURSE_MODE) & 0x40 != 0 {
        let current = read_i32(entry + 0x404);
        if current != 1 && current != 3 {
            return;
        }
        write_u32(entry + 0x404, current.wrapping_sub(1) as u32);
    } else {
        let current = read_i32(entry + 0x774);
        if current != 1 && current != 3 {
            return;
        }
        write_u32(entry + 0x774, current.wrapping_sub(1) as u32);
    }
}

