/// Builds the fukidashi layout on first use.
///
/// Stores the owner id at `+0x88`, loads `fukidashiInfo_16.brlyt`, binds the
/// `inFukidashi` animation, the `A00_fukidashi` material animation, the
/// `P_afterImageUD1` pane (`+0x1FC`), and a second pane table at `+0x214`.
/// It then caches the root pane at `+0x1F4`, forces its `+0xBB` bit 0 on,
/// stops animation channels 0 and 1, resets the timer/kind fields, and marks
/// `+0x238` created. A second call is a no-op returning `1`.
///
/// # Original
/// - Ghidra: `FUN_800b1760` at `0x800B1760` (428 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b1760_FUN_800b1760.c`
/// - observed: the `+0x238` guard, the `0x800C8FB0` / `0x800C90F0` /
///   `0x80007220` / `0x800C8E40` / `0x800C8EB0` sequence and the final block of
///   `+0x1D8..+0x23A` stores.
///
/// # Arguments
/// - `this`: fukidashi object.
/// - `owner`: owner id stored at `+0x88`.
///
/// # Returns
/// `1` in every path (the original never returns `0`).
///
/// # Side effects
/// Allocates the NW4R layout subtree and writes the balloon's default timing,
/// animation and colour fields.
///
/// # Safety
/// `this` must be a constructed fukidashi object; the NW4R layout and
/// animation services must be initialised.
///
/// # Confidence
/// medium - the call order and stores are literal; the meaning of `+0x1F4`,
/// `+0x1FC`, `+0x208`, `+0x214` and the `0x208` triple is inferred from the
/// sibling bodies.
pub unsafe fn fn_800b1760(this: usize, owner: u32) -> u32 {
    if read_u8(this + 0x238) == 0 {
        write_u32(this + 0x88, owner);
        // +0xC holds the layout vtable; slot +0x14 mounts the brlyt resource.
        let layout_vtable = read_u32(this + 0xc) as usize;
        let mount = read_u32(layout_vtable + 0x14) as usize;
        platform::call3(mount, (this + 4) as u32, W45_LAYOUT_NAME as u32, 0);
        platform::call3(
            0x800C_8FB0,
            (this + 4) as u32,
            W45_ANIM_NAME as u32,
            7,
        );
        platform::call4(
            0x800C_90F0,
            (this + 4) as u32,
            W45_MATERIAL_ANIM_NAME as u32,
            W45_MATERIAL_PATTERN as u32,
            7,
        );
        let root = platform::call1(0x8000_7220, (this + 4) as u32);
        write_u32(this + 0x1f4, root);
 // inferred: root pane of the layout
        platform::call4(
            0x800C_8E40,
            (this + 4) as u32,
            W45_PANE_AFTERIMAGE as u32,
            (this + 0x1fc) as u32,
            6,
        );
        platform::call4(
            0x800C_8EB0,
            (this + 4) as u32,
            W45_PANE_NAME_ARRAY as u32,
            (this + 0x214) as u32,
            2,
        );
        let root = read_u32(this + 0x1f4) as usize;
        // root pane +0xBB bit 0 = visible
        write_u8(root + 0xbb, (read_u8(root + 0xbb) & 0xfe) | 1);
        platform::call3(0x800C_93D0, (this + 4) as u32, 0, 0);
        platform::call3(0x800C_93D0, (this + 4) as u32, 1, 0);
        platform::call1(0x800C_9560, (this + 4) as u32);
        // inferred: +0x208 is the text pane whose translation is reset here.
        let text = read_u32(this + 0x208) as usize;
        write_u32(text + 0x2c, read_u32(W45_SDA2_ZERO));
        // observed: the export self-assigns the y and z words.
        write_u32(text + 0x30, read_u32(text + 0x30));
        write_u32(text + 0x34, read_u32(text + 0x34));
        // Layout vtable slot +0x10 lays the subtree out.
        let layout_vtable = read_u32(this + 0xc) as usize;
        let layout = read_u32(layout_vtable + 0x10) as usize;
        platform::call1(layout, (this + 4) as u32);
        let zero = read_u32(W45_SDA2_ZERO);
        let root = read_u32(this + 0x1f4) as usize;
        write_u8(root + 0xbb, read_u8(root + 0xbb) & 0xfe);
        write_u32(this + 0x1d8, 0);
        write_u32(this + 0x1dc, zero);
        write_u32(this + 0x1e0, zero);
        write_u32(this + 0x1e4, zero);
        write_u32(this + 0x224, 0);
        write_u32(this + 0x228, 0x1e0);
        write_u32(this + 0x22c, 0);
        write_u8(this + 0x238, 1);
        write_u8(this + 0x239, 0);
        write_u8(this + 0x23a, 0);
        write_u32(this + 0x1f0, 3);
        write_u32(this + 0x230, 0xffff_ffff);
        write_u32(this + 0x1e8, read_u32(W45_SDA2_WORD_5D50));
        write_u32(this + 0x1ec, read_u32(W45_SDA2_WORD_5D4C));
    }
    1
}

