// ---------------------------------------------------------------------------
// 0x800B2070
// ---------------------------------------------------------------------------

/// Shows or hides the balloon's secondary pane for the current kind.
///
/// Saves the `+0x210` object's x/y/z, forces the root pane's `+0xBB` bit 0 on,
/// and then selects "visible" for kinds `3..8` and `0x13..0x15`, "hidden" for
/// `0..2` and `9..0x12`, and leaves the value untouched for negative kinds and
/// kinds above `0x15`. The x word is replaced by the `-0x6B28` or `-0x6B3C`
/// small-data float and the triple is stored back.
///
/// # Original
/// - Ghidra: `FUN_800b2070` at `0x800B2070` (272 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b2070_FUN_800b2070.c`
/// - observed: the `+0x220` range tests, the `+0xBB` bit updates, the two
///   `FUN_800c92f0` calls and the restored `+0x210` triple.
///
/// # Arguments
/// - `this`: fukidashi object.
///
/// # Side effects
/// Writes the `+0x214` pane visibility and the `+0x210` object's `+0x2C` word;
/// then calls [`fn_800b1eb0`].
///
/// # Safety
/// `+0x210`, `+0x214` and `+0x1F4` must hold live panes/objects.
///
/// # Confidence
/// medium - the control flow is literal; the `+0x210` triple is inferred as a
/// translation vector.
pub unsafe fn fn_800b2070(this: usize) {
    let target = read_u32(this + 0x210) as usize;
    let z = read_u32(target + 0x34);
    let y = read_u32(target + 0x30);
    let mut x = read_u32(target + 0x2c);
    let root = read_u32(this + 0x1f4) as usize;
    write_u8(root + 0xbb, (read_u8(root + 0xbb) & 0xfe) | 1);
    let kind = read_i32(this + 0x220);
    if (kind >= 3 && kind <= 8) || (kind >= 0x13 && kind <= 0x15) {
        let pane = read_u32(this + 0x214) as usize;
        write_u8(pane + 0xbb, (read_u8(pane + 0xbb) & 0xfe) | 1);
        platform::call3(0x800C_92F0, (this + 4) as u32, 1, 0);
        x = read_u32(W45_SDA2_VISIBLE_X);
    } else if kind >= 0 && kind <= 0x15 {
        let pane = read_u32(this + 0x214) as usize;
        write_u8(pane + 0xbb, read_u8(pane + 0xbb) & 0xfe);
        platform::call3(0x800C_92F0, (this + 4) as u32, 0, 0);
        x = read_u32(W45_SDA2_ZERO);
    }
    let target = read_u32(this + 0x210) as usize;
    write_u32(target + 0x2c, x);
    write_u32(target + 0x30, y);
    write_u32(target + 0x34, z);
    fn_800b1eb0(this);
}

