///
/// # Side effects
/// May rewrite the tag byte at `+0xA4` and the word at `+0xA0`.
///
/// # Safety
/// `this+0xA0..+0xA5` must be readable/writable.
///
/// # Confidence
/// medium - the stores and comparisons are literal; the table's role as a
/// weight ranking is inferred from the three sibling functions.
pub unsafe fn fn_80070650(this: usize, candidate: u32) -> u32 {
    let new_weight = read_i32(W61_WEIGHT_TABLE + ((candidate >> 14) & 0x3fc) as usize);
    let current_weight = read_i32(W61_WEIGHT_TABLE + (read_u8(this + 0xa4) as usize) * 4);
    if current_weight < new_weight {
        write_u8(this + 0xa4, (candidate >> 16) as u8);
        write_u32(this + 0xa0, candidate);
    }
    if read_u8(this + 0xa4) == 3 {
        0
    } else {
        1
    }
}

