// ---------------------------------------------------------------------------
// 0x80070CD0
// ---------------------------------------------------------------------------

/// Applies the owner record's status bits to the current object.
///
/// The function takes the current object from the incoming `r3` and the id
/// from the incoming `r4`. It copies the
/// owner's `+0x30` byte into the local flag word, optionally sets bit `0`
/// when `0x80056900` rejects the id, and runs `0x800D9940`. On success it sets
/// `0x8000` (and, when [`fn_80070760`] reports a non-zero band, `0xC000`) in
/// both the local result and `this+0x88`, then mirrors four bits from the
/// record returned by `0x800D9900`:
///
/// | record `+0x3C` bit | result bit | `this+0x88` bit |
/// |---|---|---|
/// | `0x8000` | `0x40000` | `0x40000` |
/// | `0x20000` | `0x80000` | `0x80000` |
/// | `0x40000` | `0x100000` | `0x100000` |
/// | `0x100000` | `0x20000` | `0x20000` |
///
/// Finally `0x80056CF0` marks byte `+0x46`, byte `+0x47` feeds
/// [`fn_80070650`], and record bit `0x200` clears both `0x4000` masks before
/// `+0x58` is zeroed. The local word is published through `0x802DCDC0`.
///
/// # Original
/// - Ghidra: `FUN_80070cd0` at `0x80070CD0` (408 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80070cd0_FUN_80070cd0.c`
/// - observed: the packed `uVar6 = FUN_802dcd74();`, `iVar1 = (int)(uVar6 >> 0x20)`,
///   the four `+0x3C` bit tests, the `0x80056CF0(...,0x1c)` test, the
///   `0x80070650(iVar1,(uint)*(byte *)(iVar2 + 0x47) << 0x10)` call and the
///   closing `FUN_802dcdc0(uVar4);`.
/// - Removed: the modelled `_savegpr_27` prologue call (`0x802DCD74`) and the modelled
///   `_restgpr_27` epilogue call (`0x802DCDC0`).
///   `this` is the incoming `r3` and `handle` the incoming `r4`.
///
/// # Arguments
/// - `_param_1`: the current object (`r3`).
/// - `_param_2`: the current id (`r4`).
/// - `param_3`: forwarded to `0x800D9940`.
///
/// # Returns
/// The accumulated status word.
///
/// # Side effects
/// Updates `this+0x88`, `this+0x58` and record bytes `+0x46`/flags, and calls
/// the four external helpers.
///
/// # Safety
/// The object in `_param_1` must be live, its `+0x50` owner (when
/// non-null) must be valid, and the record returned by `0x800D9900` (when
/// non-null) must be readable/writable at `+0x3C..+0x48`.
///
/// # Confidence
/// medium - every mask and store is literal; the object/id split is the
/// incoming `r3`/`r4` pair and the helper roles are inferred.
pub unsafe fn fn_80070cd0(_param_1: u32, _param_2: u32, param_3: u32) -> u32 {
    let this = _param_1 as usize;
    let handle = _param_2;
    let mut result = 0u32;
    let owner = read_u32(this + 0x50);
    if owner != 0 {
        let mut flags = read_u8(owner as usize + 0x30);
        if platform::call1(W61_CALL_80056900, handle) == 0 {
            flags |= 1;
        }
        let loaded = platform::call4(
            W61_CALL_800D9940,
            owner,
            param_3,
            flags as u32,
            0,
        );
        if loaded != 0 && flags & 1 == 0 {
            result = 0x8000;
            write_u32(this + 0x88, read_u32(this + 0x88) | 0x8000);
            if platform::call1(W61_CALL_80070760, this as u32) != 0 {
                result = 0xc000;
                write_u32(this + 0x88, read_u32(this + 0x88) | 0x4000);
            }
            let sub = platform::call1(W61_CALL_800D9900, owner) as usize;
            if sub != 0 {
                let bits = read_u32(sub + 0x3c);
                if bits & 0x8000 != 0 {
                    result |= 0x40000;
                    write_u32(this + 0x88, read_u32(this + 0x88) | 0x40000);
                }
                if bits & 0x20000 != 0 {
                    result |= 0x80000;
                    write_u32(this + 0x88, read_u32(this + 0x88) | 0x80000);
                }
                if bits & 0x40000 != 0 {
                    result |= 0x100000;
                    write_u32(this + 0x88, read_u32(this + 0x88) | 0x100000);
                }
                if bits & 0x100000 != 0 {
                    result |= 0x20000;
                    write_u32(this + 0x88, read_u32(this + 0x88) | 0x20000);
                }
                if platform::call2(W61_CALL_80056CF0, handle, 0x1c) != 0 {
                    write_u8(sub + 0x46, read_u8(sub + 0x46) | 1);
                }
                if read_u8(sub + 0x47) != 0 {
                    platform::call2(
                        W61_CALL_80070650,
                        this as u32,
                        (read_u8(sub + 0x47) as u32) << 16,
                    );
                }
                if bits & 0x200 != 0 {
                    result &= 0xffff_3fff;
                    write_u32(this + 0x88, read_u32(this + 0x88) & 0xffff_3fff);
                }
                write_u32(this + 0x58, 0);
            }
        }
    }
    result
}
// ===========================================================================
// Wave 62 - course-manager message text, effect slots and marker records
// ===========================================================================

// ---------------------------------------------------------------------------

// Shared data addresses for the three wave-62 clusters

// ---------------------------------------------------------------------------

/// `0x80354E60`: four colour rows selected by the message-text helpers.
///
/// observed: `uVar1 = (&DAT_80354e60)[param_3];` in `0x800B3540`. The same
/// table is already documented for the fukidashi colour panes.
const W62_COLOR_ROWS: usize = 0x8035_4E60;

/// `0x8010CFA0`: text draw with the alternate transform flag set.
const W62_DRAW_TEXT_ALT: usize = 0x8010_CFA0;

/// `0x8010CEF0`: the plain text draw used by both message helpers.
const W62_DRAW_TEXT: usize = 0x8010_CEF0;

/// `r13 - 0x53B0` → `0x8042A2D0`: text object shared by the message helpers.
const W62_TEXT_OBJECT: usize = SDA_BASE - 0x53B0;

/// `r13 - 0x53B8` → `0x8042A2C8`: second text object used by `0x800B44D0`.
const W62_TEXT_OBJECT_B: usize = SDA_BASE - 0x53B8;

/// `r13 - 0x5360` → `0x8042A320`: scene object that owns the per-slot state.
const W62_SCENE_OBJECT: usize = SDA_BASE - 0x5360;

/// `r13 - 0x547C` → `0x8042A204`: non-zero while the scene is frozen.
const W62_SCENE_FREEZE: usize = SDA_BASE - 0x547C;

/// `r13 - 0x5704` → `0x80429F7C`: pointer to the actor-status array base.
const W62_ACTOR_TABLE: usize = SDA_BASE - 0x5704;

/// `r13 - 0x569F` / `r13 - 0x56A0`: the two ready flags OR-ed into bit 0.
const W62_READY_FLAG_A: usize = SDA_BASE - 0x569F;
const W62_READY_FLAG_B: usize = SDA_BASE - 0x56A0;

/// `r13 - 0x56A8` → `0x80429FD8`: optional object tested for bit 2.
const W62_READY_OBJECT: usize = SDA_BASE - 0x56A8;

/// `r13 - 0x5490` → `0x8042A1F0`: optional object whose `+0xB8` byte sets bit 2.
const W62_READY_OWNER: usize = SDA_BASE - 0x5490;

/// `r13 - 0x5738` → `0x80429F48`: the packed status word maintained by
/// `0x800B3A30` and read by `0x800B3B50`.
const W62_STATUS_WORD: usize = SDA_BASE - 0x5738;

/// `0x802F0AF8`: per-kind byte table consulted by `0x800B3600`.
const W62_ACTOR_KIND_TABLE: usize = 0x802F_0AF8;

/// `0x802F8FF0`: the RTTI/type record passed to the `+8` virtual test.
const W62_EFFECT_TYPE: usize = 0x802F_8FF0;

/// `r13 - 0x5798` → `0x80429EE8`: render object used by `0x800B82D0`.
const W62_RENDER_OBJECT: usize = SDA_BASE - 0x5798;

/// `r13 - 0x5718` → `0x80429F68`: live marker count, bumped by the record
/// constructor and decremented by its destructor.
const W62_MARKER_COUNT: usize = SDA_BASE - 0x5718;

/// `0x80358AA0`: eight template rows, `0x20` bytes apart, copied by
/// `0x800B80E0` / `0x800B81C0`.
const W62_MARKER_TABLE: usize = 0x8035_8AA0;

/// `r2 - 0x6A58` → `0x8042C628`: the float word stored at scratch `+8` for both
/// virtual marker calls.
const W62_MARKER_SCRATCH_F: usize = SDA2_BASE - 0x6A58;

// ---------------------------------------------------------------------------
// 0x800B3540
// ---------------------------------------------------------------------------

/// Draws one message-text row with a colour picked from the `0x80354E60` table.
///
/// Row `0xFFFFFFFF` means "no row" and uses colour slot `4`; rows `0..3` are
/// looked up as words in the table. Any other row is ignored. The body then
/// draws through `0x8010CFA0` when `alternate` is non-zero, otherwise through
/// `0x8010CEF0`.
///
/// # Original
/// - Ghidra: `FUN_800b3540` at `0x800B3540` (100 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b3540_FUN_800b3540.c`
/// - observed: `if (param_3 == 0xffffffff) { uVar1 = 4; }` and
///   `uVar1 = (&DAT_80354e60)[param_3];`, followed by the two four-argument
///   draw calls with `*(undefined4 *)(unaff_r13 + -0x53b0)` as the object.
///
/// # Arguments
/// - `text_a`, `text_b`: the two text arguments forwarded to the draw call.
/// - `row`: colour-row selector, `0xFFFFFFFF` for the fallback row.
/// - `alternate`: selects `0x8010CFA0` (non-zero) or `0x8010CEF0` (zero).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Emits one text draw into the shared text object.
///
/// # Safety
/// The text object at [`W62_TEXT_OBJECT`] must be live and the draw callee
/// must accept the four original arguments.
///
/// # Confidence
/// high - the sentinel, the table lookup and the two forwarding calls are
/// literal.
pub unsafe fn fn_800b3540(text_a: u32, text_b: u32, row: u32, alternate: i32) {
    let colour = if row == 0xFFFF_FFFF {
        4
    } else {
        if row > 3 {
            return;
        }
        read_u32(W62_COLOR_ROWS + row as usize * 4)
    };
    let object = read_u32(W62_TEXT_OBJECT);
    if alternate != 0 {
        platform::call4(W62_DRAW_TEXT_ALT, object, text_a, text_b, colour);
    } else {
        platform::call4(W62_DRAW_TEXT, object, text_a, text_b, colour);
    }
}

// ---------------------------------------------------------------------------
// 0x800B35B0
// ---------------------------------------------------------------------------

/// Draws one text row through the plain text entry point with fixed colour `0`.
///
/// # Original
/// - Ghidra: `FUN_800b35b0` at `0x800B35B0` (20 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b35b0_FUN_800b35b0.c`
/// - observed: `FUN_8010cef0(*(undefined4 *)(unaff_r13 + -0x53b0),param_1,0x14,0);`.
///
/// # Arguments
/// - `text`: text argument forwarded unchanged.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Emits one text draw; the `0x14`/`0` pair is literal.
///
/// # Safety
/// Same requirements as [`fn_800b3540`].
///
/// # Confidence
/// high - the call and its two constants are literal.
pub unsafe fn fn_800b35b0(text: u32) {
    platform::call4(W62_DRAW_TEXT, read_u32(W62_TEXT_OBJECT), text, 0x14, 0);
}

// ---------------------------------------------------------------------------
// 0x800B3600
// ---------------------------------------------------------------------------

/// Starts or restarts one actor after checking the scene's four active slots.
///
/// The function first bails out while the freeze word is non-zero. A non-zero
/// [`W62_ACTOR_KIND_TABLE`] entry then makes it compare `kind` against the
/// active id of each of the scene's four `0x23C`-stride records; a match means
/// the actor is already running and the call returns. Kind `1` additionally
/// checks a per-slot byte at `actor_base + slot + 0xB56`, and every kind checks
/// the actor-status byte at `actor_base + slot * 0x16 + kind + 0xAFE`.
///
/// The selected record is `scene + slot * 0x23C`. If its `+0x381` byte is
/// clear the function forwards to `0x801571A0` (start); otherwise it only
/// restarts the timer when `kind` equals the record's `+0x368` id, copying
/// `+0x370` into `+0x36C` and clearing `+0x37C`.
///
/// # Original
/// - Ghidra: `FUN_800b3600` at `0x800B3600` (268 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b3600_FUN_800b3600.c`
/// - observed: the `r13-0x547c` early return, the four
///   `+0x381`/`+0x368` pairs at `0x368`, `0x5A4`, `0x7E0`, `0xA1C`, the
///   `+0xB56` and `+0xAFE` byte tests and the final `FUN_801571a0` call.
///
/// # Arguments
/// - `slot`: scene/actor slot, used for both the `0x23C` and `0x16` strides.
/// - `kind`: actor kind, used as the table index and the per-record id.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// May start an actor through `0x801571A0`, or rewrite `+0x36C`/`+0x37C` of
/// the matching scene record.
///
/// # Safety
/// The scene pointer and the actor-status base must be readable; `slot` and
/// `kind` must stay inside the arrays the original indexes.
///
/// # Confidence
/// medium - every offset, stride and early return is literal; the record roles
/// (slot actor state versus shared status byte) are inferred from the strides.
pub unsafe fn fn_800b3600(slot: i32, kind: i32) {
    if read_u32(W62_SCENE_FREEZE) != 0 {
        return;
    }
    let scene = read_u32(W62_SCENE_OBJECT) as usize;
    if read_u8(W62_ACTOR_KIND_TABLE + kind as usize) != 0 {
        // observed: four active-slot records, one per scene record.
        if read_u8(scene + 0x381) != 0 && kind == read_i32(scene + 0x368) {
            return;
        }
        if read_u8(scene + 0x5BD) != 0 && kind == read_i32(scene + 0x5A4) {
            return;
        }
        if read_u8(scene + 0x7F9) != 0 && kind == read_i32(scene + 0x7E0) {
            return;
        }
        if read_u8(scene + 0xA35) != 0 && kind == read_i32(scene + 0xA1C) {
            return;
        }
    }
    let actor_base = read_u32(W62_ACTOR_TABLE) as usize;
    if kind == 1 && read_u8(actor_base + slot as usize + 0xB56) != 0 {
        return;
    }
    if scene == 0 {
        return;
    }
    if read_u8(actor_base + slot as usize * 0x16 + kind as usize + 0xAFE) != 0 {
        return;
    }
    let record = scene + slot as usize * 0x23C;
    if read_u8(record + 0x381) == 0 {
        platform::call3(0x8015_71A0, scene as u32, slot as u32, kind as u32);
        return;
    }
    if kind != read_i32(record + 0x368) {
        return;
    }
    write_u32(record + 0x36C, read_u32(record + 0x370));
    write_u32(record + 0x37C, 0);
}

