/// Runs the ground/side probe block and folds the results into one flag byte.
///
/// # Original
/// - Ghidra: `FUN_80096e60` at `0x80096E60` (248 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80096e60_FUN_80096e60.c`
/// - observed: `uVar1 = FUN_80096f60();`, the `+0xEC` zero store when it is
///   non-zero, `FUN_8006ef40(param_1 + 0x1ec,uVar1)` for bit `2`,
///   `FUN_80097050(param_1)` for bit `4`, and the `+0x274`/`+0x23C` guarded
///   `FUN_800d9a30(..., (uVar2 | uVar3 | uVar1) & 0x1f6000, 0.0f < +0xEC, 0)`
///   that clears bit `0x8000`.
///
/// # Arguments
/// - `this`: `Wm` actor.
///
/// # Returns
/// Bit `0` when the ground block reported contact, bit `1` from
/// `0x8006EF40`, bit `2` from [`fn_80097050`].
///
/// # Side effects
/// Writes `+0xEC` and may clear the `0x8000` bit of `+0x274`.
///
/// # Safety
/// `this` must be a live actor of at least `0x278` bytes.
///
/// # Confidence
/// medium - every offset, mask and call is literal; the roles of the `0x8006EF40`
/// and `0x800D9A30` results are inferred from the bit folding.
pub unsafe fn fn_80096e60(this: usize) -> u8 {
    let ground = fn_80096f60(this);
    let mut flags = u8::from(ground != 0);
    if flags != 0 {
        write_u32(this + 0xEC, read_u32(W69_F_ZERO));
    }
    let near = platform::call2(0x8006_EF40, (this + 0x1EC) as u32, ground);
    if near != 0 {
        flags |= 2;
    }
    let side = fn_80097050(this);
    if side != 0 {
        flags |= 4;
    }
    let status = read_u32(this + 0x274);
    if status & 0x8000 != 0 && status & 3 != 0 && read_u32(this + 0x23C) != 0 {
        let hit = platform::call4(
            0x800D_9A30,
            read_u32(this + 0x23C),
            (near | side | ground) & 0x001F_6000,
            u32::from(read_f32(W69_F_ZERO) < read_f32(this + 0xEC)),
            0,
        );
        if hit == 0 {
            write_u32(this + 0x274, read_u32(this + 0x274) & 0xFFFF_7FFF);
        }
    }
    flags
}

