///   `FUN_80072bc0(+0x1EC)` return value, the two `+0x45C`/`+0x45E` clears, the
///   `FUN_80070cb0` branch that clears `+0x440..+0x448`, and the
///   `FUN_80070720` branch that copies `+0x20C..+0x214` into `+0x440..+0x448`
///   and sets `+0x45C` for state `3` / `+0x45E` for state `1`.
///
/// # Arguments
/// - `this`: `Wm` actor.
///
/// # Returns
/// The `0x80072BC0` status when `+0x1F4` is set, `0` otherwise.
///
/// # Side effects
/// Writes the three contact accumulators and the two contact flags.
///
/// # Safety
/// `this` must be a live actor of at least `0x460` bytes.
///
/// # Confidence
/// high - every branch, offset and store is literal.
pub unsafe fn fn_80096f60(this: usize) -> u32 {
    if read_u32(this + 0x1F4) == 0 {
        let zero = read_u32(W69_F_ZERO);
        write_u32(this + 0x44C, zero);
        write_u32(this + 0x450, zero);
        write_u32(this + 0x454, zero);
        return 0;
    }
    let status = platform::call1(0x8007_2BC0, (this + 0x1EC) as u32);
    write_u8(this + 0x45C, 0);
    write_u8(this + 0x45E, 0);
    if platform::call1(0x8007_0CB0, (this + 0x1EC) as u32) == 0 {
        let zero = read_u32(W69_F_ZERO);
        write_u32(this + 0x440, zero);
        write_u32(this + 0x444, zero);
        write_u32(this + 0x448, zero);
    } else {
        let state = platform::call1(0x8007_0720, (this + 0x1EC) as u32);
        if state == 3 {
            write_u8(this + 0x45C, 1);
        }
        if state == 1 {
            write_u8(this + 0x45E, 1);
        }
        write_u32(this + 0x440, read_u32(this + 0x20C));
        write_u32(this + 0x444, read_u32(this + 0x210));
        write_u32(this + 0x448, read_u32(this + 0x214));
        let zero = read_u32(W69_F_ZERO);
        write_u32(this + 0x44C, zero);
        write_u32(this + 0x450, zero);
        write_u32(this + 0x454, zero);
    }
    status
}

