/// Smooths the camera's yaw-driven scroll offset and clamps it.
///
/// The target is `scale * player[+0xC4]`; when it differs from the stored delta
/// the step is limited to `±max` around the previous value, clamped to the
/// configured window, added into `+0x8FE44` and itself limited to
/// `±[+0x8FE50]`. The actually applied delta is written back to `+0x8FE18`.
///
/// # Original
/// - Ghidra: `FUN_800799e0` at `0x800799E0` (188 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800799e0_FUN_800799e0.c`
/// - observed: the `r2-0x72FC` scale, the zero guard on `r2-0x7370`, the
///   `±(r2-0x72F8)` step limit, the `r2-0x72F0`/`r2-0x72EC` clamp and the
///   `+0x8FE44`/`+0x8FE4C`/`+0x8FE50` writes.
///
/// # Arguments
/// - `this`: camera/scene owner.
/// - `subject`: player object whose `+0xC4` float drives the scroll.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x8FE44` and `+0x8FE18`.
///
/// # Safety
/// `this+0x8FE18..+0x8FE50` and `subject+0xC4` must be readable/writable.
///
/// # Confidence
/// medium - the control flow is literal; the "yaw" role of `+0xC4` and the
/// constant names are inferred from the arithmetic.
pub unsafe fn fn_800799e0(this: usize, subject: usize) {
    let target = read_f32(W70_F_SCROLL_STEP) * read_f32(subject + 0xc4);
    let previous = read_f32(this + 0x8fe18);
    if read_f32(W70_F_ZERO) == target {
        return;
    }
    let limit = read_f32(W70_F_SCROLL_MAX);
    let mut step = target;
    let delta = target - previous;
    if delta <= limit {
        if delta < read_f32(W70_F_SCROLL_MIN) {
            step = previous - limit;
        }
    } else {
        step = limit + previous;
    }
    let upper = read_f32(W70_F_SCROLL_CLAMP_HI);
    let mut amount = upper;
    if step <= upper {
        amount = step;
        let lower = read_f32(W70_F_SCROLL_CLAMP_LO);
        if step < lower {
            amount = lower;
        }
    }
    let current = read_f32(this + 0x8fe44);
    let boundary = read_f32(this + 0x8fe4c);
    let moved = current + amount;
    write_f32(this + 0x8fe44, moved);
    if moved <= boundary {
        let floor = -read_f32(this + 0x8fe50);
        if moved < floor {
            write_f32(this + 0x8fe44, floor);
            amount = floor - current;
        }
    } else {
        amount = boundary - current;
        write_f32(this + 0x8fe44, boundary);
    }
    write_f32(this + 0x8fe18, amount);
}

