/// `r2 - 0x6818` → `0x8042C868`: `16.0f`, used as a seed offset and as the
/// literal heading of [`fn_800c6f60`] and [`fn_800c7020`].
const W71_F_6818: usize = SDA2_BASE - 0x6818;

/// `r2 - 0x6844` → `0x8042C83C`: `0.0f`, the zero of the seed tables.
const W71_F_6844: usize = SDA2_BASE - 0x6844;

/// `r2 - 0x67E8` → `0x8042C898`: `32.0f`, used as a seed offset and as the
/// literal heading of [`fn_800c7080`] and [`fn_800c71a0`].
const W71_F_67E8: usize = SDA2_BASE - 0x67E8;

/// `r2 - 0x67A4` → `0x8042C8DC`: `-8.0f`, the y offset of the first seed.
const W71_F_67A4: usize = SDA2_BASE - 0x67A4;

/// `r2 - 0x679C` → `0x8042C8E4`: `-16.0f`, the y offset of the second seed.
const W71_F_679C: usize = SDA2_BASE - 0x679C;

/// `r2 - 0x6794` → `0x8042C8EC`: `-32.0f`, the y offset of the wide seed.
const W71_F_6794: usize = SDA2_BASE - 0x6794;

/// `r2 - 0x687C` → `0x8042C804`: `0.5f`, the damping factor of
/// [`fn_800c0540`]. observed: `*(float *)(unaff_r2 + -0x687c)`.
const W71_F_687C: usize = SDA2_BASE - 0x687C;

/// `0x800C3A10(angle, obj, delta)`: turns a `(dx, dy)` pair into the line
/// object's `+0x40`/`+0x44`/`+0x58`/`+0x5C` endpoints. Untranslated here
/// because its body is a paired-single `GQR0`/`GQR3` block.
const W71_LINE_SEED: usize = 0x800C_3A10;

/// `0x8016A960(owner, size, allocator, name, align, flag)`: builds a
/// resource array. Same helper the BG texture manager uses.
const W71_ALLOC_INIT: usize = 0x8016_A960;

/// `0x8016A9B0(owner)`: closes an `0x8016A960` array.
const W71_ALLOC_FINISH: usize = 0x8016_A9B0;

/// `0x802B9210(size)`: small-object allocator returning 0 on failure.
const W71_ALLOC_SMALL: usize = 0x802B_9210;

/// `0x802B9240(size, parent, align)`: child allocator.
const W71_ALLOC_CHILD: usize = 0x802B_9240;

/// `0x802B9280(object, size)`: deletes one allocation.
const W71_DELETE_ONE: usize = 0x802B_9280;

/// `0x802E441C()`: unit count of a `u16` text buffer.
const W71_TEXT_UNITS: usize = 0x802E_441C;

/// `0x803178C8`: `dMaskMng::m_allocator`, the cell-array name.
const W71_MASK_ALLOC_NAME: usize = 0x8031_78C8;

/// `0x800CBF60()` / `0x800CBFA0(object, heap, -1, 0x8A)`: first aux object.
const W71_MASK_A_CTOR: usize = 0x800C_BF60;
const W71_MASK_A_INIT: usize = 0x800C_BFA0;

/// `0x800CC250()` / `0x800CC2A0(object, heap, -1, 0x87)`: second aux object.
const W71_MASK_B_CTOR: usize = 0x800C_C250;
const W71_MASK_B_INIT: usize = 0x800C_C2A0;

/// `0x800CE700(cell, base, flags)`: the 0x20-byte cell constructor.
const W71_MASK_CELL_CTOR: usize = 0x800C_E700;

/// `0x8006C7F0(object, 0)`: unlink used before an optional delete.
const W71_UNLINK: usize = 0x8006_C7F0;

// ---------------------------------------------------------------------------
// 0x800C0540
// ---------------------------------------------------------------------------

/// Advances the lift actor's damping offsets by one frame.
///
/// Copies `+0xE4`/`+0xE8` to `+0xF0`/`+0xF4` and integrates `+0xEC` from
/// `+0xE0` with half of the `+0x128` speed.
///
/// # Original
/// - Ghidra: `FUN_800c0540` at `0x800C0540` (44 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c0540_FUN_800c0540.c`
/// - observed: `*(float *)(param_1 + 0xec) = *(float *)(param_1 + 0xe0) +
///   fVar1 * *(float *)(param_1 + 0x128);` with `fVar1 = *(r2 - 0x687c)`.
///
/// # Arguments
/// - `actor`: lift actor; `+0xE0..+0x128` must be readable.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0xEC`, `+0xF0` and `+0xF4`.
///
/// # Safety
/// `actor+0xE0..actor+0x12C` must be readable and `+0xEC..+0xF8` writable.
///
/// # Confidence
/// high - three copies, one multiply-add and the `0.5f` are literal.
pub unsafe fn fn_800c0540(actor: usize) {
    write_u32(actor + 0xf0, read_u32(actor + 0xe4));
    write_u32(actor + 0xf4, read_u32(actor + 0xe8));
    write_f32(
        actor + 0xec,
        read_f32(actor + 0xe0) + read_f32(W71_F_687C) * read_f32(actor + 0x128),
    );
}

// ---------------------------------------------------------------------------
// 0x800C12B0
// ---------------------------------------------------------------------------

/// Copies the lift actor's two position words into a caller buffer.
///
/// # Original
/// - Ghidra: `FUN_800c12b0` at `0x800C12B0` (20 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c12b0_FUN_800c12b0.c`
/// - observed: `uVar1 = *(undefined4 *)(param_2 + 0x44); *param_1 =
///   *(undefined4 *)(param_2 + 0x40); param_1[1] = uVar1;`.
///
/// # Arguments
/// - `out`: two-word destination.
/// - `actor`: lift actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes 8 bytes at `out`.
///
/// # Safety
/// `out` must provide 8 writable bytes; `actor+0x40..actor+0x48` readable.
///
/// # Confidence
/// high - two loads and two stores, nothing else.
pub unsafe fn fn_800c12b0(out: usize, actor: usize) {
    write_u32(out, read_u32(actor + 0x40));
    write_u32(out + 4, read_u32(actor + 0x44));
}

// ---------------------------------------------------------------------------
// 0x800C1510
// ---------------------------------------------------------------------------

/// Stores a signed speed into the actor's `+0x60`, negating it when the
/// `+0x68` byte is set.
///
/// # Original
/// - Ghidra: `FUN_800c1510` at `0x800C1510` (24 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c1510_FUN_800c1510.c`
/// - observed: `if (*(char *)(param_2 + 0x68) != '\0') { param_1 = -param_1; }
///   *(float *)(param_2 + 0x60) = (float)param_1;`.
///
/// # Arguments
/// - `value`: speed read from the `f1` register (the export prints it as a
///   `double` argument).
/// - `actor`: lift actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x60`.
///
/// # Safety
/// `actor+0x60` writable and `actor+0x68` readable.
///
/// # Confidence
/// high - the flag test, the negation and the store are literal.
pub unsafe fn fn_800c1510(value: f32, actor: usize) {
    let signed = if read_u8(actor + 0x68) != 0 {
        -value
    } else {
        value
    };
    write_f32(actor + 0x60, signed);
}

