/// `point` must be readable for eight bytes; `this + 0x60` must hold a live
/// vtable whose `+0x21C` slot takes the object in `r3`.
///
/// # Confidence
/// high - the probe arguments, the `1..=2` window and the callback slot are
/// literal; the export's `double` casts are the usual `f32` load artefact,
/// which [`call_f32x2_u32x2`] reproduces.
pub unsafe fn fn_80097700(this: usize, point: usize) -> bool {
    let status = call_f32x2_u32x2(
        0x8007_5270,
        read_f32(point),
        read_f32(point + 4),
        read_u8(this + 0x38F) as u32,
        0,
    );
    let grounded = status.wrapping_sub(1) < 2;
    if grounded {
        let vtable = read_u32(this + 0x60) as usize;
        platform::call1(read_u32(vtable + 0x21C) as usize, this as u32);
    }
    grounded
}

