/// high - the loop bound, both calls and the comparison are literal; the
/// export prints `FUN_8005f900` as `void`, but the same call site stores its
/// `r3`, so the body uses the returned word.
pub unsafe fn fn_800979b0(owner: usize) -> u32 {
    for index in 0..4u32 {
        let player = platform::call1(0x8005_F900, index);
        if player != 0
            && platform::call1(0x8016_2D00, read_u32(player as usize + 0x2A78)) == owner as u32
        {
            return 1;
        }
    }
    0
}

