/// no arguments, so only its first slot (the object) is supplied.
pub unsafe fn fn_800c1070(this: usize, owned: i32) -> usize {
    if this != 0 && owned > 0 {
        platform::call1(W71_DELETE_ONE, this as u32);
    }
    this
}

