/// printed as `double`, so they are reconstructed from the `f1`/`f2` slots.
pub unsafe fn fn_800cb0f0(first: f32, second: f32, this: usize, source: usize) -> usize {
    write_u32(this, W85_VT_803177E0 as u32);
    write_u32(this + 8, read_u32(source));
    write_u32(this + 0xc, read_u32(source + 4));
    write_u32(this + 0x10, read_u32(source + 8));
    write_f32(this + 0x64, first);
    write_f32(this + 0x68, second);
    let child = platform::call1(W85_ALLOC_SMALL, 0x10);
    let built = if child != 0 {
        platform::call4(W85_CAVE_BUILD, child, 10, 8, 0)
    } else {
        0
    };
    write_u32(this + 4, built);
    let zero = read_u32(W85_F_6738);
    // observed: the twenty stores cover +0x14..+0x60 without a gap.
    for offset in (0x14..=0x60).step_by(4) {
        write_u32(this + offset, zero);
    }
    this
}

