///
/// # Original
/// - Ghidra: `FUN_800ccd90` at `0x800CCD90` (112 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800ccd90_FUN_800ccd90.c`
/// - observed: `*param_1 = &DAT_80317830;`, the six
///   `DAT_80377dc8/DAT_80377dcc/DAT_80377dd0` loads, the two `u16` clears and
///   `param_1[8] = uVar1; param_1[9] = uVar1; param_1[10] = 0;` plus the three
///   trailing zero words.
///
/// # Arguments
/// - `this`: record to build.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the whole `0x38`-byte record.
///
/// # Safety
/// `this` must be writable through `+0x37`.
///
/// # Confidence
/// high - every store and the vtable are literal; the descriptor's role is
/// inferred from the duplicated copy.
pub unsafe fn fn_800ccd90(this: usize) {
    write_u32(this, W85_VT_80317830 as u32);
    let a = read_u32(W85_ROW_DESCRIPTOR);
    let b = read_u32(W85_ROW_DESCRIPTOR + 4);
    let c = read_u32(W85_ROW_DESCRIPTOR + 8);
    write_u32(this + 4, a);
    write_u32(this + 8, b);
    write_u32(this + 0xc, c);
    write_u32(this + 0x10, a);
    write_u32(this + 0x14, b);
    write_u32(this + 0x18, c);
    write_u16(this + 0x1c, 0);
    write_u16(this + 0x1e, 0);
    let zero = read_u32(W85_F_6700);
    write_u32(this + 0x20, zero);
    write_u32(this + 0x24, zero);
    write_u32(this + 0x28, 0);
    write_u32(this + 0x2c, 0);
    write_u32(this + 0x30, 0);
    write_u32(this + 0x34, 0);
}

