unsafe fn w91_call_f64_u32_u32(addr: usize, value: f64, a: u32, b: u32) -> u32 {
    let f: extern "C" fn(f64, u32, u32) -> u32 = core::mem::transmute(addr);
    f(value, a, b)
}

/// Calls a PowerPC function that takes one `f64` (in `f1`) and three integer
