/// (the ratio in `f1`, the scene in `r3`) are restored from the callee exports.
pub unsafe fn fn_800791d0(this: usize) {
    let ratio = fn_80079060(this);
    let mut value = fn_80078860(ratio, this);
    let colour_a = read_f32(G_BG_COL_A) as f64;
    let colour_b = read_f32(G_BG_COL_B) as f64;
    if (read_f32(this + 0x8fea0) as f64) < ((value * colour_a) as f32) as f64 {
        value = ((read_f32(this + 0x8fea0) as f64) / colour_a) as f32 as f64;
    }
    if (read_f32(this + 0x8fea4) as f64) < ((value * colour_b) as f32) as f64 {
        value = ((read_f32(this + 0x8fea4) as f64) / colour_b) as f32 as f64;
    }
    write_f32(this + 0x90028, (W91_D_ONE / value) as f32);
}

// ---------------------------------------------------------------------------
// 0x80072DB0
// ---------------------------------------------------------------------------

/// Decodes one trigger record into three world coordinates.
///
/// The record lives at `[this+8]`. Its first word is a shape selector: bit 0
/// clear means the words at `+4`/`+8` are a box corner and are emitted twice,
/// bit 0 set means the ordered span `+4`/`+8` is emitted ascending with `+0xC`
/// as the third coordinate.
///
/// # Original
/// - Ghidra: `FUN_80072db0` at `0x80072DB0` (344 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80072db0_FUN_80072db0.c`
/// - observed: the `+8` null guard, `(*puVar2 & 1)` on the record word, the
///   `(int)puVar2[1] < (int)puVar2[2]` swap and the five
///   `CONCAT44(0x43300000, ... ^ 0x80000000)` conversions divided by the
///   `0x8042BC74` float.
///
/// # Arguments
/// - `this`: owner object; `+8` holds the record pointer.
/// - `out`: destination for the three coordinates.
///
/// # Returns
/// `1` when a record was decoded, `0` when `+8` is null.
///
/// # Side effects
/// Writes three floats through `out`.
///
/// # Safety
/// `this` must be readable at `+8` and `out` writable for 12 bytes.
///
/// # Confidence
/// medium - the selector, the swap and the five stores are literal; the fixed
/// point scale and the shape meaning are inferred from the arithmetic.
pub unsafe fn fn_80072db0(this: usize, out: usize) -> u32 {
    let record = read_u32(this + 8) as usize;
    if record == 0 {
        return 0;
    }
    let first = read_i32(record + 4);
    let second = read_i32(record + 8);
    if read_u32(record) & 1 == 0 {
        write_f32(out, w91_fixed_to_f32(first));
        write_f32(out + 4, w91_fixed_to_f32(first));
        write_f32(out + 8, w91_fixed_to_f32(second));
    } else {
        if first < second {
            write_f32(out, w91_fixed_to_f32(first));
            write_f32(out + 4, w91_fixed_to_f32(second));
        } else {
            write_f32(out, w91_fixed_to_f32(second));
            write_f32(out + 4, w91_fixed_to_f32(first));
        }
        write_f32(out + 8, w91_fixed_to_f32(read_i32(record + 12)));
    }
    1
}

