/// Ends the spin move and reports the result through the `+0x3F4` slot.
///
/// # Original
/// - Ghidra: `FUN_8009c350` at `0x8009C350` (252 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8009c350_FUN_8009c350.c`
/// - observed: `FUN_8008c380(param_1 + 0x148);`, the `+0x60` vtable `+0x6C`
///   query that yields the player slot byte, the `uVar7 < 4` guard around
///   `FUN_800e20a0(...,6,uVar7)` and `FUN_800cea20(...,uVar7)`, the `+0x7B0`
///   conditional `FUN_80162d00`/`FUN_80162510` pair, the `+0x120` bit-3 clear,
///   and `FUN_800a4c40(uVar6, fVar3 <= fVar1 - fVar2, 2)`.
///
/// # Arguments
/// - `this`: spinning actor.
/// - `other`: object whose `+0x60` vtable `+0x6C` slot returns the player-slot
///   byte.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One sub-object refresh, up to two notice calls, one player-stat update, the
/// `+0x120` flag clear and one `0x800A4C40` report. The two `r2` floats are
/// read from `0x8042CC88`/`0x8042CC8C`.
///
/// # Safety
/// `this + 0x148`, `this + 0x7B0` and `other + 0x60` must be readable; the
/// vtable slots `+0x6C` and `+0x3F4` must be callable.
///
/// # Confidence
/// medium - every call and store is literal, but the two `r2` floats and the
/// meaning of the `+0x7B0` object are inferred.
pub unsafe fn fn_8009c350(this: usize, other: usize) {
    platform::call1(0x8008_C380, (this + 0x148) as u32);
    let vtable = read_u32(other + 0x60) as usize;
    let kind_ptr = platform::call1(read_u32(vtable + 0x6C) as usize, other as u32) as usize;
    let slot = read_u8(kind_ptr) as u32;
    if slot < 4 {
        call2_f64_ptr4(
            0x800E_20A0,
            read_f32(W92_F_SAMPLE_X) as f64,
            read_f32(W69_F_SAMPLE_Y) as f64,
            read_u32(W69_G_NOTICE_OWNER),
            this as u32,
            6,
            slot,
        );
        platform::call2(0x800C_EA20, read_u32(W48_G_PLAYER_STATS), slot);
    }
    let active = if read_u32(this + 0x7B0) == 0 {
        0
    } else {
        call0_ret(0x8016_2D00)
    };
    if active != 0 {
        // observed: `r3` still holds the `0x80162D00` result.
        platform::call1(0x8016_2510, active);
    }
    let x = read_f32(this + 0xAC);
    let offset = read_f32(this + 0x788);
    let threshold = read_f32(W92_F_FALL_STEP);
    write_u32(this + 0x120, read_u32(this + 0x120) & 0xFFFF_FFF7);
    let vtable = read_u32(this + 0x60) as usize;
    let target = platform::call1(read_u32(vtable + 0x3F4) as usize, this as u32);
    platform::call3(0x800A_4C40, target, (threshold <= x - offset) as u32, 2);
}

