const W93_S_MASK_ALLOC: usize = 0x8031_7818;

/// `0x802F1080`: the fourteen-word-per-character `"Mario"`-family name table
/// indexed by `+0x151` in [`fn_800ca060`].
const W93_CHARACTER_ROWS: usize = 0x802F_1080;

/// `0x802F1150`: the four per-player default indices copied by
/// [`fn_800cded0`].
const W93_PLAYER_DEFAULTS: usize = 0x802F_1150;

