/// [`fn_800c9e80`] fills and then draws.
const W93_TEXT_BUFFER: usize = 0x8035_9538;

// ---------------------------------------------------------------------------
// 0x800C10F0
// ---------------------------------------------------------------------------

/// Initialises an arm of the lift object and publishes its start point.
///
/// The interpolation block at `+0x00..+0x37` is reset through
/// [`fn_800c1810`], then `+0x38`/`+0x3C` become `0.0f`, the start point is
/// copied into `+0x40..+0x4C`, the speed goes to `+0x60`, and two grid-snapped
/// coordinates are derived from the `-0x6848` step into `+0x50`/`+0x54`.
/// The mode bytes at `+0x66`/`+0x67`/`+0x69` are written and the object
/// transitions to state `0x80358E10`.
///
/// # Original
/// - Ghidra: `FUN_800c10f0` at `0x800C10F0` (280 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c10f0_FUN_800c10f0.c`
/// - observed: `*(undefined1 *)(param_2 + 0x69) = param_4;`, the
///   `FUN_800c1810();` call, the `+0x38`/`+0x3C` word stores, the four
///   `+0x40..+0x4C` float copies, `*(float *)(param_2 + 0x60) = (float)param_1;`
///   and the two `fVar3 * (float)(CONCAT44(0x43300000,...) - dVar5)` stores.
///
/// # Arguments
/// - `speed`: value stored at `+0x60` (arrives in `f1`).
/// - `this`: lift arm object.
/// - `point`: address of the two-float start point.
/// - `mode`: byte stored at `+0x69`.
/// - `variant`: byte stored at `+0x66`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x00..+0x69` of `this` and calls the `+0x6C` transition slot.
///
/// # Safety
/// `this` must be writable for `0x6A` bytes and `point` readable for eight.
///
/// # Confidence
/// medium - every store is literal; the single argument of `0x800C1810` is not
/// printed by Ghidra and is inferred to be `this` because the call empties the
/// block immediately below the fields this body fills.
pub unsafe fn fn_800c10f0(speed: f64, this: usize, point: usize, mode: u8, variant: u8) {
    write_u8(this + 0x69, mode);
    fn_800c1810(this);
    let start_x = read_f32(point);
    let start_y = read_f32(point + 4);
    let step = read_f32(W93_F_6848);
    let zero = read_u32(W71_F_6844);
    write_u32(this + 0x38, zero);
    write_u32(this + 0x3c, zero);
    write_f32(this + 0x40, start_x);
    write_f32(this + 0x44, start_y);
    write_f32(this + 0x48, start_x);
    write_f32(this + 0x4c, start_y);
    write_f32(this + 0x60, speed as f32);
    write_u16(this + 100, 0);
    write_u8(this + 0x66, variant);
    write_u8(this + 0x68, 0);
    // observed: `(int)(fVar1 / fVar3)` then `fVar3 * (float)(double)`, i.e. a
    // truncating snap to the `-0x6848` grid; the `r2-0x6840` `2^52` bias is the
    // usual `0x43300000` signed-int conversion constant.
    write_f32(this + 0x50, step * ((start_x / step) as i32 as f32));
    write_f32(this + 0x54, step * ((start_y / step) as i32 as f32));
    w38_transition(this, 0x8035_8E10);
    write_u8(this + 0x67, 0);
}

// ---------------------------------------------------------------------------
// 0x800CA060
// ---------------------------------------------------------------------------

/// Constructs the `0x874`-byte character model record.
///
/// Installs the `0x803175E0` vtable, builds the `0x18`-byte entry array at
/// `+0x828` with `0x802DC9A0`, resets the `+0x840`/`+0x844`/`+0x848` block,
/// binds the two `0x803295xx` pivot tables, clears the `+0x868..+0x874` tail
/// and points `+0x778` at the `"Mario"` name row selected by the byte at
/// `+0x151`.
///
/// # Original
/// - Ghidra: `FUN_800ca060` at `0x800CA060` (192 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800ca060_FUN_800ca060.c`
/// - observed: `*param_1 = &DAT_803175e0;`, `param_1[0x209] = 0;`,
///   `FUN_802dc9a0(param_1 + 0x20a,FUN_8016a2f0,FUN_8016a340,0xc,2);`,
///   `FUN_8016a5e0(param_1 + 0x213);`, the `&PTR_s_Mario_802f1080 +
///   (uint)*(byte *)((int)param_1 + 0x151) * 0xe` row and `param_1[0x1df] = 0x10`.
///
/// # Arguments
/// - `this`: record to build.
///
/// # Returns
/// `this`.
///
/// # Side effects
/// Allocates the `0xc`-stride array and writes the record header.
///
/// # Safety
/// `this` must be writable for `0x874` bytes.
///
/// # Confidence
/// high - the vtable, the array-builder arguments and every word store are
/// literal; only the two pivot tables' roles are unknown.
pub unsafe fn fn_800ca060(this: usize) -> usize {
    platform::call0(0x800D_2DD0);
    write_u32(this, 0x8031_75E0);
    write_u32(this + 0x824, 0);
    platform::call5(
        0x802D_C9A0,
        (this + 0x828) as u32,
        0x8016_A2F0,
        0x8016_A340,
        0xc,
        2,
    );
    write_u32(this + 0x844, 0);
    write_u32(this + 0x840, 0x8032_95D8);
    write_u32(this + 0x848, 0);
    platform::call1(0x8016_A5E0, (this + 0x84C) as u32);
    write_u32(this + 0x840, 0x8032_9548);
    write_u32(this + 0x868, 0);
    write_u32(this + 0x86c, 0);
    write_u32(this + 0x870, 0);
    // observed: `&PTR_s_Mario_802f1080 + byte * 0xe` in Ghidra's `int *`
    // arithmetic, i.e. `0x38` bytes per row.
    let row = W93_CHARACTER_ROWS + read_u8(this + 0x151) as usize * 0x38;
    write_u32(this + 0x778, row as u32);
    write_u32(this + 0x77c, 0x10);
    this
}

// ---------------------------------------------------------------------------
// 0x800CA120
// ---------------------------------------------------------------------------

/// Releases a character model record and optionally frees it.
///
/// Runs the two teardown calls on `+0x840` and `+0x828`, forwards to
/// `0x800D30E0(this, 0)` and, when `size > 0`, frees `this` with `0x802B9280`.
///
/// # Original
/// - Ghidra: `FUN_800ca120` at `0x800CA120` (128 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800ca120_FUN_800ca120.c`
/// - observed: `if (param_1 != 0) { FUN_80166a70(param_1 + 0x840,0xffffffff);
///   FUN_802dca98(param_1 + 0x828,FUN_8016a340,0xc,2); FUN_800d30e0(param_1,0);
///   if (0 < param_2) { FUN_802b9280(param_1); } } return param_1;`
///
/// # Arguments
/// - `this`: record to release (`0` is accepted).
/// - `size`: when positive, the record is freed as well.
///
/// # Returns
/// `this`.
///
/// # Side effects
/// Releases the embedded array and the pivot block; may free `this`.
///
/// # Safety
/// `this` must be a record built by [`fn_800ca060`] (or `0`).
///
/// # Confidence
/// high - the guard and all four calls with their literal arguments are
/// printed in the export.
pub unsafe fn fn_800ca120(this: usize, size: i32) -> usize {
    if this != 0 {
        platform::call2(0x8016_6A70, (this + 0x840) as u32, 0xffff_ffff);
        platform::call4(0x802D_CA98, (this + 0x828) as u32, 0x8016_A340, 0xc, 2);
        platform::call2(0x800D_30E0, this as u32, 0);
        if size > 0 {
            platform::call1(0x802B_9280, this as u32);
        }
    }
    this
}

