/// by `0x800BACD0`.
const W94_F_UNIFORM_SCALE: usize = SDA2_BASE - 0x69B4;

/// `r2 - 0x68F0` -> `0x8042C790`: a zero/one float constant read by the
/// lift-panel helpers.
const W94_F_ZERO_ALT: usize = SDA2_BASE - 0x68F0;

/// Calls a PowerPC function with one `f64` argument and returns its `f64`.
///
/// # Safety
/// `addr` must be a PowerPC function taking its argument in `f1`.
unsafe fn w94_call_f64_ret(addr: usize, value: f64) -> f64 {
    let function: extern "C" fn(f64) -> f64 = core::mem::transmute(addr);
    function(value)
}

/// Calls a PowerPC function with one `f64` in `f1` and one word in `r4`.
///
/// # Safety
/// `addr` must use this mixed floating/integer ABI.
unsafe fn w94_call_f64_u32(addr: usize, value: f64, arg: u32) {
    let function: extern "C" fn(f64, u32) = core::mem::transmute(addr);
    function(value, arg);
}

/// Calls a PowerPC function with three `f64` values in `f1..f3` and one word in
/// `r3`.
///
/// # Safety
/// `addr` must use this mixed floating/integer ABI.
unsafe fn w94_call_f64x3_u32(addr: usize, a: f64, b: f64, c: f64, arg: u32) {
    let function: extern "C" fn(f64, f64, f64, u32) = core::mem::transmute(addr);
    function(a, b, c, arg);
}

/// Applies the repeat/hold rule of one input bit.
///
/// This is the body the timer loop of [`fn_800b5c60`] repeats for bits `0..3`:
/// a newly pressed bit is latched immediately and reloads the hold counter from
/// `+0x28`, a bit that is merely held is released once the counter at `+0x24`
/// runs out, and a bit that is not held is ignored.
///
/// # Arguments
/// - `this`: input record.
/// - `bit`: bit index in `0..0x20`.
///
/// # Side effects
/// May write `+0x20` and `+0x24`.
///
/// # Safety
/// `this` must be a live input record.
unsafe fn w94_input_bit(this: usize, bit: u32) {
    let mask = 1u32 << bit;
    if (read_u32(this + 0x1c) & mask) != 0 {
        write_u32(this + 0x20, read_u32(this + 0x20) | mask);
        write_u32(this + 0x24, read_u32(this + 0x28));
    } else if (read_u32(this + 0x14) & mask) != 0 {
        if read_i32(this + 0x24) == 0 {
            write_u32(this + 0x20, read_u32(this + 0x20) | mask);
            write_u32(this + 0x24, read_u32(this + 0x2c));
        } else {
            write_u32(this + 0x24, read_i32(this + 0x24).wrapping_sub(1) as u32);
        }
    }
}

// ---------------------------------------------------------------------------
// 0x800B5C60
// ---------------------------------------------------------------------------

/// Rebuilds the whole per-frame sprite state of one actor from its table row.
///
/// This is the anchor of the `0x800B5C60..0x800B6930` cluster: it snapshots the
/// previous frame's fields into their "last" counterparts, refills the sprite
/// vectors from either the per-actor state table (`0x803741D0`) or the live
/// actor row (`0x80377C88`), translates both raw masks through
/// [`fn_800b6080`], derives the newly-pressed mask, runs the four repeat
/// counters, then calls [`fn_800b61a0`] (angle/height) and [`fn_800b6250`]
/// (orientation step) and finally honours a deferred mask at `+0x30` and a
/// queued sprite override at `+0x8D`.
///
/// # Original
/// - Ghidra: `FUN_800b5c60` at `0x800B5C60` (1056 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b5c60_FUN_800b5c60.c`
/// - observed: the twelve `dst = src` copy pairs (`+0x10<-+0x0C`,
///   `+0x18<-+0x14`, `+0x40<-+0x34`, `+0x44<-+0x38`, `+0x48<-+0x3C`,
///   `+0x54<-+0x4C`, `+0x58<-+0x50`, `+0x64<-+0x5C`, `+0x68<-+0x60`,
///   `+0x7C<-+0x74`, `+0x80<-+0x78`, `+0x88<-+0x84`), the
///   `(&DAT_803741d0)[param_1[1]]` split, the `& 0x7fffffff`,
///   `FUN_800b6080(param_1, ...) & (x ^ y)`, the `1 << i` / `1 << i + 1` loop
///   with `iVar6 = 2`, the `FUN_800b61a0(param_1)` / `FUN_800b6250(param_1)`
///   calls and the `param_1[0x8d]` tail.
///
/// # Arguments
/// - `this`: input record of one actor (`+0x04` is the actor id).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Rewrites roughly forty words of `this`, calls `0x802E8620` (the magnitude
/// helper), [`fn_800b6080`], [`fn_800b61a0`] and [`fn_800b6250`].
///
/// # Safety
/// `this` must be a live input record; the id at `+0x04` must index both the
/// state table and the actor row table.
///
/// # Confidence
/// medium - every copy, mask and branch is literal; the meaning of the
/// `+0x34/+0x38/+0x3C` triple and of the `0x80377CB0` table is inferred from
/// how [`fn_800b6930`] and [`fn_800b61a0`] use the same offsets.
pub unsafe fn fn_800b5c60(this: usize) {
    write_u32(this + 0x10, read_u32(this + 0x0c));
    write_u32(this + 0x18, read_u32(this + 0x14));
    write_u32(this + 0x40, read_u32(this + 0x34));
    write_u32(this + 0x44, read_u32(this + 0x38));
    write_u32(this + 0x48, read_u32(this + 0x3c));
    write_u32(this + 0x54, read_u32(this + 0x4c));
    write_u32(this + 0x58, read_u32(this + 0x50));
    write_u32(this + 0x64, read_u32(this + 0x5c));
    write_u32(this + 0x68, read_u32(this + 0x60));
    write_u32(this + 0x7c, read_u32(this + 0x74));
    write_u32(this + 0x80, read_u32(this + 0x78));
    write_u32(this + 0x88, read_u32(this + 0x84));

    let id = read_i32(this + 4) as usize;
    let row = read_u32(W94_ACTOR_STATE_TABLE + id * 4) as usize;
    if row == 0 {
        // No live state object: take the sprite block from the static row.
        let descriptors = read_u32(W75_G_STATE_DESCRIPTORS) as usize;
        let descriptor = read_u32(descriptors + 4 + id * 4) as usize;
        let kind = read_i32(descriptor + 0x10);
        if kind == 0 {
            write_u32(this + 8, 0);
        } else if kind == 1 {
            write_u32(this + 8, 1);
        }
        let actor_row = read_u32(W75_ACTOR_ROW_TABLE + id * 4) as usize;
        write_u32(this + 0x0c, read_u32(actor_row + 0x18) & 0x7fff_ffff);
        write_u32(this + 0x34, read_u32(actor_row + 0x24));
        write_u32(this + 0x38, read_u32(actor_row + 0x28));
        write_u32(this + 0x3c, read_u32(actor_row + 0x2c));
        write_u32(this + 0x4c, read_u32(actor_row + 0x6c));
        write_u32(this + 0x50, read_u32(actor_row + 0x70));
        let scale = W94_T_ROW_SCALE + id * 0x18;
        write_u32(this + 0x5c, read_u32(scale));
        write_u32(this + 0x60, read_u32(scale + 4));
        write_u32(this + 0x6c, read_u32(scale + 8));
        write_u32(this + 0x70, read_u32(scale + 0x0c));
    } else {
        // Live state object: mirror its `+0x6C..+0x98` block.
        write_u32(this + 8, 0);
        if (read_u32(row + 0x64) & 0x1000_0000) != 0 {
            write_u32(this + 0x10, read_u32(row + 0x70));
        }
        write_u32(this + 0x0c, read_u32(row + 0x6c));
        write_u32(this + 0x34, read_u32(row + 0x78));
        write_u32(this + 0x38, read_u32(row + 0x7c));
        write_u32(this + 0x3c, read_u32(row + 0x80));
        write_u32(this + 0x4c, read_u32(row + 0x84));
        write_u32(this + 0x50, read_u32(row + 0x88));
        write_u32(this + 0x5c, read_u32(row + 0x8c));
        write_u32(this + 0x60, read_u32(row + 0x90));
        write_u32(this + 0x6c, read_u32(row + 0x94));
        write_u32(this + 0x70, read_u32(row + 0x98));
    }

    let actor_row = read_u32(W75_ACTOR_ROW_TABLE + id * 4) as usize;
    write_u32(this + 0x74, read_u32(actor_row + 0x4c));
    write_u32(this + 0x78, read_u32(actor_row + 0x50));

    let previous = fn_800b6080(this, read_u32(this + 0x10));
    write_u32(this + 0x18, previous);
    let current = fn_800b6080(this, read_u32(this + 0x0c));
    write_u32(this + 0x14, current);
    // newly pressed = pressed now and not pressed last frame.
    write_u32(this + 0x1c, current & (current ^ previous));

    if read_u32(this + 8).wrapping_sub(1) < 2 {
        let first = read_u32(this + 0x34);
        write_u32(this + 0x34, read_u32(this + 0x3c));
        // observed: `*(param_1 + 0x38) = *(param_1 + 0x38)` - a kept no-op.
        write_u32(this + 0x3c, first);
    }

    write_u32(this + 0x20, 0);
    let mut bit = 0u32;
    while bit < 4 {
        w94_input_bit(this, bit);
        w94_input_bit(this, bit + 1);
        bit += 2;
    }

    fn_800b61a0(this);

    let plane = read_f32(this + 0x3c);
    let depth = read_f32(this + 0x34);
    let height = read_f32(this + 0x38);
    let squared = plane * plane + depth * depth + height * height;
    // inferred: 0x802E8620 is the magnitude (length) of that vector.
    let magnitude = w94_call_f64_ret(0x802E_8620, squared as f64) as f32;
    write_f32(this + 0x84, magnitude);
    if magnitude < read_f32(W94_F_MIN_MAGNITUDE) {
        write_f32(this + 0x84, read_f32(W94_F_MAGNITUDE_FLOOR));
    }

    fn_800b6250(this);

    let forced = read_u32(this + 0x30);
    if forced != 0 {
        write_u32(this + 0x30, 0);
        write_u32(this + 0x1c, read_u32(this + 0x1c) | forced);
    }
    if read_u8(this + 0x8d) != 0 {
        write_u8(this + 0x8c, read_u8(this + 0x8d));
        write_u8(this + 0x8d, 0);
    }
}

// ---------------------------------------------------------------------------
// 0x800B61A0
// ---------------------------------------------------------------------------

/// Refreshes the sprite rotation at `+0x8E` from the actor row or the angle.
///
/// # Original
/// - Ghidra: `FUN_800b61a0` at `0x800B61A0` (164 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b61a0_FUN_800b61a0.c`
/// - observed: `if ((&DAT_803741d0)[*(int *)(param_1 + 4)] == 0)`, the
///   `*(int *)(param_1 + 8) == 0` split, the `(short)(int)(f * +0x50)` store,
///   `FUN_8015f200(param_1 + 0x8e, ..., 10, 0x1000, 0)` and the `+0x9c` copy.
///
/// # Arguments
/// - `this`: input record.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the `i16` at `+0x8E`; the second arm also runs the `0x8015F200`
/// tween on that field.
///
/// # Safety
/// `this+0x04` must index the state table; `this+0x8E` must be writable.
///
/// # Confidence
/// high - the guard, both arms and the table copy are literal; only the unit of
/// the `0x6AC0` scale is inferred.
pub unsafe fn fn_800b61a0(this: usize) {
    let id = read_i32(this + 4) as usize;
    let state = read_u32(W94_ACTOR_STATE_TABLE + id * 4) as usize;
    if state == 0 {
        let scale = read_f32(W94_F_ANGLE_SCALE);
        if read_i32(this + 8) == 0 {
            let angle = scale * read_f32(this + 0x50);
            write_u16(this + 0x8e, angle as i32 as u16);
        } else {
            let angle = scale * -read_f32(this + 0x3c);
            platform::call5(
                0x8015_F200,
                (this + 0x8e) as u32,
                angle as i32 as u32,
                10,
                0x1000,
                0,
            );
        }
    } else {
        write_u16(this + 0x8e, read_u16(state + 0x9c));
    }
}

// ---------------------------------------------------------------------------
// 0x800B6250
// ---------------------------------------------------------------------------

/// Advances the "teleport" orientation counter of the input record.
///
/// While the record has no live state object the function compares the two
/// sprite halves of the record: when the horizontal gap reaches the `0x6ABC`
/// threshold it bumps the step counter at `+0x90`, clears `+0x8C` until the
/// counter passes `4`, and - once the vertical gap is smaller than the
/// horizontal one - enters the `5`-frame wind-down that sets the `+0x92`
/// counter and the `+0x8C` flag. Below the threshold it instead counts
/// "settled" frames at `+0x91` and resets after three. With a live state object
/// the flag at `+0x8C` is simply bit `29` of the state's `+0x64` word.
///
/// # Original
/// - Ghidra: `FUN_800b6250` at `0x800B6250` (328 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b6250_FUN_800b6250.c`
/// - observed: the `ABS(+0x38 - +0x44)` / `ABS(+0x3C - +0x48)` pair, the
///   `+0x90/+0x91/+0x92` counters with the literal `4`, `5` and `'\\x02'`
///   bounds, and the `>> 0x1d & 1` extraction from the state arm.
///
/// # Arguments
/// - `this`: input record.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x8C..+0x92`.
///
/// # Safety
/// `this` must be a live input record and `+0x04` must index the state table.
///
/// # Confidence
/// medium - the counters and bounds are literal; the "teleport/settling"
/// reading of the three bytes is inferred from the `5`-frame countdown.
pub unsafe fn fn_800b6250(this: usize) {
    let id = read_i32(this + 4) as usize;
    let state = read_u32(W94_ACTOR_STATE_TABLE + id * 4) as usize;
    if state == 0 {
        if read_u8(this + 0x92) == 0 {
            let dx = (read_f32(this + 0x38) - read_f32(this + 0x44)).abs();
            let dz = (read_f32(this + 0x3c) - read_f32(this + 0x48)).abs();
            if read_f32(W94_F_MOVE_EPSILON) <= dx {
                let step = read_u8(this + 0x90).wrapping_add(1);
                write_u8(this + 0x90, step);
                if step < 4 {
                    write_u8(this + 0x8c, 0);
                } else if dz <= dx
                    || dz <= (read_f32(this + 0x34) - read_f32(this + 0x40)).abs()
                {
                    write_u8(this + 0x92, 5);
                    write_u8(this + 0x90, 0);
                    write_u8(this + 0x8c, 1);
                } else {
                    write_u8(this + 0x8c, 0);
                }
            } else {
                if read_u8(this + 0x90) != 0 {
                    let settled = read_u8(this + 0x91).wrapping_add(1);
                    write_u8(this + 0x91, settled);
                    if settled > 2 {
                        write_u8(this + 0x91, 0);
                        write_u8(this + 0x90, 0);
                    }
                }
                write_u8(this + 0x8c, 0);
            }
        } else {
            write_u8(this + 0x92, read_u8(this + 0x92).wrapping_sub(1));
            write_u8(this + 0x8c, 0);
        }
    } else {
        write_u8(this + 0x8c, ((read_u32(state + 0x64) >> 0x1d) & 1) as u8);
    }
}

// ---------------------------------------------------------------------------
// 0x800B6930
// ---------------------------------------------------------------------------

/// Resets the sprite orientation and refreshes the three ground-speed words.
///
/// # Original
/// - Ghidra: `FUN_800b6930` at `0x800B6930` (184 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b6930_FUN_800b6930.c`
/// - observed: `sVar2 = FUN_801611c0();`, the `sVar2 + -0x8000` store to
///   `+0x8e`, the two `undefined2` clears at `+0x8c`/`+0x90`, and the three
///   `fVar1 * (a + b)` stores at `+0x80..+0x88`.
///
/// # Arguments
/// - `this`: input record; `+0xAC..+0xC0` are the two speed triples.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x8C`, `+0x8E`, `+0x90` and `+0x80..+0x88`; calls `0x801611C0`.
///
/// # Safety
/// `this` must be a live input record.
///
/// # Confidence
/// high - the call, the offset `-0x8000` and the three sums are literal.
pub unsafe fn fn_800b6930(this: usize) {
    let heading = call0_ret(0x8016_11C0) as u16;
    let scale = read_f32(W94_F_SPEED_SCALE);
    write_u16(this + 0x8e, heading.wrapping_sub(0x8000));
    write_u16(this + 0x8c, 0);
    write_u16(this + 0x90, 0);
    write_f32(
        this + 0x80,
        scale * (read_f32(this + 0xac) + read_f32(this + 0xb8)),
    );
    write_f32(
        this + 0x84,
        scale * (read_f32(this + 0xb0) + read_f32(this + 0xbc)),
    );
    write_f32(
        this + 0x88,
        scale * (read_f32(this + 0xb4) + read_f32(this + 0xc0)),
    );
}

// ---------------------------------------------------------------------------
// 0x800B55F0
// ---------------------------------------------------------------------------

/// Tests whether a point sprite lies outside the visible x/z window.
///
/// The point is `+0x00/+0x04` of `point`, the sprite is `x, y, width, height` in
/// `rect`. The point is shifted by the scene's x wrap
/// ([`bg_scene_wrap_x`]) and by the scene's z origin `+0x3C`, then compared
/// against the scene limits at `+0x40`/`+0x44` with one texel of margin.
///
/// # Original
/// - Ghidra: `FUN_800b55f0` at `0x800B55F0` (232 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b55f0_FUN_800b55f0.c`
/// - observed: `dVar9 = (double)FUN_80082240(*(undefined4 *)(unaff_r13 +
///   -0x5880));`, `fVar1 = (float)((double)((fVar1 + fVar2) - fVar3) - dVar9);`,
///   the `+0x3c`/`+0x40`/`+0x44` reads and the two `return 1` arms.
///
/// # Arguments
/// - `point`: two `f32` values (x, y).
/// - `rect`: four `f32` values (x, y, width, height).
///
/// # Returns
/// `1` when the sprite is off-screen, `0` when it is visible.
///
/// # Safety
/// Both pointers must be readable for the sizes above and the BG scene
/// ([`G_BG_SCENE`]) must be live.
///
/// # Confidence
/// medium - the arithmetic and both reject arms are literal; the export drops
/// the float argument of `0x80082240`, so the sum is passed there by inference.
pub unsafe fn fn_800b55f0(point: usize, rect: usize) -> u32 {
    let scene = read_u32(G_BG_SCENE) as usize;
    let sum_x = (read_f32(point) + read_f32(rect)) - read_f32(rect + 8);
    let x = sum_x - bg_scene_wrap_x(sum_x, scene);
    let z = read_f32(rect + 0xc) + read_f32(point + 4) + read_f32(rect + 4)
        - read_f32(scene + 0x3c);
    if x + read_f32(W94_F_SPRITE_MARGIN) * read_f32(rect + 8) < read_f32(W94_F_SCREEN_X)
        || read_f32(scene + 0x40) < x
    {
        return 1;
    }
    if read_f32(W94_F_SCREEN_X) < z - read_f32(W94_F_SPRITE_MARGIN) * read_f32(rect + 0xc)
        || z < -read_f32(scene + 0x44)
    {
        return 1;
    }
    0
}

// ---------------------------------------------------------------------------
// 0x800B56E0
// ---------------------------------------------------------------------------

/// Tests a scrolling point sprite against a moving background rectangle.
///
/// Same idea as [`fn_800b55f0`] but the window comes from `window` and is
/// advanced by the per-frame scroll step: `0x6AE8 / camera[+0x90028]` scaled by
/// the two `r13-0x5594`/`r13-0x5590` offsets, blended with the `0x6B08` factor
/// against the scene bounds.
///
/// # Original
/// - Ghidra: `FUN_800b56e0` at `0x800B56E0` (348 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b56e0_FUN_800b56e0.c`
/// - observed: `fVar6 = *(float *)(unaff_r2 + -0x6ae8) / *(float *)(*(int *)
///   (unaff_r13 + -0x58b0) + 0x90028);`, the `fVar5 * fVar7` / `fVar5 * fVar6`
///   blends, and the three `return 1` arms over `-param_3[2] <= ...`.
///
/// # Arguments
/// - `point`: two `f32` values (x, y).
/// - `rect`: four `f32` values (x, y, width, height).
/// - `window`: four `f32` values, the current background window.
///
/// # Returns
/// `1` when the sprite is outside the window, `0` when it is inside.
///
/// # Safety
/// All three pointers must be readable; the BG scene and camera owner must be
/// live.
///
/// # Confidence
/// medium - every product and comparison is literal, but the roles of the two
/// `r13-0x5590`/`r13-0x5594` offsets and of `camera+0x90028` are inferred.
pub unsafe fn fn_800b56e0(point: usize, rect: usize, window: usize) -> u32 {
    let scene = read_u32(G_BG_SCENE) as usize;
    let sum_x = (read_f32(point) + read_f32(rect)) - read_f32(rect + 8);
    let z = read_f32(point + 4) + read_f32(rect + 4) + read_f32(rect + 0xc);

    let camera = read_u32(G_CAMERA_OWNER) as usize;
    let step = read_f32(W94_F_6AE8) / read_f32(camera + 0x90028);
    let blend = read_f32(W94_F_6B08);
    let scroll_x = step * read_f32(W94_F_SCROLL_X);
    let scroll_z = step * read_f32(W94_F_SCROLL_Z);

    let origin_x = read_f32(scene + 0x40);
    let origin_z = read_f32(scene + 0x3c);
    let limit_z = read_f32(scene + 0x44);
    // observed: `dVar10` (the wrap result) is used exactly once, in this sum.
    let wrap = bg_scene_wrap_x(sum_x, scene);
    let x = sum_x - ((wrap + blend * origin_x) - blend * scroll_x);
    let z = z - ((origin_z - blend * limit_z) + blend * scroll_z);

    if -read_f32(window + 8) > x + read_f32(W94_F_SPRITE_MARGIN) * read_f32(rect + 8) {
        return 1;
    }
    if x > scroll_x + read_f32(window + 0xc) {
        return 1;
    }
    if read_f32(window) < z - read_f32(W94_F_SPRITE_MARGIN) * read_f32(rect + 0xc)
        || z < -(scroll_z + read_f32(window + 4))
    {
        return 1;
    }
    0
}

// ---------------------------------------------------------------------------
// 0x800B37E0
// ---------------------------------------------------------------------------

/// Rescales a two-word point to the current screen aspect ratio.
///
/// `0x801DD1D0` selects the wide-screen divisor pair; `mode != 0` replaces the
/// screen-width numerator with the fixed `0x6AF0` constant. The two divisors are
/// then applied to the point in place.
///
/// # Original
/// - Ghidra: `FUN_800b37e0` at `0x800B37E0` (228 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b37e0_FUN_800b37e0.c`
/// - observed: `cVar3 = thunk_FUN_801dd1d0();`, the four divisions, the
///   `CONCAT44(0x43300000, (uint)*(ushort *)(**(int **)(unaff_r13 + -0x5200) +
///   6))` conversion and the two `*param_1` stores.
///
/// # Arguments
/// - `point`: two `f32` values, scaled in place (x, y).
/// - `mode`: when non-zero, uses the fixed y numerator instead of the screen
///   width.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `point[0]` and `point[1]`.
///
/// # Safety
/// `point` must be writable for eight bytes; the display object at
/// [`W94_G_DISPLAY_INFO`] must be live.
///
/// # Confidence
/// medium - the divisions and the branch are literal; the flag returned by
/// `0x801DD1D0` and the unit of the four divisors are inferred.
pub unsafe fn fn_800b37e0(point: usize, mode: i32) {
    let wide = call0_ret(0x801D_D1D0) as u8;
    let (scale_x, scale_y) = if wide == 0 {
        let y = if mode == 0 {
            let display = read_u32(W94_G_DISPLAY_INFO) as usize;
            read_u16(display + 6) as f32 / read_f32(W94_F_ASPECT_B)
        } else {
            read_f32(W94_F_6AF0) / read_f32(W94_F_ASPECT_B)
        };
        (read_f32(W94_F_6AF8) / read_f32(W94_F_ASPECT_A), y)
    } else {
        let display = read_u32(W94_G_DISPLAY_INFO) as usize;
        let y = read_u16(display + 6) as f32 / read_f32(W94_F_ASPECT_D);
        (read_f32(W94_F_6AF8) / read_f32(W94_F_ASPECT_C), y)
    };
    write_f32(point, read_f32(point) / scale_x);
    write_f32(point + 4, read_f32(point + 4) / scale_y);
}

// ---------------------------------------------------------------------------
// 0x800BC460
// ---------------------------------------------------------------------------

/// Hands the five `0x2C`-stride slots at `+0xCC` to `0x80166EF0`.
///
/// # Original
/// - Ghidra: `FUN_800bc460` at `0x800BC460` (92 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800bc460_FUN_800bc460.c`
/// - observed: `uVar1 = param_2 + 0xcc; do { FUN_80166ef0(param_1, uVar1, 0);
///   uVar1 = uVar1 + 0x2c; } while (uVar1 < param_2 + 0x150U);`.
///
/// # Arguments
/// - `owner`: the first argument of every submit call.
/// - `record`: base of the `0x2C`-stride array; the walk starts at `+0xCC`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Three submit calls on `0x80166EF0`, the last `0x2C` block ending at
/// `+0x124`.
///
/// # Safety
/// Every visited address must be a live object.
///
/// # Confidence
/// high - the stride, the start and the bound are literal.
pub unsafe fn fn_800bc460(owner: u32, record: usize) {
    let mut slot = record + 0xcc;
    while slot < record + 0x150 {
        platform::call3(0x8016_6EF0, owner, slot as u32, 0);
        slot += 0x2c;
    }
}

// ---------------------------------------------------------------------------
// 0x800B8550
// ---------------------------------------------------------------------------

/// Starts the timer record: picks its state, arms the phase and queues a sound.
///
/// The state comes from [`fn_800b8620`]; the previous "state mirror" word at
/// `+0x20` becomes the variant selector at `+0x1C`, and the `+0x2C` "hold"
/// flag is armed unless the state machine says otherwise. The record then
/// enters phase `1`, builds the `0xAC`-offset matrix of the `+0x64` actor and
/// submits sound id `0x26A` through `0x80198C30`, and finally reloads the
/// countdown through [`fn_800b88d0`].
///
/// # Original
/// - Ghidra: `FUN_800b8550` at `0x800B8550` (208 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b8550_FUN_800b8550.c`
/// - observed: `iVar1 = FUN_800b8620();`, the `*(param_1 + 0x10/0x1c/0x18)`
///   stores, the `if (2 < iVar1 - 3U)` block with the `== 2` arm, the
///   `FUN_8006a4b0(auStack_18, *(int *)(param_1 + 100) + 0xac)` call,
///   `FUN_80198c30(uVar3, 0x26a, auStack_18, 0)` and `FUN_800b88d0(param_1)`.
///
/// # Arguments
/// - `this`: timer record.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x10`..`+0x2C`, runs the matrix builder and the sound submit, and
/// lets [`fn_800b88d0`] rewrite `+0x04`/`+0x08`.
///
/// # Safety
/// `this+0x64` must be a live actor and the sound owner must be initialised.
///
/// # Confidence
/// medium - the branch table and every store are literal; `FUN_800b8620` is
/// printed without arguments, so the record is restored as its receiver.
pub unsafe fn fn_800b8550(this: usize) {
    let state = fn_800b8620(this);
    let mirror = read_u32(this + 0x20);
    write_u32(this + 0x10, state as u32);
    write_u32(this + 0x1c, mirror);
    write_u32(this + 0x18, 0);

    let mut arm_hold = true;
    // observed: `2 < iVar1 - 3U` is true for every state outside 3..=5.
    if state.wrapping_sub(3) as u32 > 2 {
        if state == 2 {
            if mirror == 1 {
                write_u32(this + 0x10, 1);
            } else {
                write_u32(this + 0x2c, 1);
            }
            arm_hold = false;
        } else if state != 8 && mirror != 5 {
            arm_hold = false;
        }
    }
    if arm_hold {
        write_u32(this + 0x2c, 1);
    }

    write_u32(this + 0x14, 1);
    let owner = read_u32(W94_G_SOUND_OWNER);
    let actor = read_u32(this + 0x64) as usize;
    let mut matrix = [0u32; 4];
    platform::call2(
        0x8006_A4B0,
        matrix.as_mut_ptr() as u32,
        (actor + 0xac) as u32,
    );
    platform::call4(0x8019_8C30, owner, 0x26a, matrix.as_mut_ptr() as u32, 0);
    fn_800b88d0(this);
}

// ---------------------------------------------------------------------------
// 0x800B8620
// ---------------------------------------------------------------------------

/// Chooses the timer record's state from its mode and the actor's surroundings.
///
/// Modes `1`, `3`, `7` and `8` are returned unchanged. Otherwise the record's
/// actor is probed with `0x80075270`: a hit copies the alternate state at
/// `+0x28`, a miss that also fails the `0x80070CB0` ground test falls back to
/// `2` or `3` depending on [`fn_800b8cf0`].
///
/// # Original
/// - Ghidra: `FUN_800b8620` at `0x800B8620` (196 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b8620_FUN_800b8620.c`
/// - observed: `FUN_8006ced0(&local_28, iVar4);`, the
///   `iVar3 != 1 && iVar3 != 7 && iVar3 != 3 && iVar3 != 8` guard,
///   `FUN_80075270((double)local_28,(double)local_24,*(undefined1 *)(iVar4 +
///   0x38f),0)`, `FUN_80070cb0(iVar4 + 0x1ec)` and
///   `iVar3 = 2 - ((int)(-uVar2 | uVar2) >> 0x1f);`.
///
/// # Arguments
/// - `this`: timer record; `+0x24` is the mode and `+0x64` the actor pointer.
///
/// # Returns
/// The state word `1..=8`.
///
/// # Side effects
/// Runs the position reader, one ground probe and the ground test; no writes.
///
/// # Safety
/// `this+0x64` must be a live actor with a readable `+0x38F` flag.
///
/// # Confidence
/// medium - the guard and both result arms are literal; `2 - (sign of -v|v)`
/// is reproduced as `v != 0 -> 3, else 2`, and `0x800B8CF0` is a GQR helper
/// that stays an address call.
pub unsafe fn fn_800b8620(this: usize) -> i32 {
    let actor = read_u32(this + 0x64) as usize;
    let mut position = [0u32; 2];
    platform::call2(0x8006_CED0, position.as_mut_ptr() as u32, actor as u32);

    let mode = read_i32(this + 0x24);
    let mut state = mode;
    if mode != 1 && mode != 7 && mode != 3 && mode != 8 {
        let hit = call_f32x2_u32x2(
            0x8007_5270,
            f32::from_bits(position[0]),
            f32::from_bits(position[1]),
            read_u8(actor + 0x38f) as u32,
            0,
        );
        if hit == 0 {
            let ground = platform::call1(0x8007_0CB0, (actor + 0x1ec) as u32);
            if ground == 0 {
                // unknown: 0x800B8CF0 is the untranslated GQR probe helper.
                let probe = platform::call1(0x800B_8CF0, this as u32);
                state = if probe != 0 { 3 } else { 2 };
            }
        } else {
            state = read_i32(this + 0x28);
        }
    }
    state
}

// ---------------------------------------------------------------------------
// 0x800B8850
// ---------------------------------------------------------------------------

/// Releases the twelve `+0x34`-offset handles of a timer record.
///
/// # Original
/// - Ghidra: `FUN_800b8850` at `0x800B8850` (120 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b8850_FUN_800b8850.c`
/// - observed: `param_1[3] = 0; *param_1 = 0;`, the twelve-iteration loop over
///   `param_1[0xd]`, `FUN_80162d00();` / `FUN_80162510();` and the
///   `param_1[0xd] = 0;` clear.
///
/// # Arguments
/// - `record`: base of the handle array; `+0x0C` and `+0x00` are the counts.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Calls the two handle accessors per live handle and clears every slot.
///
/// # Safety
/// `record+0x34..+0x63` must be writable.
///
/// # Confidence
/// high - the twelve-iteration bound, both calls and the clears are literal.
pub unsafe fn fn_800b8850(record: usize) {
    write_u32(record + 0x0c, 0);
    write_u32(record, 0);
    let mut index = 0usize;
    while index < 0xc {
        let slot = record + index * 4;
        if read_u32(slot + 0x34) != 0 {
            let handle = call0_ret(0x8016_2D00);
            if handle != 0 {
                // observed: `r3` still holds the `0x80162D00` result.
                platform::call1(0x8016_2510, handle);
            }
            write_u32(slot + 0x34, 0);
        }
        index += 1;
    }
}

// ---------------------------------------------------------------------------
// 0x800B8EE0
// ---------------------------------------------------------------------------

/// Steps the two-phase timer record and reports the current phase.
///
/// Phase `1` counts the `+0x04` word down (unless `+0x2C` says "hold"), runs
/// the `0x800B89B0` limit test and, once the countdown reaches zero, calls
/// [`fn_800b8c30`] and switches to phase `2`. Phase `2` switches to phase `3`
/// on the next call. Any other phase reports `3` without touching the record.
///
/// # Original
/// - Ghidra: `FUN_800b8ee0` at `0x800B8EE0` (184 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b8ee0_FUN_800b8ee0.c`
/// - observed: `uVar2 = 3;`, the `+0x14 == 1` / `+0x14 == 2` split, the
///   `*(param_1 + 4) + -1` decrement guarded by `+0x2c == 0`, the
///   `FUN_800b8c30(param_1)` / `FUN_800b89b0(param_1)` /
///   `FUN_800b8ab0(param_1)` calls and the `return uVar2` values `0`, `1`, `3`.
///
/// # Arguments
/// - `this`: timer record.
///
/// # Returns
/// `1` when the countdown just finished, `0` while phase `1` runs, `3` for
/// phase `2`/finished and `3` for any unknown phase.
///
/// # Side effects
/// Writes `+0x04` and `+0x14`; may run the three `0x800B8xxx` handlers.
///
/// # Safety
/// `this` must be a live timer record.
///
/// # Confidence
/// high - every phase arm, the decrement guard and all return values are
/// literal.
pub unsafe fn fn_800b8ee0(this: usize) -> u32 {
    let mut result = 3u32;
    if read_i32(this + 0x14) == 1 {
        result = 0;
        if read_i32(this + 0x2c) == 0 {
            write_u32(this + 4, read_i32(this + 4).wrapping_sub(1) as u32);
        }
        if read_i32(this + 4) < 1 {
            fn_800b8c30(this);
            write_u32(this + 0x14, 2);
            result = 1;
        } else if fn_800b89b0(this) != 0 {
            fn_800b8ab0(this);
        }
    } else if read_i32(this + 0x14) == 2 {
        write_u32(this + 0x14, 3);
        result = 3;
    }
    result
}

