// 0x800B4730
// ---------------------------------------------------------------------------

/// Fills the two colour blocks once, then hands one entry of each to the
/// object's `+0x28` virtual setter.
///
/// # Original
/// - Ghidra: `FUN_800b4730` at `0x800B4730` (436 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b4730_FUN_800b4730.c`
/// - observed: the twenty literal `DAT_80358a78..DAT_80358a8b` byte stores
///   guarded by `r13-0x5732`, the twenty `DAT_80358a8c..DAT_80358a9f` stores
///   guarded by `r13-0x5731`, and the two
///   `(**(code **)(*param_1 + 0x28))(param_1, 0|2, &local_x)` calls.
///
/// # Arguments
/// - `this`: object with a `+0x28` virtual setter.
/// - `index`: entry index used with a `4`-byte stride into both blocks.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Builds both blocks on first use and calls the setter twice.
///
/// # Safety
/// `this` must hold a readable vtable whose `+0x28` slot takes
/// `(object, slot, pointer)`.
///
/// # Confidence
/// high - every byte, both guards and both virtual calls are literal.
pub unsafe fn fn_800b4730(this: usize, index: u32) {
    // unknown: the colour blocks' meaning; only the literal bytes are known.
    const BLOCK_A: [u8; 20] = [
        0xff, 0xff, 0x32, 0xff, 0xd2, 0xff, 0x00, 0xff, 0xd2, 0xf0, 0xff, 0xff, 0xff, 0xff, 0x64,
        0xff, 0xff, 0xff, 0xff, 0xff,
    ];
    const BLOCK_B: [u8; 20] = [
        0xe6, 0x00, 0x00, 0xff, 0x19, 0x7d, 0x0a, 0xff, 0x1e, 0x2d, 0xf0, 0xff, 0xff, 0xbe, 0x00,
        0xff, 0xff, 0xbe, 0xff, 0xff,
    ];

    if read_u8(W94_B_COLOUR_A_READY) == 0 {
        for (offset, value) in BLOCK_A.iter().enumerate() {
            write_u8(W94_B_COLOUR_A + offset, *value);
        }
        write_u8(W94_B_COLOUR_A_READY, 1);
    }
    if read_u8(W94_B_COLOUR_B_READY) == 0 {
        for (offset, value) in BLOCK_B.iter().enumerate() {
            write_u8(W94_B_COLOUR_B + offset, *value);
        }
        write_u8(W94_B_COLOUR_B_READY, 1);
    }

    let vtable = read_u32(this) as usize;
    let setter = read_u32(vtable + 0x28) as usize;
    let mut value = read_u32(W94_B_COLOUR_A + index as usize * 4);
    platform::call3(setter, this as u32, 0, (&mut value as *mut u32) as u32);
    value = read_u32(W94_B_COLOUR_B + index as usize * 4);
    platform::call3(setter, this as u32, 2, (&mut value as *mut u32) as u32);
}

