pub unsafe fn fn_800babb0(this: usize, animation: u32) {
    let manager = read_u32(G_ARC_MANAGER) as usize;
    let archive = platform::call3(
        0x800D_F180,
        (manager + 4) as u32,
        W94_S_WANWAN_IGGY as u32,
        W94_S_G3D_WANWAN_IGGY as u32,
    );
    write_u32(this, archive);

    let selector = ((read_u32(this + 0x64).wrapping_add(1) * 4) & 4) as usize;
    let descriptor = read_u32(W94_T_IGGY_ANIM + selector);
    let mut model = [descriptor];
    platform::call6(
        0x8016_A3A0,
        (this + 4) as u32,
        model.as_mut_ptr() as u32,
        animation,
        0x120,
        1,
        0,
    );

    let name = platform::call2(0x8023_A270, this as u32, W94_S_MAGIC_CHAIN_AB as u32);
    write_u32(this + 0x10, name);
    let mut animation_id = [descriptor];
    let mut animation_name = [name];
    platform::call6(
        0x8016_7420,
        (this + 0x14) as u32,
        animation_id.as_mut_ptr() as u32,
        animation_name.as_mut_ptr() as u32,
        animation,
        0,
        1,
    );
    let mut stored = [read_u32(this + 0x10)];
    platform::call5(
        0x8016_7800,
        (this + 0x14) as u32,
        (this + 4) as u32,
        stored.as_mut_ptr() as u32,
        0,
        0,
    );
    call_vtable_slot2(this + 4, 0x18, (this + 0x14) as u32);
    platform::call1(0x8006_4BD0, (this + 4) as u32);
}

// ---------------------------------------------------------------------------
// 0x800BACD0
// ---------------------------------------------------------------------------

/// Places the record's `+0x44..+0x60` transform into the model at `+0x04`.
///
/// Runs only while `+0x80` is zero. The position triple at `+0x44..+0x4C` and
/// the three `u16` rotation angles at `+0x5C..+0x60` are handed to
/// `0x80064AF0`, which builds a 3x4 matrix through `0x801C0BD0`; the three
/// angles are then re-applied by `0x8016EDD0`/`0x8016EEF0`/`0x8016ECB0`
/// (y, z, x, in that call order) before the matrix is bound to the model and a
/// uniform scale from `0x8042C6CC` is copied in.
///
/// # Original
/// - Ghidra: `FUN_800bacd0` at `0x800BACD0` (236 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800bacd0_FUN_800bacd0.c`
/// - observed: `if (*(int *)(param_1 + 0x80) == 0)`, the three `local_48..40`
///   float loads from `+0x44..+0x4C`, the three `local_5c..58` `u16` loads from
///   `+0x5C..+0x60`, `FUN_80064af0(&local_48,&local_5c,1)`,
///   `FUN_801c0bd0(...,auStack_38)`, the three rotation calls,
///   `FUN_8016a170(param_1 + 4,auStack_38)` and the repeated
///   `*(undefined4 *)(unaff_r2 + -0x69b4)` scale triple.
///
/// # Arguments
/// - `this`: record with the transform at `+0x44` and the model at `+0x04`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the 0x34-byte matrix on the stack and binds it to the model.
///
/// # Safety
/// `this+0x04` must be a live model and `this+0x44..+0x60` readable.
///
/// # Confidence
/// high - the guard, all six field loads, the three rotation calls and the two
/// model calls are literal; only the axis order is inferred from the call
/// order.
pub unsafe fn fn_800bacd0(this: usize) {
    if read_i32(this + 0x80) != 0 {
        return;
    }
    let mut point = [0u32; 3];
    point[0] = read_u32(this + 0x44);
    point[1] = read_u32(this + 0x48);
    point[2] = read_u32(this + 0x4c);
    let mut angles = [0u16; 3];
    angles[0] = read_u16(this + 0x5c);
    angles[1] = read_u16(this + 0x5e);
    angles[2] = read_u16(this + 0x60);

    platform::call3(
        0x8006_4AF0,
        point.as_mut_ptr() as u32,
        angles.as_mut_ptr() as u32,
        1,
    );

    let mut matrix = [0u32; 13];
    w94_call_f64x3_u32(
        0x801C_0BD0,
        f32::from_bits(point[0]) as f64,
        f32::from_bits(point[1]) as f64,
        f32::from_bits(point[2]) as f64,
        matrix.as_mut_ptr() as u32,
    );

    let mut angle = [angles[1]];
    platform::call2(0x8016_EDD0, matrix.as_mut_ptr() as u32, angle.as_mut_ptr() as u32);
    angle = [angles[2]];
    platform::call2(0x8016_EEF0, matrix.as_mut_ptr() as u32, angle.as_mut_ptr() as u32);
    angle = [angles[0]];
    platform::call2(0x8016_ECB0, matrix.as_mut_ptr() as u32, angle.as_mut_ptr() as u32);

    platform::call2(0x8016_A170, (this + 4) as u32, matrix.as_mut_ptr() as u32);
    let scale = read_u32(W94_F_UNIFORM_SCALE);
    let mut uniform = [scale, scale, scale];
    platform::call2(
        0x8016_A150,
        (this + 4) as u32,
        uniform.as_mut_ptr() as u32,
    );
}

