/// Computes the two z-window scales of a rectangle and writes them to `out`.
///
/// `out[0]` is the horizontal span divided by the BG colour A factor, clamped
/// to `1.0f` and the incoming depth; `out[1]` is the vertical span over the
/// `+0x90038`/`+0x9003C` limits, scaled by `param_2` and divided by BG colour
/// B, with the same clamp.
///
/// # Original
/// - Ghidra: `FUN_8007bd40` at `0x8007BD40` (432 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8007bd40_FUN_8007bd40.c`
/// - observed: the `1.0f` seeds at `r2-0x7368`, the
///   `r13-0x5594`/`r13-0x5590` colour divisors, the `+0x90038`/`+0x9003C`
///   limits, the `r2-0x730C`/`r2-0x7314` clamps and the two `out` stores.
///
/// # Arguments
/// - `depth`: incoming horizontal depth (float in `f1`).
/// - `scale`: vertical scale (float in `f2`).
/// - `out`: two-float result.
/// - `this`: BG scene object.
/// - `rect`: four-float rectangle (x0, x1, y0, y1).
///
/// # Side effects
/// Writes both floats of `out`.
///
/// # Safety
/// The scene owner at `G_BG_SCENE`, `this+0x90038`, `this+0x9003C` and `rect`
/// must be readable.
///
/// # Confidence
/// medium - every clamp and store is literal; the rectangle roles are inferred.
pub unsafe fn fn_8007bd40(depth: f32, scale: f32, out: usize, this: usize, rect: usize) {
    write_f32(out, read_f32(W91_F_ONE_ALT));
    write_f32(out + 4, read_f32(W91_F_ONE_ALT));
    let colour_a = read_f32(G_BG_COL_A);
    let colour_b = read_f32(G_BG_COL_B);
    let front = fn_80078a70(this);
    let back = fn_80078c10(this);
    let reference = read_f32(W96_F_REF_HEIGHT);
    let mut left = reference;
    if read_f32(rect) - reference < front {
        left = read_f32(rect) - front;
    }
    let mut right = reference;
    if back < reference + read_f32(rect + 4) {
        right = back - read_f32(rect + 4);
    }
    let horizontal = (right + (left + (read_f32(rect + 4) - read_f32(rect)))) / colour_a;
    let mut horizontal_out = read_f32(W91_F_ONE_ALT);
    if horizontal >= read_f32(W91_F_ONE_ALT) {
        horizontal_out = horizontal;
        if depth < horizontal {
            horizontal_out = depth;
        }
    }
    let mut top = read_f32(W96_F_SCENE_C);
    let mut bottom = read_f32(W96_F_SCENE_A);
    if read_f32(this + 0x90038) < top + read_f32(rect + 8) {
        top = read_f32(this + 0x90038) - read_f32(rect + 8);
    }
    if read_f32(rect + 0xc) - bottom < read_f32(this + 0x9003c) {
        bottom = read_f32(rect + 0xc) - read_f32(this + 0x9003c);
    }
    let vertical = (bottom + top + (read_f32(rect + 8) - read_f32(rect + 0xc))) * scale / colour_b;
    let mut vertical_out = read_f32(W91_F_ONE_ALT);
    if vertical >= read_f32(W91_F_ONE_ALT) {
        vertical_out = vertical;
        if depth < vertical {
            vertical_out = depth;
        }
    }
    write_f32(out, horizontal_out);
    write_f32(out + 4, vertical_out);
}

