/// medium - the single float argument is literal, and the pass-through of
/// `r4`..`r6` is inferred from the shared callee's argument count.
pub unsafe fn fn_800c2030(this: usize, point: usize, a: usize, b: usize) -> u32 {
    fn_800c1e90(this, point, a, b, read_f32(W38_F_6844))
}

