/// `r2 - 0x68B8` → `0x8042C7C8`: the floor and rest value of [`fn_800bfe90`].
const W100_F_68B8: usize = SDA2_BASE - 0x68B8;

/// `r2 - 0x68B4` → `0x8042C7CC`: base height of [`fn_800bfe90`].
const W100_F_68B4: usize = SDA2_BASE - 0x68B4;

