const W100_F_68A4: usize = SDA2_BASE - 0x68A4;

/// `r2 - 0x68A0` → `0x8042C7E0`: the rise ceiling of the state-3 branch.
const W100_F_68A0: usize = SDA2_BASE - 0x68A0;

/// Calls a PowerPC function with six integer arguments (`r3..r8`).
///
/// [`fn_800b8700`] is the only caller; the export prints
/// `FUN_80064680(0x19b,piVar1[0x19],uVar5,&local_4c,0,0)`.
///
/// # Safety
/// `addr` must be a PowerPC function taking exactly six integers.
unsafe fn call6(addr: usize, a: u32, b: u32, c: u32, d: u32, e: u32, f: u32) -> u32 {
    let func: extern "C" fn(u32, u32, u32, u32, u32, u32) -> u32 = core::mem::transmute(addr);
    func(a, b, c, d, e, f)
}

// ---------------------------------------------------------------------------
// 0x800B38D0
// ---------------------------------------------------------------------------

/// Scales the remaining count above a threshold and returns it with a sign.
///
/// `0x802DE514` supplies a `u16` sample; when it is below `count` the result is
/// zero, otherwise the difference is converted to `f32`, multiplied by `scale`
/// and truncated to an `i16`. A negative `sign` negates the result.
///
/// # Original
/// - Ghidra: `FUN_800b38d0` at `0x800B38D0` (164 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b38d0_FUN_800b38d0.c`
/// - observed: `uVar1 = FUN_802de514();`, `if ((uVar1 & 0xffff) < param_3)`,
///   the `CONCAT44(0x43300000,...) - *(double *)(r2-0x6b00)` conversion, the
///   `* param_1` product, `sVar3 = (short)(int)...` and `if (param_2 < 0)`.
///
/// # Arguments
/// - `scale`: multiplier applied to the remaining count.
/// - `sign`: a negative value negates the result.
/// - `count`: the threshold the sample must reach.
///
/// # Returns
/// The signed, scaled remainder, or `0` when the sample is too small.
///
/// # Side effects
/// One call to `0x802DE514`; no memory is written.
///
/// # Safety
/// The threshold sample must be a live `u16`; nothing else is dereferenced.
///
/// # Confidence
/// medium - the comparison, conversion and negation are literal; the GQR
/// quantisation around the pair is not reproduced because the export does not
/// show which scale register was active.
pub unsafe fn fn_800b38d0(scale: f64, sign: i32, count: u32) -> i32 {
    let sample = call0_ret(0x802D_E514);
    let low = sample & 0xffff;
    if low < count {
        return 0;
    }
    // observed: `(uVar1 & 0xffff) - param_3 & 0xffff` then the 0x43300000
    // conversion, i.e. the unsigned difference as f32.
    let remaining = low.wrapping_sub(count) & 0xffff;
    let scaled = ((remaining as f32) as f64 * scale) as i32 as i16;
    if sign < 0 {
        -(scaled as i32)
    } else {
        scaled as i32
    }
}

// ---------------------------------------------------------------------------
// 0x800B53A0
// ---------------------------------------------------------------------------

/// Raises one slot record to priority `0x200`, or `0x600` when it is loaded.
///
/// The slot table behind `r13-0x5658` is indexed by `index`; when the pointed
/// record's `+0x10` word is zero the record is only brought up to `0x200`,
/// otherwise it receives `0x600`. The call is the record's `+0x20` vtable slot.
///
/// # Original
/// - Ghidra: `FUN_800b53a0` at `0x800B53A0` (92 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b53a0_FUN_800b53a0.c`
/// - observed: `if (*(int *)(*(int *)(*(int *)(unaff_r13 + -0x5658) +
///   param_1 * 4 + 4) + 0x10) == 0)` selects the `0x200` call, else the
///   `0x600` call; both go through `*(int *)(&DAT_80377c88)[param_1] + 0x20`.
///
/// # Arguments
/// - `index`: slot index into both tables.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One virtual call on the indexed record.
///
/// # Safety
/// Both tables must hold at least `index + 1` pointers and the selected
/// record's `+0x20` slot must take `(record, priority)`.
///
/// # Confidence
/// medium - the guard and both priorities are literal; the table roles are
/// inferred from the `+0x10` loaded flag and the two constants.
pub unsafe fn fn_800b53a0(index: i32) {
    let manager = read_u32(W100_G_SLOT_TABLE) as usize;
    let slot = read_u32(manager + index as usize * 4 + 4) as usize;
    let record = read_u32(W100_SLOT_RECORDS + index as usize * 4) as usize;
    let vtable = read_u32(record) as usize;
    let priority = if read_u32(slot + 0x10) == 0 { 0x200 } else { 0x600 };
    platform::call2(read_u32(vtable + 0x20) as usize, record as u32, priority);
}

// ---------------------------------------------------------------------------
// 0x800B6460
// ---------------------------------------------------------------------------

/// Sets up the two render callbacks and registers the load result.
///
/// The body calls the two no-argument initialisers, arms the two callback
/// limits `0x100000`/`0x300000`, then asks `0x802B9240(4, a1, 4)` for a handle;
/// a non-zero handle is published through [`fn_800b6450`].
///
/// # Original
/// - Ghidra: `FUN_800b6460` at `0x800B6460` (124 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b6460_FUN_800b6460.c`
/// - observed: `FUN_80007520();`, `FUN_800c0ae0();`,
///   `FUN_80163180(param_2,0x100000);`, `FUN_80006c50(param_3,0x300000);`,
///   `iVar1 = FUN_802b9240(4,param_1,4);` and the guarded
///   `FUN_800b6450();`.
///
/// # Arguments
/// - `a1`: selector forwarded to `0x802B9240`.
/// - `a2`: handle forwarded to `0x80163180`.
/// - `a3`: handle forwarded to `0x80006C50`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Two initialisers, two callback registrations and one object publication.
///
/// # Safety
/// The callees must be live; `0x802B9240` must return either `0` or the object
/// that [`fn_800b6450`] is allowed to register.
///
/// # Confidence
/// medium - every call argument is literal; the two zero-argument callees lose
/// their names, and the registered object is `0x802B9240`'s `r3` result because
/// that register still holds it at the call.
pub unsafe fn fn_800b6460(a1: u32, a2: u32, a3: u32) {
    platform::call0(0x8000_7520);
    platform::call0(0x800C_0AE0);
    platform::call2(0x8016_3180, a2, 0x10_0000);
    platform::call2(0x8000_6C50, a3, 0x30_0000);
    let handle = platform::call3(0x802B_9240, 4, a1, 4);
    if handle != 0 {
        fn_800b6450(handle as usize);
    }
}

// ---------------------------------------------------------------------------
// 0x800B6830
// ---------------------------------------------------------------------------

/// Places one lift cell: builds its matrix and stores three position words.
///
/// A rotation matrix is built from the three floats at `position`, rotated by
/// the second of the three `u16` angles at `angles`, and two translation
/// vectors are written into the object's `+0xAC` and `+0xB8` slots. The raw
/// position and angles are then copied to `+0x80..+0x90`.
///
/// # Original
/// - Ghidra: `FUN_800b6830` at `0x800B6830` (252 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b6830_FUN_800b6830.c`
/// - observed: `FUN_801c0bd0(*param_3,param_3[1],param_3[2],auStack_58);`,
///   `local_78[0] = param_4[1]; FUN_8016edd0(auStack_58,local_78);`, the two
///   `local_60 = [r2-0x6aa0] * param_1` / `local_6c = [r2-0x6a9c] * param_1`
///   vectors, the two `FUN_801c1160(...,param_2+0xac/0xb8)` calls and the six
///   `+0x80..+0x90` stores.
///
/// # Arguments
/// - `scale`: `double` (single-precision in the original) height multiplier.
/// - `this`: lift object; `+0xAC` and `+0xB8` receive the two vectors.
/// - `position`: three readable floats.
/// - `angles`: three readable `u16` angles.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes two vectors, six position/angle fields and three stack matrices.
///
/// # Safety
/// `this`, `position` and `angles` must be readable/writable as described.
///
/// # Confidence
/// medium - every store and call is literal; the two `r2` words at `-0x6AB4`
/// are passed through as raw words because the export does not name them.
pub unsafe fn fn_800b6830(scale: f64, this: usize, position: usize, angles: usize) {
    let mut matrix = [0u32; 15];
    call3_f32_ptr(
        W100_MTX_TRANSLATE,
        read_f32(position),
        read_f32(position + 4),
        read_f32(position + 8),
        matrix.as_mut_ptr() as u32,
    );
    let mut angle = [0u16; 2];
    angle[0] = read_u16(angles + 2);
    platform::call2(
        W100_MTX_ROTATE,
        matrix.as_mut_ptr() as u32,
        angle.as_ptr() as u32,
    );
    let zero = read_u32(SDA2_BASE - 0x6AB4);
    let mut first = [
        zero,
        zero,
        ((read_f32(SDA2_BASE - 0x6AA0) as f64 * scale) as f32).to_bits(),
    ];
    platform::call3(
        W100_MTX_VEC,
        matrix.as_mut_ptr() as u32,
        first.as_mut_ptr() as u32,
        (this + 0xAC) as u32,
    );
    let mut second = [
        zero,
        zero,
        ((read_f32(SDA2_BASE - 0x6A9C) as f64 * scale) as f32).to_bits(),
    ];
    platform::call3(
        W100_MTX_VEC,
        matrix.as_ptr() as u32,
        second.as_mut_ptr() as u32,
        (this + 0xB8) as u32,
    );
    // observed: the raw position and angles are copied last.
    write_f32(this + 0x80, read_f32(position));
    write_f32(this + 0x84, read_f32(position + 4));
    write_f32(this + 0x88, read_f32(position + 8));
    write_u16(this + 0x8C, read_u16(angles));
    write_u16(this + 0x8E, read_u16(angles + 2));
    write_u16(this + 0x90, read_u16(angles + 4));
}

// ---------------------------------------------------------------------------
// 0x800B6E50
// ---------------------------------------------------------------------------

/// Refreshes the `+8` interface and re-places the lift cell.
///
/// The `+8` interface is ticked through its `+0x1C` slot, then the three
/// position floats and three `u16` angles of the `+0x224` source record are
/// handed to [`fn_800b6830`]. The middle angle is halved first.
///
/// # Original
/// - Ghidra: `FUN_800b6e50` at `0x800B6E50` (160 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b6e50_FUN_800b6e50.c`
/// - observed: `(**(code **)(*(int *)(param_2 + 8) + 0x1c))(param_2 + 8);`,
///   `iVar1 = *(int *)(param_2 + 0x224);`, the `+0xAC..+0xB4` and
///   `+0x100..+0x104` copies, `local_36 = *(short *)(iVar1 + 0x102) >> 1;`
///   and `FUN_800b6830(param_1,param_2,&local_30,&local_38);`.
///
/// # Arguments
/// - `scale`: height multiplier forwarded to [`fn_800b6830`].
/// - `this`: lift object; `+8` is the interface, `+0x224` the source record.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One virtual tick plus everything [`fn_800b6830`] writes.
///
/// # Safety
/// `this + 8` must be a live interface and `this + 0x224` a readable record.
///
/// # Confidence
/// medium - the layout and the call are literal; `scale` is printed as
/// `undefined8` because of the paired-single ABI.
pub unsafe fn fn_800b6e50(scale: f64, this: usize) {
    let vtable = read_u32(this + 8) as usize;
    platform::call1(read_u32(vtable + 0x1C) as usize, (this + 8) as u32);
    let source = read_u32(this + 0x224) as usize;
    let mut position = [
        read_u32(source + 0xAC),
        read_u32(source + 0xB0),
        read_u32(source + 0xB4),
    ];
    let mut angles = [
        read_u16(source + 0x100),
        ((read_u16(source + 0x102) as i16) >> 1) as u16,
        read_u16(source + 0x104),
    ];
    fn_800b6830(
        scale,
        this,
        position.as_mut_ptr() as usize,
        angles.as_mut_ptr() as usize,
    );
}

