        if result & 3 == 0 {
            if was_touched {
                if read_f32(this + 0xd4) < read_f32(position + 4) {
                    write_f32(position + 4, read_f32(this + 0xd4));
                }
            } else {
                let snap = ((points[1] as i32) as u32 & 0xfff0) as u16 as i16 as u32;
                let offset = (w101_bias(snap) as f32 as f64 - near as f64) as i32;
                let low_word = (offset as u16) as i16 as u32;
                write_f32(position + 4, w101_bias(low_word) as f32);
            }
        }
