        let block = platform::call3(
            W101_ALLOC,
            0x44,
            read_u32(W70_G_ACTOR_HEAP),
            4,
        );
        if block != 0 {
            tilemap = call0_ret(W101_TILEMAP_ALLOC);
        }
        call9(
            W101_TILEMAP_INIT,
            tilemap,
            param_3,
            param_4,
            param_5,
            param_6,
            param_7,
            param_8,
            read_u32(W101_DAT_80377C48),
            token & 0xffff,
        );
        let name = platform::call3(W101_UNIT_NAME, manager, stage, 1) as usize;
        let special = read_u8(name) != 0
            && (w101_name_eq(name, b"Pa1_nohara")
                || w101_name_eq(name, b"Pa1_nohara2")
                || w101_name_eq(name, b"Pa1_daishizen"));
