///   (`actor`, `flags`), and `extraout_f1` as the incoming bias.
/// - observed: the `*(r13-0x58a0)` list walk, `FUN_80080e40(puVar14,iVar6,
///   uVar12,3)`, the `FUN_80073290` call, the `puVar14[0x18..0x1d]` midpoints,
///   the `puVar14[0x33] - 5 < 3` split, every `+0xD0` mask test and the
///   `+0xD8` OR stores, `FUN_80070760`, `FUN_80081030`, `FUN_80070600`,
///   `FUN_800731e0`, `FUN_800705b0`, `FUN_80080d00` and the two indirect calls.
/// - observed: the `countLeadingZeros` chain reduces to `kind <= 2`.
/// - observed: `uVar18 & 0x8000000`/`& 0x4000`/`& 0x10000000` are bits of the
///   `r4` flags word; the GQR0 prologue writes dead locals.
///
/// # Arguments
/// - `bias`: the `f1` word added to the x midpoint and forwarded to
///   [`fn_80073290`].
/// - `actor`: dynamic actor; `+8` is the trigger record, `+0x14` the position.
/// - `flags`: caller status word tested throughout the attribute ladder.
///
/// # Returns
/// The accumulated contact bits.
///
/// # Side effects
/// Writes entry `+0xD8` bits, the actor position (x and y) and calls the two
/// virtual hooks.
///
/// # Safety
/// The actor, the scroll-layer list and every listed entry must be live; the
/// function pointers at `+0x60`/`+0x40` must be valid when present.
///
/// # Confidence
/// medium - every mask, store and call is literal; the bit names come from the
/// comments of the already translated tile routines.
pub unsafe fn fn_80073670(bias: f32, actor: usize, flags: u32) -> u32 {
    let mut decoded = [0.0f32; 3];
    if fn_80072db0(actor, decoded.as_mut_ptr() as usize) == 0 {
        return 0;
    }
    let position = read_u32(actor + 0x14) as usize;
    let pos_x = read_f32(position);
    let mut pos_y = read_f32(position + 4);
    let start = [
        decoded[0] + pos_x,
        decoded[1] + pos_x,
        decoded[2] + pos_y,
    ];
    let zero = read_f32(W91_F_ZERO);
    let half = read_f32(W103_F_73F4);
    let mut result = 0u32;
    let mut entry = read_u32(W33_G_SCROLL_HEAD) as usize;
    while entry != 0 {
        if call4(W101_ACTOR_FILTER, entry as u32, actor as u32, flags, 3) != 0 {
            let mut point = start;
            let mut normal = [0.0f32; 3];
            if fn_80073290(
                bias,
                actor,
                entry,
                point.as_mut_ptr() as usize,
                normal.as_mut_ptr() as usize,
            ) != 0
            {
                let mut probe = [0.0f32; 3];
                probe[0] = (read_f32(entry + 0x60) + read_f32(entry + 0x70)) * half + bias;
                probe[1] = (read_f32(entry + 0x64) + read_f32(entry + 0x74)) * half;
                probe[2] = zero;
                let kind = read_u32(entry + 0xcc);
                if kind.wrapping_sub(5) < 3 {
                    fn_80074ff0(
                        actor as u32,
                        entry,
                        probe.as_mut_ptr() as u32,
                        flags,
                    );
                } else {
                    let attr = read_u32(entry + 0xd0);
                    let mut value;
                    if flags & 0x0800_0000 != 0 && attr & 0x20 != 0 {
                        value = 0x40_0000;
                        write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 4);
                    } else if flags & 0x4000 != 0 && attr & 0x40 != 0 {
                        value = 0x40_0000;
                        write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 2);
                    } else {
                        value = 0x1_0000;
                        if attr & 0x200 != 0 && flags & 0x0010_0000 != 0 {
                            value = 0x81_0000;
                            write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 0x20);
                        }
                        if attr & 0x80 != 0 {
                            if flags & 0x0080_0000 == 0 {
                                if flags & 0x0040_0000 != 0 {
                                    value |= 0x80_0000;
                                    write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 0x20);
                                }
                            } else {
                                value |= 0x40_0000;
                                write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 8);
                            }
                        }
                        if attr & 0x100 != 0 && flags & 0x00c0_0000 != 0 {
                            value |= 0x40_0000;
                            write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 8);
                        }
                        if fn_80070760(actor) != 0 {
                            value |= 0x4000;
                        }
                        if flags & 8 != 0 && kind == 10 {
                            write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 0x10);
                        }
                        if flags & 0x1000_0000 != 0 && value & 0x40_0000 != 0 {
                            value &= 0xfffe_ffff;
                        }
                        if platform::call2(W103_ENTRY_TOUCH, entry as u32, flags) != 0 {
                            if attr & 0x40_0000 != 0 {
                                value |= 0x2_0000;
                            }
                            if attr & 4 != 0 {
                                fn_80070600(actor, 1);
                            }
                            if attr & 8 != 0 {
                                fn_80070600(actor, 1);
                                value |= 0x0200_0000;
                            }
                            if attr & 0x10 != 0 {
                                fn_80070600(actor, 10);
                            }
                            if pos_y < normal[0] - decoded[2] {
                                pos_y = normal[0] - decoded[2];
                            }
                        }
                    }
                    if read_u32(actor + 4) != 0 {
                        fn_800731e0(actor, entry, normal.as_mut_ptr() as usize);
                    }
                    result |= value;
                }
                let target = fn_800705b0(actor);
                if target != 0 {
                    if kind <= 2 && platform::call2(W103_ENTRY_ACCEPT, entry as u32, target) != 0 {
                        let vtable = read_u32(target as usize + 0x60) as usize;
                        let function = read_u32(vtable + 0x68) as usize;
                        if platform::call2(function, target, entry as u32) != 0 {
                            write_u8(target as usize + 0x34a, read_u8(target as usize + 0x34a) | 4);
                        }
                    }
                    let callback = read_u32(entry + 0x40) as usize;
                    if callback != 0 {
                        platform::call2(callback, read_u32(entry), target);
                    }
                }
            }
        }
        entry = read_u32(entry + 4) as usize;
    }
    if result != 0 {
        let step = read_f32(W96_F_STEP_TIER) + read_f32(read_u32(actor + 0x14) as usize + 4);
        if step <= pos_y {
            pos_y = step;
        }
        let position = read_u32(actor + 0x14) as usize;
        write_f32(position, pos_x);
        write_f32(position + 4, pos_y);
    }
    result
}

