/// Calls a PowerPC function with two `f64` arguments and three words.
///
/// Used for `0x800BD970`, the per-strip lift builder that takes
/// `(f64 x, f64 y, this, index, mode)`.
///
/// # Safety
/// `addr` must use this mixed floating/integer ABI.
unsafe fn call2_f64_3u32(addr: usize, a: f64, b: f64, c: u32, d: u32, e: u32) -> u32 {
    let func: extern "C" fn(f64, f64, u32, u32, u32) -> u32 = core::mem::transmute(addr);
    func(a, b, c, d, e)
}

// ---------------------------------------------------------------------------
// 0x800B3000
// ---------------------------------------------------------------------------

/// Rotates a two-component vector by a `s16` angle.
///
/// The angle is scaled by `r2-0x6B0C`, then evaluated through the sine
/// (`0x80237BD0`) and cosine (`0x80237C40`) helpers. The cosine term is added
/// to `out[1]` and the sine term is subtracted from `out[0]`.
///
/// # Original
/// - Ghidra: `FUN_800b3000` at `0x800B3000` (192 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b3000_FUN_800b3000.c`
/// - observed: `dVar5 = (double)FUN_80237bd0(...)`, `dVar6 =
///   (double)FUN_80237c40(...)`, `param_3[1] = (float)(param_1 * dVar5) +
///   (float)(param_2 * dVar6);` and `*param_3 = (float)(param_1 * dVar6) -
///   (float)(param_2 * dVar5);`.
///
/// # Arguments
/// - `first`: first vector component (the `f1` double).
/// - `second`: second vector component (the `f2` double).
/// - `out`: two-float destination.
/// - `angle`: the `s16` rotation angle at `param_4`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes two floats at `out`.
///
/// # Safety
/// `out` must be writable for eight bytes.
///
/// # Confidence
/// medium - the four products are literal; the `s16` argument reaches the
/// arithmetic through a paired-single `GQR3` default-mode conversion, which is
/// reproduced as a plain `i16` to `f32` cast (the same reading as
/// [`stage_circle_wrap`]).
pub unsafe fn fn_800b3000(first: f64, second: f64, out: usize, angle: i16) {
    let radians = (read_f32(W104_F_6B0C) * angle as f32) as f64;
    let sine = call1_f64(W104_TRIG_SIN, radians);
    let cosine = call1_f64(W100_TRIG_COS, radians);
    write_f32(out + 4, (first * sine) as f32 + (second * cosine) as f32);
    write_f32(out, (first * cosine) as f32 - (second * sine) as f32);
}

// ---------------------------------------------------------------------------
// 0x800B33D0
// ---------------------------------------------------------------------------

/// Converts a two-word point into screen-relative units.
///
/// [`fn_800b30c0`] and [`fn_800b30e0`] supply the camera offsets that are
/// subtracted from `point[0]`/`point[1]`. The x divisor is `[owner+0x40] /
/// r2-0x6AF8`; the y divisor is `[owner+0x44]` over the display width (or the
/// wide-screen word) times `r2-0x6AF4`. `0x801DD1D0` picks the branch.
///
/// # Original
/// - Ghidra: `FUN_800b33d0` at `0x800B33D0` (248 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b33d0_FUN_800b33d0.c`
/// - observed: `dVar4 = [owner+0x40] / [r2-0x6af8]`, the two
///   `(double)*param_1 - dVar3` stores, `cVar2 = thunk_FUN_801dd1d0();`, the
///   `[r2-0x6af4] * (ushort)(display+4)` form and the two divisions.
///
/// # Arguments
/// - `point`: two `f32` values, rescaled in place.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes both floats of `point`.
///
/// # Safety
/// `point` must be writable for eight bytes and the display object behind
/// [`W94_G_DISPLAY_INFO`] must be live.
///
/// # Confidence
/// medium - every division and both branches are literal; the display pair and
/// the role of `0x801DD1D0` are the same as in [`fn_800b37e0`].
pub unsafe fn fn_800b33d0(point: usize) {
    let owner = read_u32(W104_G_SCREEN_OWNER) as usize;
    let scale_x = read_f32(owner + 0x40) / read_f32(W94_F_6AF8);
    write_f32(point, (read_f32(point) as f64 - fn_800b30c0()) as f32);
    write_f32(point + 4, (read_f32(point + 4) as f64 - fn_800b30e0()) as f32);
    let wide = call0_ret(0x801D_D1D0) as u8;
    let display = read_u32(W94_G_DISPLAY_INFO) as usize;
    let scale_y = if wide == 0 {
        read_f32(owner + 0x44) / (read_f32(W104_F_6AF4) * read_u16(display + 4) as f32)
    } else {
        read_f32(owner + 0x44) / read_u16(display + 6) as f32
    };
    write_f32(point, read_f32(point) / scale_x);
    write_f32(point + 4, read_f32(point + 4) / scale_y);
}

// ---------------------------------------------------------------------------
// 0x800B39C0
// ---------------------------------------------------------------------------

/// Scales one sampled `s16` by the caller's scale and sign.
///
/// The sample object is `table[index]`; [`fn_800b5c50`] returns its `+0x8E`
/// halfword in the high half of a word, so the sign reaches
/// [`fn_800b38d0`] as a negative `i32`.
///
/// # Original
/// - Ghidra: `FUN_800b39c0` at `0x800B39C0` (92 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b39c0_FUN_800b39c0.c`
/// - observed: `FUN_800b5c50(*(undefined4 *)(*(int *)(unaff_r13 + -0x5730) +
///   param_2 * 4 + 4));` followed by
///   `FUN_800b38d0(param_1,(int)extraout_var,param_3);`.
///
/// # Arguments
/// - `scale`: multiplier forwarded to [`fn_800b38d0`].
/// - `index`: slot index into [`W104_G_SAMPLE_TABLE`].
/// - `count`: the count compared against the sample.
///
/// # Returns
/// Nothing; [`fn_800b38d0`]'s result is discarded.
///
/// # Side effects
/// None beyond the callee.
///
/// # Safety
/// The table must be live and `index` in range; the sample object must be
/// readable at `+0x8E`.
///
/// # Confidence
/// high - the two calls and the table read are literal; only the sign role of
/// the packed halfword is inferred from [`fn_800b5c50`].
pub unsafe fn fn_800b39c0(scale: f64, index: i32, count: u32) {
    let table = read_u32(W104_G_SAMPLE_TABLE) as usize;
    let slot = read_u32(table + index as usize * 4 + 4);
    let sample = fn_800b5c50(slot as usize) as i32;
    fn_800b38d0(scale, sample, count);
}

// ---------------------------------------------------------------------------
// 0x800B8CF0
// ---------------------------------------------------------------------------

/// Walks two probes across a slope layer and reports whether either hits.
///
/// The source record's `+0xAC`/`+0xB0`/`+0xB4` point is used with the
/// `r2-0x6A20` step. The far probe runs at `x + step`, the near probe at the
/// current `x`; each pair is a [`W104_PROBE_GRID`] point test followed by a
/// [`W104_PROBE_RAY`] segment test whose hit height is compared with the
/// `r2-0x6A14` tolerance.
///
/// # Original
/// - Ghidra: `FUN_800b8cf0` at `0x800B8CF0` (496 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b8cf0_FUN_800b8cf0.c`
/// - observed: `iVar4 = *(int *)(param_1 + 100);`, the `+0x38F` layer byte, the
///   four `r2-0x6A14..-0x6A20` loads, `if (dVar5 <= dVar8)`, the two
///   `FUN_80075270` / `FUN_800757b0` pairs and `dVar8 = dVar8 + dVar9;`.
///
/// # Arguments
/// - `this`: object whose `+0x64` word is the source record.
///
/// # Returns
/// `1` on a hit, `0` otherwise.
///
/// # Side effects
/// None; both probes are read-only.
///
/// # Safety
/// `this+0x64` must point at a record readable through `+0xB4`, and the layer
/// byte at `+0x38F` must be valid.
///
/// # Confidence
/// medium - the probe order, the four constants and the two comparisons are
/// literal; the `GQR0` prologue blocks are dead stack writes, as in the wave-103
/// band, and are not reproduced.
pub unsafe fn fn_800b8cf0(this: usize) -> u32 {
    let source = read_u32(this + 0x64) as usize;
    let layer = read_u8(source + 0x38f) as u32;
    let step = read_f32(W104_F_6A20);
    let floor = read_f32(W104_F_6A1C);
    let reach = read_f32(W104_F_6A14);
    let scratch = read_f32(W104_F_6A18);
    let y = read_f32(source + 0xb0);
    let z = read_f32(source + 0xb4);
    let limit = step + read_f32(source + 0xac);
    let mut x = read_f32(source + 0xac) - step;
    loop {
        if limit <= x {
            if call_f32x2_u32x2(W104_PROBE_GRID, limit, y - floor, layer, 0) != 0 {
                return 1;
            }
            let mut point = [limit, y, z];
            let mut hit = scratch;
            let found = platform::call5(
                W104_PROBE_RAY,
                point.as_mut_ptr() as u32,
                (&mut hit) as *mut f32 as u32,
                layer,
                1,
                0xffff_ffff,
            );
            if found == 0 || reach < (y - hit).abs() {
                return 0;
            }
            return 1;
        }
        if call_f32x2_u32x2(W104_PROBE_GRID, x, y - floor, layer, 0) != 0 {
            return 1;
        }
        let mut point = [x, y, z];
        let mut hit = scratch;
        let found = platform::call5(
            W104_PROBE_RAY,
            point.as_mut_ptr() as u32,
            (&mut hit) as *mut f32 as u32,
            layer,
            1,
            0xffff_ffff,
        );
        if found != 0 && (y - hit).abs() <= reach {
            return 1;
        }
        x += step;
    }
}

// ---------------------------------------------------------------------------
// 0x800BBE10
// ---------------------------------------------------------------------------

/// Builds the three projected columns of a cylindrical strip.
///
/// A radius starting at `r2-0x696C` grows by `r2-0x6960`. Each of the three
/// `6`-float columns holds a `(x, y, z)` pair and its mirror: the projection is
/// `x = cos*r / (1 + sin*r)` and `y = r2-0x6964 / (1 + sin*r)` with
/// `z = -sin*r`. The angle is the `s16` at `+0x11C`.
///
/// # Original
/// - Ghidra: `FUN_800bbe10` at `0x800BBE10` (232 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800bbe10_FUN_800bbe10.c`
/// - observed: `sVar6 = *(short *)(param_1 + 0x11c);`, the `FUN_80237c40` /
///   `FUN_80237bd0` pair, `dVar17 = (float)(dVar17 + (double)fVar5);`,
///   `fVar13 = fVar4 / fVar11;`, `*pfVar14 = fVar11;` and the six stores per
///   step with `pfVar14 = pfVar14 + 6;`.
///
/// # Arguments
/// - `this`: record whose `+0xD4..+0x118` receives 18 floats and whose `+0x11C`
///   holds the `s16` angle.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes 18 floats at `this+0xD4`.
///
/// # Safety
/// `this+0xD4..+0x11E` must be readable/writable.
///
/// # Confidence
/// medium - the projection terms and the three steps are literal; the `s16`
/// angle conversion is the same `GQR3` default-mode reading as
/// [`fn_800b3000`].
pub unsafe fn fn_800bbe10(this: usize) {
    let mut radius = read_f32(W104_F_696C);
    let angle = read_u16(this + 0x11c) as i16;
    let radians = (read_f32(W104_F_6968) * angle as f32) as f64;
    let cosine = call1_f64(W100_TRIG_COS, radians);
    let sine = call1_f64(W104_TRIG_SIN, radians);
    let one = read_f32(W104_F_6970);
    let height = read_f32(W104_F_6964);
    let step = read_f32(W104_F_6960);
    let mut cursor = this + 0xd4;
    while cursor < this + 0x11c {
        let z = radius as f64 * sine;
        let horizontal = radius as f64 * cosine;
        radius += step;
        let denominator = one + z as f32;
        let y = height / denominator;
        let x = (one * horizontal as f32) / denominator;
        write_f32(cursor, x);
        write_f32(cursor + 4, y);
        write_f32(cursor + 8, -z as f32);
        write_f32(cursor + 12, x);
        write_f32(cursor + 16, -y);
        write_f32(cursor + 20, -z as f32);
        cursor += 24;
    }
}

// ---------------------------------------------------------------------------
// 0x800BC6B0
// ---------------------------------------------------------------------------

/// Copies one matrix into three sibling sub-objects at three yaw angles.
///
/// `this+0xC8` is the yaw and `this+0xC0` the scale. The first copy is
/// translated by `(yaw, offset_y, r2-0x6944)`, the second by
/// `(r2-0x6944, offset_y, r2-0x6944)` and the third by
/// `(-yaw, offset_y, r2-0x6944)`; each copy is then multiplied by the source
/// matrix and installed with `0x8016A170`/`0x8016A130` before its vtable `+0x14`
/// slot runs.
///
/// # Original
/// - Ghidra: `FUN_800bc6b0` at `0x800BC6B0` (664 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800bc6b0_FUN_800bc6b0.c`
/// - observed: `dVar7 = (double)(float)piVar4[0x32];`, `dVar8 =
///   (double)(float)piVar4[0x30];`, the twelve `puVar5[...]` copies, the three
///   `FUN_801c0bd0` / `FUN_801c0540` / `FUN_8016a170` / `FUN_8016a130` groups,
///   the three `(**(code **)(*piVar4 + 0x14))(piVar4);` calls and
///   `FUN_802dcdc0();`.
///
/// # Arguments
/// - `offset_y`: the y translation of every copy (the caller's `f1`).
/// - `this`: owner of the three `0x40`-byte sub-objects.
/// - `source`: twelve-word matrix source.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Rewrites three sub-object matrices and runs their virtual `+0x14` method.
///
/// # Safety
/// `this+0xC0..+0xC8` must be readable, `source` must hold twelve readable
/// words and each sub-object must expose a readable vtable.
///
/// # Confidence
/// medium - the three groups are literal; `offset_y` is read from `extraout_f1`
/// in the export, which is the caller's own `f1` because the register-save
/// helper preserves the floating-point registers.
pub unsafe fn fn_800bc6b0(offset_y: f32, this: usize, source: usize) {
    let yaw = read_f32(this + 0xc8);
    let scale = read_f32(this + 0xc0);
    let zero = read_f32(W104_F_6944);
    let mut base = [0u32; 12];
    for (index, word) in base.iter_mut().enumerate() {
        *word = read_u32(source + index * 4);
    }
    let mut matrix = base;
    for (offset, x) in [(0x00usize, yaw), (0x40, zero), (0x80, -yaw)] {
        let mut translation = [0u32; 12];
        call3_f32_ptr(
            W88_MATRIX_TRANSLATE,
            x,
            offset_y,
            zero,
            translation.as_mut_ptr() as u32,
        );
        platform::call3(
            W88_MATRIX_MUL,
            matrix.as_mut_ptr() as u32,
            translation.as_ptr() as u32,
            matrix.as_mut_ptr() as u32,
        );
        let object = this + offset;
        platform::call2(W29_MODEL_SET_MATRIX, object as u32, matrix.as_ptr() as u32);
        let scale_x = if offset == 0x40 {
            read_f32(this + 0xc4)
        } else {
            scale
        };
        call3_f32_ptr(
            W104_MODEL_SCALE,
            scale_x,
            scale,
            scale,
            object as u32,
        );
        call_vtable_slot1(object, 0x14);
    }
}

// ---------------------------------------------------------------------------
// 0x800BD7A0
// ---------------------------------------------------------------------------

/// Emits one row of lift cells at four y positions.
///
/// `top` becomes the negated x, `bottom` the y and `r2-0x690C` the z. Each row
/// writes four `(x, y, z)` triples with the x advanced by `r2-0x6908` per
/// step, binds an animation name through `0x80239F20`, registers the matrix
/// with [`W104_NODE_MATRIX`], attaches the cell with [`W104_NODE_BIND`] and
/// optionally sets the `0x8000` strip flag.
///
/// # Original
/// - Ghidra: `FUN_800bd7a0` at `0x800BD7A0` (452 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800bd7a0_FUN_800bd7a0.c`
/// - observed: `dVar12 = -extraout_f1;`, the `r2-0x6908`/`r2-0x690C` loads, the
///   twelve `*(float *)(iVar11 + 0x6020...)` stores, `local_88[0] =
///   FUN_80239f20(iVar3 + 0x601c, unaff_r13 + -0x7a90);`, the two
///   `FUN_8000aa70`/`FUN_8000ae50` calls, the `+0x9028`/`+0x9228` writes and
///   the four `0x300`/`0x600`/`0x40`/`0x20` strides.
///
/// # Arguments
/// - `top`: x of the row origin (the `f1` double).
/// - `bottom`: y of the row (the `f2` double).
/// - `this`: lift object; `+0x9628` is the row count.
/// - `index`: column index.
/// - `mode`: when non-zero, marks the strip through `+0x9028`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `count` cell matrices, their draw nodes and the two flag arrays.
///
/// # Safety
/// `this` must own the full cell/node arrays for `+0x9628` rows.
///
/// # Confidence
/// medium - every store offset and stride is literal; the two `f64` parameters
/// and the packed `(this, index)` pair follow the register-save convention used
/// by [`fn_800b7b10`] and the other wave-100 lift helpers.
pub unsafe fn fn_800bd7a0(top: f64, bottom: f64, this: usize, index: i32, mode: i32) {
    let neg_top = -top as f32;
    let step = read_f32(W104_F_6908);
    let z = read_u32(W104_F_690C);
    let count = read_i32(this + 0x9628);
    let bottom = bottom as f32;
    let mut upper = step + neg_top;
    let lower = bottom - step;
    let mut current = neg_top;
    let mut matrix_base = this + index as usize * 0x30;
    let mut node = this + 0x1c + index as usize * 0x60;
    let mut draw = this + 0x6020 + index as usize * 0x30;
    let mut flags = this + 0x9028 + index as usize * 2;
    let mut state = this + 0x9228 + index as usize * 4;
    let mut row = 0i32;
    while row < count {
        let x0 = current;
        let x1 = upper;
        let x2 = upper;
        let x3 = current;
        let base = matrix_base + 0x6020;
        write_f32(base, x0);
        write_f32(base + 4, bottom);
        write_u32(base + 8, z);
        write_f32(base + 12, x1);
        write_f32(base + 16, bottom);
        write_u32(base + 20, z);
        write_f32(base + 24, x2);
        write_f32(base + 28, lower);
        write_u32(base + 32, z);
        write_f32(base + 36, x3);
        write_f32(base + 40, lower);
        write_u32(base + 44, z);
        let mut animation = [0u32; 4];
        animation[0] = platform::call2(W104_MODEL_ANM, (this + 0x601c) as u32, W104_S_SAMPLE_NAME as u32);
        platform::call5(
            W104_NODE_MATRIX,
            node as u32,
            animation.as_ptr() as u32,
            0x80,
            0xffff_ffff,
            this as u32,
        );
        platform::call2(W104_NODE_BIND, node as u32, draw as u32);
        if mode != 0 {
            write_u16(flags, 0x8000);
        }
        current += step;
        upper += step;
        write_u32(state, 1);
        node += 0x600;
        draw += 0x300;
        flags += 0x20;
        state += 0x40;
        matrix_base += 0x300;
        row += 1;
    }
}

// ---------------------------------------------------------------------------
// 0x800BE000
// ---------------------------------------------------------------------------

/// Rebuilds the whole lift grid for the current variant.
///
/// The two flag arrays at `+0x9028` (`u16`, `0x200` bytes) and `+0x9228`
/// (`u32`, `0x400` bytes) are cleared, the variant's model is loaded through
/// `0x800DF180`, and the rows are emitted by [`fn_800bd7a0`] and
/// [`fn_800bd970`]: one optional top row, one row per column, the final row and
/// one optional closing row.
///
/// # Original
/// - Ghidra: `FUN_800be000` at `0x800BE000` (832 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800be000_FUN_800be000.c`
/// - observed: the eight-way unrolled `+0x9228`/`+0x9028` zeroing, the
///   `FUN_800df180(*(int *)(unaff_r13 + -0x5648) + 4, ...)` call, the
///   `*(int *)(param_1 + 0x962c) << 4` conversion, the `+0x9630` bits `8`/`4`,
///   `FUN_800bd7a0`/`FUN_800bd970` and the `+0x9628` row count.
///
/// # Arguments
/// - `this`: lift object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Clears both flag arrays, stores the model handle at `+0x601C` and rewrites
/// every cell matrix.
///
/// # Safety
/// `this` must own the full grid described at [`fn_800bd970`].
///
/// # Confidence
/// medium - every store, bit test and call is literal; the unrolled zeroing is
/// compacted into two flat loops and the per-strip `this/index/mode` triple of
/// `0x800BD970` is passed through [`call2_f64_3u32`].
pub unsafe fn fn_800be000(this: usize) {
    let mut index = 0usize;
    while index < 0x100 {
        write_u32(this + 0x9228 + index * 4, 0);
        index += 1;
    }
    let mut index = 0usize;
    while index < 0x100 {
        write_u16(this + 0x9028 + index * 2, 0);
        index += 1;
    }
    let archive = read_u32(G_ARC_MANAGER) as usize;
    let variant = read_i32(this + 0x9634) as usize;
    let model = platform::call3(
        0x800D_F180,
        (archive + 4) as u32,
        read_u32(W104_LIFT_ZEN_NAMES + variant * 4),
        read_u32(W104_LIFT_ZEN_BRRES + variant * 4),
    );
    write_u32(this + 0x601c, model);
    let flags = read_u32(this + 0x9630);
    let columns = read_i32(this + 0x962c);
    let x = read_f32(W104_F_690C) as f64;
    let mut y = (read_f32(W104_F_6910) * ((columns << 4) as f32)) as f64;
    if flags & 8 != 0 {
        y += read_f32(W104_F_6914) as f64;
        fn_800bd7a0(x, y, this, 0, 0);
        y -= read_f32(W104_F_6914) as f64;
    }
    let mut slot = u32::from(flags & 8 != 0);
    call2_f64_3u32(0x800B_D970, x, y, this as u32, slot, 0);
    let gap = read_f32(W104_F_6908) as f64;
    y -= gap;
    let mut row = 0i32;
    while row < columns - 1 {
        slot += 1;
        call2_f64_3u32(0x800B_D970, x, y, this as u32, slot, 1);
        y -= gap;
        row += 1;
    }
    y += read_f32(W104_F_6900) as f64;
    slot += 1;
    call2_f64_3u32(0x800B_D970, x, y, this as u32, slot, 2);
    if flags & 4 != 0 {
        fn_800bd7a0(
            x,
            y - read_f32(W104_F_6914) as f64,
            this,
            slot as i32 + 1,
            1,
        );
    }
}

// ---------------------------------------------------------------------------
// 0x800BE390
// ---------------------------------------------------------------------------

/// Rebuilds the 16×16 cell matrices around one world point.
///
/// The point is biased by `+0x9020`/`+0x9024`, then every cell whose `+0x9228`
/// word is non-zero gets the same five matrix steps: translate to the point,
/// scale by `r2-0x6918`, translate to the cell offset, rotate by the `+0x9028`
/// angle, translate back, and finally install the matrix and its draw record.
///
/// # Original
/// - Ghidra: `FUN_800be390` at `0x800BE390` (436 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800be390_FUN_800be390.c`
/// - observed: `local_114 = *pfVar3 + *(float *)(iVar2 + 0x9020);`, the two
///   nested `0x10`-iteration loops, `if (*(int *)(iVar10 + 0x9228) != 0)`,
///   `FUN_801c0bd0`/`FUN_801c0c60`/`FUN_801c0540`/`FUN_8016eef0`, and the
///   `FUN_8016a170`/`FUN_8000ae50` pair with the `0x600`/`0x300` strides.
///
/// # Arguments
/// - `this`: lift object.
/// - `point`: three-float world position.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Rewrites the matrices of every enabled cell.
///
/// # Safety
/// `point` must hold three readable floats and `this` must own the full grid.
///
/// # Confidence
/// medium - the five matrix steps and all four strides are literal; the dead
/// `GQR0` prologue block is not reproduced, and the rotation helper is called as
/// `0x8016EEF0` exactly as the export shows.
pub unsafe fn fn_800be390(this: usize, point: usize) {
    let px = read_f32(point) + read_f32(this + 0x9020);
    let py = read_f32(point + 4) + read_f32(this + 0x9024);
    let pz = read_f32(point + 8);
    let bias = read_f32(W104_F_6914);
    let scale = read_f32(W104_F_6918);
    let z = read_f32(W104_F_690C);
    let mut row = 0usize;
    while row < 0x10 {
        let mut column = 0usize;
        while column < 0x10 {
            if read_u32(this + 0x9228 + row * 4 + column * 0x40) != 0 {
                let cell = this + 0x6020 + row * 0x30 + column * 0x300;
                let node = this + 0x1c + row * 0x60 + column * 0x600;
                let cell_x = read_f32(cell);
                let cell_y = read_f32(cell + 4);
                let mut matrix = [0u32; 12];
                call3_f32_ptr(
                    W88_MATRIX_TRANSLATE,
                    px,
                    py,
                    pz,
                    matrix.as_mut_ptr() as u32,
                );
                let mut uniform = [0u32; 12];
                call3_f32_ptr(
                    W85_MTX_SCALE,
                    scale,
                    scale,
                    scale,
                    uniform.as_mut_ptr() as u32,
                );
                platform::call3(
                    W88_MATRIX_MUL,
                    matrix.as_mut_ptr() as u32,
                    uniform.as_ptr() as u32,
                    matrix.as_mut_ptr() as u32,
                );
                let mut to_cell = [0u32; 12];
                call3_f32_ptr(
                    W88_MATRIX_TRANSLATE,
                    bias + cell_x,
                    cell_y - bias,
                    z,
                    to_cell.as_mut_ptr() as u32,
                );
                platform::call3(
                    W88_MATRIX_MUL,
                    matrix.as_mut_ptr() as u32,
                    to_cell.as_ptr() as u32,
                    matrix.as_mut_ptr() as u32,
                );
                let mut angle = [read_u16(this + 0x9028 + row * 2 + column * 0x20); 1];
                platform::call2(
                    W29_MTX_ROTATE_C,
                    matrix.as_mut_ptr() as u32,
                    angle.as_mut_ptr() as u32,
                );
                let mut back = [0u32; 12];
                call3_f32_ptr(
                    W88_MATRIX_TRANSLATE,
                    -cell_x - bias,
                    -cell_y + bias,
                    z,
                    back.as_mut_ptr() as u32,
                );
                platform::call3(
                    W88_MATRIX_MUL,
                    matrix.as_mut_ptr() as u32,
                    back.as_ptr() as u32,
                    matrix.as_mut_ptr() as u32,
                );
                platform::call2(W29_MODEL_SET_MATRIX, node as u32, matrix.as_ptr() as u32);
                platform::call2(W104_NODE_BIND, node as u32, cell as u32);
            }
            column += 1;
        }
        row += 1;
    }
}

// ---------------------------------------------------------------------------
// 0x800BE690
// ---------------------------------------------------------------------------

/// Builds one lift draw node from one model word and, optionally, a clip.
///
/// The model word comes from [`J3D_LOAD_ANM`] on the archive slot; it is handed
/// to [`W104_NODE_BUILD`] with the caller's flags (bit 0/1 forced when a clip is
/// present). With a clip, [`W104_ANM_LOAD`] returns the second word, the pair is
/// bound to the node's `+0x40` sub-object, attached and committed.
///
/// # Original
/// - Ghidra: `FUN_800be690` at `0x800BE690` (284 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800be690_FUN_800be690.c`
/// - observed: `uVar2 = FUN_80239e30(param_3,param_4);`, the
///   `if (param_6 != 0) { param_5 = param_5 | 3; }` arm,
///   `FUN_80169d90(piVar1,&local_30,(int)uVar6,param_5,1,0);`,
///   `FUN_80064bf0(piVar1);`, `FUN_80166830(piVar1 + 0x10, ...);`,
///   `FUN_80166bd0(piVar1 + 0x10, piVar1, local_2c, 0, 1);`, the
///   `+0x18` vtable call and `FUN_802dcdbc(uVar3);`.
///
/// # Arguments
/// - `_height`: leading `f1` word; the body never reads it.
/// - `node`: the draw node (the packed `r3`).
/// - `owner`: the draw-list owner (the packed `r4`).
/// - `archive`: pointer to the archive handle word.
/// - `name`: model name.
/// - `flags`: draw flags passed to [`W104_NODE_BUILD`].
/// - `clip`: optional second resource id.
///
/// # Returns
/// The last callee's `r3`.
///
/// # Side effects
/// Builds the node, and with a clip binds, attaches and commits an animation.
///
/// # Safety
/// `node` must be a live draw node, `archive` must point at a readable word and
/// `name` must be a readable C string.
///
/// # Confidence
/// medium - the call sequence and both flag arms are literal; the `(r3, r4)`
/// pair of the register-save helper is read as `(node, owner)`, the same
/// convention as [`fn_80070cd0`], and the leading `f1` word is unused by the
/// body (`param_6` in the export is the `clip` argument).
pub unsafe fn fn_800be690(
    _height: f64,
    node: usize,
    owner: usize,
    archive: usize,
    name: usize,
    flags: u32,
    clip: u32,) -> u32 {
    let model = platform::call2(J3D_LOAD_ANM, archive as u32, name as u32);
    let mut node_flags = flags;
    if clip != 0 {
        node_flags |= 3;
    }
    let mut model_word = [0u32; 4];
    model_word[0] = model;
    let mut result = platform::call6(
        W104_NODE_BUILD,
        node as u32,
        model_word.as_mut_ptr() as u32,
        owner as u32,
        node_flags,
        1,
        0,
    );
    platform::call1(J3D_FINISH, node as u32);
    if clip != 0 {
        let animation = platform::call2(W104_ANM_LOAD, archive as u32, clip);
        let mut pair = [model, animation];
        let sub = node + 0x40;
        result = platform::call6(
            W104_ANM_BIND,
            sub as u32,
            (&mut pair[0]) as *mut u32 as u32,
            (&mut pair[1]) as *mut u32 as u32,
            owner as u32,
            0,
            1,
        );
        platform::call5(
            W104_ANM_ATTACH,
            sub as u32,
            node as u32,
            (&mut pair[1]) as *mut u32 as u32,
            0,
            1,
        );
        call_vtable_slot2(node, 0x18, sub as u32);
        platform::call3(W104_ANM_COMMIT, owner as u32, sub as u32, 0);
    }
    result
}

// ---------------------------------------------------------------------------
// 0x800BE950
// ---------------------------------------------------------------------------

/// Fills a `columns × rows` block of lift cells with the same model.
///
/// The grid size comes from [`fn_800be910`]/[`fn_800be930`]; the cells start at
/// `+0x4A4` and advance by `0x84`. Every cell is handed to [`fn_800be690`] with
/// the archive slot and model name of the caller.
///
/// # Original
/// - Ghidra: `FUN_800be950` at `0x800BE950` (168 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800be950_FUN_800be950.c`
/// - observed: `uVar1 = FUN_800be910(param_5);`, `uVar2 = FUN_800be930(param_6);`,
///   `iVar5 = (int)((ulonglong)uVar6 >> 0x20) + 0x4a4;`, the two nested loops,
///   `FUN_800be690(...,iVar5,(int)uVar6,param_3,param_4,0x20,0);` and
///   `iVar5 = iVar5 + 0x84;`.
///
/// # Arguments
/// - `this`: lift object; the cell array starts at `+0x4A4`.
/// - `owner`: draw-list owner forwarded to [`fn_800be690`].
/// - `archive`: pointer to the archive handle word.
/// - `name`: model name.
/// - `columns_raw`: raw column count.
/// - `rows_raw`: raw row count.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `columns * rows` cells through [`fn_800be690`].
///
/// # Safety
/// `this + 0x4A4` must be writable for the full grid.
///
/// # Confidence
/// medium - the strides, bounds and the `0x20` flag word are literal; the
/// `+0x4A4` base comes from the packed `r3` of the register-save helper.
pub unsafe fn fn_800be950(
    this: usize,
    owner: usize,
    archive: usize,
    name: usize,
    columns_raw: u32,
    rows_raw: u32,) {
    let columns = fn_800be910(columns_raw);
    let rows = fn_800be930(rows_raw);
    let height = read_f32(W100_F_68F0) as f64;
    let mut cell = this + 0x4a4;
    let mut row = 0u32;
    while row < rows {
        let mut column = 0u32;
        while column < columns {
            fn_800be690(height, cell, owner, archive, name, 0x20, 0);
            cell += 0x84;
            column += 1;
        }
        row += 1;
    }
}

// ---------------------------------------------------------------------------
// 0x800BEA00
// ---------------------------------------------------------------------------

/// Builds the 3×3 sprite block of one lift variant.
///
/// The variant selects the model name, BRRES name and texture-name row through
/// a `0x58`/`0x16`-word stride. Only the middle row and column are gated by the
/// two count arguments. The last step marks `+0x228C` and, when the variant's
/// flag word is non-zero, calls [`fn_800be950`] to fill the cell block.
///
/// # Original
/// - Ghidra: `FUN_800bea00` at `0x800BEA00` (336 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800bea00_FUN_800bea00.c`
/// - observed: `local_48[0] = FUN_800df180(..., (&PTR_s_lift_intore_802f0df8)[param_5 * 0x16], ...);`,
///   `iVar1 = countLeadingZeros(param_4 ^ 2);`, the `uVar5 == 1` arm with
///   `(param_4 << iVar1) >> 0x1f`, the `uVar4 != 1 || ((int)(param_3 << iVar3) < 0)`
///   test, `FUN_800be690(..., *ppuVar7, *puVar6, ppuVar7[1]);`, the `+0x228C`
///   store and `FUN_800be950(...)`.
///
/// # Arguments
/// - `this`: lift object.
/// - `owner`: draw-list owner forwarded to [`fn_800be690`].
/// - `columns`: column count argument.
/// - `rows`: row count argument.
/// - `variant`: lift variant index.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Loads one model set, draws up to nine sprites, writes `+0x228C` and may fill
/// the cell block.
///
/// # Safety
/// `this` must own the grid and the variant tables must be readable.
///
/// # Confidence
/// medium - the two `countLeadingZeros` gates are reproduced with
/// `wrapping_shl`; the texture-row pointer walk and the archive handle slot are
/// literal, and the leading `f1` word of [`fn_800be690`] is not read by it.
pub unsafe fn fn_800bea00(
    this: usize,
    owner: usize,
    columns: u32,
    rows: u32,
    variant: i32,) {
    let archive = read_u32(G_ARC_MANAGER) as usize;
    let index = variant as usize;
    let mut handle = [0u32; 18];
    handle[0] = platform::call3(
        0x800D_F180,
        (archive + 4) as u32,
        read_u32(W104_LIFT_TEXTURE_NAMES - 8 + index * 0x58),
        read_u32(W104_LIFT_TEXTURE_NAMES - 4 + index * 0x58),
    );
    let row_shift = (rows ^ 2).leading_zeros();
    let column_shift = (columns ^ 2).leading_zeros();
    let mut names = W104_LIFT_TEXTURE_NAMES + index * 0x58;
    let mut words = W104_LIFT_CELL_WORDS;
    let height = read_f32(W100_F_68F0) as f64;
    let mut cell = this;
    let mut row = 0u32;
    while row < 3 {
        let mut enabled = 1u32;
        if row == 1 {
            enabled = (rows << row_shift).wrapping_shr(31);
        }
        let mut column = 0u32;
        while column < 3 {
            if enabled != 0 && (column != 1 || ((columns << column_shift) as i32) < 0) {
                fn_800be690(
                    height,
                    cell,
                    owner,
                    handle.as_mut_ptr() as usize,
                    read_u32(names) as usize,
                    read_u32(words),
                    read_u32(names + 4),
                );
            }
            column += 1;
            words += 4;
            cell += 0x84;
            names += 8;
        }
        row += 1;
    }
    if read_u32(W104_LIFT_VARIANT_FLAGS + index * 0x58) == 0 {
        write_u8(this + 0x228c, 0);
    } else {
        write_u8(this + 0x228c, 1);
        fn_800be950(
            this,
            owner,
            handle.as_mut_ptr() as usize,
            read_u32(W104_LIFT_VARIANT_FLAGS + index * 0x58) as usize,
            columns,
            rows,
        );
    }
}

// ---------------------------------------------------------------------------
// 0x800BEB50
// ---------------------------------------------------------------------------

/// Draws the `lift_toge` sprites selected by a bit mask.
///
/// One model set is loaded from the `lift_zen` archive, then the bits of the
/// mask walk the `+0x207C..+0x228C` cells in `0x84` steps, each set bit
/// producing one [`fn_800be690`] sprite with flag `0x25`.
///
/// # Original
/// - Ghidra: `FUN_800beb50` at `0x800BEB50` (172 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800beb50_FUN_800beb50.c`
/// - observed: `local_28[0] = FUN_800df180(*(int *)(unaff_r13 + -0x5648) + 4,
///   s_lift_zen_803165f0, s_g3d_lift_zen_brres_803165dc);`, `uVar3 = iVar1 + 0x207c;`,
///   `if ((param_3 & 1) != 0) FUN_800be690(..., *ppuVar2, 0x25, 0);`,
///   `uVar3 = uVar3 + 0x84;`, `param_3 = param_3 >> 1;` and the
///   `iVar1 + 0x228c` bound.
///
/// # Arguments
/// - `this`: lift object; the sprites start at `+0x207C`.
/// - `owner`: draw-list owner forwarded to [`fn_800be690`].
/// - `mask`: one bit per sprite.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Loads one model set and draws one sprite per set bit.
///
/// # Safety
/// `this+0x207C..+0x2290` must be writable and the name tables readable.
///
/// # Confidence
/// medium - the bit walk and the `0x84`/`0x25` values are literal; the
/// `+0x207C` base comes from the packed `r3` of the register-save helper.
pub unsafe fn fn_800beb50(this: usize, owner: usize, mask: u32) {
    if mask == 0 {
        return;
    }
    let archive = read_u32(G_ARC_MANAGER) as usize;
    let mut handle = [0u32; 10];
    handle[0] = platform::call3(
        0x800D_F180,
        (archive + 4) as u32,
        W104_S_LIFT_ZEN as u32,
        W104_S_LIFT_ZEN_BRRES as u32,
    );
    let height = read_f32(W100_F_68F0) as f64;
    let mut cell = this + 0x207c;
    let mut names = W104_S_LIFT_TOGE;
    let mut bits = mask;
    while cell < this + 0x228c {
        if bits & 1 != 0 {
            fn_800be690(
                height,
                cell,
                owner,
                handle.as_mut_ptr() as usize,
                read_u32(names) as usize,
                0x25,
                0,
            );
        }
        cell += 0x84;
        bits >>= 1;
        names += 4;
    }
}

// ---------------------------------------------------------------------------
// 0x800BF3F0
// ---------------------------------------------------------------------------

/// Writes the up-to-four travel cells of a lift variant.
///
/// `flags` bit 0..3 each enable one `0x84`-byte cell at `+0x207C`, `+0x2100`,
/// `+0x2184` and `+0x2208`. Every cell gets the three `0x80358DF0` words plus
/// two scaled sizes; the first three also get a [`fn_800be7b0`] translation
/// built from the raw arguments.
///
/// # Original
/// - Ghidra: `FUN_800bf3f0` at `0x800BF3F0` (744 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800bf3f0_FUN_800bf3f0.c`
/// - observed: the four `if ((param_4 <bit>) != 0)` blocks, the
///   `CONCAT44(0x43300000,param_N ^ 0x80000000)` conversions, the `+0x20E8`,
///   `+0x216C`, `+0x21F0`, `+0x2274` triples, the four `FUN_800be7b0` calls and
///   the `+0x20F4`/`+0x217C`/`+0x21FC`/`+0x2280` scaled sizes.
///
/// # Arguments
/// - `this`: lift object.
/// - `first`: first raw count.
/// - `second`: second raw count.
/// - `flags`: enabled-cell mask.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes up to 24 floats at `+0x20E8..+0x2288`.
///
/// # Safety
/// `this+0x20E8..+0x2288` must be writable.
///
/// # Confidence
/// medium - every offset and factor is literal; the two `^ 0x80000000`
/// conversions are the signed-int-to-double idiom and are read as `i32` casts.
pub unsafe fn fn_800bf3f0(this: usize, first: i32, second: i32, flags: u32) {
    let word_a = read_u32(W100_CELL_WORD_A);
    let word_b = read_u32(W100_CELL_WORD_B);
    let word_c = read_u32(W100_CELL_WORD_C);
    let zero = read_u32(W100_F_68F0);
    let first_f = first as f32;
    let second_f = second as f32;
    if flags & 1 != 0 {
        write_u32(this + 0x20e8, word_a);
        write_f32(this + 0x20ec, second_f);
        write_u32(this + 0x20f0, word_c);
        let vector = [second_f, word_b as f32, word_c as f32];
        fn_800be7b0(this + 0x207c, vector.as_ptr() as usize);
        write_f32(this + 0x20f4, read_f32(W104_F_68C0) * first_f);
        write_f32(this + 0x20f8, read_f32(W104_F_68D4) * second_f);
        write_u32(this + 0x20fc, zero);
    }
    if flags & 2 != 0 {
        write_u32(this + 0x216c, word_a);
        write_f32(this + 0x2170, second_f);
        write_u32(this + 0x2174, word_c);
        let vector = [second_f, word_b as f32, word_c as f32];
        fn_800be7b0(this + 0x2100, vector.as_ptr() as usize);
        write_u32(this + 0x2178, zero);
        write_f32(this + 0x217c, read_f32(W104_F_68D4) * second_f);
        write_u32(this + 0x2180, zero);
    }
    if flags & 4 != 0 {
        write_f32(this + 0x21f0, first_f);
        write_u32(this + 0x21f4, word_b);
        write_u32(this + 0x21f8, word_c);
        let vector = [first_f, word_b as f32, word_c as f32];
        fn_800be7b0(this + 0x2184, vector.as_ptr() as usize);
        write_f32(this + 0x21fc, read_f32(W104_F_68D8) * first_f);
        write_f32(this + 0x2200, read_f32(W104_F_68BC) * second_f);
        write_u32(this + 0x2204, zero);
    }
    if flags & 8 != 0 {
        write_f32(this + 0x2274, first_f);
        write_u32(this + 0x2278, word_b);
        write_u32(this + 0x227c, word_c);
        let vector = [first_f, word_b as f32, word_c as f32];
        fn_800be7b0(this + 0x2208, vector.as_ptr() as usize);
        write_f32(this + 0x2280, read_f32(W104_F_68D8) * first_f);
        write_u32(this + 0x2284, zero);
        write_u32(this + 0x2288, zero);
    }
}

