/// bytes.
///
/// # Confidence
/// low - the guard and both stores are literal, but the probe point is an
/// argument the Ghidra export drops.
pub unsafe fn fn_800976b0(this: usize, point: usize) -> bool {
    let grounded = fn_80097700(this, point);
    if !grounded {
        let rest = read_u32(W105_W_REST_WORD);
        write_u32(this + 0xF8, rest);
        write_u32(this + 0x118, rest);
    }
    grounded
}

