///
/// # Safety
/// Same as [`fn_800cb670`].
///
/// # Confidence
/// low - literal body, dropped argument registers.
pub unsafe fn fn_800cb760(
    this: usize,
    resource: u32,
    id: u32,
    width: i32,
    height: i32,
    texture: u32,
) {
    fn_800cb670(
        this,
        resource,
        id,
        width,
        height,
        texture,
        read_f32(W106_F_670C) as f64,
    );
}

// ---------------------------------------------------------------------------
// 0x800CB780
// ---------------------------------------------------------------------------

/// Third alpha flavour, which also marks the record as flipped on success.
///
/// Calls the shared initialiser with the `r2-0x6738` alpha and, when it
/// reports success, sets the `+0x14` byte to `1` before returning the same
/// truth value.
///
/// # Original
/// - Ghidra: `FUN_800cb780` at `0x800CB780` (88 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800cb780_FUN_800cb780.c`
/// - observed: `iVar1 = FUN_800cb670((double)*(float *)(unaff_r2 + -0x6738));`
///   `if (iVar1 != 0) { *(undefined1 *)(param_1 + 0x14) = 1; }`
///   `return iVar1 != 0;`.
///
/// # Arguments
/// Same six registers as [`fn_800cb670`]; the alpha is the `-0x6738` constant.
///
/// # Returns
/// `true` when the render object was created.
///
/// # Side effects
/// Everything [`fn_800cb670`] does, plus `+0x14 = 1` on success.
///
/// # Safety
/// Same as [`fn_800cb670`].
///
/// # Confidence
/// low - the body is literal and `param_1` is the record, but the remaining
/// argument registers are dropped by the export.
pub unsafe fn fn_800cb780(
    this: usize,
    resource: u32,
    id: u32,
    width: i32,
    height: i32,
    texture: u32,
) -> bool {
    let created = fn_800cb670(
        this,
        resource,
        id,
        width,
        height,
        texture,
        read_f32(W106_F_6738) as f64,
    );
    if created != 0 {
        write_u8(this + 0x14, 1);
    }
    created != 0
}

// ===========================================================================
// Wave 107 - the actor/ground-trace cluster (0x800728C0 .. 0x8007FFA0)
// ===========================================================================

// Small-data slots this pass reads.

/// `r2 - 0x73F0` -> `0x8042BC90`: slack subtracted from a segmented walk's
/// height in [`fn_80074470`].
const W107_F_73F0: usize = SDA2_BASE - 0x73F0;

/// `r2 - 0x7390` -> `0x8042BCF0`: outer bearing tolerance of the segmented
/// walk in [`fn_80074470`].
const W107_F_7390: usize = SDA2_BASE - 0x7390;

/// `r2 - 0x7388` -> `0x8042BCF8`: inner bearing tolerance of the same walk.
const W107_F_7388: usize = SDA2_BASE - 0x7388;

/// `r2 - 0x7398` -> `0x8042BCE8`: the small step the segment owner is nudged by
/// when its own segment is already occupied.
const W107_F_7398: usize = SDA2_BASE - 0x7398;

/// `r2 - 0x71F0` -> `0x8042BE90`: radians per 16-bit angle unit.
const W107_F_RADIANS_PER_UNIT: usize = SDA2_BASE - 0x71F0;

/// `r2 - 0x71F8` -> `0x8042BE88`: the `0.0f` seed of [`fn_8007ffa0`].
const W107_F_SEED: usize = SDA2_BASE - 0x71F8;

// Tables.

/// `0x802EF488`: eight-byte normal pair per tile kind (`+0` slope, `+4` cross
/// term) read by [`fn_800728c0`] and [`fn_80075ca0`].
const W107_TBL_SLOPE_B: usize = 0x802E_F488;

/// `0x802EF648`: four signed node offsets (in 8-byte units) into a
/// scroll-layer entry, indexed by the top two bits of its first node word.
const W107_TBL_SEGMENT: usize = 0x802E_F648;

// Callees that are not translated in this file.

/// `0x80081030`: per-entry height probe; non-zero means "the owner is inside
/// this entry".
const W107_CALL_80081030: usize = 0x8008_1030;

/// `0x80080D40`: actor/entry filter used before the virtual hook.
const W107_CALL_80080D40: usize = 0x8008_0D40;

/// `0x80080D80`: entry/actor filter of the lane-aware walk.
const W107_CALL_80080D80: usize = 0x8008_0D80;

/// `0x8006D120`: advances one probe cursor along a vertical line.
const W107_CALL_8006D120: usize = 0x8006_D120;

/// `0x802390D0`: infinite-line intersection; the parameter comes back in `f1`.
const W107_CALL_802390D0: usize = 0x8023_90D0;

/// `0x80237BA0`: root helper of the circle-height arm of [`fn_80074470`].
const W107_CALL_80237BA0: usize = 0x8023_7BA0;

/// `0x80237BD0`: second member of the 16-bit angle pair.
const W107_CALL_80237BD0: usize = 0x8023_7BD0;

/// `0x80237C40`: first member of the 16-bit angle pair.
const W107_CALL_80237C40: usize = 0x8023_7C40;

/// `0x80237ED0`: two-coordinate 16-bit bearing helper.
const W107_CALL_80237ED0: usize = 0x8023_7ED0;

/// `0x802BE470`: square-root helper (`f1` in, `f1` out).
const W107_CALL_802BE470: usize = 0x802B_E470;

/// `0x80101AA0`: the shared wrap helper the camera code also uses.
const W107_CALL_80101AA0: usize = 0x8010_1AA0;

/// `0x8015F480`: steps a float toward a bound (`thunk_FUN_8015f480`).
const W107_CALL_8015F480: usize = 0x8015_F480;

/// Calls `(f64, u32) -> u32`; used for `0x8015F480`-shaped helpers that take
/// one float and one pointer word.
///
/// # Safety
/// `addr` must use this mixed ABI.
unsafe fn w107_call_f64_ptr(addr: usize, a: f64, ptr: u32) -> u32 {
    let f: extern "C" fn(f64, u32) -> u32 = core::mem::transmute(addr);
    f(a, ptr)
}

/// Calls `(f64, f64) -> f64`; used for the `0x80237BA0` root helper.
///
/// # Safety
/// `addr` must take two doubles and return one in `f1`.
unsafe fn w107_call_f64x2_f64(addr: usize, a: f64, b: f64) -> f64 {
    let f: extern "C" fn(f64, f64) -> f64 = core::mem::transmute(addr);
    f(a, b)
}

/// Calls `(f64, f64, f64, u32) -> u32`; used for `0x80080880`.
///
/// # Safety
/// `addr` must use this mixed ABI.
unsafe fn w107_call_f64x3_u32(addr: usize, a: f64, b: f64, c: f64, d: u32) -> u32 {
    let f: extern "C" fn(f64, f64, f64, u32) -> u32 = core::mem::transmute(addr);
    f(a, b, c, d)
}

/// Calls `(u32, u32, u32, u32) -> f64`; used for `0x802390D0`.
///
/// # Safety
/// `addr` must take four words and return one double in `f1`.
unsafe fn w107_call4_f64(addr: usize, a: u32, b: u32, c: u32, d: u32) -> f64 {
    let f: extern "C" fn(u32, u32, u32, u32) -> f64 = core::mem::transmute(addr);
    f(a, b, c, d)
}

/// Calls `(u32) -> f32`; used for `0x80078EB0`, whose result is printed as a
/// `double` because of the paired-single return.
///
/// # Safety
/// `addr` must take one word and return a float in `f1`.
unsafe fn w107_call_u32_f32(addr: usize, a: u32) -> f32 {
    let f: extern "C" fn(u32) -> f32 = core::mem::transmute(addr);
    f(a)
}

// ---------------------------------------------------------------------------
// 0x800728C0
// ---------------------------------------------------------------------------

/// Walks one actor's feet down the BG grid to the first floor below them.
///
/// The actor position at `+0x14` is probed once with `0x80072790`; when that
/// reports a scroll-layer entry the search starts at the returned height,
/// otherwise at `feet + r2-0x73A8`. The loop then samples every
/// `r2-0x743C` units with [`fn_80070ba0`]/[`fn_80070bf0`]:
///
/// * a `0x40` kind is a slope tile: the two table floats at
///   `0x802EF488 + kind*8` give the plane, and the fixed-point product is
///   snapped to a 16-unit row;
/// * `0x4899` kinds are probed with [`fn_80070a40`], whose `0`/`2` answers the
///   code turns into `row + 8` / `row + 0x10`;
/// * anything else just steps down.
///
/// # Original
/// - Ghidra: `FUN_800728c0` at `0x800728C0` (768 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800728c0_FUN_800728c0.c`
/// - observed: `FUN_802dcd70()` (the `__savegprlr_26` prologue) returns the
///   entry `r3:r4`, so `iVar7` is the actor and `pfVar13` its position pair;
///   `FUN_80072790(iVar7,&local_c0)`, the `0x40` / `0x4899` ladder, the
///   `uVar8 = (uint)-dVar15` row conversions and `FUN_802dcdbc(uVar12)`.
/// - observed: the six `ldexpf` prologue blocks only write dead locals, so
///   `f26..f31` carry no data into the body.
/// - Removed: the modelled `_restgpr_26` epilogue call (`0x802DCDBC`).
///   it only restores registers.
///
/// # Arguments
/// - `owner`: actor record; `+0xEC` is its collision area byte.
/// - `position`: two-float position (`x`, `y`); only `y` is walked.
/// - `out_floor`: optional `f32` receiver for the found floor height.
///
/// # Returns
/// `1` when a floor was found, `0` otherwise.
///
/// # Side effects
/// Writes `out_floor` when non-null.
///
/// # Safety
/// `owner`, `position` and `out_floor` (when non-null) must be valid; the BG
/// grid and the `0x802EF488` table must be mapped.
///
/// # Confidence
/// medium - every branch, table index and store is literal; the masked
/// `& 0xFFFF`/`& 0xFFF0` folds are the low-word truncations the export prints
/// as `CONCAT44(0x43300000, word) & mask ^ 0x80000000`.
pub unsafe fn fn_800728c0(owner: usize, position: usize, out_floor: usize) -> u32 {
    let area = read_u8(owner + 0xec) as u32;
    let pos_x = read_f32(position);
    let pos_y = read_f32(position + 4);
    let pad = read_f32(W96_F_CEILING_PAD);
    let mut probe = [pos_x, pos_y, 0.0f32, pos_x, pos_y + pad, 0.0f32];
    let mut floor = pos_y + pad;
    if fn_80072790(owner, probe.as_mut_ptr() as usize) != 0 {
        floor = probe[4];
    }
    let step = read_f32(W96_F_STEP_TIER);
    let scale = read_f32(W91_F_FIXED_ONE);
    let mut y = pos_y;
    let mut result = 0u32;
    loop {
        if floor < y {
            break;
        }
        let type_word = fn_80070ba0(pos_x as f64, y as f64, area);
        let info = fn_80070bf0(pos_x as f64, y as f64, area);
        let row = (-(y as i32)) as u32;
        if type_word & 0x40 != 0 {
            let index = (info & 0xff) as usize * 8;
            let slope = read_f32(W107_TBL_SLOPE_B + index);
            let cross = read_f32(W107_TBL_SLOPE_B + index + 4);
            let fixed_y = (scale * y) as i32;
            let fixed_slope = (scale * slope) as i32;
            let blend = fixed_slope as f32 + (fixed_y as u32 & 0xffff) as f32 * cross;
            floor = -((row & 0xfff0) as f32 + (blend as i32) as f32 / scale);
            result = 1;
            break;
        }
        if type_word & 0x4899 != 0 {
            let kind = fn_80070a40(pos_x as f64, y as f64, area);
            if kind == 0 {
                floor = (((-(y as i32)) & 0xfff8) + 8) as f32;
                result = 1;
            } else if kind == 2 {
                floor = (((row & 0xfff0) as i32) + 0x10) as f32;
                result = 1;
            }
            if result != 0 {
                break;
            }
        }
        y += step;
    }
    if result != 0 {
        if floor < pos_y {
            floor = pos_y;
        }
        if out_floor != 0 {
            write_f32(out_floor, floor);
        }
    }
    result
}

// ---------------------------------------------------------------------------
// 0x80073FC0
// ---------------------------------------------------------------------------

/// Scans the scroll-layer list around one actor and applies the contact bits.
///
/// The body first asks `0x80072F10` for the actor's decoded position triplet,
/// rebases it on the actor's `+0x14` position, and then walks the
/// `r13-0x58A0` list. Each entry that `0x80080E40` accepts and that
/// [`fn_80073bc0`] reports a contact for gets a midpoint probe block
/// `(x_centre + angle, y_centre, 0)` and the `+0xD0` attribute ladder:
/// the `0x200`/`0x80`/`0x100`/`0x400` flags set the `0x20000000`,
/// `0x80000000`, `0x40000000` and `0x100` answer bits and raise the entry's
/// `+0xD8` marker. A kind of `0`..`2` then runs the two virtual hooks.
///
/// # Original
/// - Ghidra: `FUN_80073fc0` at `0x80073FC0` (1040 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80073fc0_FUN_80073fc0.c`
/// - observed: `FUN_802dcd68()` (the `__savegprlr_24` prologue) keeps the
///   entry `r3`/`r4`, so `iVar6` is the actor and `uVar12` its second word;
///   `extraout_f1` is the caller's angle; `FUN_80072f10`, the
///   `FUN_80080e40`/`FUN_80073bc0` pair, the `+0xc4` mode store and the
///   `clz`-based `kind - 2 < 3` test are all literal.
/// - observed: `local_94` is never assigned directly; it is the second float
///   of the `auStack_98` block that `FUN_80073bc0` fills.
/// - Removed: the two modelled `_restgpr_24` epilogue calls (`0x802DCDB4`).
///   it only restores registers.
///
/// # Arguments
/// - `angle`: bearing offset added to the entry's x midpoint (`f1`).
/// - `owner`: actor record (`+0x14` position, `+0xEC` area byte).
/// - `token`: second word forwarded to `0x80080E40` and stored into `+0x5C`.
///
/// # Returns
/// The accumulated answer bits (`0x20000000`, `0x40000000`, `0x80000000`,
/// `0x100`, `0x40`) or `0` when nothing matched.
///
/// # Side effects
/// May write the entry's `+0xC4`, `+0xD8`, the actor's `+0x34A`, the
/// `+0x5C` entry pointer, the actor position `y` (`+0x14`) and the
/// `[entry+0x44]` virtual hook.
///
/// # Safety
/// The actor, both position vectors, the scroll list and the two virtual
/// hooks must be valid; the BG grid must be mapped.
///
/// # Confidence
/// medium - every compare, store and call site is literal; the `local_94`
/// reading is inferred from the `auStack_98` block layout, and the two
/// virtual offsets (`+0x60`/`+0x68`, `+0x44`) are read from the record.
pub unsafe fn fn_80073fc0(angle: f64, owner: u32, token: u32) -> u32 {
    let actor = owner as usize;
    let mut decoded = [0f32; 3];
    let mut result = 0u32;
    if fn_80072f10(actor, decoded.as_mut_ptr() as usize) == 0 {
        return 0;
    }
    let position = read_u32(actor + 0x14) as usize;
    let pos_x = read_f32(position);
    let pos_y = read_f32(position + 4);
    let mut point = [
        decoded[0] + pos_x,
        decoded[1] + pos_x,
        decoded[2] + pos_y,
    ];
    let mut normal = [0f32; 3];
    let half = read_f32(W103_F_73F4);
    let zero = read_f32(W91_F_ZERO);
    let mut top = pos_y;
    let mut entry = read_u32(W33_G_SCROLL_HEAD) as usize;
    while entry != 0 {
        if platform::call4(W101_ACTOR_FILTER, entry as u32, actor as u32, token, 2) != 0
            && fn_80073bc0(
                angle as f32,
                actor,
                entry,
                point.as_mut_ptr() as usize,
                normal.as_mut_ptr() as usize,
            ) != 0
        {
            let kind = read_i32(entry + 0xcc);
            let mut bits = 0x2000_0000u32;
            let mut contact = [0f32; 3];
            contact[0] = (read_f32(entry + 0x60) + read_f32(entry + 0x70)) * half + angle as f32;
            contact[1] = (read_f32(entry + 0x64) + read_f32(entry + 0x74)) * half;
            contact[2] = zero;
            if (kind as u32).wrapping_sub(5) < 3 {
                fn_80074ff0(actor as u32, entry, contact.as_mut_ptr() as u32, token);
            } else {
                write_u32(actor + 0xc4, 0);
                let flags = read_u32(entry + 0xd0);
                if flags & 0x100_0000 != 0 {
                    write_u32(actor + 0xc4, 2);
                }
                if flags & 0x200_0000 != 0 {
                    write_u32(actor + 0xc4, 1);
                }
                if token & 0x800_0000 == 0 || flags & 0x20 == 0 {
                    if token & 0x4000 == 0 || (flags & 0x40 == 0 && flags & 0x100 == 0) {
                        let body = read_u32(actor + 4);
                        if body != 0
                            && (read_f32(W91_F_ZERO) < read_f32(body as usize + 0xec)
                                || token & 0x400_0000 != 0)
                        {
                            if flags & 0x200 != 0 && token & 0x10_0000 != 0 {
                                bits = 0xa000_0000;
                                write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 0x20);
                            }
                            if flags & 0x80 != 0 {
                                if token & 0x80_0000 == 0 {
                                    if token & 0x40_0000 != 0 {
                                        bits |= 0x8000_0000;
                                        write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 0x20);
                                    }
                                } else {
                                    bits |= 0x4000_0000;
                                    write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 8);
                                }
                            }
                            if flags & 0x100 != 0 && token & 0xc0_0000 != 0 {
                                bits |= 0x4000_0000;
                                write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 8);
                            }
                            if flags & 0x400 != 0 && token & 0x200_0000 != 0 {
                                bits |= 0x100;
                                write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 8);
                            }
                        }
                        if platform::call2(W107_CALL_80081030, entry as u32, token) != 0 {
                            top = normal[1] - decoded[2];
                        }
                    } else {
                        bits = 0x4000_0000;
                        write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 2);
                    }
                } else {
                    bits = 0x4000_0000;
                    write_u32(entry + 0xd8, read_u32(entry + 0xd8) | 4);
                }
                if read_u32(actor + 4) != 0 {
                    write_u32(actor + 0x5c, entry as u32);
                }
                result |= bits;
            }
            let player = fn_800705b0(actor);
            if player != 0 {
                if kind <= 2
                    && platform::call2(W107_CALL_80080D40, entry as u32, player) != 0
                {
                    let vtable = read_u32(player as usize + 0x60) as usize;
                    let hook: extern "C" fn(u32, u32) -> u32 =
                        core::mem::transmute(read_u32(vtable + 0x68) as usize);
                    if hook(player, entry as u32) != 0 {
                        write_u8(player as usize + 0x34a, read_u8(player as usize + 0x34a) | 8);
                    }
                }
                let callback = read_u32(entry + 0x44);
                if callback != 0 {
                    let f: extern "C" fn(u32, u32) = core::mem::transmute(callback as usize);
                    f(read_u32(entry), player);
                }
            }
        }
        entry = read_u32(entry + 4) as usize;
    }
    if result != 0 {
        let limit = pos_y - read_f32(W96_F_STEP_TIER);
        if top <= limit {
            top = limit;
        }
        write_f32(position, pos_x);
        write_f32(position + 4, top);
    }
    result
}

// ---------------------------------------------------------------------------
// 0x80074470
// ---------------------------------------------------------------------------

/// Finds the height of one scroll-layer segment under a moving actor.
///
/// Three arms share the entry:
///
/// * `+0xC8 == 1`: a circle arm. The probe block is stepped from
///   `point_in[1]` to `point_in[2]` with `0x8006D120`; each accepted point is
///   resolved against the circle at `+0x58`/`+0x90`, and the height is
///   `radius_remainder + floor` (lane 1) or `floor - radius_remainder`.
/// * `+0xBC` first node word `== 0`: a plain box arm that tests the three
///   point coordinates against `+0x60..+0x74` and returns the near/far edge.
/// * otherwise: a segmented arm. The node word's top two bits select one of
///   the four entries of `0x802EF648`; the walk interpolates the segment at
///   the current row, takes the 16-bit bearing with `0x80237ED0` and keeps the
///   lowest (lane 0) or highest (lane 1) crossing.
///
/// # Original
/// - Ghidra: `FUN_80074470` at `0x80074470` (1656 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80074470_FUN_80074470.c`
/// - observed: `FUN_802dcd60()` (`__savegprlr_22`) keeps `r3`/`r4`, so
///   `iVar6` is the actor and `iVar10` the scroll-layer entry; `extraout_f1`
///   is the caller's angle; the `param_3` lane split, the four
///   `0x802EF648` offsets, the `0x638e` bearing window, the
///   `0x8015F480`/`0x8006D120` walks and `FUN_802dcdac(uVar8)` are literal.
/// - observed: the seven `ldexpf` prologue blocks only write dead locals.
/// - Removed: the two modelled `_restgpr_22` epilogue calls (`0x802DCDAC`).
///   it only restores registers.
///
/// # Arguments
/// - `angle`: bearing offset (`f1`) added to every x coordinate.
/// - `owner`: actor record (`+0x14` position, `+0x58` nearby segment,
///   `+0x88` flags, `+0xC8` bearing result).
/// - `entry`: scroll-layer entry (`+0x58`/`+0x5C` floor/ceiling, `+0x90`
///   radius, `+0xBC` node pointer, `+0xC8` mode).
/// - `lane`: `0` or `1`, selecting the near/far edge and the comparison.
/// - `point_in`: three-float query (`x`, `y`, `z`).
/// - `point_out`: three-float result (`x` along the segment, `y`, `z`).
///
/// # Returns
/// A flag word: bit 0/1/2 for "inside neither / the start / the end", bit 3
/// when the bearing was outside the tolerance window.
///
/// # Side effects
/// Writes `point_out`, the owner's `+0xC8` bearing, and (through
/// [`fn_80073ac0`]) the entry's `+0x3C`/`+0x40`.
///
/// # Safety
/// Both records and `point_out` must be writable; the BG grid, the
/// `0x802EF648` table and the two callees must be live.
///
/// # Confidence
/// medium - every branch, offset and table index is literal. One call,
/// `FUN_80101aa0()` in the segmented arm, arrives with no printed argument; the
/// interpolated coordinate is used, which the other three arms in this file
/// confirm.
pub unsafe fn fn_80074470(
    angle: f64,
    owner: usize,
    entry: usize,
    lane: u32,
    point_in: usize,
    point_out: usize,
) -> u32 {
    let node_word = read_u16(read_u32(entry + 0xbc) as usize) as u32;
    let mode = read_i32(entry + 0xc8);
    let step = read_f32(W107_F_7398);
    if mode == 1 || node_word != 0 {
        if read_u32(owner + 0x88) & 0x1_0000 == 0 {
            call_f64x2_ptr(
                W107_CALL_8015F480,
                read_f32(point_in + 8) as f64,
                step as f64,
                (point_in + 4) as u32,
            );
        } else {
            let nearby = read_u32(owner + 0x58) as usize;
            if nearby != 0 {
                if nearby == entry {
                    return 0;
                }
                let tag = read_u8(entry + 0xe0) as i8 as i32;
                if tag != -1 && tag == read_i32(nearby + 0xe0) {
                    call_f64x2_ptr(
                        W107_CALL_8015F480,
                        read_f32(point_in + 8) as f64,
                        step as f64,
                        (point_in + 4) as u32,
                    );
                }
            }
        }
    }
    let position = read_u32(owner + 0x14) as usize;
    let pos_y = read_f32(position + 4);
    let pos_z = read_f32(position + 8);
    let in_x = read_f32(point_in);
    let in_y = read_f32(point_in + 4);
    let in_z = read_f32(point_in + 8);
    let mut result = 0u32;
    if mode == 1 {
        let mut cursor = [in_x, in_y, 0.0f32];
        let mut radius = 0.0f64;
        loop {
            let sample = cursor[1];
            if call_f64_u32_u32(
                W101_POINT_TEST,
                angle,
                owner as u32,
                cursor.as_mut_ptr() as u32,
            ) != 0
            {
                let dy = read_f32(entry + 0x5c) - sample;
                let rad = read_f32(entry + 0x90);
                let d = rad * rad - dy * dy;
                if 0.0f64 < d as f64 {
                    radius = (d as f64 * call1_f64(W107_CALL_80237BA0, d as f64)) as f64;
                }
                let height = if lane == 1 {
                    radius + read_f32(entry + 0x58) as f64
                } else {
                    read_f32(entry + 0x58) as f64 - radius
                };
                let wrapped = call1_f64(W107_CALL_80101AA0, height) as f32;
                write_f32(point_out, wrapped);
                write_f32(point_out + 4, pos_y);
                write_f32(point_out + 8, pos_z);
                if sample == in_y {
                    result |= 4;
                }
                if sample == in_z {
                    result |= 2;
                }
                if sample != in_y && sample != in_z {
                    result |= 1;
                }
            }
            if w107_call_f64_ptr(
                W107_CALL_8006D120,
                in_z as f64,
                (&mut cursor[1] as *mut f32) as u32,
            ) != 0
            {
                break;
            }
        }
    } else if node_word == 0 {
        if angle as f32 + read_f32(entry + 0x60) <= in_x
            && in_x <= angle as f32 + read_f32(entry + 0x70)
        {
            if in_z <= read_f32(entry + 0x64) && read_f32(entry + 0x74) <= in_z {
                result = 2;
            }
            if in_y <= read_f32(entry + 0x64) && read_f32(entry + 0x74) <= in_y {
                result |= 4;
            }
            if read_f32(entry + 0x64) <= in_z && in_y <= read_f32(entry + 0x74) {
                result = 1;
            }
        }
        let edge = if lane == 1 {
            read_f32(entry + 0x70)
        } else {
            read_f32(entry + 0x60)
        };
        write_f32(point_out, call1_f64(W107_CALL_80101AA0, edge as f64) as f32);
        write_f32(point_out + 4, pos_y);
        write_f32(point_out + 8, pos_z);
        if result & 6 == 6 {
            result |= 8;
            fn_80073ac0(owner, entry, point_out);
        }
    } else {
        let span = w107_call_f64x3_u32(
            W103_SPAN_TEST,
            in_x as f64,
            in_x as f64,
            angle,
            entry as u32,
        );
        if span == 0 {
            result = 0;
        } else {
            let dir = node_word >> 0xe & 3;
            let mut cursor = [in_x, in_y, 0.0f32];
            loop {
                if call_f64_u32_u32(
                    W101_POINT_TEST,
                    angle,
                    owner as u32,
                    cursor.as_mut_ptr() as u32,
                ) != 0
                {
                    let (first_x, first_y, second_x, second_y);
                    if lane == 0 {
                        let node = entry + read_i32(W107_TBL_SEGMENT + dir as usize * 4) as usize * 8;
                        let a_x = read_f32(node + 0x60);
                        let a_y = read_f32(node + 0x64);
                        if cursor[1] <= a_y {
                            let other = entry
                                + read_i32(
                                    W107_TBL_SEGMENT
                                        + ((dir.wrapping_sub(1) & 3) as usize) * 4,
                                ) as usize
                                    * 8;
                            second_x = read_f32(other + 0x60);
                            second_y = read_f32(other + 0x64);
                            first_x = a_x;
                            first_y = a_y;
                        } else {
                            let other = entry
                                + read_i32(
                                    W107_TBL_SEGMENT
                                        + ((dir.wrapping_add(1) & 3) as usize) * 4,
                                ) as usize
                                    * 8;
                            first_x = read_f32(other + 0x60);
                            first_y = read_f32(other + 0x64);
                            second_x = a_x;
                            second_y = a_y;
                        }
                    } else {
                        let base = dir.wrapping_add(2) & 3;
                        let node = entry + read_i32(W107_TBL_SEGMENT + base as usize * 4) as usize * 8;
                        let a_x = read_f32(node + 0x60);
                        let a_y = read_f32(node + 0x64);
                        if cursor[1] <= a_y {
                            let other = entry
                                + read_i32(
                                    W107_TBL_SEGMENT
                                        + ((base.wrapping_add(1) & 3) as usize) * 4,
                                ) as usize
                                    * 8;
                            first_x = read_f32(other + 0x60);
                            first_y = read_f32(other + 0x64);
                            second_x = a_x;
                            second_y = a_y;
                        } else {
                            let other = entry
                                + read_i32(
                                    W107_TBL_SEGMENT
                                        + ((base.wrapping_sub(1) & 3) as usize) * 4,
                                ) as usize
                                    * 8;
                            second_x = read_f32(other + 0x60);
                            second_y = read_f32(other + 0x64);
                            first_x = a_x;
                            first_y = a_y;
                        }
                    }
                    let dx = first_x - second_x;
                    let dy = first_y - second_y;
                    if 0.0f32 != dy {
                        let bearing = call_f64_f64_u32(
                            W107_CALL_80237ED0,
                            dx as f64,
                            -dy as f64,
                            0,
                        ) as u16 as i16;
                        if 0x638e
                            < (bearing as i32 as u32).wrapping_sub(0xe39) & 0xffff
                        {
                            let crossing = dx * (cursor[1] - second_y).abs() / dy.abs()
                                + second_x;
                            if result == 0
                                || (lane == 0 && crossing < read_f32(point_out))
                                || (lane == 1 && read_f32(point_out) < crossing)
                            {
                                write_u16(owner + 0xc8, bearing as u16);
                                write_f32(
                                    point_out,
                                    call1_f64(W107_CALL_80101AA0, crossing as f64) as f32,
                                );
                                write_f32(point_out + 4, pos_y);
                                write_f32(point_out + 8, pos_z);
                            }
                            if cursor[1] == in_y {
                                result |= 4;
                            }
                            if cursor[1] == in_z {
                                result |= 2;
                            }
                            if cursor[1] != in_y && cursor[1] != in_z {
                                result |= 1;
                            }
                            let magnitude = (bearing as i32) as f32;
                            if magnitude.abs() <= read_f32(W107_F_7390)
                                || read_f32(W107_F_7388) < magnitude.abs()
                            {
                                result |= 8;
                                fn_80073ac0(owner, entry, point_out);
                            }
                        }
                    }
                }
                if w107_call_f64_ptr(
                    W107_CALL_8006D120,
                    in_z as f64,
                    (&mut cursor[1] as *mut f32) as u32,
                ) != 0
                {
                    break;
                }
            }
        }
    }
    result
}

// ---------------------------------------------------------------------------
// 0x80074AF0
// ---------------------------------------------------------------------------

/// Lane-aware twin of [`fn_80073fc0`], reading the segment solver instead.
///
/// The entry's decoded triplet comes from `0x80073070`; the body rebases it on
/// the actor's `+0x14` position and asks [`fn_80074470`] per scroll-layer
/// entry. A hit runs the `+0xD0` attribute ladder with the lane-scaled answer
/// bits (`4`, `0x40`, `0x10`, `0x200`, `0x100`, `1 << lane`), stores the entry
/// into `+0x60` and `+0x64 + lane*4`, and finally runs the per-player hooks.
/// When anything matched, the actor x is pulled back inside
/// `±1.0f` of its wrapped position.
///
/// # Original
/// - Ghidra: `FUN_80074af0` at `0x80074AF0` (1280 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80074af0_FUN_80074af0.c`
/// - observed: `FUN_802dcd58()` (`__savegprlr_20`) keeps `r3`/`r4`;
///   `extraout_f1` is the angle; `FUN_80073070`, `FUN_80074470`,
///   `FUN_80074ff0`, the `0x80080e40`/`0x80081030`/`0x80080d80` filters, the
///   `r13-0x7d38` byte table and `FUN_802dcda4(uVar7)` are literal.
/// - observed: the five `ldexpf` prologue blocks only write dead locals.
/// - Removed: the two modelled `_restgpr_20` epilogue calls (`0x802DCDA4`).
///   it only restores registers.
///
/// # Arguments
/// - `angle`: bearing offset (`f1`) added to every x coordinate.
/// - `owner`: actor record (`+0x04` player, `+0x14` position, `+0x60`/`+0x64`
///   last entries).
/// - `token`: the caller's second word, tested by the `+0xD0` attribute ladder.
/// - `lane`: `0`..`3`, selecting the answer bit, the entry slot and the
///   `r13-0x7D38` byte.
///
/// # Returns
/// The accumulated answer bits, or `0` when no entry matched.
///
/// # Side effects
/// Writes the entry's `+0xD8`, the actor's `+0x60`/`+0x64+n*4` and `+0x34A`
/// of the player, the actor x at `+0x14`, and runs the two virtual hooks.
///
/// # Safety
/// The actor, the scroll list and the player objects must be live; the BG grid
/// and the two tables must be mapped.
///
/// # Confidence
/// medium - every branch and store is literal. The `FUN_8005f900()` call
/// arrives with no printed argument; the player index is rebuilt the way
/// [`fn_800705b0`] already documents it.
pub unsafe fn fn_80074af0(angle: f64, owner: u32, token: u32, lane: u32) -> u32 {
    let actor = owner as usize;
    let mut decoded = [0f32; 3];
    let mut result = 0u32;
    if fn_80073070(actor, decoded.as_mut_ptr() as usize, 0) == 0 {
        return 0;
    }
    let position = read_u32(actor + 0x14) as usize;
    let pos_x = read_f32(position);
    let pos_y = read_f32(position + 4);
    let half = read_f32(W103_F_73F4);
    let zero = read_f32(W91_F_ZERO);
    let push = read_f32(W107_F_73F0);
    let one = read_f32(W91_F_ONE);
    let mut x = pos_x;
    let mut item = read_u32(W33_G_SCROLL_HEAD) as usize;
    while item != 0 {
        if platform::call4(W101_ACTOR_FILTER, item as u32, actor as u32, token, lane & 0xff) != 0 {
            let mut point = [
                decoded[0] + pos_x,
                decoded[1] + pos_y,
                decoded[2] + pos_y,
            ];
            let mut out = [0f32; 3];
            let hit = fn_80074470(
                angle,
                actor,
                item,
                lane,
                point.as_mut_ptr() as usize,
                (&mut out[0] as *mut f32) as usize,
            );
            if hit != 0 {
                let mut answer = 0u32;
                let mut centre = [
                    (read_f32(item + 0x60) + read_f32(item + 0x70)) * half + angle as f32,
                    (read_f32(item + 0x64) + read_f32(item + 0x74)) * half,
                    zero,
                ];
                if (read_i32(item + 0xcc) as u32).wrapping_sub(5) < 3 {
                    fn_80074ff0(actor as u32, item, centre.as_mut_ptr() as u32, token);
                } else {
                    let mut bits = (4u32 << lane) | (0x40u32 << lane);
                    if hit & 8 != 0 {
                        bits |= 0x10u32 << lane;
                    }
                    let flags = read_u32(item + 0xd0);
                    if token & 0x800_0000 == 0 || flags & 0x20 == 0 {
                        if token & 0x4000 == 0 || flags & 0x40 == 0 {
                            if flags & 0x200 != 0 && token & 0x10_0000 != 0 {
                                bits |= 0x200;
                                write_u32(item + 0xd8, read_u32(item + 0xd8) | 0x20);
                            }
                            if flags & 0x100 != 0 && token & 0xc0_0000 != 0 {
                                bits |= 0x100;
                                write_u32(item + 0xd8, read_u32(item + 0xd8) | 8);
                            }
                            if flags & 0x80 != 0 {
                                if token & 0x80_0000 == 0 {
                                    if token & 0x40_0000 != 0 {
                                        bits |= 0x200;
                                        write_u32(item + 0xd8, read_u32(item + 0xd8) | 0x20);
                                    }
                                } else {
                                    bits |= 0x100;
                                    write_u32(item + 0xd8, read_u32(item + 0xd8) | 8);
                                }
                            }
                            if flags & 0x400 != 0 && token & 0x200_0000 != 0 {
                                bits |= 0x100;
                                write_u32(item + 0xd8, read_u32(item + 0xd8) | 8);
                            }
                            bits |= 1u32 << lane;
                            if token & 0x1000_0000 != 0 && bits & 0x100 != 0 {
                                bits &= !(1u32 << lane);
                            }
                            if platform::call2(W107_CALL_80081030, item as u32, token) != 0 {
                                if lane == 0 {
                                    let delta = point[0] - (push + out[0]);
                                    if 0.0f32 <= delta {
                                        x -= delta;
                                    }
                                } else {
                                    let delta = point[0] - (out[0] - one);
                                    if delta <= 0.0f32 {
                                        x -= delta;
                                    }
                                }
                            }
                            answer = bits;
                            if read_u8(actor + 0x99) != 0xff {
                                answer = bits | 0x1000;
                                if hit == 2 {
                                    answer = bits | 0x800;
                                }
                            }
                        } else {
                            write_u32(item + 0xd8, read_u32(item + 0xd8) | 2);
                            answer = 0x100;
                        }
                    } else {
                        write_u32(item + 0xd8, read_u32(item + 0xd8) | 4);
                        answer = 0x100;
                    }
                    if read_u32(actor + 4) != 0 {
                        write_u32(actor + 0x60, item as u32);
                        write_u32(actor + 0x64 + lane as usize * 4, item as u32);
                    }
                }
                result |= answer;
                let mut player = read_u32(actor + 4);
                if read_u8(actor + 0x99) != 0xff && hit == 2 {
                    let index = platform::call_u64(0x8007_0530) as u32 as u8;
                    player = platform::call1(
                        W83_CALL_8005F900,
                        index as i8 as i32 as u32,
                    );
                }
                if player != 0 {
                    let kind = read_i32(item + 0xcc);
                    if kind <= 2
                        && platform::call3(
                            W107_CALL_80080D80,
                            item as u32,
                            player,
                            lane & 0xff,
                        ) != 0
                    {
                        let vtable = read_u32(player as usize + 0x60) as usize;
                        let hook: extern "C" fn(u32, u32) -> u32 =
                            core::mem::transmute(read_u32(vtable + 0x68) as usize);
                        if hook(player, item as u32) != 0 {
                            write_u8(
                                player as usize + 0x34a,
                                read_u8(player as usize + 0x34a)
                                    | read_u8(SDA_BASE - 0x7d38 + (lane as usize & 1) * 4),
                            );
                        }
                    }
                    let callback = read_u32(item + 0x48);
                    if callback != 0 {
                        let f: extern "C" fn(u32, u32, u32) = core::mem::transmute(callback as usize);
                        f(read_u32(item), player, lane & 0xff);
                    }
                }
            }
        }
        item = read_u32(item + 4) as usize;
    }
    if result != 0 {
        let wrapped = call1_f64(W107_CALL_80101AA0, read_f32(position) as f64) as f32;
        if wrapped + one <= x {
            x = wrapped + one;
        }
        if x <= wrapped - one {
            x = wrapped - one;
        }
        write_f32(position, x);
        write_f32(position + 4, pos_y);
    }
    result
}

// ---------------------------------------------------------------------------
// 0x80075CA0
// ---------------------------------------------------------------------------

/// Drops a straight vertical probe from an actor onto the first floor.
///
/// The start is `y + r2-0x73A8`, clamped to `0.0f`; `0x800766F0` may replace it
/// with a segment hit. The loop then walks down by `r2-0x743C`, sampling
/// [`fn_80070ba0`]/[`fn_80070bf0`] until the current row is below the last
/// floor. `0x40` kinds are slope tiles (normal pair at `0x802EF488`) and
/// `0x4899` kinds are snapped with `0x80070A40`.
///
/// # Original
/// - Ghidra: `FUN_80075ca0` at `0x80075CA0` (812 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80075ca0_FUN_80075ca0.c`
/// - observed: `FUN_802dcd70()` (`__savegprlr_26`) keeps `r3`/`r4`, so
///   `pfVar8` is the position and `uVar19` the out pointer; the
///   `0x73A8` lift, the `0.0f` clamp, the `0x40` slope arm and the
///   `0x4899` snap arm are literal.
/// - observed: the six `ldexpf` prologue blocks only write dead locals.
/// - Removed: the modelled `_restgpr_26` epilogue call (`0x802DCDBC`).
///   it only restores registers.
///
/// # Arguments
/// - `position`: two-float position (`x`, `y`).
/// - `out_floor`: optional `f32` receiver for the found floor.
/// - `layer`: collision layer/area byte forwarded to the three probes.
/// - `mask`: entry mask forwarded to `0x800766F0`.
///
/// # Returns
/// `1` when a floor was found, `0` otherwise.
///
/// # Side effects
/// Writes `out_floor` when non-null.
///
/// # Safety
/// `position` and `out_floor` (when non-null) must be valid; the BG grid and
/// the `0x802EF488` table must be mapped.
///
/// # Confidence
/// medium - every branch and store is literal; the masked folds are the
/// low-word truncations of the `CONCAT44(0x43300000, word)` idiom.
pub unsafe fn fn_80075ca0(
    position: usize,
    out_floor: usize,
    layer: u32,
    mask: u32,
) -> u32 {
    let pos_x = read_f32(position);
    let pos_y = read_f32(position + 4);
    let pad = read_f32(W96_F_CEILING_PAD);
    let mut start = pos_y + pad;
    if read_f32(W91_F_ZERO) <= start {
        start = read_f32(W91_F_ZERO);
    }
    let mut probe = [pos_x, pos_y, 0.0f32, pos_x, start, 0.0f32];
    let mut floor = start;
    if fn_800766f0(probe.as_mut_ptr() as usize, 0, mask, layer) != 0 {
        floor = probe[4];
    }
    let step = read_f32(W96_F_STEP_TIER);
    let scale = read_f32(W91_F_FIXED_ONE);
    let mut y = pos_y;
    let mut result = 0u32;
    loop {
        if floor < y {
            break;
        }
        let type_word = fn_80070ba0(pos_x as f64, y as f64, layer);
        let info = fn_80070bf0(pos_x as f64, y as f64, layer);
        let row = (-(y as i32)) as u32;
        if type_word & 0x40 != 0 {
            let index = (info & 0xff) as usize * 8;
            let slope = read_f32(W107_TBL_SLOPE_B + index);
            let cross = read_f32(W107_TBL_SLOPE_B + index + 4);
            let fixed_y = (scale * y) as i32;
            let fixed_slope = (scale * slope) as i32;
            let blend = fixed_slope as f32 + (fixed_y as u32 & 0xffff) as f32 * cross;
            floor = -((row & 0xfff0) as f32 + (blend as i32) as f32 / scale);
            result = 1;
            break;
        }
        if type_word & 0x4899 != 0 {
            let kind = fn_80070a40(pos_x as f64, y as f64, layer);
            if kind == 0 {
                floor = (((-(y as i32)) & 0xfff8) + 8) as f32;
                result = 1;
            } else if kind == 2 {
                floor = (((row & 0xfff0) as i32) + 0x10) as f32;
                result = 1;
            }
            if result != 0 {
                break;
            }
        }
        y -= step;
    }
    if result != 0 {
        if floor < pos_y {
            floor = pos_y;
        }
        if out_floor != 0 {
            write_f32(out_floor, floor);
        }
    }
    result
}

// ---------------------------------------------------------------------------
// 0x8007FFA0
// ---------------------------------------------------------------------------

/// Advances an actor by one ground-relative step along its facing.
///
/// The input delta (`+0`/`+4`) is scaled by `+0xD8` in mode `0` and stored at
/// `+0xDC`; when the owner's `+0xC2` angle is non-zero the delta is rotated by
/// `base + atan2(vector.y, vector.x)` where the vector is `+0x34` (modes other
/// than `2`) or `+0x3C`. The rotated delta is added to the actor's `+0x14`
/// position, with the x coordinate wrapped by `0x80101AA0`, and in mode `0`
/// also to the body's `+0x310`/`+0x314` camera-relative pair.
///
/// # Original
/// - Ghidra: `FUN_8007ffa0` at `0x8007FFA0` (460 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8007ffa0_FUN_8007ffa0.c`
/// - observed: `FUN_802dcd74()` (`__savegprlr_27`) keeps `r3`/`r4`, so
///   `iVar5` is the owner and `iVar7` the actor; `param_3` is the two-float
///   delta and `param_4` the mode; the `+0xD0 & 2` guard, the `+0x34`/`+0x3C`
///   vector choice, `FUN_802be470`, `FUN_80237ed0`, the two
///   `FUN_80237c40`/`FUN_80237bd0` calls and the `+0x310`/`+0x314` adds are
///   literal.
/// - observed: `FUN_802dcdc0()` is the epilogue.
/// - Removed: the modelled `_restgpr_27` epilogue call (`0x802DCDC0`).
///   it only restores registers.
///
/// # Arguments
/// - `owner`: owner record; `+0xC2` is the base bearing, `+0xD0` the flag word.
/// - `actor`: actor record (`+0x04` body, `+0x14` position, `+0x34`/`+0x3C`
///   facing vectors, `+0xD8` scale, `+0xDC` last delta).
/// - `delta`: two-float input delta.
/// - `mode`: `0` (scaled), `1` (raw) or `2` (uses the `+0x3C` vector).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the actor position, `+0xDC`, and in mode `0` the body's `+0x310` and
/// `+0x314`.
///
/// # Safety
/// Both records, `delta` and the body (when mode is `0`) must be valid; the
/// `r2-0x71F0` scale must be mapped.
///
/// # Confidence
/// low - the branches, stores and callee sequence are literal, but the signed
/// `s16` bearing reaches `0x80237C40`/`0x80237BD0` through a `GQR3`
/// quantisation whose scale is not printed; the zero (1.0) scale used by every
/// other site in this file is assumed.
pub unsafe fn fn_8007ffa0(owner: usize, actor: usize, delta: usize, mode: i32) {
    let zero = read_f32(W107_F_SEED);
    let position = read_u32(actor + 0x14) as usize;
    let mut dx = zero;
    let mut dz;
    if read_u32(owner + 0xd0) & 2 == 0 {
        dx = read_f32(delta);
        if mode == 0 {
            dx *= read_f32(actor + 0xd8);
        }
        dx += zero;
        write_f32(actor + 0xdc, read_f32(delta));
    }
    dz = zero + read_f32(delta + 4);
    if read_u16(owner + 0xc2) != 0 {
        let vector = if mode == 2 {
            actor + 0x3c
        } else {
            actor + 0x34
        };
        let vx = read_f32(vector);
        let vy = read_f32(vector + 4);
        let length = call1_f64(W107_CALL_802BE470, (vx * vx + vy * vy) as f64) as f32;
        let bearing = call_f64_f64_u32(W107_CALL_80237ED0, vy as f64, vx as f64, 0) as u16 as i16;
        let angle = (read_u16(owner + 0xc2) as i16).wrapping_add(bearing);
        let radians =
            (read_f32(W107_F_RADIANS_PER_UNIT) as f64 * angle as i32 as f64) as f32;
        let cosine = call1_f64(W107_CALL_80237C40, radians as f64) as f32;
        dx += length * cosine - vx;
        let sine = call1_f64(W107_CALL_80237BD0, radians as f64) as f32;
        dz += length * sine - vy;
    }
    if mode == 2 && zero == dx {
        dz = zero;
    }
    let wrapped = call1_f64(W107_CALL_80101AA0, (read_f32(position) + dx) as f64) as f32;
    write_f32(position, wrapped);
    write_f32(position + 4, read_f32(position + 4) + dz);
    if mode == 0 {
        let body = read_u32(actor + 4);
        if body != 0 {
            write_f32(body as usize + 0x310, read_f32(body as usize + 0x310) + dx);
            write_f32(body as usize + 0x314, read_f32(body as usize + 0x314) + dz);
        }
    }
}

