///   `shape = record+0x34` ladder over `0x80087340`/`0x80087360`/`400.0f`, the
///   `0x801C0BD0`/`0x801C0540`/`0x801C9940`/`0x801C99C0` sequence, the
///   `0x909C8` mode switch and the `0x8010AA40`/`0x8010A6C0`/`0x8010AA90`
///   triple around every emitted cell.
/// - Removed: the modelled `_restgpr_17` epilogue call (`0x802DCD98`).
///   it only restores registers.
///
/// # Arguments
/// - `x`, `z`: world position of the layer origin.
/// - `desc`: the scene record; `+0x30` is the row length and `+0x34` the shape.
/// - `mode`: `0` selects the "thin" filter, anything else the layered filter.
/// - `block`: the 12-word colour/vertex block [`fn_80082740`] built.
/// - `columns`, `rows`: the clamped tile window size.
/// - `tiles`: base of the tile-id table.
/// - `offset_x`, `offset_y`: the first tile coordinate.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Emits GX draw calls and reads the camera/render globals.
///
/// # Safety
/// `desc`, `tiles` and `block` must be valid; `tiles` must cover the addressed
/// cells; the camera and render globals must be live.
///
/// # Confidence
/// medium - the transform chain, the four table offsets and the filter are
/// literal; the 22-float `GQR0` dequantisation prologue only saves `f21..f31`
/// and its locals are never read, so it is not reproduced.
pub unsafe fn fn_80082be0(
    x: f64,
    z: f64,
    desc: usize,
    mode: u32,
    _a5: u32,
    block: u32,
    columns: u32,
    rows: u32,
    tiles: u32,
    offset_x: u32,
    offset_y: u32,
) {
    let mut e8 = [0u32; 12];
    let mut b8 = [0u32; 12];
    let e8_ptr = e8.as_mut_ptr() as u32;
    let b8_ptr = b8.as_mut_ptr() as u32;
    let shape = read_u16(desc + 0x34);
    let mut radius = x;
    if shape == 0 {
        radius = call0_f32(W108_CALL_80087340) as f64;
    } else if shape == 1 {
        radius = call0_f32(W108_CALL_80087360) as f64;
    } else if shape == 2 {
        radius = read_f32(W108_F_400) as f64;
    }
    w108_call_3f64_ptr(W108_CALL_801C0BD0, -x, z, radius, e8_ptr);
    platform::call3(W108_CALL_801C0540, block, e8_ptr, b8_ptr);
    platform::call2(W108_CALL_801C9940, b8_ptr, 0x1b);
    platform::call2(W108_CALL_801C99C0, b8_ptr, 0x1b);
    let camera = read_u32(G_CAMERA_OWNER) as usize;
    let render = read_u32(W108_G_RENDER) as usize;
    let left = call1_f32(W108_CALL_800789A0, camera as u32) as f64;
    let right = call1_f32(W108_CALL_80078B40, camera as u32) as f64;
    let stripe = read_u8(render + 0x54);
    // observed: `(uint)(right - left)` then `/ 16` rounding toward zero.
    let stripes = ((right - left) as f32) as i32 / 16;
    let cell_width = read_u16(desc + 0x30) as u32;
    let mut row = 0u32;
    let mut y = offset_y;
    loop {
        if rows <= row {
            return;
        }
        let mut cursor = offset_x;
        let mut column = 0u32;
        while column < columns {
            let layer_mode = read_u16(camera + 0x909c8);
            let raw;
            if layer_mode == 0 {
                let sum = cell_width.wrapping_add(cursor);
                let index = (sum.wrapping_sub((sum / cell_width) * cell_width))
                    .wrapping_mul(2)
                    .wrapping_add(tiles)
                    .wrapping_add(cell_width.wrapping_mul(y).wrapping_mul(2));
                raw = read_u16(index as usize) as u32;
            } else if layer_mode == 1 {
                let divisor = stripes as u32;
                let sum = divisor.wrapping_add(cursor);
                let index = (sum.wrapping_sub((sum / divisor) * divisor))
                    .wrapping_mul(2)
                    .wrapping_add(tiles)
                    .wrapping_add(cell_width.wrapping_mul(y).wrapping_mul(2))
                    .wrapping_add(0x4e);
                raw = read_u16(index as usize) as u32;
            } else if layer_mode == 2 {
                let divisor = stripes as u32;
                let sum = divisor.wrapping_add(cursor);
                let index = (sum.wrapping_sub((sum / divisor) * divisor))
                    .wrapping_mul(2)
                    .wrapping_add(tiles)
                    .wrapping_add(cell_width.wrapping_mul(y).wrapping_mul(2))
                    .wrapping_add(0x10e);
                raw = read_u16(index as usize) as u32;
            } else if layer_mode == 3 {
                let divisor = stripes as u32;
                let sum = divisor.wrapping_add(cursor);
                let index = (sum.wrapping_sub((sum / divisor) * divisor))
                    .wrapping_mul(2)
                    .wrapping_add(tiles)
                    .wrapping_add(cell_width.wrapping_mul(y).wrapping_mul(2))
                    .wrapping_add(0x1ca);
                raw = read_u16(index as usize) as u32;
            } else {
                raw = 0;
            }
            let tile = raw & 0x3ff;
            if tile != 0 {
                let draw = if mode == 0 {
                    (tile.wrapping_add(0xfd40) & 0xffff) < 0x40
                } else {
                    stripe == 0 || tile < 0x2c0 || 0x2ff < tile
                };
                if draw {
                    let value = if tile < 0x100 {
                        platform::call2(W108_CALL_800822E0, raw, 1)
                    } else {
                        tile
                    };
                    platform::call1(W108_CALL_8010AA40, 1);
                    platform::call3(W108_CALL_8010A6C0, value & 0xffff, column, row);
                    platform::call0(W108_CALL_8010AA90);
                }
            }
            cursor = cursor.wrapping_add(1);
            column += 1;
        }
        y = y.wrapping_add(1);
        row += 1;
    }
}

