            let mut place = [0u32; 4];
            let place_ptr = place.as_mut_ptr() as usize;
            write_f32(place_ptr, (x as i32) as f32);
            write_f32(place_ptr + 0x04, (y_raw as i32) as f32);
            write_u8(place_ptr + 0x08, depth as u8);
            write_u8(place_ptr + 0x09, 0);
