// 0x8008A090
// ---------------------------------------------------------------------------

/// Builds the stage-object draw record and projects it into `dest`.
///
/// Three stack objects are involved:
///
/// * `record` (0x88 bytes) - the model record `0x802BF930` constructs; its
///   `+0x64..+0x84` tail is filled from two `0x800890E0` queries and then
///   composed with the other two objects.
/// * `matrix` (0x40 bytes) - the projection `0x802BFE90`/`0x802BE880` build on
///   top of the `0x80164B20(2)` handle at `+0`, with the `+0x10` half used by
///   the final `0x801C0540` compose.
/// * `scratch` (0x70 bytes) - the camera/scene block `0x802BFDA0` and
///   `0x802BFE10` fill from the caller's target.
///
/// # Original
/// - Ghidra: `FUN_8008a090` at `0x8008A090` (412 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8008a090_FUN_8008a090.c`
/// - observed: the `0x802BF930`/`0x802BEA00`/`0x802BFDA0`/`0x802BFE10`/
///   `0x802BFE90`/`0x802BE880` chain, the seven `FUN_800890e0()` field reads,
///   the `0x80253D00`/`0x802541F0`/`0x802540B0` projection and the closing
///   `0x801C0540(param_2, auStack_168, param_2)`.
///
/// # Arguments
/// - `target`: the object `0x802BFDA0` copies into the scratch block.
/// - `dest`: the destination draw record, written by the last three calls.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Fills three stack blocks and writes `dest`.
///
/// # Safety
/// `target` must be a live stage object, `dest` a writable draw record, and the
/// record behind `0x800890E0` readable through `+0x30`.
///
/// # Confidence
/// medium - every store offset and call is literal; the two arguments are `r3`
/// and `r5` (the export's `undefined8` first parameter skips the unused `r4`),
/// and the internal field roles of the three blocks are inferred from the
/// callees.
pub unsafe fn fn_8008a090(target: u32, dest: u32) {
    let mut record = [0u32; 0x22];
    let mut matrix = [0u32; 0x10];
    let mut scratch = [0u32; 0x1c];
    let b = record.as_mut_ptr() as usize;
    let a = matrix.as_mut_ptr() as usize;
    let c = scratch.as_mut_ptr() as usize;
    platform::call1(W108_CALL_802BF930, c as u32);
    write_u32(b + 0x64, read_u32(W108_F_ZERO_C));
    write_u32(b + 0x68, read_u32(W108_F_10));
    write_u32(b + 0x80, read_u32(W108_F_ONE_C));
    write_u32(b, W108_DAT_80350078 as u32);
    write_u32(b + 0x6c, read_u32(W108_F_ZERO_C));
    write_u32(b + 0x70, read_u32(W108_F_ZERO_C));
    write_u32(b + 0x74, read_u32(W108_F_ZERO_C));
    write_u32(b + 0x78, read_u32(W108_F_ZERO_C));
    write_u32(b + 0x7c, read_u32(W108_F_ZERO_C));
    write_u32(b + 0x84, read_u32(W108_F_ZERO_C));
    let first = call0_ret(W108_CALL_800890E0) as usize;
    write_u32(b + 0x64, read_u32(first));
    write_u32(b + 0x68, read_u32(first + 0x04));
    write_u32(b + 0x6c, read_u32(first + 0x08));
    let second = call0_ret(W108_CALL_800890E0) as usize;
    write_u32(b + 0x70, read_u32(second + 0x0c));
    write_u32(b + 0x74, read_u32(second + 0x10));
    write_u32(b + 0x78, read_u32(second + 0x14));
    write_u32(a + 0x04, read_u32(W108_F_ZERO_C));
    write_u32(a + 0x08, read_u32(W108_F_ONE_C));
    write_u32(a + 0x0c, read_u32(W108_F_ZERO_C));
    write_u32(b + 0x7c, read_u32(W108_F_ZERO_C));
    write_u32(b + 0x80, read_u32(W108_F_ONE_C));
    write_u32(b + 0x84, read_u32(W108_F_ZERO_C));
    platform::call1(W108_CALL_802BEA00, b as u32);
    platform::call2(W108_CALL_802BFDA0, target, c as u32);
    let scale_source = call0_ret(W108_CALL_800890E0) as usize;
    w108_call_f64_ptr_void(
        W108_CALL_802BFE10,
        read_f32(scale_source + 0x20) as f64,
        c as u32,
    );
    write_u32(a, platform::call1(W108_CALL_80164B20, 2));
    platform::call2(W108_CALL_802BFE90, c as u32, a as u32);
    platform::call2(W108_CALL_802BE880, b as u32, a as u32);
    let src_w = call0_ret(W108_CALL_800890E0) as usize;
    let w = read_f32(src_w + 0x30) as f64;
    let src_z = call0_ret(W108_CALL_800890E0) as usize;
    let z = read_f32(src_z + 0x2c) as f64;
    let src_y = call0_ret(W108_CALL_800890E0) as usize;
    let y = read_f32(src_y + 0x28) as f64;
    let src_x = call0_ret(W108_CALL_800890E0) as usize;
    let x = read_f32(src_x + 0x24) as f64;
    call4_f64_ptr(W108_CALL_80253D00, x, y, z, w, a as u32);
    platform::call2(W108_CALL_802541F0, a as u32, dest);
    platform::call2(W108_CALL_802540B0, a as u32, (a + 0x10) as u32);
    platform::call3(W108_CALL_801C0540, dest, (a + 0x10) as u32, dest);
}

