/// Reads a big-endian signed 16-bit word.
///
/// # Safety
/// `addr` must be a readable, 2-byte aligned address.
unsafe fn w109_read_s16(addr: usize) -> i16 {
    read_u16(addr) as i16
}

/// Calls a PowerPC function with four integer arguments and returns the whole
/// `r3:r4` pair as a `u64` (`r3` in the high word).
///
/// Used for `0x80077650`, whose caller `0x80077700` wants the second word.
///
/// # Safety
/// `addr` must use the PowerPC integer ABI and return the `r3:r4` pair.
unsafe fn w109_call4_u64(addr: usize, a: u32, b: u32, c: u32, d: u32) -> u64 {
    let f: extern "C" fn(u32, u32, u32, u32) -> u64 = core::mem::transmute(addr);
    f(a, b, c, d)
}

/// Calls a PowerPC function with four `f64` and eight integer arguments.
///
/// Used for `0x8007FA40`, the twelve-argument layer bootstrap.
///
/// # Safety
/// `addr` must use the PowerPC mixed ABI (doubles in `f1..f4`, words in
/// `r3..r10`).
unsafe fn w109_call_4f64_8u(
    addr: usize,
    a: f64,
    b: f64,
    c: f64,
    d: f64,
    e: u32,
    f: u32,
    g: u32,
    h: u32,
    i: u32,
    j: u32,
    k: u32,
    l: u32,) {
    let func: extern "C" fn(f64, f64, f64, f64, u32, u32, u32, u32, u32, u32, u32, u32) =
        core::mem::transmute(addr);
    func(a, b, c, d, e, f, g, h, i, j, k, l);
}

