/// Recomputes one scroll layer's screen rectangle and its depth offsets.
///
/// The body tracks the camera zoom (`+0x9000C`), converts the BG colours into
/// the layer's x/z spans (`+0x8FE78`/`+0x8FE7C`), and uses the two scene bounds
/// plus the camera-relative point to pick the x target (`+0x8FE88`). The z
/// target (`+0x8FE8C`) is chosen from the camera depth and the two trigger
/// snaps ([`fn_8007bba0`]/[`fn_8007bbf0`] are reached from the sibling body
/// `0x8007AC40`, not from here). Two row sorts and the rectangle clamp finish
/// the frame.
///
/// # Original
/// - Ghidra: `FUN_8007a6c0` at `0x8007A6C0` (1200 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8007a6c0_FUN_8007a6c0.c`
/// - observed: `uVar21 = FUN_802dcd70();` (the `r3`/`r4` save pair), the
///   `FUN_800791d0`/`FUN_80078eb0`/`FUN_80078a70`/`FUN_80078c10`/`FUN_800789a0`
///   bounds, the `+0x900C6`/`+0x900C4` flag pair, the two
///   `FUN_8005F900`-free depth branches through `FUN_8007e0e0`, the
///   `FUN_8007ca90` row sorts and the `FUN_8007cd70` clamp.
/// - observed: the `unaff_GQR0` prologue only writes dead locals.
/// - Removed: the modelled `_restgpr_26` epilogue call (`0x802DCDBC`).
///   it only restores registers.
///
/// # Arguments
/// - `scene`: the BG scene record (`+0x90000..+0x900C6`).
/// - `point`: two readable floats, the camera-relative point.
/// - `param_3`: non-zero selects the direct z store instead of the smoother.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the layer rectangle, the zoom and the two depth accumulators, then
/// sorts both row tables and clamps the destination rectangle.
///
/// # Safety
/// `scene` must be writable through `+0x90120`, `point` must hold two floats,
/// and the scene/camera globals must be live.
///
/// # Confidence
/// medium - every store, branch and call is literal; the comma-operator chains
/// are rewritten as nested `if`s, and the roles of `+0x8FE44`/`+0x8FE48` as the
/// camera x/z are inferred from the neighbouring draw bodies.
pub unsafe fn fn_8007a6c0(scene: usize, point: usize, param_3: u32) {
    let manager = read_u32(G_BG_SCENE) as usize;
    let colour_a = read_f32(G_BG_COL_A) as f64;
    let colour_b = read_f32(G_BG_COL_B) as f64;
    if read_u8(read_u32(G_CAMERA_OWNER) as usize + 0x909ca) == 0 {
        platform::call1(W109_CALL_800791D0, scene as u32);
        let zoom = read_f32(scene + 0x90010) as f64;
        if (read_f32(W91_F_ZERO_ALT) as f64) < zoom {
            let camera = read_u32(G_CAMERA_OWNER);
            let extent = read_f32(manager + 0x34) as f64;
            let scale = call1_f32(W109_CALL_80078EB0, camera) as f64;
            let one = read_f32(W91_F_ONE_ALT) as f64;
            let correction = ((one / zoom) - (one / scale)) * extent;
            let scale2 = call1_f32(W109_CALL_80078EB0, camera) as f64;
            write_f32(scene + 0x9000c, ((one / scale2) + correction) as f32);
        }
        let zoom = read_f32(scene + 0x9000c);
        let half = read_f32(W109_F_HALF) as f64;
        let inverse = read_f32(W91_F_ONE_ALT) as f64 / zoom as f64;
        write_f32(scene + 0x90088, zoom);
        write_f32(scene + 0x9009c, zoom);
        let span_x = (colour_a * inverse) as f32;
        let span_z = (colour_b * inverse) as f32;
        write_f32(scene + 0x8fe78, span_x);
        write_f32(scene + 0x8fe7c, span_z);
        let half_span_x = (half * span_x as f64) as f32 as f64;
        let widened = call1_f32(W109_CALL_80078A70, scene as u32) as f64;
        let right = call1_f32(W109_CALL_80078C10, scene as u32) as f64;
        let right_inner = (right - span_x as f64) as f32 as f64;
        let ceiling = read_f32(scene + 0x90038) as f64;
        let mut horizontal = true;
        let mut vertical = true;
        let bottom = (span_z as f64 + read_f32(scene + 0x9003c) as f64) as f32 as f64;
        let left = call1_f32(W109_CALL_800789A0, scene as u32) as f64;
        write_u32(scene + 0x8fea8, read_u32(manager + 0x38));
        let point_y = read_f32(point + 4) as f64;
        let point_x = read_f32(point) as f64;
        let camera_x = read_f32(scene + 0x8fe44) as f64;
        write_u32(scene + 0x8feac, read_u32(manager + 0x3c));
        let camera_z = read_f32(scene + 0x8fe48) as f64;
        write_f32(scene + 0x90060, point_y as f32);
        let probe_z = (point_y + half * span_z as f64) - camera_z;
        let probe_x = (point_x + camera_x) - half_span_x;
        let mut hit_x = probe_x;
        if read_u32(G_GAME_MODE) == 2 {
            let info = read_u32(G_STAGE_INFO) as usize;
            let special = read_u8(info + 0x120c) == 1
                && read_u8(info + 0x120d) == 0x17
                && read_u8(info + 0x120e) == 0;
            if special && read_u16(scene + 0x909c8) == 0 && widened <= probe_x {
                hit_x = probe_x;
                if right_inner < probe_x {
                    hit_x = right_inner;
                }
            }
        } else {
            hit_x = widened;
            if widened <= probe_x {
                hit_x = probe_x;
                if right_inner < probe_x {
                    hit_x = right_inner;
                }
            }
        }
        let mut hit_z = bottom;
        if bottom <= probe_z {
            hit_z = probe_z;
            if ceiling < probe_z {
                hit_z = ceiling;
            }
        }
        if read_u8(scene + 0x900c6) != 0 {
            let kind = read_u8(scene + 0x900c4);
            if kind == 0 {
                horizontal = false;
                vertical = false;
            } else if kind == 1 {
                horizontal = false;
                vertical = true;
            } else if kind == 2 {
                horizontal = true;
                vertical = false;
            }
        }
        if horizontal {
            write_f32(scene + 0x8fe88, hit_x as f32);
        }
        if vertical {
            let corrected = call1_f32(W109_CALL_8007E0E0, scene as u32) as f64;
            if (read_f32(W91_F_NO_LIMIT) as f64) < corrected {
                let far = read_f32(manager + 0x3c) as f64;
                let corrected2 = call1_f32(W109_CALL_8007E0E0, scene as u32) as f64;
                if far <= corrected2 {
                    let corrected3 = call1_f32(W109_CALL_8007E0E0, scene as u32) as f64;
                    if corrected3 < hit_z
                        && platform::call1(W109_CALL_80078540, scene as u32) == 0
                    {
                        hit_z = call1_f32(W109_CALL_8007E0E0, scene as u32) as f64;
                    }
                }
            }
            let limit = if param_3 != 0 {
                true
            } else {
                let corrected = call1_f32(W109_CALL_8007E0E0, scene as u32) as f64;
                corrected <= read_f32(W91_F_NO_LIMIT) as f64
            };
            if limit {
                write_f32(scene + 0x8fe8c, hit_z as f32);
            } else {
                call_f64x2_ptr(
                    W109_CALL_8015F480,
                    hit_z,
                    read_f32(W109_F_16) as f64,
                    (scene + 0x8fe8c) as u32,
                );
            }
        }
        let mode = read_u8(scene + 0x900fe);
        if mode == 1 || mode == 4 {
            write_f32(
                scene + 0x8fe88,
                ((left + half * read_f32(scene + 0x8fea0) as f64)
                    - half * span_x as f64) as f32,
            );
        }
        if mode == 6 {
            write_f32(
                scene + 0x8fe8c,
                read_f32(scene + 0x8fe70) + span_z,
            );
        }
        write_f32(scene + 0x8fe44, camera_x as f32);
        write_f32(scene + 0x8fe48, camera_z as f32);
        if read_u8(scene + 0x900c6) == 0 {
            write_u32(scene + 0x900ac, read_u32(scene + 0x8fe88));
            write_u32(scene + 0x900b0, read_u32(scene + 0x8fe8c));
        }
        if read_u8(scene + 0x90117) != 0 {
            write_f32(
                scene + 0x8fe88,
                read_f32(scene + 0x9011c) - half as f32 * span_x,
            );
            write_f32(
                scene + 0x8fe8c,
                read_f32(scene + 0x90120) + span_z,
            );
        }
    }
    fn_8007ca90(
        scene,
        scene + 0x909d8,
        read_u8(scene + 0x90079) as u32,
        1,
    );
    fn_8007ca90(
        scene,
        scene + 0x909d8,
        read_u8(scene + 0x9007a) as u32,
        1,
    );
    if read_u8(read_u32(G_CAMERA_OWNER) as usize + 0x909ca) == 0 {
        fn_8007cd70(scene, scene + 0x90a0c, scene + 0x909d8, 1);
    }
}

// ---------------------------------------------------------------------------
// 0x80075FD0
// ---------------------------------------------------------------------------

/// Sweeps a segment across the stage and returns the first blocking cell.
///
/// The query `0x800766F0` is run first on the six-float point pair. When it
/// hits, the pair is collapsed to the hit point and returned directly when both
/// endpoints already coincide. Otherwise the body walks from `start` toward
/// `end` in `1.0` steps, reclassifying each new `/8` cell through `0x80070A40`;
/// a class `2` result re-probes the `/16` cell with `0x80070BA0`/`0x80070BF0`
/// and, for the `0x60` slope bits, intersects the segment with the slope tile
/// through `0x802390D0`.
///
/// # Original
/// - Ghidra: `FUN_80075fd0` at `0x80075FD0` (1368 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80075fd0_FUN_80075fd0.c`
/// - observed: the `FUN_802dcd50` save pair, the
///   `FUN_800766f0(&local_f0,0,param_5,...)` query, the `<<3`/`<<4` grid
///   latches, the `0x80070A40` class walk, the `0x819`/`0x60` bit tests, the
///   `&DAT_802ef3f0`/`&DAT_802ef488` slope tables, the `0x802390d0` rectangle
///   distance and the `FUN_802dcd9c(uVar10)` epilogue.
/// - observed: the `unaff_GQR0` prologue only fills dead locals.
/// - Removed: the two modelled `_restgpr_18` epilogue calls (`0x802DCD9C`).
///   it only restores registers.
///
/// # Arguments
/// - `start`: two readable floats, the segment origin.
/// - `end`: two readable floats, the segment target.
/// - `out`: optional float destination for the hit x.
/// - `layer`: layer mask passed to the cell probes.
/// - `mode`: mask passed to `0x800766F0`.
/// - `flag`: optional word destination for the query kind.
///
/// # Returns
/// `1` when a hit was found (and the outputs were written), `0` otherwise.
///
/// # Side effects
/// Writes `out` and `flag`; the callees update the probe caches.
///
/// # Safety
/// Both points must be readable, `out`/`flag` either null or writable, and the
/// camera owner must be live for the `+0x8FE70` bound.
///
/// # Confidence
/// low - every branch, offset and arithmetic trick is literal, but the export
/// drops the fourth argument of the `0x800766F0` call (recovered from the
/// sibling call at `0x80075820` as `layer`), and the two four-float windows
/// handed to `0x802390D0` are transcribed by stack position because their field
/// roles are not named in the export.
pub unsafe fn fn_80075fd0(
    start: usize,
    end: usize,
    out: usize,
    layer: u32,
    mode: u32,
    flag: usize,) -> u32 {
    let zero = read_f32(W91_F_ZERO);
    let x0 = read_f32(start);
    let y0 = read_f32(start + 4);
    let mut x1 = read_f32(end);
    let mut y1 = read_f32(end + 4);
    let mut block = [x0, y0, zero, x1, y1, zero];
    let hit = platform::call4(
        W109_CALL_800766F0,
        block.as_mut_ptr() as u32,
        0,
        mode,
        layer,
    );
    let mut result = 0u32;
    let mut fallback_x = zero as f64;
    let mut hit_kind = 0u32;
    let mut valid = false;
    if hit != 0 {
        valid = true;
        hit_kind = hit;
        fallback_x = x1 as f64;
        x1 = block[3];
        y1 = block[4];
        if block[0] == block[3] && block[1] == block[4] && block[2] == block[5] {
            if out != 0 {
                write_f32(out, block[3]);
            }
            if flag != 0 {
                write_u32(flag, hit);
            }
            return 1;
        }
    }
    let camera = read_u32(G_CAMERA_OWNER);
    let left = call1_f32(W109_CALL_800789A0, camera) as f64;
    let mut grid_x3 = left as i32;
    let mut grid_y3 = read_f32(camera as usize + 0x8fe70) as i32;
    let mut grid_x4 = grid_x3;
    let mut grid_y4 = grid_y3;
    let mut scan_x = x0;
    let mut scan_y = y0 as f64;
    let target_x = x1 as f64;
    let step_z = (((y1 - y0) / (x1 - x0)) as f64).abs();
    loop {
        if scan_x as f64 == target_x {
            break;
        }
        call_f64x2_ptr(
            W109_CALL_8015F480,
            target_x,
            read_f32(W91_F_ONE) as f64,
            &mut scan_x as *mut f32 as u32,
        );
        if (grid_x3 as i16) != (((scan_x as i32) as i16) >> 3)
            || (grid_y3 as i16) != (((scan_y as i32) as i16) >> 3)
        {
            grid_x3 = (scan_x as i32) >> 3;
            grid_y3 = (scan_y as i32) >> 3;
            let class = call_f64_f64_u32(
                W109_CALL_80070A40,
                scan_x as f64,
                scan_y,
                layer,
            );
            if class == 0 {
                if out != 0 {
                    write_f32(out, scan_x);
                }
                result = 1;
                break;
            }
            if class == 2 {
                let next_x4 = (((scan_x as i32) as i16) >> 4) as i32;
                let next_y4 = (((scan_y as i32) as i16) >> 4) as i32;
                if grid_x4 != next_x4 || grid_y4 != next_y4 {
                    grid_x4 = next_x4;
                    grid_y4 = next_y4;
                    let bits = call_f64_f64_u32(
                        W109_CALL_80070BA0,
                        scan_x as f64,
                        scan_y,
                        layer,
                    );
                    let depth = call_f64_f64_u32(
                        W109_CALL_80070BF0,
                        scan_x as f64,
                        scan_y,
                        layer,
                    );
                    if bits & 0x819 != 0 {
                        if out != 0 {
                            write_f32(out, scan_x);
                        }
                        result = 1;
                        break;
                    }
                    if bits & 0x60 != 0 {
                        let index = (depth & 0xff) as usize * 8;
                        let (table, slope) = if bits & 0x40 != 0 {
                            (
                                W109_TBL_SLOPE_B,
                                -read_f32(W109_TBL_SLOPE_B + 4 + index),
                            )
                        } else {
                            (W109_TBL_SLOPE_A, read_f32(W109_TBL_SLOPE_A + 4 + index))
                        };
                        if slope * (x1 - x0) < 0.0 {
                            // observed: the unsigned `-y0 & 0xFFF0` word and the
                            // signed `x & 0xFFF0` word feed the two corners.
                            let y_field =
                                (((-(y0 as i32)) as u32) & 0x0000_fff0) as f64;
                            let base = -(y_field + read_f32(table + index) as f64);
                            let x_field =
                                ((((scan_x as i32) & 0xffff) as i16) & -16i16) as f64;
                            let x_high = (x_field + 16.0) as f32;
                            let mut block_a =
                                [block[0], block[1], block[2], block[3]];
                            let mut block_b =
                                [x_field as f32, base as f32, 0.0f32, x_high];
                            let mut t = 0.0f32;
                            let distance = call3_ptr_f64(
                                W109_CALL_802390D0,
                                block_a.as_mut_ptr() as u32,
                                block_b.as_mut_ptr() as u32,
                                &mut t as *mut f32 as u32,
                                0,
                            );
                            if distance < read_f32(W109_F_0_1_7408) as f64 {
                                if out != 0 {
                                    write_f32(
                                        out,
                                        (x0 as f64 + (x1 as f64 - x0 as f64) * t as f64)
                                            as f32,
                                    );
                                }
                                result = 1;
                                break;
                            }
                        }
                    }
                }
            }
        }
        scan_y += step_z;
    }
    if result == 0 && valid {
        if out != 0 {
            write_f32(out, fallback_x as f32);
        }
        if flag != 0 {
            write_u32(flag, hit_kind);
        }
        result = 1;
    }
    result
}

// ---------------------------------------------------------------------------
// 0x80075820
// ---------------------------------------------------------------------------

/// Finds the first ground/slope hit below a point on one scroll layer.
///
/// The body starts from the three-float point at `origin` and drops it by
/// `256.0`; the optional `0x800DAA10` probe and the mode `-1` rectangle query
/// `0x800766F0` seed a hit. It then walks downward in `8.0` steps, reading
/// `0x80070BA0`/`0x80070BF0` for each `/8` cell, resolving the `0x20` slope bit
/// into a height through the `0x802EF3F0` table, and otherwise classifying the
/// cell through `0x80070A40`.
///
/// # Original
/// - Ghidra: `FUN_80075820` at `0x80075820` (1144 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80075820_FUN_80075820.c`
/// - observed: the `FUN_802dcd50` save pair, `FUN_800daa10(&local_f4,
///   &local_104, local_108)`, the `FUN_800766f0(&local_e8, local_108, param_5,
///   param_4)` query, the `<<3` grid walk with `dVar18` `8.0`, the `0x20` and
///   `0x88899` bit arms, the `0x802EF3F0`/`0x802EF548` tables and
///   `FUN_802dcd9c(uVar13)`.
/// - observed: all eight `unaff_GQR0` prologue blocks write dead locals.
/// - Removed: the modelled `_restgpr_18` epilogue call (`0x802DCD9C`).
///   it only restores registers.
///
/// # Arguments
/// - `origin`: three readable floats, the start point.
/// - `out_value`: optional `float` destination for the hit height.
/// - `out_tile`: optional `u16` destination for the hit tile id.
/// - `layer`: layer word passed to the probes.
/// - `mask`: mask passed to `0x800766F0`.
/// - `mode`: layer selector; `-1` enables the rectangle query.
/// - `kind`: optional word destination for the hit source (`1`/`2`).
/// - `flag`: `1` enables the `0x8000` blocked test.
///
/// # Returns
/// `1` when a hit was found, `0` otherwise.
///
/// # Side effects
/// Writes the three optional outputs.
///
/// # Safety
/// `origin` must hold three floats and the outputs must be null or writable;
/// the stage probe tables must be initialised.
///
/// # Confidence
/// medium - every branch, offset and table lookup is literal; the
/// `CONCAT44`/`XOR` sequences are rewritten as [`w101_bias`] because they are
/// the compiler's signed-word-to-double idiom, and the `dVar19` limit is
/// traced as the value that the two seed queries update.
pub unsafe fn fn_80075820(
    origin: usize,
    out_value: usize,
    out_tile: usize,
    layer: u32,
    mask: u32,
    mode: u8,
    kind: usize,
    flag: u32,) -> u32 {
    let x = read_f32(origin);
    let y = read_f32(origin + 4);
    let z = read_f32(origin + 8);
    let zero = read_f32(W91_F_ZERO);
    let mut limit = y - read_f32(W109_F_256);
    let mut found = false;
    let mut hit_kind = 0u32;
    let mut hit_height = zero as f64;
    let mut tile_out = 0u16;
    let mut point = [x, y, z];
    let mut probe_height = 0.0f32;
    let mut probe_tile = 0u16;
    let seeded = platform::call3(
        W109_CALL_800DAA10,
        point.as_mut_ptr() as u32,
        &mut probe_height as *mut f32 as u32,
        &mut probe_tile as *mut u16 as u32,
    );
    if seeded != 0 {
        hit_height = probe_height as f64;
        limit = probe_height;
        if kind != 0 {
            write_u32(kind, 2);
        }
        found = true;
        tile_out = probe_tile;
    }
    if mode == 0xff {
        let mut block = [x, y, zero, x, limit, zero];
        let query = platform::call4(
            W109_CALL_800766F0,
            block.as_mut_ptr() as u32,
            &mut probe_tile as *mut u16 as u32,
            mask,
            layer,
        );
        if query != 0 {
            limit = block[4];
            hit_height = block[4] as f64;
            if kind != 0 {
                write_u32(kind, 1);
            }
            found = true;
            tile_out = probe_tile;
        }
    }
    let x64 = x as f64;
    let limit64 = limit as f64;
    let mut scan_y = y;
    'scan: loop {
        if (scan_y as f64) < limit64 {
            let cell_bits = call_f64_f64_u32(
                W109_CALL_80070BA0,
                x64,
                scan_y as f64,
                layer,
            );
            let depth_bits = call_f64_f64_u32(
                W109_CALL_80070BF0,
                x64,
                scan_y as f64,
                layer,
            );
            let blocked = flag == 1 && (cell_bits & 0x8000) != 0;
            let neg_y = (-(scan_y as f64)) as u32;
            let grid_word = neg_y & 0x0000_fff0;
            if mode == 0xff || mode as u32 == (depth_bits >> 0x10) & 0xff {
                if cell_bits & 0x20 != 0 {
                    let scale = read_f32(W91_F_FIXED_ONE) as f64;
                    let index = (depth_bits & 0xff) as usize * 8;
                    let world_x = (scale * x64) as i32 as u32;
                    let slope_x = (scale * read_f32(W109_TBL_SLOPE_A + index) as f64)
                        as i32 as u32;
                    let value = (w101_bias(slope_x)
                        + w101_bias(world_x & 0xffff)
                            * read_f32(W109_TBL_SLOPE_A + index + 4) as f64)
                        as f32;
                    let height = -((grid_word as f64)
                        + w101_bias(value as u32) / scale);
                    if !blocked || ((height - 4.0) as f32) <= y {
                        tile_out = read_u16(
                            W109_TBL_TILE + (depth_bits & 0xff) as usize * 2,
                        );
                        if kind != 0 {
                            write_u32(kind, 0);
                        }
                        found = true;
                        hit_height = height;
                    }
                    break 'scan;
                }
                if cell_bits & 0x88899 != 0 {
                    let class = call_f64_f64_u32(
                        W109_CALL_80070A40,
                        x64,
                        scan_y as f64,
                        layer,
                    );
                    if class == 0 {
                        let word = (((-scan_y) as i32) & 0xfff8).wrapping_neg() as u32;
                        let height = w101_bias(word);
                        if !blocked || ((height - 4.0) as f32) <= y {
                            tile_out = 0;
                            if kind != 0 {
                                write_u32(kind, 0);
                            }
                            found = true;
                            hit_height = height;
                        }
                    } else if class == 2 {
                        let word = grid_word.wrapping_neg();
                        let height = w101_bias(word);
                        if !blocked || ((height - 4.0) as f32) <= y {
                            tile_out = 0;
                            if kind != 0 {
                                write_u32(kind, 0);
                            }
                            found = true;
                            hit_height = height;
                        }
                    }
                    if found {
                        break 'scan;
                    }
                }
            }
        }
        scan_y -= 8.0;
    }
    let result = if found { 1 } else { 0 };
    if found {
        if out_value != 0 {
            write_f32(out_value, hit_height as f32);
        }
        if out_tile != 0 {
            write_u16(out_tile, tile_out);
        }
    }
    result
}

// ---------------------------------------------------------------------------
// 0x80079E80
// ---------------------------------------------------------------------------

/// Advances one stage-scroll tile walk and its two facing angles.
///
/// The body reads a course-section record through `0x800D90C0`, walks the tile
/// table at `stageObject+0x3C` while the player is outside the current cell,
/// and derives two angles from the segment between the current and previous
/// cell corners. Each angle is smoothed (or stored directly when the walk has
/// not started) and then drives the scene's matrix position through the
/// `0x80237C40`/`0x80237BD0` pair. The last block clamps the depth window to
/// the scene bounds and the four players, and rebuilds the two BG spans.
///
/// # Original
/// - Ghidra: `FUN_80079e80` at `0x80079E80` (2072 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80079e80_FUN_80079e80.c`
/// - observed: `iVar12 = FUN_802dcd6c();` (the save helper leaves `r3` as the
///   scene), the `FUN_800d90c0` record, the `0x14D` tile-advance guard, the
///   `FUN_80170980` normalisations, the two `0x801611c0` angles, the
///   `0x8015f200` smoothers, the four `0x80237C40`/`0x80237BD0` calls, the
///   `FUN_8005f900` four-player scan and `FUN_802dcdb8()`.
/// - observed: the `unaff_GQR0`/`unaff_GQR3` prologue only fills dead locals;
///   the `s16` angles are the same `1/256`-turn values [`fn_8007ffa0`] uses.
/// - Removed: the modelled `_restgpr_25` epilogue call (`0x802DCDB8`).
///   it only restores registers.
///
/// # Arguments
/// - `scene`: the BG scene record (`+0x900AC..+0x900FD`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Advances the tile index/phase, writes the two angles and the matrix
/// position, and refreshes `+0x8FE78`/`+0x8FE7C`/`+0x8FE80`/`+0x8FE88`/
/// `+0x8FE8C` plus the manager copy at `+0x8FEA8`.
///
/// # Safety
/// The scene, the stage object at `r13-0x57E8`, the stage info and the camera
/// owner must all be live; `record` must point at six readable halfwords.
///
/// # Confidence
/// low - every branch, offset and call is literal; the two angles come from the
/// `CONCAT22`/GQR3 paired-single idiom, transcribed as `s16 * (1/256)` like
/// [`fn_8007ffa0`], and the `local_b8` point block is traced by position because
/// `0x801C1650` does not name its fields.
pub unsafe fn fn_80079e80(scene: usize) {
    let manager = read_u32(G_BG_SCENE) as usize;
    let extent_x = read_f32(manager + 0x40) as f64;
    let extent_y = read_f32(manager + 0x44) as f64;
    let record = platform::call1(
        W109_CALL_800D90C0,
        read_u8(scene + 0x900c0) as u32,
    ) as usize;
    let info = read_u32(G_STAGE_INFO) as usize;
    let stage = read_u32(G_STAGE_OBJECTS) as usize
        + read_u8(info + 0x120e) as usize * 0x3b0;
    let stage = if read_u32(stage + 0x2c) == 0 { 0 } else { stage };
    let left = call1_f32(W109_CALL_80078A70, scene as u32) as f64;
    let right = call1_f32(W109_CALL_80078C10, scene as u32) as f64 - extent_x;
    let ceiling = read_f32(scene + 0x90038) as f64;
    let floor = extent_y + read_f32(scene + 0x9003c) as f64;
    let mut horizontal = true;
    let mut vertical = true;
    if read_u8(info + 0x120c) == 1
        && read_u8(info + 0x120d) == 0x17
        && read_u8(info + 0x120e) == 0
    {
        platform::call1(W109_CALL_80079BF0, scene as u32);
    } else if read_u8(W69_G_PAUSE_FLAGS) & 8 == 0 && read_u8(scene + 0x900fc) == 0 {
        let mut tile = read_u32(stage + 0x3c) as usize + read_u16(record + 2) as usize * 0x10;
        if read_u8(scene + 0x900fd) != 0 {
            let mut guard = 0x14du32;
            'advance: loop {
                for _ in 0..3 {
                    if read_u8(scene + 0x90079) == 0 {
                        let index = read_u32(scene + 0x900ec) as usize;
                        let raw = read_u16(tile + index * 0x10);
                        if (read_f32(scene + 0x900ac) as f64) <= w101_bias(raw as u32) {
                            break 'advance;
                        }
                        write_u32(scene + 0x900ec, read_u32(scene + 0x900ec) + 1);
                    }
                }
                guard -= 1;
                if guard == 0 {
                    break 'advance;
                }
            }
        }
        let zero = read_f32(W91_F_ZERO_ALT);
        let saved_x = read_f32(scene + 0x900ac);
        let saved_z = read_f32(scene + 0x900b0);
        write_u8(scene + 0x900fd, 0);
        if read_u32(scene + 0x900f0) < 999 {
            let index = read_u32(scene + 0x900ec) as usize * 0x10;
            let cell_x = w101_bias(read_u16(tile + index) as u32) as f32;
            let cell_z = -(w101_bias(read_u16(tile + index + 2) as u32) as f32);
            let mut previous_x = saved_x;
            let mut previous_z = saved_z;
            if read_u32(scene + 0x900ec) > 0 {
                previous_x =
                    w101_bias(read_u16(tile + index - 0x10) as u32) as f32;
                previous_z =
                    -(w101_bias(read_u16(tile + index - 0x0e) as u32) as f32);
            }
            let mut segment = [cell_x - previous_x, cell_z - previous_z, 0.0f32];
            platform::call1(
                W109_CALL_80170980,
                segment.as_mut_ptr() as u32,
            );
            let mut direction = [cell_x - saved_x, cell_z - saved_z, 0.0f32];
            platform::call1(
                W109_CALL_80170980,
                direction.as_mut_ptr() as u32,
            );
            let dx = direction[0] as f64;
            let dz = direction[1] as f64;
            let length = call1_f64(W107_CALL_802BE470, dx * dx);
            let angle_x = call2_f64_i32(
                W109_CALL_801611C0,
                dz,
                length,
            ) as i16;
            let angle_z = call2_f64_i32(W109_CALL_801611C0, dx, 0.0) as i16;
            if (read_u32(scene + 0x900f0) == 0 && read_u32(scene + 0x900ec) < 2)
                || read_u8(scene + 0x900c1) != 0
            {
                write_u16(scene + 0x900f8, angle_x as u16);
                write_u16(scene + 0x900fa, angle_z as u16);
            } else {
                platform::call5(
                    W109_CALL_8015F200,
                    (scene + 0x900f8) as u32,
                    angle_x as i32 as u32,
                    0x3c,
                    0xfa,
                    1,
                );
                platform::call5(
                    W109_CALL_8015F200,
                    (scene + 0x900fa) as u32,
                    angle_z as i32 as u32,
                    0x3c,
                    0xfa,
                    1,
                );
            }
            let first = w109_read_s16(scene + 0x900f8);
            let second = w109_read_s16(scene + 0x900fa);
            let unit = read_f32(W109_F_ANGLE) as f64;
            let cos_first = call1_f64(W109_CALL_80237C40, unit * first as i32 as f64);
            let sin_second = call1_f64(W109_CALL_80237BD0, unit * second as i32 as f64);
            let step_x = (cos_first * sin_second) as f32;
            let sin_first = call1_f64(W109_CALL_80237BD0, unit * first as i32 as f64) as f32;
            let cos_first2 = call1_f64(W109_CALL_80237C40, unit * first as i32 as f64);
            let cos_second = call1_f64(W109_CALL_80237C40, unit * second as i32 as f64);
            let step_z = (cos_first2 * cos_second) as f32;
            call4_f64_ptr(
                W109_CALL_8015F140,
                read_f32(tile + index + 4) as f64,
                read_f32(W91_F_ONE_ALT) as f64,
                read_f32(tile + index + 8) as f64,
                read_f32(W109_F_0_0001) as f64,
                (scene + 0x900b8) as u32,
            );
            write_u32(scene + 0x900b4, read_u32(W91_F_ZERO_ALT));
            write_f32(
                scene + 0x900ac,
                read_f32(scene + 0x900ac) + step_x * read_f32(scene + 0x900b8),
            );
            write_f32(
                scene + 0x900b0,
                read_f32(scene + 0x900b0) + sin_first * read_f32(scene + 0x900b8),
            );
            let mut probe = [cell_x, cell_z, 0.0f32];
            // observed: `0x801C1650` leaves the squared distance in `f1` and
            // `0x802BE470` takes it from there; the magnitude is not stored.
            let squared = call2_f32(
                W109_CALL_801C1650,
                (scene + 0x900ac) as u32,
                probe.as_mut_ptr() as u32,
            );
            let _ = call1_f64(W107_CALL_802BE470, squared as f64);
            let mut face_x = false;
            let mut face_z = false;
            let face = read_u8(scene + 0x900c4);
            if face == 1 {
                face_x = true;
            } else if face == 2 {
                face_z = true;
            }
            let x_in = face_z
                || segment[0] == 0.0
                || (0.0 < segment[0] && probe[0] <= read_f32(scene + 0x900ac))
                || (segment[0] <= 0.0 && read_f32(scene + 0x900ac) <= probe[0]);
            let z_in = face_x
                || segment[1] == 0.0
                || (0.0 < segment[1] && probe[1] <= read_f32(scene + 0x900b0));
            let z_in = z_in
                || (segment[1] <= 0.0 && read_f32(scene + 0x900b0) <= probe[1]);
            let mut finished = false;
            if x_in && z_in {
                let next = read_u32(scene + 0x900ec) + 1;
                write_u32(scene + 0x900ec, next);
                if (read_u16(record + 4) as i32) <= next as i32 {
                    match read_u8(scene + 0x900c3) {
                        0 => fn_8007a6b0(scene),
                        1 => {
                            write_u32(scene + 0x900ec, read_u8(scene + 0x900c2) as u32);
                            write_u32(
                                scene + 0x900f0,
                                read_u32(scene + 0x900f0) + 1,
                            );
                        }
                        _ => {
                            write_u32(
                                scene + 0x900ec,
                                read_u16(record + 4) as u32 - 1,
                            );
                            write_u32(scene + 0x900f0, 999);
                        }
                    }
                    finished = true;
                }
            }
            if !finished {
                let mut window_x = read_f32(scene + 0x900ac);
                write_u32(scene + 0x8fea8, read_u32(manager + 0x38));
                let mut window_z = read_f32(scene + 0x900b0);
                write_u32(scene + 0x8feac, read_u32(manager + 0x3c));
                if left <= window_x as f64 {
                    if right < window_x as f64 {
                        window_x = right as f32;
                    }
                } else {
                    window_x = left as f32;
                }
                if floor <= window_z as f64 {
                    if ceiling < window_z as f64 {
                        window_z = ceiling as f32;
                    }
                } else {
                    window_z = floor as f32;
                }
                let face = read_u8(scene + 0x900c4);
                if face == 0 {
                    horizontal = true;
                    vertical = true;
                } else if face == 1 {
                    horizontal = true;
                    vertical = false;
                } else if face == 2 {
                    horizontal = false;
                    vertical = true;
                }
                if horizontal {
                    let mut best = read_f32(W91_F_NO_LIMIT) as f64;
                    let mut index = 0usize;
                    while index < 4 {
                        let player = platform::call1(W109_CALL_8005F900, index as u32) as usize;
                        if player != 0 && best < read_f32(player + 0x152c) as f64 {
                            best = read_f32(player + 0x152c) as f64;
                        }
                        index += 1;
                    }
                    write_f32(scene + 0x8fe88, window_x);
                }
                if vertical {
                    write_f32(scene + 0x8fe8c, window_z);
                }
                let scale = call1_f32(W109_CALL_80078EB0, read_u32(G_CAMERA_OWNER)) as f64;
                let one = read_f32(W91_F_ONE_ALT) as f64;
                let reciprocal = one / scale;
                write_f32(scene + 0x9000c, reciprocal as f32);
                let inv = one / reciprocal as f64;
                write_f32(
                    scene + 0x8fe78,
                    (read_f32(G_BG_COL_A) as f64 * inv) as f32,
                );
                write_f32(
                    scene + 0x8fe7c,
                    (read_f32(G_BG_COL_B) as f64 * inv) as f32,
                );
            }
        }
    }
}

// ---------------------------------------------------------------------------
// 0x8007CD70
// ---------------------------------------------------------------------------

/// Clamps a source rectangle into the scene and smooths the destination.
///
/// The ten-word source block at `src+0x20` is copied into `dst+0x20` and its
/// four coordinates are clamped to the scene box (`manager+0x38..+0x44`). The
/// single-player arm only offsets the rectangle by `8.0`; the other arm checks
/// whether the rectangle straddles the scene edge, derives a depth scale from
/// the two centres, and runs the four `0x8015F140` smoothers, each gated by a
/// per-corner factor at `scene+0x90068..+0x90074`. The final block publishes the
/// two centre offsets at `camera+0x90128`/`+0x9012C`.
///
/// # Original
/// - Ghidra: `FUN_8007cd70` at `0x8007CD70` (2108 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8007cd70_FUN_8007cd70.c`
/// - observed: the `r13-0x5986 & 2` and `r13-0x5480 < 10` guards, the two
///   ten-word copy loops, the `manager+0x38..+0x44` clamps, the
///   `r2-0x7240` `8.0` arm, the `r2-0x7314` `80.0` tall-rectangle override, the
///   `FUN_802e8620` distance root, the four `FUN_8015f140` pairs and the two
///   `camera+0x90128`/`+0x9012C` stores.
/// - observed: the `unaff_GQR0` prologue only fills dead locals.
/// - Removed: the modelled `_restgpr_26` epilogue call (`0x802DCDBC`).
///   it only restores registers.
///
/// # Arguments
/// - `scene`: the BG scene record (`+0x90079`, `+0x90068..+0x90074`).
/// - `dst`: destination rectangle, at least `0x34` bytes.
/// - `src`: source rectangle, at least `0x34` bytes.
/// - `mode`: `1` forces the single-player arm.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes both rectangles, the four gating factors and two camera offsets.
///
/// # Safety
/// Both rectangles must be readable/writable through `+0x33`, the scene must be
/// live and the camera owner must be readable.
///
/// # Confidence
/// low - every branch, offset and call is literal, but the corner smoothers mix
/// the x and z weights in a way the export does not name, so the four `y`/`z`
/// slots are traced by position rather than by meaning.
pub unsafe fn fn_8007cd70(scene: usize, dst: usize, src: usize, mode: u32) {
    let manager = read_u32(G_BG_SCENE) as usize;
    let extent_x = read_f32(manager + 0x40) as f64;
    let mut changed = false;
    let left_bound = read_f32(manager + 0x38) as f64;
    let right_bound = read_f32(manager + 0x3c) as f64;
    let depth = read_f32(manager + 0x44) as f64;
    if read_u8(W69_G_PAUSE_FLAGS) & 2 == 0 {
        if mode != 0 || read_u32(W109_G_FRAME_COUNTER) < 10 {
            let mut index = 8usize;
            while index < 0xc {
                write_f32(dst + index * 4, read_f32(src + index * 4));
                index += 1;
            }
        }
        if read_f32(dst + 0x30) != read_f32(src + 0x30)
            && (read_f32(dst + 0x20) != read_f32(src + 0x20)
                || read_f32(dst + 0x24) != read_f32(src + 0x24)
                || read_f32(dst + 0x28) != read_f32(src + 0x28)
                || read_f32(dst + 0x2c) != read_f32(src + 0x2c))
        {
            changed = true;
        }
        let mut edge = false;
        let mut index = 8usize;
        while index < 0xc {
            write_f32(dst + index * 4, read_f32(src + index * 4));
            index += 1;
        }
        let x0 = read_f32(dst) as f64;
        let z0 = read_f32(dst + 4) as f64;
        let half = read_f32(W109_F_HALF) as f64;
        let centre_x = half * (x0 + z0);
        let x1 = read_f32(dst + 8) as f64;
        let z1 = read_f32(dst + 0xc) as f64;
        let centre_z = half * (x1 + z1);
        let mut x_min = read_f32(src) as f64;
        if x_min < left_bound {
            x_min = left_bound;
        }
        let mut y_min = read_f32(src + 4) as f64;
        if (left_bound + extent_x) < y_min {
            y_min = left_bound + extent_x;
        }
        let mut x_max = read_f32(src + 8) as f64;
        if right_bound < x_max {
            x_max = right_bound;
        }
        let mut y_max = read_f32(src + 0xc) as f64;
        if y_max < (right_bound - depth) {
            y_max = right_bound - depth;
        }
        if read_u32(G_GAME_MODE) == 2 || mode == 1 {
            let inset = read_f32(W109_F_8) as f64;
            write_f32(dst + 4, y_min as f32);
            write_f32(dst + 8, x_max as f32);
            write_f32(dst, (inset + x_min) as f32);
            write_f32(dst + 0xc, y_max as f32);
        } else {
            let mut margin = read_f32(W91_F_32) as f64;
            if read_u8(scene + 0x90079) == 3 {
                margin = read_f32(W109_F_80) as f64;
            }
            if (x1 < x_max && (right_bound - margin) < x_max)
                || (y_max < z1 && y_max < (margin + (right_bound - depth)))
            {
                edge = true;
            }
            let factor = read_f32(W109_F_HALF) as f64;
            let source_x = factor * (read_f32(dst) + read_f32(dst + 4)) as f64;
            let source_z = factor * (read_f32(dst + 8) + read_f32(dst + 0xc)) as f64;
            let target_x = factor * (read_f32(src) + read_f32(src + 4)) as f64;
            let target_z = factor * (read_f32(src + 8) + read_f32(src + 0xc)) as f64;
            let distance = call1_f64(
                W109_CALL_802E8620,
                (target_x - source_x) * (target_x - source_x)
                    + (target_z - source_z) * (target_z - source_z),
            );
            let mut ratio_x;
            let mut ratio_z;
            if distance == 0.0 {
                ratio_x = read_f32(W91_F_ONE_ALT) as f64;
                ratio_z = ratio_x;
            } else {
                ratio_x = (target_x - source_x) / distance;
                ratio_z = (target_z - source_z) / distance;
            }
            let abs_x = ratio_x.abs();
            let abs_z = ratio_z.abs();
            let mut x_step = 6.0 * abs_x;
            let z_step;
            let mut y_weight;
            let mut x_weight;
            let mut z_weight;
            if (read_u8(read_u32(G_STAGE_INFO) as usize + 0x120c) == 7
                && read_u8(read_u32(G_STAGE_INFO) as usize + 0x120d) == 6)
                || edge
            {
                x_step = 6.0 * abs_x;
                y_weight = 0.5;
                x_weight = 6.0 * abs_x;
                z_weight = 0.5;
                z_step = 6.0 * abs_z;
            } else {
                y_weight = 0.2;
                x_weight = abs_x;
                z_weight = 0.5;
                z_step = 2.0 * abs_z;
            }
            let zero = read_f32(W91_F_ZERO_ALT) as f64;
            let mut factor_value = zero;
            if changed {
                write_u32(scene + 0x90064, 0x78);
                write_u32(scene + 0x90068, read_u32(W91_F_ONE_ALT));
                write_u32(scene + 0x9006c, read_u32(W91_F_ONE_ALT));
                write_u32(scene + 0x90070, read_u32(W91_F_ONE_ALT));
                write_u32(scene + 0x90074, read_u32(W91_F_ONE_ALT));
            }
            if read_u32(scene + 0x90064) != 0 {
                write_u32(scene + 0x90064, read_u32(scene + 0x90064) - 1);
                factor_value = read_f32(W91_F_ONE_ALT) as f64;
            }
            let start = factor_value;
            let band = read_f32(W109_F_0_1_7408) as f64;
            let step = read_f32(W109_F_0_005) as f64;
            let step_slow = read_f32(W109_F_0_0001) as f64;
            let mut slot = scene + 0x90068;
            let mut gate = if x0 <= x_min {
                x_min <= (left_bound + 0.5 * extent_x)
            } else {
                false
            };
            if gate {
                call4_f64_ptr(W109_CALL_8015F140, start, band, step, step_slow, slot as u32);
            } else {
                call4_f64_ptr(
                    W109_CALL_8015F140,
                    zero,
                    band,
                    step,
                    step_slow,
                    slot as u32,
                );
            }
            let f = read_f32(scene + 0x90068) as f64;
            call4_f64_ptr(
                W109_CALL_8015F140,
                x_min,
                y_weight + f * (0.5 - y_weight),
                x_step + f * (x_weight - x_step),
                read_f32(W96_F_SCENE_D) as f64,
                dst as u32,
            );
            slot = scene + 0x9006c;
            gate = if y_min <= z0 {
                (left_bound + 0.5 * extent_x) <= y_min
            } else {
                false
            };
            if gate {
                call4_f64_ptr(W109_CALL_8015F140, start, band, step, step_slow, slot as u32);
            } else {
                call4_f64_ptr(
                    W109_CALL_8015F140,
                    zero,
                    band,
                    step,
                    step_slow,
                    slot as u32,
                );
            }
            let f = read_f32(scene + 0x9006c) as f64;
            call4_f64_ptr(
                W109_CALL_8015F140,
                y_min,
                y_weight + f * (0.5 - y_weight),
                x_step + f * (x_weight - x_step),
                read_f32(W96_F_SCENE_D) as f64,
                (dst + 4) as u32,
            );
            slot = scene + 0x90070;
            gate = if x_max <= x1 {
                (right_bound - 0.5 * depth) <= x_max
            } else {
                false
            };
            if gate {
                call4_f64_ptr(W109_CALL_8015F140, start, band, step, step_slow, slot as u32);
            } else {
                call4_f64_ptr(
                    W109_CALL_8015F140,
                    zero,
                    band,
                    step,
                    step_slow,
                    slot as u32,
                );
            }
            let f = read_f32(scene + 0x90070) as f64;
            call4_f64_ptr(
                W109_CALL_8015F140,
                x_max,
                y_weight + f * (z_weight - y_weight),
                z_step + f * (z_weight - z_step),
                read_f32(W96_F_SCENE_D) as f64,
                (dst + 8) as u32,
            );
            slot = scene + 0x90074;
            gate = if z1 <= y_max {
                y_max <= (right_bound - 0.5 * depth)
            } else {
                false
            };
            if gate {
                call4_f64_ptr(W109_CALL_8015F140, start, band, step, step_slow, slot as u32);
            } else {
                call4_f64_ptr(
                    W109_CALL_8015F140,
                    zero,
                    band,
                    step,
                    step_slow,
                    slot as u32,
                );
            }
            let f = read_f32(scene + 0x90074) as f64;
            call4_f64_ptr(
                W109_CALL_8015F140,
                y_max,
                y_weight + f * (z_weight - y_weight),
                z_step + f * (z_weight - z_step),
                read_f32(W96_F_SCENE_D) as f64,
                (dst + 0xc) as u32,
            );
        }
        let camera = read_u32(G_CAMERA_OWNER) as usize;
        let out_x = 0.5 * (read_f32(dst) + read_f32(dst + 4)) as f64;
        let out_z = 0.5 * (read_f32(dst + 8) + read_f32(dst + 0xc)) as f64;
        let left = call1_f32(W109_CALL_80078A70, camera as u32) as f64;
        let left_ok = if left_bound <= left {
            true
        } else {
            let right = call1_f32(W109_CALL_80078C10, camera as u32) as f64;
            right <= (left_bound + extent_x)
        };
        if left_ok {
            write_u32(camera + 0x90128, read_u32(W91_F_ZERO_ALT));
        } else {
            write_f32(camera + 0x90128, (out_x - centre_x) as f32);
        }
        if (read_f32(camera + 0x90038) as f64) <= right_bound
            || (right_bound - depth) <= (read_f32(camera + 0x9003c) as f64)
        {
            write_u32(camera + 0x9012c, read_u32(W91_F_ZERO_ALT));
        } else {
            write_f32(camera + 0x9012c, (out_z - centre_z) as f32);
        }
    }
}

// ---------------------------------------------------------------------------
// Wave 110 - the remainder of the 0x800B0000 bucket
// ---------------------------------------------------------------------------
//
// The three entries below are the lift-object builders and the follow pass that
// the wave-100 and wave-104 batches left behind. They use the rest of the lift
// family's layout: the `+0x88` next-node word, the six-float node record at
// `+0x68..+0x7C`, the `0x40`-stride draw nodes and the `+0xC0` half-extent
// consumed by [`fn_800bc5a0`].

/// `r2 - 0x69E0` -> `0x8042C6A0`: z clamp of [`fn_800b9a90`].
const W110_F_69E0: usize = SDA2_BASE - 0x69E0;

/// `r2 - 0x69D4` -> `0x8042C6AC`: offset added to the source `+0x78C` word to
/// form the y clamp of [`fn_800b9a90`].
const W110_F_69D4: usize = SDA2_BASE - 0x69D4;

/// `r2 - 0x69D0` -> `0x8042C6B0`: interpolation factor of [`fn_800b9a90`].
const W110_F_69D0: usize = SDA2_BASE - 0x69D0;

/// `r2 - 0x69CC` -> `0x8042C6B4`: y offset subtracted after the interpolation
/// of [`fn_800b9a90`].
const W110_F_69CC: usize = SDA2_BASE - 0x69CC;

/// `r2 - 0x69F0` -> `0x8042C690`: the `2^52 + 2^31` bias used by the unsigned
/// conversions of [`fn_800b9a90`].
const W110_D_69F0: usize = SDA2_BASE - 0x69F0;

/// `0x802F0D50`: per-node draw flags of [`fn_800bc2e0`] (three words).
const W110_NODE_FLAGS_A: usize = 0x802F_0D50;

/// `0x802F0D60`: per-node draw flags of [`fn_800bc5d0`] (three words).
const W110_NODE_FLAGS_B: usize = 0x802F_0D60;

/// `r2 - 0x6950` -> `0x8042C730`: per-node clip-index bytes of
/// [`fn_800bc2e0`], added to `4` when indexing the name array.
const W110_CLIP_INDEX: usize = SDA2_BASE - 0x6950;

// ---------------------------------------------------------------------------
// 0x800B9A90
// ---------------------------------------------------------------------------

/// Follows every lift node along the source segment, blending the last nodes
/// into the source anchor.
///
/// The node count and head come from `this+0x1C`/`+0x20`, and the source
/// record's `+0x638`/`+0x63C`/`+0x640` is the first start point.
/// [`fn_800b95e0`] supplies a ratio that fixes how many trailing nodes take
/// part in the blend (`steps`). Each iteration places the node's end point by
/// moving the `r2-0x69D0` fraction of the way from the current start to the
/// previous end, clamps y and z, optionally blends toward the source
/// `+0x62C`/`+0x630` pair and the `r2-0x69E0` z word, then normalises the
/// remaining vector to `r2-0x69B8` before [`fn_800bae60`] rebuilds the derived
/// fields.
///
/// # Original
/// - Ghidra: `FUN_800b9a90` at `0x800B9A90` (936 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800b9a90_FUN_800b9a90.c`
/// - observed: `dVar11 = (double)([r2-0x69d4] + [src+0x78c])`,
///   `uVar1 = (uint)((CONCAT44(0x43300000,count^0x80000000) - [r2-0x69f0]) * dVar6)`,
///   `dVar6 = (double)(float)(dVar12 / (double)(float)uVar1)`,
///   `local_110 = (float)((local_f8 + (float)(dVar13 * local_104)) - dVar14)`
///   with its two siblings, the `tail_start <= index` blend, the
///   `FUN_801c14c0(&local_120)` length, the six `+0x68..+0x7C` stores and
///   `FUN_800bae60(iVar5,*(undefined4 *)(param_1 + 0x24));`.
///
/// # Arguments
/// - `this`: lift element; `+0x1C` count, `+0x20` first node, `+0x24` source.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Rewrites every node's `+0x68..+0x7C` and calls [`fn_800bae60`] per node.
///
/// # Safety
/// The `+0x88` node chain must hold `this+0x1C` live nodes and the source
/// record must be readable through `+0x78C`.
///
/// # Confidence
/// medium - the loop, both clamps and all stores are literal; the ten
/// `in_f30`/`in_f31` dequantisation blocks are dead stack writes and are not
/// reproduced, and the five `r2` constants are read by address.
pub unsafe fn fn_800b9a90(this: usize) {
    let source = read_u32(this + 0x24) as usize;
    let count = read_i32(this + 0x1c);
    let clamp_y = (read_f32(W110_F_69D4) + read_f32(source + 0x78c)) as f64;
    let ratio = fn_800b95e0(this) as f64;
    let ceiling = read_f32(W100_F_69E8);
    // observed: the `CONCAT44(0x43300000,count^0x80000000) - [r2-0x69f0]`
    // chain is the unsigned-int-to-double idiom; the product is truncated.
    let steps = (((count as u32) as f32 as f64) * ratio) as u32;
    // observed: `dVar6 = (float)(ceiling / (float)steps)`.
    let step = (ceiling as f64 / (steps as f32 as f64)) as f32 as f64;
    let mut weight = read_f32(W100_F_69F4) as f64;
    let pull = read_f32(W110_F_69D0) as f64;
    let y_offset = read_f32(W110_F_69CC) as f64;
    let z_clamp = read_f32(W110_F_69E0) as f64;
    let target = read_f32(W100_F_69B8) as f64;
    let anchor_x = read_f32(source + 0x62c);
    let anchor_y = read_f32(source + 0x630);
    let anchor_z = read_f32(W110_F_69E0);
    let mut start_x = read_f32(source + 0x638);
    let mut start_y = read_f32(source + 0x63c);
    let mut start_z = read_f32(source + 0x640);
    let mut node = read_u32(this + 0x20) as usize;
    // observed: `(int)(count - uVar1)`, i.e. a wrapping unsigned difference.
    let tail_start = (count as u32).wrapping_sub(steps) as i32;
    let mut index = 0i32;
    while index < count {
        let node_x1 = read_f32(node + 0x68);
        let node_y1 = read_f32(node + 0x6c);
        let node_z1 = read_f32(node + 0x70);
        let node_x2 = read_f32(node + 0x74);
        let node_y2 = read_f32(node + 0x78);
        let node_z2 = read_f32(node + 0x7c);
        let mut end_x = node_x2 + (pull * (start_x - node_x1) as f64) as f32;
        let mut end_y =
            ((node_y2 + (pull * (start_y - node_y1) as f64) as f32) as f64 - y_offset) as f32;
        let mut end_z = node_z2 + (pull * (start_z - node_z1) as f64) as f32;
        if (end_y as f64) < clamp_y {
            end_y = clamp_y as f32;
        }
        if (end_z as f64) < z_clamp {
            end_z = z_clamp as f32;
        }
        if tail_start <= index {
            weight = ((weight + step) as f32) as f64;
            let rest = (ceiling as f64 - weight) as f32;
            // observed: `t * anchor + (1 - t) * end`, all in f32.
            end_x = (weight * anchor_x as f64) as f32 + rest * end_x;
            end_y = (weight * anchor_y as f64) as f32 + rest * end_y;
            end_z = (weight * anchor_z as f64) as f32 + rest * end_z;
        }
        let mut delta = [end_x - start_x, end_y - start_y, end_z - start_z];
        let length = call1_f32(W88_VEC_LENGTH, delta.as_mut_ptr() as u32) as f64;
        let scale = (target / length) as f32;
        write_f32(node + 0x68, start_x);
        write_f32(node + 0x6c, start_y);
        write_f32(node + 0x70, start_z);
        write_f32(node + 0x74, start_x + delta[0] * scale);
        write_f32(node + 0x78, start_y + delta[1] * scale);
        write_f32(node + 0x7c, start_z + delta[2] * scale);
        fn_800bae60(node);
        start_x += delta[0] * scale;
        start_y += delta[1] * scale;
        start_z += delta[2] * scale;
        node = read_u32(node + 0x88) as usize;
        index += 1;
    }
}

// ---------------------------------------------------------------------------
// 0x800BC2E0
// ---------------------------------------------------------------------------

/// Builds the lift's three animated draw nodes and their animation pairs.
///
/// Every node is built like [`fn_800be690`]: the model word comes from
/// [`J3D_LOAD_ANM`], the node is handed to [`W104_NODE_BUILD`] with its
/// per-node flags, [`J3D_FINISH`] closes it, and the clip from
/// [`W104_ANM_LOAD`] is bound to the `+0xCC` sub-object with
/// [`W104_ANM_BIND`]/[`W104_ANM_ATTACH`]/[`W104_ANM_COMMIT`]. The three nodes
/// are `0x40` bytes apart; the three animation sub-objects are `0x2C` apart
/// starting at `+0xCC`.
///
/// # Original
/// - Ghidra: `FUN_800bc2e0` at `0x800BC2E0` (384 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800bc2e0_FUN_800bc2e0.c`
/// - observed: `uVar14 = FUN_802dcd54();`, `piVar5 = (int *)((ulonglong)uVar14
///   >> 0x20);`, `puVar11 = &DAT_802f0d50;`, the `piVar8 < piVar5 + 0x30` loop
///   with `piVar8 = piVar8 + 0x10`, the `&DAT_802f0d50` flag words, the
///   `unaff_r2 + -0x6950` byte table in `param_7[*pbVar10 + 4]`, the
///   `piVar9 = piVar5 + 0x33` / `piVar9 = piVar9 + 0xb` sub-object walk, the
///   `+0x18` vtable call, `FUN_80166ef0(param_2,piVar9,0)`,
///   `piVar5[0x30] = (int)(float)param_3;` and
///   `FUN_800bc5a0(uVar13,(double)(float)param_7[3],piVar5);`.
///
/// # Arguments
/// - `scale`: half-extent stored at `+0xC0` and split by [`fn_800bc5a0`].
/// - `this`: lift object; the node block starts at `+0x00`.
/// - `owner`: draw-list owner handed to the node build and the bind calls.
/// - `anim_owner`: animation-list owner for [`W104_ANM_COMMIT`]; the export
///   prints its parameter as an `undefined8` but the callee reads only `r3`.
/// - `archive`: archive handle handed to both loaders.
/// - `names`: word table; entry `slot` is the model, entry `4 + clip_index`
///   the clip.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Builds three nodes, three animation pairs and stores `+0xC0`.
///
/// # Safety
/// `this` must own the `0x00..0xC8` node block plus the `0xCC..0x130`
/// sub-object block, and both tables must be live.
///
/// # Confidence
/// medium - every call, stride and table index is literal; the three
/// dequantisation blocks at the top only write dead stack words and are not
/// reproduced, and the `+0xC0` store is typed as `int` in the export although
/// its neighbour stores the same word as a `float`.
pub unsafe fn fn_800bc2e0(
    scale: f64,
    this: usize,
    owner: usize,
    anim_owner: u32,
    archive: usize,
    names: usize,
) {
    for slot in 0..3usize {
        let node = this + slot * 0x40;
        let sub = this + 0xcc + slot * 0x2c;
        let model = platform::call2(
            J3D_LOAD_ANM,
            archive as u32,
            read_u32(names + slot * 4),
        );
        let mut model_word = [model];
        platform::call6(
            W104_NODE_BUILD,
            node as u32,
            model_word.as_mut_ptr() as u32,
            owner as u32,
            read_u32(W110_NODE_FLAGS_A + slot * 4),
            1,
            0,
        );
        platform::call1(J3D_FINISH, node as u32);
        let clip_index = read_u8(W110_CLIP_INDEX + slot) as usize + 4;
        let clip = platform::call2(
            W104_ANM_LOAD,
            archive as u32,
            read_u32(names + clip_index * 4),
        );
        let mut pair = [model, clip];
        platform::call6(
            W104_ANM_BIND,
            sub as u32,
            (&mut pair[0]) as *mut u32 as u32,
            (&mut pair[1]) as *mut u32 as u32,
            owner as u32,
            0,
            1,
        );
        platform::call5(
            W104_ANM_ATTACH,
            sub as u32,
            node as u32,
            (&mut pair[1]) as *mut u32 as u32,
            0,
            1,
        );
        call_vtable_slot2(node, 0x18, sub as u32);
        platform::call2(W104_ANM_COMMIT, anim_owner, sub as u32);
    }
    write_f32(this + 0xc0, scale as f32);
    // inferred: the export reads `[names+0xC]` through an `undefined4 *`; its
    // value is the second half-extent of [`fn_800bc5a0`], so it is an `f32`.
    fn_800bc5a0(scale, read_f32(names + 0x0c) as f64, this);
}

// ---------------------------------------------------------------------------
// 0x800BC5D0
// ---------------------------------------------------------------------------

/// Builds the lift's three plain draw nodes and stores the half-extent.
///
/// Unlike [`fn_800bc2e0`] there are no animation pairs: each node only gets the
/// model word from [`J3D_LOAD_ANM`], the [`W104_NODE_BUILD`] call and
/// [`J3D_FINISH`]. The nodes are `0x40` bytes apart and their per-node flags
/// come from the three words at `0x802F0D60`.
///
/// # Original
/// - Ghidra: `FUN_800bc5d0` at `0x800BC5D0` (212 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800bc5d0_FUN_800bc5d0.c`
/// - observed: `uVar9 = FUN_802dcd68();`, `uVar4 = (uint)((ulonglong)uVar9 >>
///   0x20);`, `puVar6 = &DAT_802f0d60;`, the `uVar5 < uVar4 + 0xc0` loop with
///   `uVar5 = uVar5 + 0x40`, `FUN_80239e30(param_5,*puVar7)`,
///   `FUN_80169d90(uVar5,local_48,(int)uVar9,*puVar6,1,0)`,
///   `FUN_80064bf0(uVar5)`, `*(float *)(uVar4 + 0xc0) = (float)param_2;` and
///   `FUN_800bc5a0(uVar8,(double)(float)param_6[3],uVar4);`.
///
/// # Arguments
/// - `scale`: half-extent stored at `+0xC0` and split by [`fn_800bc5a0`].
/// - `this`: lift object; the node block starts at `+0x00`.
/// - `owner`: draw-list owner handed to [`W104_NODE_BUILD`].
/// - `archive`: archive handle handed to [`J3D_LOAD_ANM`].
/// - `names`: three-word model-name table plus the `+0xC` half-extent.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Builds three nodes and stores `+0xC0`.
///
/// # Safety
/// `this` must hold three `0x40`-byte nodes plus `+0xC0`, and `names` must be
/// live through `+0xC`.
///
/// # Confidence
/// medium - the loop, the two calls and the stride are literal; the two
/// dequantisation blocks at the top only write dead stack words and are not
/// reproduced, and the `+0xC` word is read as an `f32` because
/// [`fn_800bc5a0`] uses it as a length.
pub unsafe fn fn_800bc5d0(scale: f64, this: usize, owner: usize, archive: usize, names: usize) {
    for slot in 0..3usize {
        let node = this + slot * 0x40;
        let model = platform::call2(
            J3D_LOAD_ANM,
            archive as u32,
            read_u32(names + slot * 4),
        );
        let mut model_word = [model];
        platform::call6(
            W104_NODE_BUILD,
            node as u32,
            model_word.as_mut_ptr() as u32,
            owner as u32,
            read_u32(W110_NODE_FLAGS_B + slot * 4),
            1,
            0,
        );
        platform::call1(J3D_FINISH, node as u32);
    }
    write_f32(this + 0xc0, scale as f32);
    // inferred: as in [`fn_800bc2e0`], the export types the word as
    // `undefined4`, but [`fn_800bc5a0`] divides by it as a length.
    fn_800bc5a0(scale, read_f32(names + 0x0c) as f64, this);
}

// ---------------------------------------------------------------------------
// Wave 111 - the last entries of the 0x800B0000 bucket
// ---------------------------------------------------------------------------
//
// The bucket's six open rows are the leftovers of the lift-grid family. Two are
// 4-byte branch thunks into bodies that already have rows (`0x800B4610` and
// `0x801DD1D0`); two (`0x800B96A0`, `0x800BC140`) read stack slots that nothing
// in their exports writes. The two below are the paired grid passes of the
// `0x800BE000` strip loop: they share the `0x84`-stride cell array of
// [`fn_800bec00`] and the [`fn_800be7b0`] translation submit.

/// `r2 - 0x6904` -> `0x8042C77C`: the y of a single-row lift in [`fn_800bd970`].
const W111_F_6904: usize = SDA2_BASE - 0x6904;

/// `0x80316018`: the `z_lift_A`/`z_lift_B`/`z_lift_C` animation names, four per
/// strip mode (16 bytes apart), read by [`fn_800bd970`].
const W111_Z_LIFT_NAMES: usize = 0x8031_6018;

/// `r2 - 0x68D0` -> `0x8042C7B0`: the x of the left/right cell pair written by
/// [`fn_800bef00`].
const W111_F_68D0: usize = SDA2_BASE - 0x68D0;

/// Writes one six-float cell of the lift grid and binds its draw node.
///
/// The cell layout is the one [`fn_800bec00`] fills: three `0x80358DF0` words
/// followed by two sizes and the `r2-0x68F0` tail word. The node is the
/// `0x60`-stride record at `+0x1C`, the draw record the `0x30`-stride block at
/// `+0x6020` and the enable flag the `0x40`-stride word at `+0x9228`.
///
/// # Safety
/// `this` must own the grid for `layer` and `index`.
unsafe fn w111_emit_lift_row(
    this: usize,
    layer: usize,
    index: usize,
    cells: [u32; 12],
    animation_name: u32,
) {
    let draw = this + layer * 0x300 + 0x6020 + index * 0x30;
    for (word, value) in cells.iter().enumerate() {
        write_u32(draw + word * 4, *value);
    }
    let mut animation = [0u32; 4];
    animation[0] = platform::call2(W104_MODEL_ANM, (this + 0x601c) as u32, animation_name);
    let node = this + layer * 0x600 + index * 0x60 + 0x1c;
    platform::call5(
        W104_NODE_MATRIX,
        node as u32,
        animation.as_ptr() as u32,
        0x80,
        0xffff_ffff,
        this as u32,
    );
    platform::call2(W104_NODE_BIND, node as u32, draw as u32);
    write_u32(this + layer * 0x40 + index * 4 + 0x9228, 1);
}

// ---------------------------------------------------------------------------
// 0x800BD970
// ---------------------------------------------------------------------------

/// Emits one two-layer strip of lift cells and their draw nodes.
///
/// The strip starts at `(-x, y)` and uses `r2-0x6908` as the row pitch and
/// `r2-0x690C` as the shared z word. `mode` selects the two-entry
/// `0x802F0DE8` offset pair and one of the four-entry `0x80316018` name groups.
/// When the lift's flags (`+0x9630`) carry bit 1 and the mode is not `2`, a
/// first row is written into the layer-0 cells; the main row follows in layer
/// `1`, one row per remaining column, then a final row advanced by
/// `r2-0x6900` (or the row pitch when `+0x9628` is one). Flag bit 0 adds one
/// closing row whose two size words carry `0xC000`.
///
/// # Original
/// - Ghidra: `FUN_800bd970` at `0x800BD970` (1680 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800bd970_FUN_800bd970.c`
/// - observed: `local_bc = param_2 - *(float *)(&DAT_802f0de8 + param_5 * 8)`,
///   the `+0x9630` bit `2` guard, the `+0x9628` count, the twelve-word
///   `+0x6020` groups with the `0x300` layer / `0x30` index strides,
///   `FUN_80239f20`/`FUN_8000aa70`/`FUN_8000ae50`, the `0x10000 - 0x6FD8`
///   halfword and `0x10000 - 0x6DD8` word writes, and the `0x802F0DE8` /
///   `&PTR_s_z_lift_A_80316018` tables.
///
/// # Arguments
/// - `x`: first `f64` register (`f1`); the export negates it as the origin.
/// - `y`: second `f64` register (`f2`); the row coordinate.
/// - `this`: lift object (`r3`), the `+0x9628`/`+0x9630` layout of
///   [`fn_800be000`].
/// - `index`: cell row (`r4`), the `0x30` stride inside a `0x300` layer.
/// - `mode`: strip mode (`0..3`), indexing both per-mode tables.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes up to `count + 3` rows of twelve floats, their `0x60`-byte nodes,
/// the `+0x9028` halfword and the `+0x9228` enable words.
///
/// # Safety
/// `this` must own the full grid for `index` and the row count, and `mode`
/// must be below the table lengths.
///
/// # Confidence
/// medium - every store offset, stride, guard and table read is literal; the
/// dead `GQR0` paired-single stores at the top are not reproduced (they write
/// only stack words nothing reads), and the `param_5` table index is read as
/// `mode` because it indexes four entries per strip exactly like the sibling
/// [`fn_800bd7a0`].
pub unsafe fn fn_800bd970(x: f64, y: f64, this: usize, index: i32, mode: i32) {
    let x = x as f32;
    let y = y as f32;
    let neg_x = -x;
    let step = read_f32(W104_F_6908);
    let z = read_u32(W104_F_690C);
    let flags = read_u32(this + 0x9630);
    let count = read_i32(this + 0x9628);
    let index = index as usize;
    let mode = mode as usize;

    let mut upper = step + neg_x;
    let first_y = y - read_f32(W104_STRIP_OFFSETS + mode * 8);
    let bottom = y - step;
    let first_x = neg_x - step;
    let last_y = y - read_f32(W104_STRIP_OFFSETS + (mode * 2 + 1) * 4);
    let mut row_x = neg_x;
    let row_y = y;
    let row_y2 = y;
    let mut tail_x = neg_x;
    let mut closing_x = upper;
    let mut layer = 0usize;

    if flags & 2 == 0 || mode == 2 {
        if count == 1 {
            upper = read_f32(W111_F_6904) + neg_x;
            closing_x = upper;
        }
    } else {
        let base = this + index * 0x30;
        write_f32(base + 0x6020, first_x);
        write_f32(base + 0x6024, first_y);
        write_u32(base + 0x6028, z);
        write_f32(base + 0x602c, neg_x);
        write_f32(base + 0x6030, first_y);
        write_u32(base + 0x6034, z);
        write_f32(base + 0x6038, neg_x);
        write_f32(base + 0x603c, last_y);
        write_u32(base + 0x6040, z);
        write_f32(base + 0x6044, first_x);
        write_f32(base + 0x6048, last_y);
        write_u32(base + 0x604c, z);
        let mut animation = [0u32; 4];
        animation[0] = platform::call2(
            W104_MODEL_ANM,
            (this + 0x601c) as u32,
            W104_S_SAMPLE_NAME as u32,
        );
        let node = this + index * 0x60 + 0x1c;
        platform::call5(
            W104_NODE_MATRIX,
            node as u32,
            animation.as_ptr() as u32,
            0x80,
            0xffff_ffff,
            this as u32,
        );
        platform::call2(
            W104_NODE_BIND,
            node as u32,
            (this + 0x6020 + index * 0x30) as u32,
        );
        write_u16(this + 0x9028 + index * 2, 0x4000);
        write_u32(this + 0x9228 + index * 4, 1);
        layer = 1;
    }

    let cells = [
        row_x.to_bits(),
        row_y.to_bits(),
        z,
        upper.to_bits(),
        row_y2.to_bits(),
        z,
        closing_x.to_bits(),
        bottom.to_bits(),
        z,
        tail_x.to_bits(),
        bottom.to_bits(),
        z,
    ];
    w111_emit_lift_row(
        this,
        layer,
        index,
        cells,
        read_u32(W111_Z_LIFT_NAMES + mode * 16),
    );

    let mut layer_cursor = layer + 1;
    if count > 2 {
        let mut row = 0i32;
        while row < count - 2 {
            row_x += step;
            upper += step;
            closing_x += step;
            tail_x += step;
            if mode != 1 {
                let cells = [
                    row_x.to_bits(),
                    row_y.to_bits(),
                    z,
                    upper.to_bits(),
                    row_y2.to_bits(),
                    z,
                    closing_x.to_bits(),
                    bottom.to_bits(),
                    z,
                    tail_x.to_bits(),
                    bottom.to_bits(),
                    z,
                ];
                w111_emit_lift_row(
                    this,
                    layer_cursor,
                    index,
                    cells,
                    read_u32(W111_Z_LIFT_NAMES + mode * 16 + 4),
                );
                layer_cursor += 1;
            }
            row += 1;
        }
    }

    let final_step = if count == 1 {
        read_f32(W104_F_6900)
    } else {
        step
    };
    tail_x += final_step;
    closing_x += final_step;
    upper += final_step;
    row_x += final_step;
    let cells = [
        row_x.to_bits(),
        row_y.to_bits(),
        z,
        upper.to_bits(),
        row_y2.to_bits(),
        z,
        closing_x.to_bits(),
        bottom.to_bits(),
        z,
        tail_x.to_bits(),
        bottom.to_bits(),
        z,
    ];
    w111_emit_lift_row(
        this,
        layer_cursor,
        index,
        cells,
        read_u32(W111_Z_LIFT_NAMES + mode * 16 + 8),
    );

    if flags & 1 != 0 && mode != 2 {
        let close_x = step + row_x;
        let close_y = step + upper;
        let close_tail = step + closing_x;
        let after_tail = step + tail_x;
        let cells = [
            close_x.to_bits(),
            first_y.to_bits(),
            z,
            close_y.to_bits(),
            first_y.to_bits(),
            z,
            close_tail.to_bits(),
            last_y.to_bits(),
            z,
            after_tail.to_bits(),
            last_y.to_bits(),
            z,
        ];
        w111_emit_lift_row(
            this,
            layer_cursor + 1,
            index,
            cells,
            W104_S_SAMPLE_NAME as u32,
        );
        write_u16(this + 0x9028 + (layer_cursor + 1) * 0x20 + index * 2, 0xc000);
        write_u32(this + 0x9228 + (layer_cursor + 1) * 0x40 + index * 4, 1);
    }
}

// ---------------------------------------------------------------------------
// 0x800BEF00
// ---------------------------------------------------------------------------

/// Fills one 3x3 block of lift cells around a strip corner.
///
/// `rows` and `columns` are the raw counts; `rows - 2` and `columns - 2` are
/// the free spans, and every cell past the first takes the `r2-0x68D8` pitch
/// or the `r2-0x68D4` height. The nine cells sit at `+0x6C` with a `0x84`
/// stride. Cells 0, 2, 3, 4 and 6 also receive a [`fn_800be7b0`] translation;
/// the `0x802F0E4C` byte pair of the variant swaps its first two components.
/// When `+0x228C` is set, [`fn_800bec00`] rebuilds the rest of the grid from
/// the same two counts.
///
/// # Original
/// - Ghidra: `FUN_800bef00` at `0x800BEF00` (1260 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800bef00_FUN_800bef00.c`
/// - observed: `uVar15 = FUN_802dcd6c();` (keeps `r3`/`r4`),
///   `uVar11 = (int)uVar15 - 2`, `uVar10 = param_3 - 2`, the
///   `CONCAT44(0x43300000, ... ^ 0x80000000)` conversions, the nine
///   `+0x6C`/`+0xF0`/`+0x174`/`+0x1F8`/`+0x27C`/`+0x300`/`+0x384`/`+0x408`/
///   `+0x48C` six-word groups, the five [`fn_800be7b0`] calls, the
///   `(&DAT_802f0e4c)[param_4 * 0x58]` byte pair and the
///   `*(char *)(iVar9 + 0x228c)` guard on [`fn_800bec00`].
///
/// # Arguments
/// - `this`: lift object (`r3`), the `+0x6C` cell array of the lift grid.
/// - `rows`: raw row count (`r4`); `rows - 2` is the free row span.
/// - `columns`: raw column count (`r5`); `columns - 2` the free column span.
/// - `variant`: lift variant (`r6`), indexing the mirror bytes at `0x58`
///   stride.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes nine six-word cells, five translation triples and the `+0x9028`
/// flags of any grid rebuilt by [`fn_800bec00`].
///
/// # Safety
/// `this` must own the nine cells and the full grid behind `+0x4A4`, and
/// `variant` must be below the mirror table length.
///
/// # Confidence
/// medium - every cell offset, size, guard and table read is literal, and the
/// cell layout is the one already translated in [`fn_800bec00`] and
/// [`fn_800bf3f0`]; the `local_64`/`local_68` running size pair is tracked
/// through the body rather than guessed, and the dead `GQR0` prologue stores
/// are not reproduced.
pub unsafe fn fn_800bef00(this: usize, rows: i32, columns: i32, variant: i32) {
    let rows_f = (rows - 2) as f32;
    let columns_f = (columns - 2) as f32;
    let pitch = read_f32(W104_F_68D8);
    let height = read_f32(W104_F_68D4);
    let second_x = read_f32(W111_F_68D0);
    let word_a = read_u32(W100_CELL_WORD_A);
    let word_b = read_u32(W100_CELL_WORD_B);
    let word_c = read_u32(W100_CELL_WORD_C);
    let tail = read_u32(W100_F_68F0);
    let mirror = W104_LIFT_MIRROR + variant as usize * 0x58;
    let mirror_first = read_u8(mirror) != 0;
    let mirror_second = read_u8(mirror + 1) != 0;

    let word_b_float = f32::from_bits(word_b);
    let word_c_float = f32::from_bits(word_c);
    let mut size_x = pitch + pitch + pitch * rows_f;
    let mut size_y = height;

    // Cell 0.
    write_u32(this + 0x6c, word_a);
    write_u32(this + 0x70, word_b);
    write_u32(this + 0x74, word_c);
    write_f32(this + 0x78, pitch);
    write_f32(this + 0x7c, height);
    write_u32(this + 0x80, tail);

    if rows - 2 > 0 {
        // Cell 1.
        write_f32(this + 0xf0, rows_f);
        write_u32(this + 0xf4, word_b);
        write_u32(this + 0xf8, word_c);
        write_f32(this + 0xfc, size_x);
        write_f32(this + 0x100, size_y);
        write_u32(this + 0x104, tail);
        let vector = if mirror_first {
            [word_b_float, rows_f, word_c_float]
        } else {
            [rows_f, word_b_float, word_c_float]
        };
        fn_800be7b0(this + 0x84, vector.as_ptr() as usize);
    }

    // Cell 2.
    write_u32(this + 0x174, word_a);
    write_u32(this + 0x178, word_b);
    write_u32(this + 0x17c, word_c);
    write_f32(this + 0x180, size_x + pitch + pitch * rows_f);
    write_f32(this + 0x184, size_y);
    write_u32(this + 0x188, tail);

    let lower_y = height - (pitch + pitch * columns_f);
    size_y = lower_y;
    size_x = pitch;

    if columns - 2 > 0 {
        // Cell 3.
        write_f32(this + 0x1f8, second_x);
        write_f32(this + 0x1fc, columns_f);
        write_u32(this + 0x200, word_c);
        write_f32(this + 0x204, pitch);
        write_f32(this + 0x208, size_y);
        write_u32(this + 0x20c, tail);
        let vector = if mirror_second {
            [columns_f, second_x, word_c_float]
        } else {
            [second_x, columns_f, word_c_float]
        };
        fn_800be7b0(this + 0x18c, vector.as_ptr() as usize);
    }

    size_x = size_x + pitch + pitch * rows_f;

    if columns - 2 > 0 && rows - 2 > 0 {
        // Cell 4.
        write_f32(this + 0x27c, rows_f);
        write_f32(this + 0x280, columns_f);
        write_u32(this + 0x284, word_c);
        write_f32(this + 0x288, size_x);
        write_f32(this + 0x28c, size_y);
        write_u32(this + 0x290, tail);
        let vector = [rows_f, columns_f, word_c_float];
        fn_800be7b0(this + 0x210, vector.as_ptr() as usize);
    }

    size_x = size_x + pitch + pitch * rows_f;

    if columns - 2 > 0 {
        // Cell 5.
        write_f32(this + 0x300, second_x);
        write_f32(this + 0x304, columns_f);
        write_u32(this + 0x308, word_c);
        write_f32(this + 0x30c, size_x);
        write_f32(this + 0x310, size_y);
        write_u32(this + 0x314, tail);
        let vector = if mirror_second {
            [columns_f, second_x, word_c_float]
        } else {
            [second_x, columns_f, word_c_float]
        };
        fn_800be7b0(this + 0x294, vector.as_ptr() as usize);
    }

    size_y = size_y - (pitch + pitch * columns_f);
    size_x = pitch + pitch + pitch * rows_f;

    // Cell 6.
    write_u32(this + 0x384, word_a);
    write_u32(this + 0x388, word_b);
    write_u32(this + 0x38c, word_c);
    write_f32(this + 0x390, pitch);
    write_f32(this + 0x394, size_y);
    write_u32(this + 0x398, tail);

    if rows - 2 > 0 {
        // Cell 7.
        write_f32(this + 0x408, rows_f);
        write_f32(this + 0x40c, second_x);
        write_u32(this + 0x410, word_c);
        write_f32(this + 0x414, size_x);
        write_f32(this + 0x418, size_y);
        write_u32(this + 0x41c, tail);
        let vector = if mirror_first {
            [second_x, rows_f, word_c_float]
        } else {
            [rows_f, second_x, word_c_float]
        };
        fn_800be7b0(this + 0x39c, vector.as_ptr() as usize);
    }

    size_x = size_x + pitch + pitch * rows_f;

    // Cell 8.
    write_u32(this + 0x48c, word_a);
    write_u32(this + 0x490, word_b);
    write_u32(this + 0x494, word_c);
    write_f32(this + 0x498, size_x);
    write_f32(this + 0x49c, size_y);
    write_u32(this + 0x4a0, tail);

    if read_u8(this + 0x228c) != 0 {
        fn_800bec00(this, rows, columns as u32);
    }
}

// ===========================================================================
// Wave 112 - the last opens of the 0x800C0000 bucket
// (0x800C9A60 .. 0x800CB490)
// ===========================================================================
//
// The `0x800C0000` bucket opened with 290 entries, 284 of which already had
// `game::stage` rows. Three of the six that were left can be reconstructed
// from the export: the two variadic message front-ends (`0x800C9A60` and
// `0x800C9DF0`) and the overlay-object arming helper `0x800CB490`. The two
// 4-byte branch thunks and the 660-byte screen-offset body are listed with
// their reasons in `docs/COVERAGE_WAVE112_STAGE.md`.

/// Calls a PowerPC function with eight integer arguments (`r3..r10`).
///
/// # Safety
/// `addr` must be a PowerPC function with this integer ABI.
unsafe fn w112_call8(
    addr: usize,
    a: u32,
    b: u32,
    c: u32,
    d: u32,
    e: u32,
    f: u32,
    g: u32,
    h: u32,
) -> u32 {
    let func: extern "C" fn(u32, u32, u32, u32, u32, u32, u32, u32) -> u32 =
        core::mem::transmute(addr);
    func(a, b, c, d, e, f, g, h)
}

/// Writes a big-endian IEEE-754 double to `addr`, the mirror of [`read_f64`].
///
/// The two variadic front-ends of this pass home the incoming `f1..f8` into
/// their `va_list` floating-point save area with eight word stores, which this
/// helper reproduces.
///
/// # Safety
/// `addr` must be a writable, 4-byte aligned address covering eight bytes.
unsafe fn w112_write_f64(addr: usize, value: f64) {
    let bits = value.to_bits();
    write_u32(addr, (bits >> 32) as u32);
    write_u32(addr + 4, bits as u32);
}

// Small-data slots and tables this pass reads.

/// `r13 - 0x5704` -> `0x80429F7C`: the global message/animation state.
/// `+0x3D0` and `+0x3D4` are the two frame words [`fn_800c9a60`] stores.
const W112_G_MESSAGE_STATE: usize = SDA_BASE - 0x5704;

/// `0x803177BC`: vtable of the first overlay object of [`fn_800cb490`].
const W112_DAT_803177BC: u32 = 0x8031_77BC;

/// `0x80317798`: vtable of the second overlay object of [`fn_800cb490`].
const W112_DAT_80317798: u32 = 0x8031_7798;

/// `0x80317774`: vtable of the single overlay object of the variant-1 arm.
const W112_DAT_80317774: u32 = 0x8031_7774;

// Callees that are not translated in this file.

/// `0x800C9B50`: the message worker that formats and draws one line, landed in
/// wave 116 as [`fn_800c9b50`]. Its export leads with two `psq_st` blocks; the
/// code bytes show those are the `f30`/`f31` spills and reloads, not
/// paired-single arguments, so the body needed nothing beyond the six named
/// words. This constant keeps the original eight-register call of
/// [`fn_800c9a60`] intact: the callee reads `r3..r8`, the two extra words are
/// the vararg tail.
const W112_CALL_800C9B50: usize = 0x800C_9B50;

/// `0x800CAB10`: loads the `cave_bti` texture selected by its argument. The
/// archive loader's `r3` result is taken as the texture handle.
const W112_CALL_800CAB10: usize = 0x800C_AB10;

/// `0x802B9210`: `operator new`, used for the 0x18-byte overlay objects.
const W112_ALLOC: usize = 0x802B_9210;

/// `0x8016A010`: the two-word object initialiser called before the vtable store.
const W112_CALL_8016A010: usize = 0x8016_A010;

// ---------------------------------------------------------------------------
// 0x800C9A60
// ---------------------------------------------------------------------------

/// Plays one animation `start`..`end` on the message record of a pane.
///
/// This is the variadic front-end of the message/animation system. It homes the
/// eight incoming argument words (`r3..r10`) - and, when CR1 bit 1 says a
/// floating-point argument was passed, the eight double-precision argument
/// registers (`f1..f8`) - into the `va_list` save areas, tags the list
/// `0x0500_0000` (`gpr = 5`, `fpr = 0`), stores the two frame words into the
/// global message state at `+0x3D0`/`+0x3D4`, and calls the message worker
/// `0x800C9B50` with the six argument words still in registers. The worker
/// formats the line through [`fn_800c9e80`] and draws it.
///
/// # Original
/// - Ghidra: `FUN_800c9a60` at `0x800C9A60` (160 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c9a60_FUN_800c9a60.c`
/// - observed: the `if ((bool)(in_cr1 >> 1 & 1)) { local_58 = param_1; ... }`
///   guard around the eight `undefined8` stores, the eight word stores
///   `local_78 .. local_5c = param_9 .. param_16`, the two pointers
///   `local_14 = &stack0x00000008` / `local_10 = &local_78`, the tag
///   `local_18 = 0x5000000`, and the two state stores
///   `*(iVar1 + 0x3d0) = param_11; *(iVar1 + 0x3d4) = param_12;` through
///   `iVar1 = *(int *)(unaff_r13 + -0x5704)`.
/// - observed: `FUN_800c9b50();` prints no argument list, so the six forwarded
///   registers below are the ones the body leaves untouched.
/// - inferred: the two frame roles. Every call site passes five words, for
///   example `FUN_800c9a60(pane, handle, 0x67, 0x32, 0)` from `0x80014FF0`;
///   `0x67`/`0x32` end up at state `+0x3D0`/`+0x3D4`, which is why they are
///   named `start`/`end`.
///
/// # Arguments
/// - `this`: `r3`, the animation owner (a pane of the message object).
/// - `handle`: `r4`, the animation handle.
/// - `start`: `r5`, first frame word; stored at message state `+0x3D0`.
/// - `end`: `r6`, second frame word; stored at message state `+0x3D4`.
/// - `tail`: `r7`, the fifth and last named word (`0` at every call site).
/// - `gpr`: `r8..r10`, the remaining register varargs.
/// - `fpr`: `f1..f8`, the floating-point varargs.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the two message-state words, fills the `va_list` save areas on the
/// stack, and calls the message worker.
///
/// # Safety
/// The message state pointer at `r13-0x5704` must be live and writable at
/// `+0x3D0..+0x3D8`; `0x800C9B50` must be a live PowerPC function with this
/// integer ABI.
///
/// # Confidence
/// low - the save areas, the `0x0500_0000` `va_list` word, the two state stores
/// and the register set are literal, but the export prints the worker call with
/// no argument list, so the forwarded words are the caller's registers rather
/// than a proven prototype.
pub unsafe fn fn_800c9a60(
    this: u32,
    handle: u32,
    start: u32,
    end: u32,
    tail: u32,
    gpr: [u32; 3],
    fpr: [f64; 8],
) {
    // -0x78: the eight saved GPRs (r3..r10); the eight FPRs follow at -0x58,
    // which is `reg_save_area + 0x20`, the offset the MSL va_list expects.
    let mut save = [0u32; 24];
    save[0] = this;
    save[1] = handle;
    save[2] = start;
    save[3] = end;
    save[4] = tail;
    save[5..8].copy_from_slice(&gpr);
    let mut index = 0;
    while index < 8 {
        w112_write_f64(save.as_mut_ptr().add(8 + index * 2) as usize, fpr[index]);
        index += 1;
    }

    // -0x18: the va_list {register word, input_arg_area, register_save_area}.
    // 0x0500_0000 = gpr index 5 (five named words), fpr index 0.
    let mut va = [0u32; 3];
    va[0] = 0x0500_0000;
    // observed: `local_14 = &stack0x00000008` - the caller's stacked arguments.
    // The reconstruction has no stack-argument area of its own, so it is null.
    va[1] = 0;
    va[2] = save.as_mut_ptr() as u32;
    // The original builds the list for the worker's own `va_arg` reads, which
    // the export does not show; keeping the block is what makes the save-area
    // layout literal. Nothing in this reconstruction consumes it.
    let _ = va;

    let state = read_u32(W112_G_MESSAGE_STATE) as usize;
    write_u32(state + 0x3D0, start);
    write_u32(state + 0x3D4, end);

    w112_call8(
        W112_CALL_800C9B50,
        this,
        handle,
        start,
        end,
        tail,
        gpr[0],
        gpr[1],
        gpr[2],
    );
}

// ---------------------------------------------------------------------------
// 0x800C9DF0
// ---------------------------------------------------------------------------

/// Shows one formatted text line on a message record (three named arguments).
///
/// The second variadic front-end of the message system. It homes the eight
/// incoming argument words (`r3..r10`) and the eight argument doubles
/// (`f1..f8`) into the `va_list` save areas, tags the list `0x0300_0000`
/// (`gpr = 3`, `fpr = 0`), and calls [`fn_800c9e80`] with the three named words
/// plus the first two register varargs, which is exactly the five arguments
/// that formatter takes.
///
/// # Original
/// - Ghidra: `FUN_800c9df0` at `0x800C9DF0` (144 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800c9df0_FUN_800c9df0.c`
/// - observed: the `if ((bool)(in_cr1 >> 1 & 1)) { local_58 = param_1; ... }`
///   guard, the eight word stores `local_78 .. local_5c = param_9 .. param_16`,
///   `local_14 = &stack0x00000008`, `local_10 = &local_78`,
///   `local_18 = 0x3000000`, then `FUN_800c9e80();`.
/// - observed: `FUN_800c9e80` is already translated here as
///   `(this, format, a3, a4, a5)`, and the one call site in the image,
///   `FUN_800c9df0(param_3, auStack_28, 0)` from `0x800B3B60`, passes three
///   named words - the same count the `0x0300_0000` tag records.
/// - inferred: with `gpr = 3` the first vararg is `r6`, so the formatter's
///   `a3/a4/a5` are `r5`, `r6`, `r7`.
///
/// # Arguments
/// - `this`: `r3`, the message/text writer.
/// - `format`: `r4`, the format string handed to the formatter.
/// - `a3`: `r5`, first substitution word.
/// - `gpr`: `r6..r10`, the remaining register varargs; the first two are the
///   formatter's second and third substitution words.
/// - `fpr`: `f1..f8`, the floating-point varargs.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Fills the `va_list` save areas on the stack, formats into the shared
/// `0x80359538` buffer and draws one string through the writer's `+0x80` slot.
///
/// # Safety
/// `this` must be a live text writer and `format` a readable format string;
/// the shared text buffer and the formatter must be live.
///
/// # Confidence
/// medium - the save areas, the `0x0300_0000` word and the callee are literal,
/// and the five forwarded words follow from the callee's arity plus the gpr
/// index in the tag; the export prints the call with no argument list.
pub unsafe fn fn_800c9df0(
    this: u32,
    format: u32,
    a3: u32,
    gpr: [u32; 5],
    fpr: [f64; 8],
) {
    // -0x78: the eight saved GPRs; the eight FPRs follow at -0x58.
    let mut save = [0u32; 24];
    save[0] = this;
    save[1] = format;
    save[2] = a3;
    save[3..8].copy_from_slice(&gpr);
    let mut index = 0;
    while index < 8 {
        w112_write_f64(save.as_mut_ptr().add(8 + index * 2) as usize, fpr[index]);
        index += 1;
    }

    // -0x18: the va_list {register word, input_arg_area, register_save_area}.
    // 0x0300_0000 = gpr index 3 (three named words), fpr index 0.
    let mut va = [0u32; 3];
    va[0] = 0x0300_0000;
    // observed: `local_14 = &stack0x00000008`; no stack-argument area exists in
    // the reconstruction, so it stays null.
    va[1] = 0;
    va[2] = save.as_mut_ptr() as u32;
    // Built and never read, exactly as in the export (see [`fn_800c9a60`]).
    let _ = va;

    fn_800c9e80(this as usize, format, a3, gpr[0], gpr[1]);
}

// ---------------------------------------------------------------------------
// 0x800CB490
// ---------------------------------------------------------------------------

/// Arms the overlay-object record behind a mask helper.
///
/// `variant == 0` builds two 0x18-byte render objects: the first with vtable
/// `0x803177BC` at record `+4` and the `0x800CB740` alpha flavour, the second
/// with vtable `0x80317798` at record `+8` and the `0x800CB760` flavour.
/// `variant == 1` builds only the first, with vtable `0x80317774` and the
/// `0x800CB780` flavour, which also marks the record as flipped. The texture
/// handle forwarded as the flavour's first size word is the `r3` result of the
/// `0x800CAB10` cave-texture load.
///
/// # Original
/// - Ghidra: `FUN_800cb490` at `0x800CB490` (280 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800cb490_FUN_800cb490.c`
/// - observed: `uVar5 = FUN_802dcd74(); iVar1 = (int)((ulonglong)uVar5 >> 0x20);`
///   (the save helper returns `r3` as the high word), `uVar2 =
///   FUN_800cab10(param_5);`, the `if (param_4 == 0)` / `else if (param_4 == 1)`
///   arms, each `FUN_802b9210(0x18)` allocation guarded by a null test, the
///   `FUN_8016a010(); *puVar3 = &DAT_803177xx;` pair, the `+4`/`+8` record
///   stores and the three flavour calls `FUN_800cb740(puVar3,uVar4,param_3,uVar2)`
///   (likewise `...760` and `...780`).
/// - observed: `FUN_802dcdc0(1)` is the save-helper epilogue; like
///   [`fn_800cb670`] it is not reproduced, because the function returns nothing.
/// - inferred: the flavour family reads six registers (`this`, `resource`, `id`,
///   first size, second size, texture) while this call site prints only four, so
///   the caller's fifth and sixth registers are exposed as `texture_index` and
///   `texture` and forwarded unchanged.
///
/// # Arguments
/// - `this`: `r3`, the 0xc-byte mask record whose `+4`/`+8` slots are filled.
/// - `resource`: `r4`, the buffer/heap handle forwarded to every flavour.
/// - `id`: `r5`, the object id forwarded to every flavour.
/// - `variant`: `r6`, `0` builds two objects, `1` builds one.
/// - `texture_index`: `r7`, cave-texture index for `0x800CAB10`; forwarded as
///   the flavour's second size word.
/// - `texture`: `r8`, the flavour's texture word, forwarded unchanged.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Allocates one or two 0x18-byte objects, writes their vtables and the record's
/// `+4`/`+8` slots, and loads one cave texture.
///
/// # Safety
/// `this` must be the 0xc-byte record built by `0x800CB470`, and the allocator,
/// archive loader and flavour initialisers must be live.
///
/// # Confidence
/// medium - the two arms, the three vtables, the allocation guards and the
/// record slots are literal; only the flavour's last two registers are inferred
/// from the callee's own prototype.
pub unsafe fn fn_800cb490(
    this: usize,
    resource: u32,
    id: u32,
    variant: u32,
    texture_index: u32,
    texture: u32,
) {
    // observed: `uVar2 = FUN_800cab10(param_5);` - the export takes the archive
    // loader's `r3` result as the handle, which `call1` reproduces.
    let loaded = platform::call1(W112_CALL_800CAB10, texture_index);

    if variant == 0 {
        let first = platform::call1(W112_ALLOC, 0x18);
        if first != 0 {
            // observed: `r3` still holds the allocation, which `0x8016A010`
            // installs the vtable on.
            platform::call1(W112_CALL_8016A010, first);
            write_u32(first as usize, W112_DAT_803177BC);
        }
        write_u32(this + 4, first);
        fn_800cb740(
            first as usize,
            resource,
            id,
            loaded as i32,
            texture_index as i32,
            texture,
        );
        let second = platform::call1(W112_ALLOC, 0x18);
        if second != 0 {
            platform::call1(W112_CALL_8016A010, second);
            write_u32(second as usize, W112_DAT_80317798);
        }
        write_u32(this + 8, second);
        fn_800cb760(
            second as usize,
            resource,
            id,
            loaded as i32,
            texture_index as i32,
            texture,
        );
    } else if variant == 1 {
        let only = platform::call1(W112_ALLOC, 0x18);
        if only != 0 {
            platform::call1(W112_CALL_8016A010, only);
            write_u32(only as usize, W112_DAT_80317774);
        }
        write_u32(this + 4, only);
        fn_800cb780(
            only as usize,
            resource,
            id,
            loaded as i32,
            texture_index as i32,
            texture,
        );
    }
}

