/// `0x80267420`: sets the object's `+0xA0..+0xAC` ground-lerp record.
const W113_CALL_80267420: usize = 0x8026_7420;

/// `0x80267390`: stores one byte at `+0x98` and notifies the object.
const W113_CALL_80267390: usize = 0x8026_7390;

/// `0x802674C0`: stores one word at `+0xB4`.
const W113_CALL_802674C0: usize = 0x8026_74C0;

/// `r13 - 0x5788` -> `0x80429EF8`: the object [`stage_effect_screen_matrix`] reads its scene
/// from. It is the only caller-supplied word of that body and stays unused.
const W113_G_5788: usize = SDA_BASE - 0x5788;

/// `r13 - 0x51F8` -> `0x8042A488`: the object-id manager of
/// [`fn_80098900`]; `+0x100` holds the resolver handle.
const W113_G_51F8: usize = SDA_BASE - 0x51F8;

/// `r13 - 0x51D8` -> `0x8042A4A8`: the global mode record whose `+0x10`/`+0x14`
/// words select the ground-lerp arm of [`fn_80098900`].
const W113_G_51D8: usize = SDA_BASE - 0x51D8;

/// `r2 - 0x6F18` / `r2 - 0x6F14`: the two words copied into the effect
/// record's `+0x74`/`+0x78`, `+0x7C`/`+0x80` and `+0x88..+0x94`. The first is
/// also read as an `f32` extent in the `2`/`3`/`6` arm, so both uses are kept
/// verbatim.
const W113_W_6F18: usize = SDA2_BASE - 0x6F18;
const W113_W_6F14: usize = SDA2_BASE - 0x6F14;

/// `r2 - 0x6F10` / `r2 - 0x6F08`: the normal/wide-screen x extent.
const W113_F_6F10: usize = SDA2_BASE - 0x6F10;
const W113_F_6F08: usize = SDA2_BASE - 0x6F08;

/// `r2 - 0x6F0C`: the y extent of the same quad.
const W113_F_6F0C: usize = SDA2_BASE - 0x6F0C;

/// `r2 - 0x6F04` / `r2 - 0x6F00`: the two depth words of the quad.
const W113_F_6F04: usize = SDA2_BASE - 0x6F04;
const W113_F_6F00: usize = SDA2_BASE - 0x6F00;

/// `r2 - 0x6EFC` / `r2 - 0x6EF8`: the near/far words of the `0x801C1350` quad
/// and of the draw record's `+0x18`/`+0x1C`.
const W113_W_6EFC: usize = SDA2_BASE - 0x6EFC;
const W113_W_6EF8: usize = SDA2_BASE - 0x6EF8;

/// `r2 - 0x6EF4`: the draw-record scale.
const W113_F_6EF4: usize = SDA2_BASE - 0x6EF4;

/// `r2 - 0x6EB8`: default value of the probe output slot of [`fn_80097250`].
const W113_F_6EB8: usize = SDA2_BASE - 0x6EB8;

/// `r2 - 0x6E7C`: third word of the [`fn_80097250`] position record.
const W113_F_6E7C: usize = SDA2_BASE - 0x6E7C;

/// Calls a PowerPC function with no arguments and returns `f1` as `f64`.
///
/// # Safety
/// `addr` must be a PowerPC function returning a double in `f1`.
unsafe fn w113_call0_f64(addr: usize) -> f64 {
    let f: extern "C" fn() -> f64 = core::mem::transmute(addr);
    f()
}

/// Calls a virtual method with `scale` in `f1`, `this` in `r3` and `record` in
/// `r4`. The three [`fn_80097250`] transition slots use this shape.
///
/// # Safety
/// `function` must be a PowerPC function with this mixed ABI and `record` must
/// be a readable three-word vector.
unsafe fn w113_vcall_f64_ptr2(function: usize, scale: f64, this: usize, record: usize) {
    let f: extern "C" fn(f64, u32, u32) = core::mem::transmute(function);
    f(scale, this as u32, record as u32);
}

/// Copies the twelve words of one quad into the effect record.
///
/// # Safety
/// `dst..dst+0x30` must be writable.
unsafe fn w113_copy_quad(dst: usize, src: &[u32; 12]) {
    let mut index = 0usize;
    while index < 12 {
        write_u32(dst + index * 4, src[index]);
        index += 1;
    }
}

/// Submits the effect id sampled by `0x800E27C0` for the wide-screen arms.
///
/// The id is truncated to `i32`, sign-extended into the record's `+0xA0`
/// long-long and forwarded to `0x801693F0` with the low 16 bits only. The two
/// GX state flushes `0x801C4F70`/`0x801C76C0` follow.
///
/// # Safety
/// `base + 0xA0` must be writable and the effect slot must be live.
unsafe fn w113_submit_effect_id(base: usize) {
    let id = w113_call0_f64(W113_CALL_800E27C0) as i32;
    write_u32(base + 0xA0, id as u32);
    write_u32(base + 0xA4, (id >> 31) as u32);
    platform::call4(
        W113_CALL_801693F0,
        W113_DAT_803575FC as u32,
        0,
        id as u32 & 0xFFFF,
        0,
    );
    platform::call0(0x801C_4F70);
    platform::call0(0x801C_76C0);
}

// ---------------------------------------------------------------------------
// 0x80093F10
// ---------------------------------------------------------------------------

/// Draws one mode-selected 2-D effect record for a UI pane.
///
/// The effect table behind `0x80286630` is indexed with `mode`; when its `+8`
/// `u16` is non-zero and the effect table is ready (`r13-0x5787`), the body
/// builds a 0xA8-byte record whose first two 0x30-byte quads live at `+0x00`
/// and `+0x30`, fills the colour/flip words at `+0x60..+0x9F`, samples the
/// camera object once, and dispatches on `mode`:
///
/// * `0`, `4`, `5`, `7`, `8`, `9`, `10`: the camera colour block
///   (`0x802540B0`) becomes the first quad and `0x80094660` fills the second;
/// * `1`, `0xB..0xE`: the same, plus one effect id from `0x800E27C0` and two
///   GX state flushes;
/// * `2`, `3`, `6`: both quads are built locally through
///   `0x801C0C10`/`0x801C10D0`, the wide-screen flag of `0x801DD1D0` picks the
///   x extent and the second quad route, and mode `3` also submits the id.
///
/// The record is then handed to `0x8016C850`, which resolves pane `pane`
/// through the global renderer and calls its vtable slot `+0x1C`.
///
/// # Original
/// - Ghidra: `FUN_80093f10` at `0x80093F10` (1120 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80093f10_FUN_80093f10.c`
/// - observed: `uVar12 = FUN_802dcd74(); iVar8 = (int)uVar12;` (the save helper
///   hands back `r3` in the high half and `r4` in the low half, so `pane` is
///   `r3` and `mode` is `r4`), `FUN_80286630()`/`FUN_80286b50(uVar5,iVar8)`,
///   the `r13-0x5787` readiness test, the two `FUN_801c04d0` quad resets, every
///   `local_xx` store, `local_218 = FUN_80164b30();`, the three switch arms with
///   their `FUN_80094660`/`FUN_801c0c10`/`FUN_801c10d0`/`FUN_801c1350` calls,
///   the two `thunk_FUN_801dd1d0` tests, the `FUN_802d0cc0`/`FUN_802d0f40`
///   record, the `mode == 3` id submit and `FUN_8016c850(&local_e0,r3,r4)`.
/// - observed: the two `ldexpf`/`unaff_GQR0` blocks only pre-scale the incoming
///   `f30`/`f31` save slots; their two results (`local_8`, `local_18`) are never
///   read, so they are the `psq_st` prologue artefact of the frame and are not
///   reproduced.
/// - inferred: the record offsets. Ghidra names the frame slots `local_e0`
///   (`0xE0`) down to `local_41`, i.e. the block starts at `local_e0` and grows
///   upward; `+0x00`/`+0x30` are therefore the two 0x30-byte quads and
///   `+0x60..+0xA4` the fields listed below.
///
/// # Arguments
/// - `pane`: `r3`, the index `0x8016C850` resolves through the global renderer.
/// - `mode`: `r4`, the effect-record selector (`0..14`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Builds the record, submits up to one effect id, may run three GX state
/// flushes, and calls one pane vtable method.
///
/// # Safety
/// `mode` must index a live effect-table record; the GX/render helpers and the
/// pane's vtable `+0x1C` must be callable.
///
/// # Confidence
/// medium - every guard, offset, extent and call is literal; the record's field
/// roles come only from the stores, and the `r2` slots are read at runtime.
pub unsafe fn fn_80093f10(pane: u32, mode: u32) {
    let table = call0_ret(W113_CALL_80286630);
    let present = platform::call2(W113_CALL_80286B50, table, mode);
    if present == 0 || read_u8(W105_G_TABLE_READY) == 0 {
        return;
    }

    // observed: `&local_e0` is the record base; the offsets below are the
    // original frame offsets relative to it.
    let mut record = [0u8; 0xA8];
    let base = record.as_mut_ptr() as usize;
    platform::call1(W113_CALL_801C04D0, base as u32);
    platform::call1(W113_CALL_801C04D0, (base + 0x30) as u32);

    let top = read_u32(W113_W_6F18);
    let bottom = read_u32(W113_W_6F14);
    write_u32(base + 0x74, top);
    write_u32(base + 0x78, bottom);
    write_u8(base + 0x60, 0);
    write_u32(base + 0x64, 0);
    write_u32(base + 0x68, 0);
    write_u8(base + 0x6C, 1);
    write_u32(base + 0x70, 0);
    // observed: the eight byte stores spell two RGBA colours, white then black.
    write_u8(base + 0x9A, 0xFF);
    write_u8(base + 0x99, 0xFF);
    write_u8(base + 0x98, 0xFF);
    write_u8(base + 0x9B, 0xFF);
    write_u8(base + 0x9E, 0);
    write_u8(base + 0x9D, 0);
    write_u8(base + 0x9C, 0);
    write_u8(base + 0x9F, 0xFF);
    write_u32(base + 0x7C, top);
    write_u32(base + 0x80, bottom);
    write_u32(base + 0x88, top);
    write_u32(base + 0x8C, top);
    write_u32(base + 0x90, top);
    write_u32(base + 0x94, top);

    // observed: `local_218 = FUN_80164b30();` - sampled for every mode, and
    // `0x802540b0` reads the object pointer out of the word it is stored in.
    let camera = call0_ret(W113_CALL_80164B30);
    let mut cam = [camera];
    // The 0x198 and 0x1C8 scratch quads never coexist: the first is copied into
    // the record before the second is built, so one buffer is enough.
    let mut quad = [0u32; 12];

    match mode {
        0 | 4 | 5 | 7 | 8 | 9 | 10 => {
            platform::call2(
                W113_CALL_802540B0,
                cam.as_mut_ptr() as u32,
                quad.as_mut_ptr() as u32,
            );
            w113_copy_quad(base, &quad);
            stage_effect_screen_matrix(W113_G_5788 as u32, base);
        }
        1 | 0xB | 0xC | 0xD | 0xE => {
            platform::call2(
                W113_CALL_802540B0,
                cam.as_mut_ptr() as u32,
                quad.as_mut_ptr() as u32,
            );
            w113_copy_quad(base, &quad);
            stage_effect_screen_matrix(W113_G_5788 as u32, base);
            w113_submit_effect_id(base);
        }
        2 | 3 | 6 => {
            platform::call1(W113_CALL_801C04D0, quad.as_mut_ptr() as u32);
            let extent = read_f32(W113_W_6F18) as f64;
            w108_call_3f64_2u(
                W113_CALL_801C0C10,
                extent,
                extent,
                extent,
                quad.as_mut_ptr() as u32,
                quad.as_mut_ptr() as u32,
            );
            w113_copy_quad(base, &quad);

            // observed: `thunk_FUN_801dd1d0()` selects the wide-screen x extent.
            let (x_extent, y_extent) = if call0_ret(W113_CALL_801DD1D0) == 0 {
                (read_f32(W113_F_6F10), read_f32(W113_F_6F0C))
            } else {
                (read_f32(W113_F_6F08), read_f32(W113_F_6F0C))
            };
            let x_extent = x_extent as f64;
            let y_extent = y_extent as f64;
            let depth = read_f32(W113_F_6F04) as f64;
            call8_f64_ptr(
                W113_CALL_801C10D0,
                y_extent,
                -y_extent,
                -x_extent,
                x_extent,
                depth,
                read_f32(W113_F_6F00) as f64,
                depth,
                depth,
                quad.as_mut_ptr() as u32,
            );
            w113_copy_quad(base + 0x30, &quad);

            // observed: the second `thunk_FUN_801dd1d0()` chooses the quad
            // submit or the draw-record path.
            if call0_ret(W113_CALL_801DD1D0) == 0 {
                platform::call1(W113_CALL_801C04D0, quad.as_mut_ptr() as u32);
                call6_f64_ptr(
                    W113_CALL_801C1350,
                    y_extent,
                    -y_extent,
                    -x_extent,
                    x_extent,
                    read_f32(W113_W_6EFC) as f64,
                    read_f32(W113_W_6EF8) as f64,
                    quad.as_mut_ptr() as u32,
                );
                platform::call2(W113_CALL_801C9840, quad.as_ptr() as u32, 1);
            } else {
                let mut draw = [0u8; 0x38];
                let dbase = draw.as_mut_ptr() as usize;
                platform::call1(W113_CALL_802D0CC0, dbase as u32);
                write_u32(dbase, 0);
                if read_u32(dbase + 4) != 0 {
                    write_u32(dbase + 4, 0);
                    write_u16(dbase + 0x34, read_u16(dbase + 0x34) | 1);
                }
                let scale = read_f32(W113_F_6EF4) as f64;
                write_f32(dbase + 8, (scale * x_extent) as f32);
                write_u32(dbase + 0x18, read_u32(W113_W_6EFC));
                write_f32(dbase + 0x0C, (scale * y_extent) as f32);
                write_u32(dbase + 0x1C, read_u32(W113_W_6EF8));
                write_u16(dbase + 0x34, read_u16(dbase + 0x34) | 1);
                platform::call1(W113_CALL_802D0F40, dbase as u32);
            }
            if mode == 3 {
                w113_submit_effect_id(base);
            }
        }
        _ => {}
    }

    platform::call3(W113_CALL_8016C850, base as u32, pane, mode);
}

// ---------------------------------------------------------------------------
// 0x80097170
// ---------------------------------------------------------------------------

/// Latches the actor's "notice taken" byte once the ground probe reports it.
///
/// When `+0x45A` is still clear the body runs [`fn_80097250`]; code `3` starts
/// the actor's death state (`0x800A0DC0`, argument `0`) and sets the latch,
/// while any other non-zero code sets the latch only when `+0x390` is already
/// set (the actor's own "seen" flag).
///
/// # Original
/// - Ghidra: `FUN_80097170` at `0x80097170` (116 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80097170_FUN_80097170.c`
/// - observed: `if (*(char *)(param_1 + 0x45a) == '\0')`, `iVar1 =
///   FUN_80097250();`, the `iVar1 == 3` arm with `FUN_800a0dc0(param_1,0)` and
///   `*(undefined1 *)(param_1 + 0x45a) = 1;`, and the `iVar1 != 0 &&
///   *(char *)(param_1 + 0x390) != '\0'` latch.
/// - observed: both callers (`0x8002E440`, `0x800A1830`) pass
///   `(f1 = r2-0x7C74, r3 = actor, r4 = actor + 0xAC)`, and
///   [`fn_80097250`] declares `(scale, this, point)`, which fixes the three
///   parameters the export drops.
///
/// # Arguments
/// - `scale`: `f1`, forwarded unchanged to [`fn_80097250`].
/// - `this`: `r3`, the `Wm` actor.
/// - `point`: `r4`, the two-float position at `this + 0xAC`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// May call `0x800A0DC0(this, 0)` and writes `+0x45A`.
///
/// # Safety
/// `this + 0x390`/`+0x45A` must be readable/writable and `point` must hold two
/// readable floats.
///
/// # Confidence
/// medium - the guard, the probe result and both stores are literal; the three
/// parameters are restored from the two call sites because the export declares
/// the function `(void)`.
pub unsafe fn fn_80097170(scale: f64, this: usize, point: usize) {
    if read_u8(this + 0x45A) != 0 {
        return;
    }
    let code = fn_80097250(scale, this, point);
    if code == 3 {
        platform::call2(W113_CALL_800A0DC0, this as u32, 0);
        write_u8(this + 0x45A, 1);
    } else if code != 0 && read_u8(this + 0x390) != 0 {
        write_u8(this + 0x45A, 1);
    }
}

// ---------------------------------------------------------------------------
// 0x80097250
// ---------------------------------------------------------------------------

/// Ground-probes the actor's position and runs the matching contact transition.
///
/// The probe [`fn_80075270`] is fed the two floats of `point`, the actor's
/// `+0x38F` layer byte and a stack slot seeded from `r2-0x6EB8`. The resulting
/// code then selects one of four groups through the actor's vtable at `+0x60`:
///
/// * `1`, `2`: latch `+0x45D`, save `+0x114`/`+0xF8`/`+0x118` into
///   `+0x4F0`/`+0x4F4`/`+0x4F8`, then slot `+0x21C` and slot `+0xC8`;
/// * `3`: latch `+0x45D` and slot `+0xCC`;
/// * `4`: latch `+0x45D` and slot `+0xD0`;
/// * `0`: restore the three saved words and clear `+0x45D`.
///
/// Every slot except `+0x21C` receives `(f1 = scale, r3 = this, r4 = &record)`
/// where `record` is `{ this+0xAC, probed height, r2-0x6E7C }`.
///
/// # Original
/// - Ghidra: `FUN_80097250` at `0x80097250` (404 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80097250_FUN_80097250.c`
/// - observed: `local_28 = *(undefined4 *)(r2-0x6eb8);`,
///   `iVar1 = FUN_80075270((double)*param_3,(double)param_3[1],
///   *(undefined1 *)(param_2+0x38f),&local_28);`, `local_24 =
///   *(param_2+0xac); local_1c = *(r2-0x6e7c); local_20 = local_28;`, the
///   `iVar1 - 1U < 2` / `== 3` / `== 4` ladder with the `+0x45D` latches and
///   the three `+0x4F0..+0x4F8` saves, the `+0x114`/`+0xF8`/`+0x118` restore,
///   and the four vtable slots `+0x21C`, `+0xC8`, `+0xCC`, `+0xD0`.
/// - observed: the two `ldexpf` blocks only pre-scale the saved quad in the
///   prologue/epilogue and never reach a store; they are the `psq_l`/`psq_st`
///   artefact and are not reproduced.
/// - inferred: `param_1` of the export is the `f1` argument (both call sites
///   pass it in `f1` and only `r3`/`r4` are live for the actor and the point),
///   which is why it is named `scale` here.
///
/// # Arguments
/// - `scale`: `f1`, forwarded to the transition slots.
/// - `this`: `r3`, the `Wm` actor (vtable at `+0x60`).
/// - `point`: `r4`, two floats read as the probe `(x, y)`.
///
/// # Returns
/// The probe code `0..4` (`0` = no surface).
///
/// # Side effects
/// Writes the probe output slot, `+0x45D`, `+0x4F0..+0x4F8` and, in the reset
/// arm, `+0x114`/`+0xF8`/`+0x118`; calls one or two vtable slots.
///
/// # Safety
/// `this` must carry a readable vtable and `point` two readable floats; the
/// probe and the vtable slots must be callable.
///
/// # Confidence
/// medium - the probe call, every guard and all four slot offsets are literal;
/// only the `f1`/`param_1` correspondence is inferred from the call sites.
pub unsafe fn fn_80097250(scale: f64, this: usize, point: usize) -> i32 {
    let mut height = read_f32(W113_F_6EB8);
    let code = fn_80075270(
        read_f32(point) as f64,
        read_f32(point + 4) as f64,
        read_u8(this + 0x38F) as u32,
        (&mut height as *mut f32) as usize,
    ) as i32;
    let vtable = read_u32(this + 0x60) as usize;
    let mut target = [read_f32(this + 0xAC), height, read_f32(W113_F_6E7C)];
    let record = target.as_mut_ptr() as usize;

    if (code as u32).wrapping_sub(1) < 2 {
        if read_u8(this + 0x45D) == 0 {
            write_u8(this + 0x45D, 1);
            write_u32(this + 0x4F0, read_u32(this + 0x114));
            write_u32(this + 0x4F4, read_u32(this + 0xF8));
            write_u32(this + 0x4F8, read_u32(this + 0x118));
            platform::call1(read_u32(vtable + 0x21C) as usize, this as u32);
            w113_vcall_f64_ptr2(read_u32(vtable + 0xC8) as usize, scale, this, record);
        }
    } else if code == 3 {
        if read_u8(this + 0x45D) == 0 {
            write_u8(this + 0x45D, 1);
            w113_vcall_f64_ptr2(read_u32(vtable + 0xCC) as usize, scale, this, record);
        }
    } else if code == 4 {
        if read_u8(this + 0x45D) == 0 {
            write_u8(this + 0x45D, 1);
            w113_vcall_f64_ptr2(read_u32(vtable + 0xD0) as usize, scale, this, record);
        }
    } else {
        if read_u8(this + 0x45D) != 0 {
            write_u32(this + 0x114, read_u32(this + 0x4F0));
            write_u32(this + 0xF8, read_u32(this + 0x4F4));
            write_u32(this + 0x118, read_u32(this + 0x4F8));
        }
        write_u8(this + 0x45D, 0);
    }
    code
}

// ---------------------------------------------------------------------------
// 0x80098900
// ---------------------------------------------------------------------------

/// Re-targets the `Wm` actor's ground effect after a mode-`2` event.
///
/// In mode `2` the actor's world position is normalised into two screen words
/// (`0x8006A4B0`) and stored at `+0x5E8`/`+0x5EC`. The four `+0x544` slots are
/// then scanned through `0x80275560`; the first slot with a positive value
/// selects the render block behind `+0x5B8` records, whose count is `+0x598`.
/// For every live record the state mask of its id (`+0x9C`) is fetched from
/// the `r13-0x51F8` manager with `0x80196660`, and the mask bits drive four
/// actions: the ground lerp `0x80267420` (bit `0`), the byte store
/// `0x80267390` with the `0x80275780` layer word (bit `3`), and the single
/// word store `0x802674C0` (bit `2`). Finally the generic mode handler
/// [`fn_80095480`] runs with the same arguments.
///
/// # Original
/// - Ghidra: `FUN_80098900` at `0x80098900` (464 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80098900_FUN_80098900.c`
/// - observed: `uVar8 = FUN_802dcd74(); iVar1 = (int)((ulonglong)uVar8 >> 0x20);`
///   (the save helper's `r3`/`r4` pair is `this`/`mode`), the `== 2` guard,
///   `FUN_8006a4b0(&local_48,iVar1 + 0xac)`, the two `+0x5E8`/`+0x5EC` stores,
///   the `FUN_80275560(iVar1 + 0x544,iVar5)` scan, `FUN_8019ece0(...)`, the
///   `*(uint *)(iVar1 + 0x598)` record walk with `*(int *)(iVar5 + 0x5b8)`,
///   `uVar3 = ~FUN_80196660(...)`, the `&1`/`&8`/`&2` tests with the
///   `*(r13-0x51d8)+0x14` (`== 3`, `== 2 && +0x10 == 3`) gate, and
///   `FUN_80095480(iVar1,(int)uVar8)`.
/// - observed: `FUN_8019ece0` and `FUN_80196660` are printed with an `f1`
///   argument that neither callee reads (the first one's result is discarded,
///   the second one's prototype starts at `r3`), so the `f1` value is not
///   modelled; the arguments the export does print are kept.
/// - observed: `FUN_80267420(dVar7,obj,0)` and `FUN_802674C0(dVar7,obj)` print
///   their `f1` value separately from the two integer arguments, which is why
///   they are called with `call1_f64_ptr2`/`call1_f64_ptr`.
///
/// # Arguments
/// - `this`: `r3`, the `Wm` actor.
/// - `mode`: `r4`, the event id; only `2` runs the retarget pass.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x5E8`/`+0x5EC` and the per-record words `+0x98`, `+0xA0..+0xAC`,
/// `+0xB4`; calls [`fn_80095480`] with the same arguments.
///
/// # Safety
/// `this` must be a live `Wm` actor whose `+0x5B8` record pointers are null or
/// live, and the `r13-0x51F8` manager must be initialised.
///
/// # Confidence
/// medium - the mask tests, the loop bounds, all offsets and the call order are
/// literal; the `f1` inputs of the two lerp callees are restored from the
/// preceding loads, and the two helper calls keep only the arguments their own
/// exports declare.
pub unsafe fn fn_80098900(this: usize, mode: u32) {
    if mode == 2 {
        let mut point = [0u32; 2];
        platform::call2(
            W113_CALL_8006A4B0,
            point.as_mut_ptr() as u32,
            (this + 0xAC) as u32,
        );
        write_u32(this + 0x5E8, point[0]);
        write_u32(this + 0x5EC, point[1]);

        let mut slot = 0u32;
        while slot < 4 {
            let found =
                platform::call2(W113_CALL_80275560, (this + 0x544) as u32, slot) as i32;
            if found > 0 {
                platform::call4(
                    W113_CALL_8019ECE0,
                    read_u32(this + 0x5A0),
                    (this + 0x5A8) as u32,
                    (this + 0x5E8) as u32,
                    0,
                );
                let manager = read_u32(W113_G_51F8);
                let count = read_u32(this + 0x598) as usize;
                let mut index = 0usize;
                while index < count {
                    let object = read_u32(this + 0x5B8 + index * 8) as usize;
                    if object != 0 {
                        let mask = !platform::call2(
                            W113_CALL_80196660,
                            manager,
                            read_u32(object + 0x9C),
                        );
                        if mask & 1 == 0 {
                            let state = read_u32(W113_G_51D8) as usize;
                            let kind = read_u32(state + 0x14);
                            if kind == 3 || (kind == 2 && read_u32(state + 0x10) == 3) {
                                let value = read_f32(this + 0x5A8) as f64;
                                call1_f64_ptr2(W113_CALL_80267420, value, object as u32, 0);
                            }
                        } else {
                            let value = read_f32(this + 0x5A8) as f64;
                            call1_f64_ptr2(W113_CALL_80267420, value, object as u32, 0);
                        }
                        if mask & 8 != 0 {
                            // observed: the export's `0xFFFFFFFF` fallback is
                            // unreachable here because the record is non-null.
                            let id = read_u32(object + 0x9C);
                            let mut out = [0u32; 8];
                            platform::call3(
                                W113_CALL_80275780,
                                read_u32(manager as usize + 0x100),
                                id,
                                out.as_mut_ptr() as u32,
                            );
                            let offset = read_i32(this + 0x5AC);
                            let layer = if offset < 0 {
                                (out[0] as i32).wrapping_add(offset) as u8
                            } else {
                                out[0] as u8
                            };
                            platform::call2(
                                W113_CALL_80267390,
                                object as u32,
                                layer as u32,
                            );
                        }
                        if mask & 2 != 0 {
                            call1_f64_ptr(
                                W113_CALL_802674C0,
                                read_f32(this + 0x5B4) as f64,
                                object as u32,
                            );
                        }
                    }
                    index += 1;
                }
                break;
            }
            slot += 1;
        }
    }
    fn_80095480(this, mode);
}

