/// Builds the clown-Jr stage model: archive handle, five named entries, three
/// bound nodes and the animation tie-ins.
///
/// The sequence is:
/// 1. `STAGE_BLOCK_INIT(this + 0x524, -1, <tile heap word>, 0, 0x20)`;
/// 2. [`ARC_LOAD_SUB`] loads `"g3d/koopaJr_clown.brres"` from `"koopaJr_clown"`
///    off the archive manager and the result is stored at `+0x540`;
/// 3. [`J3D_LOAD_ANM`] resolves `"koopaJr_clown"` on that handle and the model
///    is registered with [`FN_80169D90_A223`] under `+0x544`;
/// 4. the holder at `+0x548` is type-tested against [`W62_EFFECT_TYPE`] on its
///    `+0x08` slot and then driven with `(0x30001, 0)` on `+0x20`;
/// 5. `"getin"`, `"face"` and `"damage"` are looked up with
///    [`FN_8023A0B0_A223`]/[`FN_8023A120_A223`]/[`FN_8023A190_A223`] and bound
///    into the `+0x584`, `+0x5EC`, `+0x61C` and `+0x5BC` nodes, each followed
///    by the virtual `+0x18` attach and the two scale calls;
/// 6. [`FN_800690E0_A223`] tears the block down.
///
/// This is the clown-Jr twin of the `Wm_clown` constructor `fn_8009d010`,
/// which uses the same callees with the `+0x600` node family.
///
/// # Original
/// - Ghidra: `FUN_800a3100` at `0x800A3100` (812 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800a3100_FUN_800a3100.c`
/// - observed: `FUN_800690c0(param_1 + 0x524,0xffffffff,DAT_80377c48,0,0x20);`
///   then `FUN_800df180(*(int *)(unaff_r13 + -0x5648) + 4,
///   s_koopaJr_clown_80313718, s_g3d_koopaJr_clown_brres_80313700);`
/// - observed: `lwz r5,0x7c48(r4)` proves the fifth argument is the *word* at
///   `0x80377C48`, hence `read_u32(TILE_HEAP)`.
/// - observed: `local_38 = &DAT_802f8ff0;` is written to `r1+0x18` and its
///   address passed to the `+0x08` type test.
/// - observed: every float argument is `lfs f1,0xffff92bc(r2)` = `0.0f`.
///
/// # Arguments
/// - `this`: the clown-Jr actor; the block starts at `+0x524`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One archive load, five entry lookups, four node binds, three virtual
/// attaches and the block teardown.
///
/// # Safety
/// `this + 0x524 .. this + 0xD40` must be writable, the archive manager at
/// `G_ARC_MANAGER` must be mounted, and the vtables at `+0x544`/`+0x548` must
/// have live `+0x18`/`+0x08`/`+0x20` slots.
///
/// # Confidence
/// high - all 203 instructions were re-read: every call, argument register,
/// string and offset is literal. The only inference is the semantic naming of
/// the five animation/metadata calls.
pub unsafe fn fn_800a3100(this: usize) {
    platform::call5(
        STAGE_BLOCK_INIT,
        (this + 0x524) as u32,
        0xFFFF_FFFF,
        read_u32(TILE_HEAP),
        0,
        0x20,
    );
    let archive = read_u32(G_ARC_MANAGER) as usize;
    let model = platform::call3(
        ARC_LOAD_SUB,
        (archive + 4) as u32,
        S_KOOPAJR_CLOWN_A223 as u32,
        S_KOOPAJR_BRRES_A223 as u32,
    );
    write_u32(this + 0x540, model);
    let handle = platform::call2(
        J3D_LOAD_ANM,
        (this + 0x540) as u32,
        S_KOOPAJR_CLOWN_A223 as u32,
    );
    let mut entry = [handle];
    platform::call6(
        FN_80169D90_A223,
        (this + 0x544) as u32,
        entry.as_mut_ptr() as u32,
        (this + 0x524) as u32,
        0x16b,
        1,
        0,
    );
    let mut holder = read_u32(this + 0x548) as usize;
    let mut matched = false;
    if holder != 0 {
        let mut type_word: u32 = W62_EFFECT_TYPE as u32;
        let vtable = read_u32(holder) as usize;
        let ok = platform::call2(
            read_u32(vtable + 0x08) as usize,
            holder as u32,
            &mut type_word as *mut u32 as u32,
        );
        if ok != 0 {
            matched = true;
        }
    }
    if !matched {
        holder = 0;
    }
    let holder_vtable = read_u32(holder) as usize;
    platform::call3(
        read_u32(holder_vtable + 0x20) as usize,
        holder as u32,
        0x30001,
        0,
    );
    platform::call1(J3D_FINISH, (this + 0x544) as u32);
    platform::call2(
        FN_8016A000_A223,
        (this + 0x544) as u32,
        (this + 0xD40) as u32,
    );
    // "getin"
    let getin = platform::call2(
        FN_8023A0B0_A223,
        (this + 0x540) as u32,
        S_GETIN_A223 as u32,
    );
    // `local_3c` (handle) precedes `local_40` (`"getin"`) in the original
    // stack frame, so the handle slot is the first argument.
    let mut pair = [handle, getin];
    let pair_ptr = pair.as_mut_ptr() as u32;
    platform::call5(
        FN_801650D0_A223,
        (this + 0x584) as u32,
        pair_ptr,
        pair_ptr + 4,
        (this + 0x524) as u32,
        0,
    );
    let mut single = [getin];
    platform::call4(
        FN_801651F0_A223,
        (this + 0x584) as u32,
        (this + 0x544) as u32,
        single.as_mut_ptr() as u32,
        1,
    );    let zero = read_f32(F_ZERO_A223);
    call1_f64_ptr2(
        FN_80169F80_A223,
        zero as f64,
        (this + 0x544) as u32,
        (this + 0x584) as u32,
    );
    let _ = call1_f64_ptr(FN_801680E0_A223, zero as f64, (this + 0x584) as u32);
    // "face"
    let face = platform::call2(
        FN_8023A120_A223,
        (this + 0x540) as u32,
        S_FACE_A223 as u32,
    );
    write_u32(this + 0x5E8, face);
    let mut face_pair = [handle, face];
    let face_pair_ptr = face_pair.as_mut_ptr() as u32;
    platform::call6(
        W104_ANM_BIND,
        (this + 0x5EC) as u32,
        face_pair_ptr,
        face_pair_ptr + 4,
        (this + 0x524) as u32,
        0,
        1,
    );
    let mut face_single = [read_u32(this + 0x5E8)];
    platform::call5(
        W104_ANM_ATTACH,
        (this + 0x5EC) as u32,
        (this + 0x544) as u32,
        face_single.as_mut_ptr() as u32,
        0,
        1,
    );
    let vtable = read_u32(this + 0x544) as usize;
    platform::call2(
        read_u32(vtable + 0x18) as usize,
        (this + 0x544) as u32,
        (this + 0x5EC) as u32,
    );
    call1_f64_ptr2(FN_80166F10_A223, zero as f64, (this + 0x5EC) as u32, 0);
    call1_f64_ptr2(FN_80166EF0_A223, zero as f64, (this + 0x5EC) as u32, 0);
    // second "face" lookup feeding the +0x61C node
    let face2 = platform::call2(
        FN_8023A120_A223,
        (this + 0x540) as u32,
        S_FACE_A223 as u32,
    );
    write_u32(this + 0x618, face2);
    let mut face2_pair = [handle, face2];
    let face2_pair_ptr = face2_pair.as_mut_ptr() as u32;
    platform::call5(
        FN_80167C40_A223,
        (this + 0x61C) as u32,
        face2_pair_ptr,
        face2_pair_ptr + 4,
        (this + 0x524) as u32,
        0,
    );
    let mut face2_single = [read_u32(this + 0x618)];
    platform::call4(
        FN_80167D60_A223,
        (this + 0x61C) as u32,
        (this + 0x544) as u32,
        face2_single.as_mut_ptr() as u32,
        1,
    );
    let vtable2 = read_u32(this + 0x544) as usize;
    platform::call2(
        read_u32(vtable2 + 0x18) as usize,
        (this + 0x544) as u32,
        (this + 0x61C) as u32,
    );
    let _ = call1_f64_ptr(FN_801680E0_A223, zero as f64, (this + 0x61C) as u32);
    let _ = call1_f64_ptr(FN_80168FE0_A223, zero as f64, (this + 0x61C) as u32);
    // "damage"
    let damage = platform::call2(
        FN_8023A190_A223,
        (this + 0x540) as u32,
        S_DAMAGE_A223 as u32,
    );
    let mut damage_pair = [handle, damage];
    let damage_pair_ptr = damage_pair.as_mut_ptr() as u32;
    platform::call6(
        FN_80165C30_A223,
        (this + 0x5BC) as u32,
        damage_pair_ptr,
        damage_pair_ptr + 4,
        (this + 0x524) as u32,
        0,
        1,
    );
    let vtable3 = read_u32(this + 0x544) as usize;
    platform::call2(
        read_u32(vtable3 + 0x18) as usize,
        (this + 0x544) as u32,
        (this + 0x5BC) as u32,
    );
    let mut damage_single = [damage];
    platform::call5(
        FN_80165FD0_A223,
        (this + 0x5BC) as u32,
        (this + 0x544) as u32,
        damage_single.as_mut_ptr() as u32,
        0,
        1,
    );
    call1_f64_ptr2(FN_80166310_A223, zero as f64, (this + 0x5BC) as u32, 0);
    call1_f64_ptr2(FN_801662F0_A223, zero as f64, (this + 0x5BC) as u32, 0);
    platform::call1(FN_800690E0_A223, (this + 0x524) as u32);
}

