/// (the word is spilled to `r1+0x10` in between).
const W223B_F_MINUS_4: usize = 0x802F_0708;

/// `0x802F070C` → `0xBE799999` = `-0.24374999f`: the second padding float,
/// stored into `+0x420`.
const W223B_F_420: usize = 0x802F_070C;

/// `0x802F0714` → `0xFFFFFFFF`: the "no value" word stored into `+0x428`.
const W223B_W_428: usize = 0x802F_0714;

/// `0x802F0718` → `0xFFFFFFFF`: the "no value" word stored into `+0x42C`.
const W223B_W_42C: usize = 0x802F_0718;

/// `r2 - 0x6D44` → `0x8042C33C`: `0.0f`.
