/// The `+0x1C` word is copied into the stack temporary but never consumed.
const W224_REACTION_PARAMS_A224: usize = 0x802F_0900;

/// Calls a PowerPC function that takes two floats in `f1`/`f2` and three
/// integers in `r3`/`r4`/`r5`.
///
/// Used for `0x800E20A0`, which this module reaches through the 4-argument
/// `w223_call2_f64_ptr2_F` in the `fn_800a16a0` family; that helper drops the
/// third integer operand, which [`fn_800a9550`] sets to `6`.
///
/// # Safety
/// `addr` must use this mixed floating/integer ABI.
unsafe fn call2_f64_u32x3_A224(addr: usize, a: f64, b: f64, c: u32, d: u32, e: u32) {
    let f: extern "C" fn(f64, f64, u32, u32, u32) = core::mem::transmute(addr);
    f(a, b, c, d, e)
}

