/// The word at `record + 0x27FC`, or `0` when the id does not resolve.
///
/// # Safety
/// A non-zero result of `0x8005F900` must be a readable 0x2800-byte actor.
///
/// # Confidence
/// high - five instructions plus the frame, every operand literal.
pub unsafe fn fn_800a7890(_first: usize, index: u32) -> u32 {
    let record = platform::call1(FN_8005F900_A224, index);
    if record == 0 {
        0
    } else {
        read_u32(record as usize + 0x27FC)
    }
}

