/// `r2 - 0x6CA8` → `0x8042C3D8`: `480.0f`, the third component of the
/// three-float block [`fn_800a7690`] builds on its stack frame.
const W224D_F_480: usize = SDA2_BASE - 0x6CA8;

/// `r2 - 0x6C6C` → `0x8042C414`: `0.0f`, the height the two height branches in
/// [`fn_800a99d0`]/[`fn_800aa150`] compare against.
const W224D_F_ZERO: usize = SDA2_BASE - 0x6C6C;

/// `r2 - 0x6C64` → `0x8042C41C`: `24.0f`, the second float of the
/// `0x800E23C0` notice spawn in [`fn_800a99d0`].
const W224D_F_24: usize = SDA2_BASE - 0x6C64;

/// `r2 - 0x6C70` → `0x8042C410`: `1.0f`, the positive step used by
/// [`fn_800aa150`].
const W224D_F_ONE: usize = SDA2_BASE - 0x6C70;

/// `r2 - 0x6C5C` → `0x8042C424`: `-1.0f`, the negative step used by
/// [`fn_800aa150`].
const W224D_F_MONE: usize = SDA2_BASE - 0x6C5C;

/// `r2 - 0x6C48` → `0x8042C438`: `0.9f`, the bias [`fn_800aa150`] subtracts
/// before truncating to the `+0x840` coefficient index.
const W224D_F_09: usize = SDA2_BASE - 0x6C48;

/// `0x803584C4`: the record whose address [`fn_800a99d0`] hands to virtual
/// slot `0xD4`. It sits in the `0x80351680..0x80427680` segment, which has no
/// file image (`.bss`), so it reads as zeros at reset.
const W224D_DAT_803584C4: usize = 0x8035_84C4;

/// `0x80064610` (104 bytes): five-argument submitter; it clears the flag
/// through `0x80064600` and forwards `r3..r6` to `0x8006CA80`.
const FN_80064610_D: usize = 0x8006_4610;

/// `0x80162510` (116 bytes): destroys one object once (`+0xB` guard) and then
/// recurses down the `+0x14` / `+0xC` / `+0x10` child chain.
const FN_80162510_D: usize = 0x8016_2510;

/// Calls a PowerPC function with two widened floats and three words.
///
/// This is the argument list of `0x800E23C0` at the [`fn_800a99d0`] call site
/// (`f1`, `f2`, notice owner, actor, kind). The callee only declares four
/// parameters; the fifth word lands in `r5`, which `0x800E23C0` never reads.
///
/// # Safety
/// `addr` must use this mixed floating/integer ABI.
unsafe fn w224d_call2_f64_ptr3_D(addr: usize, a: f64, b: f64, c: u32, d: u32, e: u32) {
    let f: extern "C" fn(f64, f64, u32, u32, u32) = core::mem::transmute(addr);
    f(a, b, c, d, e)
}

