///   `FUN_801651f0(param_1 + 0x644,param_1 + 0x604,local_18,1);`,
///   `FUN_80169f80((double)*(float *)(unaff_r2 + -0x6c6c),param_1 + 0x604,
///   param_1 + 0x644);` and
///   `FUN_801680e0((double)*(float *)(param_1 + 0xacc),param_1 + 0x644);`.
