/// is the destination, `r4` the actor) is inferred, from the store/load
/// directions.
pub unsafe fn fn_800a8fa0(out: usize, source: usize) {
    write_f32(out, read_f32(source + 0xAC));
    write_f32(out + 0x4, read_f32(source + 0xB0));
    write_f32(out + 0x8, read_f32(source + 0xB4));
}

