/// Binds the `+0x760` resource at `slot` into both animation nodes.
///
/// The shared seven-call sequence of slots 51, 54, 57 and 60: look the entry up
/// (`0x8023A0B0`), bind it into the `+0x644` node (`0x801651F0`), scale that
/// node (`0x80169F80`), force it to `1.0f` (`0x801680E0`), load the second
/// handle (`0x8023A200`) into `+0x6A8`, attach it to the `+0x6AC` track
/// (`0x80166BD0`), blend the pair (`0x80169F80`) and finish with
/// `0x80166F10(1.0f, +0x6AC, 0)`.
///
/// # Safety
/// `this + 0x600`, `+0x604`, `+0x644`, `+0x6AC` and the `+0x760` handle set
/// must all be live, and `*(*(this + 0x760) + slot)` a loadable resource id.
unsafe fn bind_760_resource_w229(
    this: usize,
    slot: usize,
    scale: f32,
    bind_flag: u32,
    track_flag: u32,
) {
    let set = read_u32(this + 0x760) as usize;
    let resource = read_u32(set + slot);
    if resource == 0 {
        return;
    }
    let mut entry = [0u32; 1];
    entry[0] = platform::call1(FN_8023A0B0_A223, (this + 0x600) as u32);
    let _ = platform::call4(
        FN_801651F0_A223,
        (this + 0x644) as u32,
        (this + 0x604) as u32,
        entry.as_mut_ptr() as u32,
        bind_flag,
    );
    call_f32_u32x2_w229(
        FN_80169F80_A223,
        scale,
        (this + 0x604) as u32,
        (this + 0x644) as u32,
    );
    call_f32_u32_w229(
        FN_801680E0_A223,
        read_f32(W224D_F_ONE),
        (this + 0x644) as u32,
    );
    let mut value = [0u32; 1];
    value[0] = platform::call2(W104_ANM_LOAD, (this + 0x600) as u32, resource);
    write_u32(this + 0x6A8, value[0]);
    let _ = platform::call5(
        W104_ANM_ATTACH,
        (this + 0x6AC) as u32,
        (this + 0x604) as u32,
        value.as_mut_ptr() as u32,
        0,
        track_flag,
    );
    call_f32_u32x2_w229(
        FN_80169F80_A223,
        read_f32(W224D_F_ZERO),
        (this + 0x604) as u32,
        (this + 0x6AC) as u32,
    );
    call_f32_u32x2_w229(
        FN_80166F10_A223,
        read_f32(W224D_F_ONE),
        (this + 0x6AC) as u32,
        0,
    );
}

/// Releases both animation nodes of the actor.
