/// records, like [`W223B_BIND_RECORD`].
pub unsafe fn fn_800a5a00(this: usize) {
    let vtable = read_u32(this + 0x60) as usize;
    platform::call2(read_u32(vtable + 0x378) as usize, this as u32, 2);
    let vtable = read_u32(this + 0x60) as usize;
    platform::call1(read_u32(vtable + 0x390) as usize, this as u32);

    let zero = read_f32(W254B_F_ZERO);
    write_f32(this + 0x11C, zero);
    write_f32(this + 0x114, zero);
    write_u16(this + 0x744, 0);
    write_f32(this + 0xEC, zero);
    write_u32(this + 0xD18, 120);
    write_u32(this + 0xD1C, 40);
    write_u32(this + 0x360, 1);

    let side = u8::from(!(read_f32(this + 0xAC) < read_f32(this + 0x750)));
    write_u8(this + 0x348, side);

    let record = match read_u32(this + 0xD24) {
        0 => Some(W254B_RECORD_80357974),
        2 | 1 => Some(W254B_RECORD_80357934),
        _ => None,
    };
    if let Some(record) = record {
        let vtable = read_u32(this + 0x60) as usize;
        let owner = platform::call1(read_u32(vtable + 0x2DC) as usize, this as u32) as usize;
        let owner_vtable = read_u32(owner + 0x60) as usize;
        platform::call2(
            read_u32(owner_vtable + 0xD4) as usize,
            owner as u32,
            record as u32,
        );
    }
}

