    crate::resource::registry::fn_80166280(this + 0x5BC, 0);

    let vtable = read_u32(this + 0x60) as usize;
    platform::call1(read_u32(vtable + 0x33C) as usize, this as u32);
    let vtable = read_u32(this + 0x60) as usize;
    platform::call1(read_u32(vtable + 0x340) as usize, this as u32);

