///   `0x801c0540(this+0x7C,&stack48,this+0x7C)` pair, the `+0x104` halfword
///   through `0x8016eef0`, the mirrored `-0x774` translation, and the `+0x102`
///   halfword through `0x8016edd0`.
/// - observed: `0x8016a170(this+0x544,this+0x7C)` and
///   `0x8016a150(this+0x544,this+0xDC)`.
///
/// # Arguments
/// * `this` - actor with the position, the three angles, the `+0x7C` matrix and
///   the `+0x544` draw node.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Rewrites the `0x30`-byte matrix at `+0x7C` and binds it to `+0x544`.
///
/// # Safety
/// `this + 0x7C` must be a writable `0x30`-byte matrix, `+0xAC..+0xB4`,
/// `+0x100..+0x104` and `+0xDC` readable, and `+0x544` a live draw node.
///
/// # Confidence
/// high - the three rotations, the two translations and both bind calls are
/// literal. The `0x801C0BD0` position arguments are inferred from the `f1..f3`
/// registers in the raw words.
pub unsafe fn fn_800a3710(this: usize) {
    let zero = read_f32(W254B_F_ZERO);
    call3_f32_ptr(
        W29_MTX_TRANSLATION,
        read_f32(this + 0xAC),
        read_f32(this + 0xB0),
        read_f32(this + 0xB4),
        (this + 0x7C) as u32,
    );

    let mut angle_x = read_u16(this + 0x100);
    platform::call2(
        W29_MTX_ROTATE_B,
        (this + 0x7C) as u32,
        &mut angle_x as *mut u16 as u32,
    );

    let lift = read_f32(this + 0x774);
    let mut translation = [0u32; 12];
    call3_f32_ptr(
        W29_MTX_TRANSLATION,
        zero,
        lift,
        zero,
        translation.as_mut_ptr() as u32,
    );
    platform::call3(
        0x801C_0540,
        (this + 0x7C) as u32,
        translation.as_ptr() as u32,
        (this + 0x7C) as u32,
    );

    let mut angle_z = read_u16(this + 0x104);
    platform::call2(
        W29_MTX_ROTATE_C,
        (this + 0x7C) as u32,
        &mut angle_z as *mut u16 as u32,
    );

    call3_f32_ptr(
        W29_MTX_TRANSLATION,
        zero,
        -lift,
        zero,
        translation.as_mut_ptr() as u32,
    );
    platform::call3(
        0x801C_0540,
        (this + 0x7C) as u32,
        translation.as_ptr() as u32,
        (this + 0x7C) as u32,
    );

    let mut angle_y = read_u16(this + 0x102);
    platform::call2(
        W29_MTX_ROTATE_A,
        (this + 0x7C) as u32,
        &mut angle_y as *mut u16 as u32,
    );

    platform::call2(
        W29_MODEL_SET_MATRIX,
        (this + 0x544) as u32,
        (this + 0x7C) as u32,
    );
    platform::call2(
        W29_MODEL_SET_BASE,
        (this + 0x544) as u32,
        (this + 0xDC) as u32,
    );
}

