        let active =
            platform::call2(W259A_FN_ANM_ACTIVE, (this + 0x5EC) as u32, 0) != 0;
        if active || call2_f32(W259A_FN_ANM_VALUE, (this + 0x5EC) as u32, 0) == 0.0 {
            let vtable = read_u32(this + 0x60) as usize;
            platform::call2(read_u32(vtable + 0x378) as usize, this as u32, 0);
            let delay = platform::call1(W257_FN_TIMER, 300).wrapping_add(3);
            write_u32(this + 0x780, delay);
            write_u8(this + 0x784, 0);
        }
