/// Calls `func(f32, u32, u32) -> u32`.
#[inline]
unsafe fn c267_call_f32_u32x2(addr: usize, value: f32, a: u32, b: u32) -> u32 {
    let f: extern "C" fn(f32, u32, u32) -> u32 = core::mem::transmute(addr);
    f(value, a, b)
}

