    let node = platform::call2(
        B280_FUN_8023B200,
        (&mut resource as *mut u32) as u32,
        B280_STR_SKL_ROOT as u32,
    );
    let id = if node != 0 { read_u32(node as usize + 0xC) } else { 0 };
