/// high - the size, stride, count, both callback addresses and the publish slot
/// are literal.
pub unsafe fn fn_8008eb20(heap: u32) {
    let previous = platform::call1(0x8016_E4F0, heap);
    let array = platform::call1(NEW_DEFAULT, 0x0EC0) as usize;
    if array != 0 {
        platform::call5(
            W29_ARRAY_BUILD,
            array as u32,
            0x8009_EB90,
            0x8009_EBA0,
            0x03B0,
            4,
        );
        platform::write_u32(G_STAGE_OBJECTS, array as u32);
    }
    platform::call1(0x8016_E4F0, previous);
}

